import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Smooth L1 Loss with Mean Reduction
# This kernel computes the element-wise loss and performs a block-level reduction
# to minimize global memory writes (avoiding the creation of a 4GB intermediate tensor).
smooth_l1_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// CUDA Kernel
__global__ void smooth_l1_reduce_kernel(const float* __restrict__ preds, const float* __restrict__ targets, float* __restrict__ out, int size) {
    // Shared memory for partial block reduction
    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned int gridSize = blockDim.x * gridDim.x;

    float local_sum = 0.0f;

    // Grid-stride loop: handles arbitrary input sizes and allows fixed grid size
    for (int i = idx; i < size; i += gridSize) {
        float diff = fabsf(preds[i] - targets[i]);
        float val;
        // Smooth L1 logic (beta=1.0)
        if (diff < 1.0f) {
            val = 0.5f * diff * diff;
        } else {
            val = diff - 0.5f;
        }
        local_sum += val;
    }

    // Store local sum in shared memory
    sdata[tid] = local_sum;
    __syncthreads();

    // Block reduction (summing up sdata)
    // Assumes blockDim.x is a power of 2 (we use 256)
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Thread 0 writes the block's total result to global memory
    if (tid == 0) {
        out[blockIdx.x] = sdata[0];
    }
}

// C++ Wrapper
torch::Tensor smooth_l1_cuda(torch::Tensor preds, torch::Tensor targets) {
    // Check inputs
    TORCH_CHECK(preds.is_cuda, "preds must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda, "targets must be a CUDA tensor");
    TORCH_CHECK(preds.numel() == targets.numel(), "preds and targets must have the same number of elements");

    // Ensure contiguous memory for raw pointer access
    preds = preds.contiguous();
    targets = targets.contiguous();

    int size = preds.numel();
    const int threads = 256;
    const int blocks = 1024; // Fixed number of blocks to saturate the GPU

    // Allocate small output buffer for partial sums (size = number of blocks)
    auto out = torch::empty({blocks}, preds.options());

    // Launch kernel with dynamic shared memory
    smooth_l1_reduce_kernel<<<blocks, threads, threads * sizeof(float)>>>(
        preds.data_ptr<float>(),
        targets.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    // Final reduction on CPU/GPU (summing 1024 elements is trivial) and division for mean
    return out.sum() / static_cast<float>(size);
}
"""

smooth_l1_cpp_source = (
    "torch::Tensor smooth_l1_cuda(torch::Tensor preds, torch::Tensor targets);"
)

# Compile and load the custom operator
smooth_l1_op = load_inline(
    name="smooth_l1_op",
    cpp_sources=smooth_l1_cpp_source,
    cuda_sources=smooth_l1_source,
    functions=["smooth_l1_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model using custom CUDA kernel for fused Smooth L1 Loss.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.smooth_l1_op = smooth_l1_op

    def forward(self, predictions, targets):
        return self.smooth_l1_op.smooth_l1_cuda(predictions, targets)

