import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the specific Convolution layer (Conv2d)
# Architecture specs: Input (N, 3, H, W), Out (N, 96, H_out, W_out), K=11, S=4, P=2
conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_direct_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int in_h,
    int in_w,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int out_h,
    int out_w) {

    // 1D Grid mapping to 4D output tensor (N, OutC, OutH, OutW)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_h * out_w;

    if (idx < total_elements) {
        // Decompose index into dimensions: output is contiguous (N, C, H, W)
        int w_out_idx = idx % out_w;
        int tmp = idx / out_w;
        int h_out_idx = tmp % out_h;
        tmp = tmp / out_h;
        int k = tmp % out_channels;
        int n = tmp / out_channels;

        // Calculate starting input coordinates
        int h_in_start = h_out_idx * stride - padding;
        int w_in_start = w_out_idx * stride - padding;

        float val = 0.0f;

        // Direct convolution loop
        for (int c = 0; c < in_channels; ++c) {
            for (int r = 0; r < kernel_size; ++r) {
                for (int s = 0; s < kernel_size; ++s) {
                    int h_in = h_in_start + r;
                    int w_in = w_in_start + s;

                    // Boundary check for padding
                    if (h_in >= 0 && h_in < in_h && w_in >= 0 && w_in < in_w) {
                        // Input layout: (N, C, H, W)
                        int input_idx = ((n * in_channels + c) * in_h + h_in) * in_w + w_in;
                        // Weight layout: (OutC, InC, K, K)
                        int weight_idx = ((k * in_channels + c) * kernel_size + r) * kernel_size + s;

                        val += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        // Add bias
        if (bias != nullptr) {
            val += bias[k];
        }

        output[idx] = val;
    }
}

torch::Tensor conv2d_cuda_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);

    const int out_channels = weight.size(0);
    const int kernel_size = weight.size(2);

    // Parameters fixed by the architecture definition
    const int stride = 4;
    const int padding = 2;

    const int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    const int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    const int total_elements = batch_size * out_channels * out_h * out_w;
    const int threads = 256;
    const int blocks = (total_elements + threads - 1) / threads;

    const float* bias_ptr = (bias.defined()) ? bias.data_ptr<float>() : nullptr;

    conv2d_direct_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, in_h, in_w,
        out_channels, kernel_size, stride, padding,
        out_h, out_w
    );

    return output;
}
"""

conv2d_cpp_source = "torch::Tensor conv2d_cuda_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

# Compile the inline CUDA code
conv2d_custom_op = load_inline(
    name="conv2d_custom_op",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_cuda_forward"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Use standard nn.Conv2d to store parameters (weights/bias) compatible with standard optimizers/saving
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        # Delegate computation to the custom CUDA kernel
        # Ensure contiguous memory layout for correct pointer arithmetic in kernel
        return conv2d_custom_op.conv2d_cuda_forward(
            x.contiguous(), 
            self.conv1.weight.contiguous(), 
            self.conv1.bias.contiguous()
        )

