import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Split-K Matrix Multiplication
# This kernel optimizes for the "skinny" matrix multiplication (large K) by splitting 
# the reduction dimension K across multiple thread blocks and using atomic additions.
matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Block Tile sizes
#define BM 32
#define BN 32
#define BK 32

__global__ void split_k_matmul_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K,
    int split_count) 
{
    // Grid indices
    int bx = blockIdx.x; // Tile index in N
    int by = blockIdx.y; // Tile index in M
    int bz = blockIdx.z; // Split index in K

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Calculate global output coordinates
    int row = by * BM + ty;
    int col = bx * BN + tx;

    // Check bounds (although aligned in this problem, good practice)
    if (row >= M || col >= N) return;

    // Determine the range of K tiles this block is responsible for
    int total_tiles = K / BK;
    int tiles_per_split = (total_tiles + split_count - 1) / split_count;

    int tile_idx_start = bz * tiles_per_split;
    int tile_idx_end = min((bz + 1) * tiles_per_split, total_tiles);

    // If this block has no work, exit
    if (tile_idx_start >= tile_idx_end) return;

    // Shared memory for tiles of A and B
    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    float val = 0.0f;

    // Loop over the assigned tiles of K
    for (int t = tile_idx_start; t < tile_idx_end; ++t) {
        int k_curr = t * BK;

        // Load A tile: A[row, k_curr + tx]
        // Threads (ty, tx) map 1:1 to tile elements (32x32)
        As[ty][tx] = A[row * K + (k_curr + tx)];

        // Load B tile: B[k_curr + ty, col]
        // Threads (ty, tx) map 1:1 to tile elements
        Bs[ty][tx] = B[(k_curr + ty) * N + col];

        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            val += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Atomic accumulation is required because multiple blocks (different split_k)
    // contribute to the same output element C[row, col].
    atomicAdd(&C[row * N + col], val);
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    // Initialize C with zeros because we use atomicAdd
    auto C = torch::zeros({M, N}, A.options());

    dim3 block(32, 32);

    // Split K into chunks to utilize more SMs. 
    // For K=524288, splitting by 128 gives 4096 K-dim elements per block.
    // Total blocks = (256/32) * (256/32) * 128 = 8192 blocks, ensuring good occupancy.
    int split_count = 128; 

    dim3 grid((N + 31) / 32, (M + 31) / 32, split_count);

    split_k_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K, split_count
    );

    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the CUDA extension
matmul_op = load_inline(
    name="matmul_split_k",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model using custom Split-K CUDA Matrix Multiplication
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_op.matmul_cuda(A, B)

