import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Batch Normalization application.
# This kernel efficiently broadcasts the channel-wise scale and shift parameters
# to the input tensor (N, C, H, W) using a custom grid layout.
bn_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA Kernel: Fused Affine Transform (y = x * scale + shift)
__global__ void batchnorm_affine_kernel(
    const float* __restrict__ x,
    const float* __restrict__ scale,
    const float* __restrict__ shift,
    float* __restrict__ y,
    int C,
    int S) {

    // Grid Mapping:
    // BlockIdx.x -> Spatial tiles (H*W)
    // BlockIdx.y -> Channel dimension (C)
    // BlockIdx.z -> Batch dimension (N)

    int n = blockIdx.z;
    int c = blockIdx.y;
    int s_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Bounds check for the spatial dimension
    if (s_idx < S) {
        // Calculate the global linear index for the flattened 1D array
        // Input layout is contiguous (N, C, H, W) => (N, C, S)
        // Index = n * (C * S) + c * S + s_idx
        long long idx = (long long)n * C * S + (long long)c * S + s_idx;

        // Apply the fused scale and shift
        y[idx] = x[idx] * scale[c] + shift[c];
    }
}

torch::Tensor batchnorm_affine_cuda(torch::Tensor x, torch::Tensor scale, torch::Tensor shift) {
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int S = H * W; // Spatial size per channel

    auto y = torch::empty_like(x);

    const int block_size = 256;
    // Calculate grid size for spatial dimension coverage
    const int grid_x = (S + block_size - 1) / block_size;
    const int grid_y = C;
    const int grid_z = N;

    dim3 grid(grid_x, grid_y, grid_z);
    dim3 block(block_size);

    batchnorm_affine_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        scale.data_ptr<float>(),
        shift.data_ptr<float>(),
        y.data_ptr<float>(),
        C,
        S
    );

    return y;
}
"""

bn_cpp_source = "torch::Tensor batchnorm_affine_cuda(torch::Tensor x, torch::Tensor scale, torch::Tensor shift);"

# Compile the inline CUDA code
bn_op = load_inline(
    name='bn_op',
    cpp_sources=bn_cpp_source,
    cuda_sources=bn_cuda_source,
    functions=['batchnorm_affine_cuda'],
    verbose=False,
    extra_cflags=['-O3'],
    extra_cuda_cflags=['-O3', '--use_fast_math']
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        # We retain nn.BatchNorm2d to manage learnable parameters (weight, bias) 
        # and running statistics (running_mean, running_var).
        self.bn = nn.BatchNorm2d(num_features=num_features)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is contiguous for the CUDA kernel
        x = x.contiguous()

        if self.training:
            # 1. Compute Batch Statistics
            # We use PyTorch's optimized reduction for mean/var calculation.
            mean = x.mean(dim=(0, 2, 3))
            # BatchNorm uses biased variance for normalization
            var = x.var(dim=(0, 2, 3), unbiased=False)

            # 2. Update Running Statistics
            # Convert to unbiased variance for running stats update
            n = x.numel() / x.size(1)
            var_unbiased = var * (n / (n - 1.0))

            with torch.no_grad():
                self.bn.running_mean.mul_(1 - self.bn.momentum).add_(mean, alpha=self.bn.momentum)
                self.bn.running_var.mul_(1 - self.bn.momentum).add_(var_unbiased, alpha=self.bn.momentum)

            # 3. Calculate Fused Parameters for the current batch
            std = torch.sqrt(var + self.bn.eps)
            scale = self.bn.weight / std
            shift = self.bn.bias - mean * scale

        else:
            # Inference Mode: Use running statistics
            mean = self.bn.running_mean
            var = self.bn.running_var
            std = torch.sqrt(var + self.bn.eps)

            # Calculate Fused Parameters from running stats
            scale = self.bn.weight / std
            shift = self.bn.bias - mean * scale

        # Ensure parameters are contiguous memory
        scale = scale.contiguous()
        shift = shift.contiguous()

        # 4. Apply Custom CUDA Kernel
        # This replaces the element-wise normalization and affine transform
        return bn_op.batchnorm_affine_cuda(x, scale, shift)

