import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for optimized Softmax
# We use an "Online Softmax" algorithm to compute Max and Sum in a single pass over the data (per thread),
# followed by reductions, and a second pass to write the output.
# We also use vectorized memory access (float4) for higher memory bandwidth utilization.

softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>
#include <limits>

#define BLOCK_SIZE 1024

// Structure to hold max and sum for online softmax reduction
struct __align__(8) MaxSum {
    float max_val;
    float sum_val;
};

// Combine two MaxSum states (Online Softmax logic)
// See "Online Normalizer Calculation for Softmax"
__device__ __forceinline__ MaxSum combine_max_sum(MaxSum a, MaxSum b) {
    if (a.max_val > b.max_val) {
        return {a.max_val, a.sum_val + b.sum_val * expf(b.max_val - a.max_val)};
    } else if (b.max_val > a.max_val) {
        return {b.max_val, b.sum_val + a.sum_val * expf(a.max_val - b.max_val)};
    } else {
        // Handle case where max is -infinity (empty or initial state)
        if (a.max_val == -INFINITY) return {-INFINITY, 0.0f};
        return {a.max_val, a.sum_val + b.sum_val};
    }
}

// Warp reduction for MaxSum
__device__ __forceinline__ MaxSum warp_reduce(MaxSum val) {
    for (int offset = 32 / 2; offset > 0; offset /= 2) {
        MaxSum other;
        other.max_val = __shfl_down_sync(0xffffffff, val.max_val, offset);
        other.sum_val = __shfl_down_sync(0xffffffff, val.sum_val, offset);
        val = combine_max_sum(val, other);
    }
    return val;
}

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int width) {
    // Each block processes one row of the batch
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Calculate row offset
    // width is large (393216), so use long long to prevent overflow in index calculation
    long long row_offset = (long long)batch_idx * width;
    const float* row_in = input + row_offset;
    float* row_out = output + row_offset;

    // Use float4 for vectorized memory access to improve bandwidth
    // We assume width is divisible by 4 (393216 % 4 == 0) and pointers are aligned
    int vec_width = width / 4; 
    const float4* row_in_vec = reinterpret_cast<const float4*>(row_in);
    float4* row_out_vec = reinterpret_cast<float4*>(row_out);

    MaxSum thread_state = {-INFINITY, 0.0f};

    // First Pass: Calculate Max and Sum (Online Softmax)
    // Stride loop to cover the row width
    for (int i = tid; i < vec_width; i += BLOCK_SIZE) {
        float4 val = row_in_vec[i];
        float vals[4] = {val.x, val.y, val.z, val.w};

        // Unroll loop for vector components
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            float v = vals[k];
            // Online update: update max and rescale running sum
            if (v > thread_state.max_val) {
                thread_state.sum_val = thread_state.sum_val * expf(thread_state.max_val - v) + 1.0f;
                thread_state.max_val = v;
            } else {
                thread_state.sum_val += expf(v - thread_state.max_val);
            }
        }
    }

    // Intra-warp reduction
    thread_state = warp_reduce(thread_state);

    // Inter-warp reduction using shared memory
    __shared__ MaxSum shared_data[32]; 
    int lane = tid % 32;
    int warp_id = tid / 32;

    if (lane == 0) {
        shared_data[warp_id] = thread_state;
    }
    __syncthreads();

    // First warp reduces the results from other warps
    if (warp_id == 0) {
        // Load from shared memory, handle partial blocks of warps if any (not case here with 1024 threads)
        MaxSum warp_val = (lane < (BLOCK_SIZE / 32)) ? shared_data[lane] : MaxSum{-INFINITY, 0.0f};
        warp_val = warp_reduce(warp_val);
        if (lane == 0) {
            shared_data[0] = warp_val;
        }
    }
    __syncthreads();

    // Broadcast global max and sum to all threads in block
    MaxSum row_stats = shared_data[0];
    float global_max = row_stats.max_val;
    float global_sum = row_stats.sum_val;
    float inv_sum = 1.0f / global_sum;

    // Second Pass: Normalize and Write Output
    for (int i = tid; i < vec_width; i += BLOCK_SIZE) {
        float4 in_val = row_in_vec[i];
        float4 out_val;

        // Compute exponentials and normalize
        out_val.x = expf(in_val.x - global_max) * inv_sum;
        out_val.y = expf(in_val.y - global_max) * inv_sum;
        out_val.z = expf(in_val.z - global_max) * inv_sum;
        out_val.w = expf(in_val.w - global_max) * inv_sum;

        row_out_vec[i] = out_val;
    }
}

torch::Tensor softmax_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int width = input.size(1);

    // Launch one block per row
    softmax_kernel<<<batch_size, BLOCK_SIZE>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        width
    );
    return output;
}
"""

softmax_cpp_source = "torch::Tensor softmax_cuda(torch::Tensor input);"

# Compile the inline CUDA code
softmax_op = load_inline(
    name="softmax_op",
    cpp_sources=softmax_cpp_source,
    cuda_sources=softmax_source,
    functions=["softmax_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.softmax_op = softmax_op

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.softmax_op.softmax_cuda(x)

