import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel for Layer Normalization
# We use float4 vectorization to improve memory throughput for large feature dimensions.
layer_norm_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector_types.h>

__global__ void layer_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ y,
    int batch_size,
    int D,
    float epsilon) {

    // Each block processes one batch item (one row of data)
    int bid = blockIdx.x; 
    if (bid >= batch_size) return;

    // Calculate pointers for the current row
    const float* row_x = x + bid * D;
    float* row_y = y + bid * D;

    // Reinterpret pointers as float4 for vectorized access
    // We assume D is divisible by 4 based on the problem description (64*256*256 % 4 == 0)
    using Vec = float4;
    const Vec* row_x_vec = reinterpret_cast<const Vec*>(row_x);
    const Vec* gamma_vec = reinterpret_cast<const Vec*>(gamma);
    const Vec* beta_vec = reinterpret_cast<const Vec*>(beta);
    Vec* row_y_vec = reinterpret_cast<Vec*>(row_y);

    int num_vecs = D / 4;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    // 1. Calculate Sum and Sum-of-Squares
    // Grid-stride loop (effectively just block-stride since grid.y/z are 1)
    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        Vec v = row_x_vec[i];
        float val_sum = v.x + v.y + v.z + v.w;
        float val_sq = v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
        sum += val_sum;
        sum_sq += val_sq;
    }

    // 2. Reduction within the block using Shared Memory
    extern __shared__ float s_mem[];
    float* s_sum = s_mem;
    float* s_sq = s_mem + blockDim.x;

    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    // Standard parallel reduction
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sq[threadIdx.x] += s_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // 3. Compute statistics (Mean and Inverse Standard Deviation)
    __shared__ float s_mean;
    __shared__ float s_inv_std;

    if (threadIdx.x == 0) {
        float mean = s_sum[0] / D;
        float var = (s_sq[0] / D) - (mean * mean);
        s_mean = mean;
        // Clamp variance to 0 to avoid NaNs from precision errors, add epsilon
        s_inv_std = rsqrtf(fmaxf(var, 0.0f) + epsilon);
    }
    __syncthreads();

    float mean = s_mean;
    float inv_std = s_inv_std;

    // 4. Normalize and Write Output
    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        Vec v = row_x_vec[i];
        Vec g = gamma_vec[i];
        Vec b = beta_vec[i];
        Vec out;

        out.x = (v.x - mean) * inv_std * g.x + b.x;
        out.y = (v.y - mean) * inv_std * g.y + b.y;
        out.z = (v.z - mean) * inv_std * g.z + b.z;
        out.w = (v.w - mean) * inv_std * g.w + b.w;

        row_y_vec[i] = out;
    }
}

torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float epsilon) {
    // Assumptions: x is (Batch, D), gamma/beta are (D)
    int batch_size = x.size(0);
    int D = x.numel() / batch_size;

    auto y = torch::empty_like(x);

    const int threads = 256;
    // Shared memory needs to hold sums and sum_sqs for the block
    size_t smem_size = 2 * threads * sizeof(float);

    layer_norm_kernel<<<batch_size, threads, smem_size>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        y.data_ptr<float>(),
        batch_size,
        D,
        epsilon
    );

    return y;
}
"""

layer_norm_cpp_source = "torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float epsilon);"

# Compile the inline CUDA code
layer_norm_op = load_inline(
    name="layer_norm_custom_op",
    cpp_sources=layer_norm_cpp_source,
    cuda_sources=layer_norm_cuda_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        # PyTorch LayerNorm parameters: weight (gamma) and bias (beta)
        # Initialization matches nn.LayerNorm: weight=1, bias=0
        self.gamma = nn.Parameter(torch.ones(normalized_shape))
        self.beta = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.op = layer_norm_op

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is contiguous for the CUDA kernel
        x = x.contiguous()
        return self.op.layer_norm_cuda(x, self.gamma, self.beta, self.eps)

