import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels for depthwise and pointwise convolutions
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input, 
    const float* __restrict__ weight, 
    const float* __restrict__ bias, 
    float* __restrict__ output,
    int batch_size, int channels, int height, int width,
    int height_out, int width_out,
    int kernel_size, int stride, int padding, int dilation, bool has_bias) {

    // Map threads to output spatial dimensions
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int z = blockIdx.z;

    // Grid Z covers Batch * Channels
    int c = z % channels;
    int b = z / channels;

    if (w_out < width_out && h_out < height_out && b < batch_size) {
        float val = 0.0f;

        // Weight layout for depthwise (groups=channels): (C, 1, K, K) -> flat (C * K * K)
        int weight_base = c * kernel_size * kernel_size;

        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h_in = h_out * stride - padding + kh * dilation;
                int w_in = w_out * stride - padding + kw * dilation;

                if (h_in >= 0 && h_in < height && w_in >= 0 && w_in < width) {
                    // Input: (N, C, H, W)
                    int in_idx = ((b * channels + c) * height + h_in) * width + w_in;
                    int w_idx = weight_base + kh * kernel_size + kw;
                    val += input[in_idx] * weight[w_idx];
                }
            }
        }

        if (has_bias) {
            val += bias[c];
        }

        int out_idx = ((b * channels + c) * height_out + h_out) * width_out + w_out;
        output[out_idx] = val;
    }
}

__global__ void pointwise_conv2d_kernel(
    const float* __restrict__ input, 
    const float* __restrict__ weight, 
    const float* __restrict__ bias, 
    float* __restrict__ output,
    int batch_size, int in_channels, int out_channels,
    int height, int width, bool has_bias) {

    // Map threads to spatial dimensions
    int w = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;
    int z = blockIdx.z; 

    // Grid Z covers Batch * OutChannels
    int out_c = z % out_channels;
    int b = z / out_channels;

    if (w < width && h < height && b < batch_size) {
        float val = 0.0f;

        // Weight layout: (OutC, InC, 1, 1) -> flat (OutC * InC)
        int w_base = out_c * in_channels;

        // Input layout: (N, InC, H, W). We need to stride over InC.
        // Base offset for this batch and pixel
        int in_base = b * in_channels * height * width + h * width + w;
        int in_stride = height * width;

        for (int ic = 0; ic < in_channels; ++ic) {
            val += input[in_base + ic * in_stride] * weight[w_base + ic];
        }

        if (has_bias) {
            val += bias[out_c];
        }

        int out_idx = ((b * out_channels + out_c) * height + h) * width + w;
        output[out_idx] = val;
    }
}

torch::Tensor depthwise_cuda(
    torch::Tensor input, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    int stride, int padding, int dilation) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    auto kernel_size = weight.size(2);

    auto height_out = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto width_out = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, height_out, width_out}, input.options());

    bool has_bias = bias.defined() && bias.numel() > 0;
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;

    dim3 block(16, 16);
    dim3 grid((width_out + 15) / 16, (height_out + 15) / 16, batch_size * channels);

    depthwise_conv2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, channels, height, width,
        height_out, width_out,
        kernel_size, stride, padding, dilation, has_bias
    );
    return output;
}

torch::Tensor pointwise_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias) {

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
