    auto out_channels = weight.size(0);

    auto output = torch::zeros({batch_size, out_channels, height, width}, input.options());

    bool has_bias = bias.defined() && bias.numel() > 0;
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;

    dim3 block(16, 16);
    dim3 grid((width + 15) / 16, (height + 15) / 16, batch_size * out_channels);

    pointwise_conv2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels, height, width, has_bias
    );
    return output;
}
