import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code for 3D Transposed Convolution
# Optimizes for stride=1, padding=0 cases common in the provided architecture,
# but supports generic parameters.
conv_transpose3d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch, int in_channels, int out_channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dilation_d, int dilation_h, int dilation_w,
    int total_elements) {

    // Global index for output element
    // Linearized index over (N, OutChannels, OutDepth, OutHeight, OutWidth)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // Decode index to (n, c_out, oz, oy, ox)
    // Layout: (N, C_out, D_out, H_out, W_out)
    int temp = idx;
    int ox = temp % out_w; temp /= out_w;
    int oy = temp % out_h; temp /= out_h;
    int oz = temp % out_d; temp /= out_d;
    int c_out = temp % out_channels; temp /= out_channels;
    int n = temp;

    float sum = 0.0f;

    // Transposed Convolution Logic (Output-centric)
    // We iterate over input channels and the kernel window to gather contributions.
    // The relationship is: oz = iz * stride + k * dilation - padding
    // Inverting for iz: iz = (oz + padding - k * dilation) / stride

    for (int c_in = 0; c_in < in_channels; ++c_in) {

        // Loop over kernel dimensions
        for (int kz = 0; kz < k_d; ++kz) {
            int rhs_z = oz + pad_d - kz * dilation_d;
            if (rhs_z % stride_d != 0) continue;
            int iz = rhs_z / stride_d;

            if (iz >= 0 && iz < in_d) {
                for (int ky = 0; ky < k_h; ++ky) {
                    int rhs_y = oy + pad_h - ky * dilation_h;
                    if (rhs_y % stride_h != 0) continue;
                    int iy = rhs_y / stride_h;

                    if (iy >= 0 && iy < in_h) {
                        for (int kx = 0; kx < k_w; ++kx) {
                            int rhs_x = ox + pad_w - kx * dilation_w;
                            if (rhs_x % stride_w != 0) continue;
                            int ix = rhs_x / stride_w;

                            if (ix >= 0 && ix < in_w) {
                                // Calculate 1D indices for input and weight tensors
                                // Input: (n, c_in, iz, iy, ix)
                                int input_idx = ((((n * in_channels + c_in) * in_d + iz) * in_h + iy) * in_w + ix);

                                // Weight: (c_in, c_out, kz, ky, kx)
                                // Note: PyTorch ConvTranspose3d weights are stored as (in, out, k...)
                                int weight_idx = ((((c_in * out_channels + c_out) * k_d + kz) * k_h + ky) * k_w + kx);

                                sum += input[input_idx] * weight[weight_idx];
                            }
                        }
                    }
                }
            }
        }
    }

    // Add bias if present
    if (bias != nullptr) {
        sum += bias[c_out];
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int output_padding_d, int output_padding_h, int output_padding_w,
    int dilation_d, int dilation_h, int dilation_w) {

    auto batch = input.size(0);
    auto in_channels = input.size(1);
    auto in_d = input.size(2);
    auto in_h = input.size(3);
    auto in_w = input.size(4);

    // weight shape: (in_channels, out_channels, k_d, k_h, k_w)
    // Assuming groups=1 for this implementation as per architecture
    auto out_channels = weight.size(1);
    auto k_d = weight.size(2);
    auto k_h = weight.size(3);
    auto k_w = weight.size(4);

    // Calculate output dimensions
    auto out_d = (in_d - 1) * stride_d - 2 * pad_d + dilation_d * (k_d - 1) + output_padding_d + 1;
    auto out_h = (in_h - 1) * stride_h - 2 * pad_h + dilation_h * (k_h - 1) + output_padding_h + 1;
    auto out_w = (in_w - 1) * stride_w - 2 * pad_w + dilation_w * (k_w - 1) + output_padding_w + 1;

    auto output = torch::zeros({batch, out_channels, out_d, out_h, out_w}, input.options());

    // Launch configuration
    int total_elements = batch * out_channels * out_d * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<float>();
    }

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch, in_channels, out_channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        k_d, k_h, k_w,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        dilation_d, dilation_h, dilation_w,
        total_elements
    );

    return output;
}
"""

