import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication optimized for symmetric matrices.
# Since A and B are symmetric, we can optimize memory access patterns.
# Standard MatMul: C_ij = sum_k (A_ik * B_kj)
# Using Symmetry B_kj = B_jk: C_ij = sum_k (A_ik * B_jk)
# This allows us to load B row-wise (coalesced) instead of column-wise (strided).
# We implement a Tiled Matrix Multiplication kernel with Shared Memory to reduce global memory bandwidth usage.

symmetric_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void symmetric_matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column indices for C
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float val = 0.0f;

    // Shared memory buffers with padding to avoid bank conflicts
    // Dimensions [32][33]
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    // Loop over tiles
    for (int k = 0; k < N; k += TILE_SIZE) {

        // Load tile of A into shared memory
        // We need A[row][k...k+TILE_SIZE]
        if (row < N && (k + tx) < N) {
            As[ty][tx] = A[row * N + (k + tx)];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        // We need column 'col' of B for the dot product.
        // Since B is symmetric, Column 'col' == Row 'col'.
        // We load Row 'col' which allows for coalesced memory access.
        // We map the threads to load the rows of B corresponding to the columns of C this block is responsible for.
        // The columns of C this block computes are [bx*TILE_SIZE, (bx+1)*TILE_SIZE].
        // So we load rows [bx*TILE_SIZE, (bx+1)*TILE_SIZE] of B.

        int b_row = bx * TILE_SIZE + ty; // varying ty selects the row of B

        if (b_row < N && (k + tx) < N) {
            Bs[ty][tx] = B[b_row * N + (k + tx)];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product for this tile
        // C_row,col += sum( A_row,k * B_col,k )
        // A value comes from As[ty][n]
        // B value comes from Bs[tx][n] (This retrieves B[col][k+n] because Bs row 'tx' maps to global row 'bx*T+tx' aka 'col')
        #pragma unroll
        for (int n = 0; n < TILE_SIZE; ++n) {
            val += As[ty][n] * Bs[tx][n];
        }

        __syncthreads();
    }

    // Store result
    if (row < N && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    symmetric_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

symmetric_matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

symmetric_matmul = load_inline(
    name="symmetric_matmul",
    cpp_sources=symmetric_matmul_cpp_source,
    cuda_sources=symmetric_matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = symmetric_matmul

    def forward(self, A, B):
        return self.matmul_op.matmul_cuda(A, B)

