    int in_d, int in_h, int in_w,
    int out_channels,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int stride, int padding) {

    // Calculate global index
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long total_elements = (long long)batch_size * out_channels * out_d * out_h * out_w;

    if (idx < total_elements) {
        // Map linear index to output coordinates (n, oc, od, oh, ow)
        // Output Layout: (N, C, D, H, W)
        long long temp = idx;
        int ow = temp % out_w; temp /= out_w;
        int oh = temp % out_h; temp /= out_h;
        int od = temp % out_d; temp /= out_d;
        int oc = temp % out_channels; 
        int n = temp; // remaining is batch index

        float sum = 0.0f;

        // Input layout: (N, Cin, Din, Hin, Win)
        // Weight layout: (Cout, Cin, Kd, Kh, Kw)

        long long input_batch_offset = (long long)n * in_channels * in_d * in_h * in_w;
        long long weight_oc_offset = (long long)oc * in_channels * k_d * k_h * k_w;

        for (int ic = 0; ic < in_channels; ++ic) {
            long long input_ic_offset = input_batch_offset + (long long)ic * in_d * in_h * in_w;
            long long weight_ic_offset = weight_oc_offset + (long long)ic * k_d * k_h * k_w;

            for (int z = 0; z < k_d; ++z) {
                int id = od * stride - padding + z;
                if (id >= 0 && id < in_d) {
                    for (int y = 0; y < k_h; ++y) {
                        int ih = oh * stride - padding + y;
                        if (ih >= 0 && ih < in_h) {
                            for (int x = 0; x < k_w; ++x) {
                                int iw = ow * stride - padding + x;
                                if (iw >= 0 && iw < in_w) {
                                    long long in_idx = input_ic_offset + (long long)id * in_h * in_w + ih * in_w + iw;
                                    long long w_idx = weight_ic_offset + (long long)z * k_h * k_w + y * k_w + x;
                                    sum += input[in_idx] * weight[w_idx];
                                }
                            }
                        }
                    }
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv3d_cuda_forward(torch::Tensor input, torch::Tensor weight, int stride, int padding) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_d = input.size(2);
    int in_h = input.size(3);
    int in_w = input.size(4);

    int out_channels = weight.size(0);
    int k_d = weight.size(2);
    int k_h = weight.size(3);
    int k_w = weight.size(4);

    int out_d = (in_d + 2 * padding - k_d) / stride + 1;
    int out_h = (in_h + 2 * padding - k_h) / stride + 1;
    int out_w = (in_w + 2 * padding - k_w) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_d, out_h, out_w}, input.options());

    long long total_elements = (long long)batch_size * out_channels * out_d * out_h * out_w;
