# Define the custom CUDA kernel for 2D Convolution
conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int kernel_h,
    int kernel_w,
    int stride,
    int padding,
    int dilation
) {
    // 2D grid block mapping to output spatial dimensions
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int ox = blockIdx.x * blockDim.x + tx;
    int oy = blockIdx.y * blockDim.y + ty;

    // Z-dimension of grid maps to batch and output channel
    int b_k = blockIdx.z;
    int b = b_k / out_channels;
    int k = b_k % out_channels;

    // Bounds check
    if (b >= batch_size || k >= out_channels || ox >= out_w || oy >= out_h) {
        return;
    }

    float val = 0.0f;

    // Add bias if present
    if (bias != nullptr) {
        val = bias[k];
    }

    // Convolution loop
    for (int c = 0; c < in_channels; ++c) {
        for (int p = 0; p < kernel_h; ++p) {
            for (int q = 0; q < kernel_w; ++q) {
                int in_y = oy * stride - padding + p * dilation;
                int in_x = ox * stride - padding + q * dilation;

                if (in_y >= 0 && in_y < in_h && in_x >= 0 && in_x < in_w) {
                    int input_idx = ((b * in_channels + c) * in_h + in_y) * in_w + in_x;
                    int weight_idx = ((k * in_channels + c) * kernel_h + p) * kernel_w + q;
                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    int out_idx = ((b * out_channels + k) * out_h + oy) * out_w + ox;
    output[out_idx] = val;
}

torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int stride,
    int padding,
    int dilation,
    int groups
) {
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(groups == 1, "Only groups=1 is supported");

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_channels = weight.size(0);
    int kernel_h = weight.size(2);
    int kernel_w = weight.size(3);

    int out_h = (in_h + 2 * padding - dilation * (kernel_h - 1) - 1) / stride + 1;
    int out_w = (in_w + 2 * padding - dilation * (kernel_w - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<float>();
    }

    dim3 block(16, 16);
    dim3 grid((out_w + block.x - 1) / block.x, (out_h + block.y - 1) / block.y, batch_size * out_channels);

    conv2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        out_h,
        out_w,
        kernel_h,
        kernel_w,
        stride,
        padding,
        dilation
    );

    return output;
}
