import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 3D Transposed Convolution
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels, int out_channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width,
    int kernel_d, int kernel_h, int kernel_w,
    int stride, int padding, int groups) {

    // Global index for output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;

    if (idx >= total_elements) return;

    // Decode 1D index to 5D coordinates (N, C_out, D_out, H_out, W_out)
    int w_out = idx % out_width;
    int tmp = idx / out_width;
    int h_out = tmp % out_height;
    tmp = tmp / out_height;
    int d_out = tmp % out_depth;
    tmp = tmp / out_depth;
    int c_out = tmp % out_channels;
    int n = tmp / out_channels;

    // Determine group and channel indices
    int channels_per_group_out = out_channels / groups;
    int channels_per_group_in = in_channels / groups;
    int group_id = c_out / channels_per_group_out;
    int c_out_rel = c_out % channels_per_group_out;

    // Starting input channel for this group
    int c_in_start = group_id * channels_per_group_in;

    // Initialize accumulator with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[c_out];
    }

    // Determine starting kernel offsets based on stride alignment
    // We only process kernel weights that align with the strided input
    // Condition: (d_out + padding - kd) % stride == 0
    // Implies: kd % stride == (d_out + padding) % stride

    int kd_start = (d_out + padding) % stride;
    int kh_start = (h_out + padding) % stride;
    int kw_start = (w_out + padding) % stride;

    // Iterate over relevant kernel weights
    for (int kd = kd_start; kd < kernel_d; kd += stride) {
        int d_in = (d_out + padding - kd) / stride;
        // Boundary check for input depth
        if (d_in < 0 || d_in >= in_depth) continue;

        for (int kh = kh_start; kh < kernel_h; kh += stride) {
            int h_in = (h_out + padding - kh) / stride;
            if (h_in < 0 || h_in >= in_height) continue;

            for (int kw = kw_start; kw < kernel_w; kw += stride) {
                int w_in = (w_out + padding - kw) / stride;
                if (w_in < 0 || w_in >= in_width) continue;

                // Accumulate over input channels within the group
                for (int c = 0; c < channels_per_group_in; ++c) {
                    int c_in = c_in_start + c;

                    // Input index calculation
                    int input_idx = ((((n * in_channels + c_in) * in_depth + d_in) * in_height + h_in) * in_width + w_in);

                    // Weight index calculation
                    // Weight shape: (in_channels, out_channels/groups, kernel_d, kernel_h, kernel_w)
                    int weight_idx = ((((c_in * channels_per_group_out + c_out_rel) * kernel_d + kd) * kernel_h + kh) * kernel_w + kw);

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    output[idx] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int stride,
    int padding,
    int output_padding,
    int groups) {

    // Get dimensions
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);

    // Parse weight dimensions
    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int kernel_d = weight.size(2);
    int kernel_h = weight.size(3);
    int kernel_w = weight.size(4);

    // Calculate output dimensions
    int out_depth = (in_depth - 1) * stride - 2 * padding + kernel_d + output_padding;
    int out_height = (in_height - 1) * stride - 2 * padding + kernel_h + output_padding;
    int out_width = (in_width - 1) * stride - 2 * padding + kernel_w + output_padding;

    // Allocate output tensor
    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, input.options());

    // Handle bias pointer
    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<float>();
    }

    // Launch kernel
    int total_elements = output.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels, out_channels,
        in_depth, in_height, in_width,
        out_depth, out_height, out_width,
        kernel_d, kernel_h, kernel_w,
        stride, padding, groups
    );

    return output;
}
"""

