import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 3D Tensor-Matrix Multiplication (Batch GEMM equivalent)
matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_WIDTH 32

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int m, int k, int n) {
    // A is (m x k), B is (k x n), C is (m x n)
    // We map the 3D tensor A (N, M, K) to a 2D matrix (N*M, K) for the multiplication

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Row and Column index of the output C
    int row = blockIdx.y * TILE_WIDTH + ty;
    int col = blockIdx.x * TILE_WIDTH + tx;

    float value = 0.0f;

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Bs[TILE_WIDTH][TILE_WIDTH];

    // Loop over the K dimension in tiles
    int num_tiles = (k + TILE_WIDTH - 1) / TILE_WIDTH;

    for (int t = 0; t < num_tiles; ++t) {

        // Load tile from A into shared memory
        // A row index: row, A col index: t * TILE_WIDTH + tx
        int a_col = t * TILE_WIDTH + tx;
        if (row < m && a_col < k) {
            As[ty][tx] = A[row * k + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory
        // B row index: t * TILE_WIDTH + ty, B col index: col
        int b_row = t * TILE_WIDTH + ty;
        if (b_row < k && col < n) {
            Bs[ty][tx] = B[b_row * n + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        // Synchronize threads to ensure tile is loaded
        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int i = 0; i < TILE_WIDTH; ++i) {
            value += As[ty][i] * Bs[i][tx];
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Write result to global memory
    if (row < m && col < n) {
        C[row * n + col] = value;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A: (N, M, K)
    // B: (K, L)

    // Ensure contiguous memory layout
    if (!A.is_contiguous()) A = A.contiguous();
    if (!B.is_contiguous()) B = B.contiguous();

    int N = A.size(0);
    int M = A.size(1);
    int K = A.size(2);
    int L = B.size(1);

    // Flatten first two dimensions of A effectively: m = N * M
    int m = N * M;
    int k = K;
    int n = L;

    // Allocate output tensor
    auto C = torch::zeros({N, M, L}, A.options());

    // Grid and Block dimensions
    dim3 dimBlock(TILE_WIDTH, TILE_WIDTH);
    dim3 dimGrid((n + TILE_WIDTH - 1) / TILE_WIDTH, (m + TILE_WIDTH - 1) / TILE_WIDTH);

    // Launch kernel
    matmul_kernel<<<dimGrid, dimBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), m, k, n);

    return C;
}
"""

matmul_cpp_source = "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
matmul_op = load_inline(
    name="matmul_op",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_cuda_source,
    functions=["custom_matmul_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    """
    Performs 3D tensor-matrix multiplication using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_op

    def forward(self, A, B):
        """
        Performs 3D tensor-matrix multiplication.

        Args:
            A (torch.Tensor): Input 3D tensor of shape (N, M, K).
            B (torch.Tensor): Input matrix of shape (K, L).

        Returns:
            torch.Tensor: Output tensor of shape (N, M, L).
        """
        return self.matmul_op.custom_matmul_cuda(A, B)

