from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for depthwise 2D convolution
depthwise_conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int k_h,
    int k_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias
) {
    // 1D Grid strategy: each thread computes one output pixel
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * out_h * out_w;

    if (idx < total_elements) {
        // Map linear index to (n, c, oh, ow)
        int ow = idx % out_w;
        int temp = idx / out_w;
        int oh = temp % out_h;
        temp = temp / out_h;
        int c = temp % channels;
        int n = temp / channels;

        float sum = 0.0f;

        // Calculate pointers
        // Input: (N, C, H, W)
        // Weight: (C, 1, KH, KW) -> conceptually (C, KH, KW) for depthwise
        // Bias: (C)

        int input_batch_offset = n * channels * in_h * in_w + c * in_h * in_w;
        int weight_offset = c * k_h * k_w;

        for (int kh = 0; kh < k_h; ++kh) {
            for (int kw = 0; kw < k_w; ++kw) {
                int ih = oh * stride_h + kh * dilation_h - pad_h;
                int iw = ow * stride_w + kw * dilation_w - pad_w;

                if (ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
                    float val = input[input_batch_offset + ih * in_w + iw];
