# Define the custom CUDA kernel for the GELU activation
gelu_source_cuda = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x_val = x[idx];

        // Constants
        // sqrt(2/pi)
        const float k0 = 0.7978845608f; 
        const float k1 = 0.044715f;

        // Compute x^3
        float x_cube = x_val * x_val * x_val;

        // Compute inner term: sqrt(2/pi) * (x + 0.044715 * x^3)
        float inner = k0 * (x_val + k1 * x_cube);

        // Compute GELU: 0.5 * x * (1 + tanh(inner))
        out[idx] = 0.5f * x_val * (1.0f + tanhf(inner));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    // Ensure contiguous tensor for direct pointer access
    x = x.contiguous();
    auto out = torch::empty_like(x);

    int size = x.numel();
    const int block_size = 512;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
