# Define the custom CUDA kernel for LeakyReLU
# We use vectorized memory access (float4) for improved bandwidth utilization
leaky_relu_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void leaky_relu_kernel(const float* __restrict__ input, float* __restrict__ output, float negative_slope, int64_t n) {
    // Grid-stride loop logic
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;

    // Vectorized path: Process 4 elements at a time using float4
    // This significantly improves memory throughput
    int64_t n_vec = n / 4;
    const float4* input_f4 = reinterpret_cast<const float4*>(input);
    float4* output_f4 = reinterpret_cast<float4*>(output);

    for (int64_t i = idx; i < n_vec; i += stride) {
        float4 v = input_f4[i];

        // Apply LeakyReLU logic component-wise
        v.x = (v.x > 0.0f) ? v.x : v.x * negative_slope;
        v.y = (v.y > 0.0f) ? v.y : v.y * negative_slope;
        v.z = (v.z > 0.0f) ? v.z : v.z * negative_slope;
        v.w = (v.w > 0.0f) ? v.w : v.w * negative_slope;

        output_f4[i] = v;
    }

    // Scalar path: Handle the remaining elements (tail)
    // The tail size is at most 3, but the loop logic handles any count
    int64_t start_scalar = n_vec * 4;
    for (int64_t i = start_scalar + idx; i < n; i += stride) {
        float v = input[i];
        output[i] = (v > 0.0f) ? v : v * negative_slope;
    }
}

torch::Tensor leaky_relu_cuda_forward(torch::Tensor input, float negative_slope) {
    // Allocate output tensor with same shape and type
    auto output = torch::empty_like(input);
    int64_t n = input.numel();

    if (n == 0) return output;

    const int block_size = 256;

    // Calculate grid size based on vectorized count
    int64_t num_vec_elements = n / 4;
    int64_t grid_size = (num_vec_elements + block_size - 1) / block_size;

    // Limit grid size to a reasonable maximum for grid-stride loop efficiency
    // and to avoid exceeding hardware limits on older devices
    if (grid_size > 32768) grid_size = 32768;
    if (grid_size == 0) grid_size = 1;

    leaky_relu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        negative_slope,
        n
    );

    return output;
}
"""

