#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void maxpool3d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch, const int channel,
    const int in_d, const int in_h, const int in_w,
    const int out_d, const int out_h, const int out_w,
    const int kernel_size, const int stride, const int padding, const int dilation) {

    // Flat index for the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int num_outputs = batch * channel * out_d * out_h * out_w;

    if (idx < num_outputs) {
        // Calculate output coordinates (b, c, d_out, h_out, w_out)
        int w_out = idx % out_w;
        int temp = idx / out_w;
        int h_out = temp % out_h;
        temp /= out_h;
        int d_out = temp % out_d;
        temp /= out_d;
        int c = temp % channel;
        int b = temp / channel;

        // Calculate the starting index of the window in the input tensor
        int d_start = d_out * stride - padding;
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        float max_val = -FLT_MAX;

        // Calculate base offset for this batch and channel in the input
        // Input shape: (N, C, D, H, W)
        int input_batch_channel_offset = (b * channel + c) * (in_d * in_h * in_w);

        // Iterate over the 3D kernel window
        for (int i = 0; i < kernel_size; ++i) {
            for (int j = 0; j < kernel_size; ++j) {
                for (int k = 0; k < kernel_size; ++k) {
                    int d_in = d_start + i * dilation;
                    int h_in = h_start + j * dilation;
                    int w_in = w_start + k * dilation;

                    // Boundary checks
                    if (d_in >= 0 && d_in < in_d &&
                        h_in >= 0 && h_in < in_h &&
                        w_in >= 0 && w_in < in_w) {

                        // Calculate flat input index
                        int in_idx = input_batch_channel_offset + 
                                     d_in * (in_h * in_w) + 
                                     h_in * in_w + 
                                     w_in;

                        float val = input[in_idx];
                        if (val > max_val) {
                            max_val = val;
                        }
                    }
                }
            }
        }
        output[idx] = max_val;
    }
}

torch::Tensor maxpool3d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    // Ensure input is on CUDA
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA");

    // Ensure contiguous memory for pointer access
    input = input.contiguous();

    int batch = input.size(0);
    int channel = input.size(1);
    int in_d = input.size(2);
    int in_h = input.size(3);
    int in_w = input.size(4);

    // Compute output dimensions according to PyTorch MaxPool3d formula (floor mode)
    // L_out = floor((L_in + 2*padding - dilation*(kernel_size-1) - 1)/stride + 1)
    int out_d = (in_d + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_h = (in_h + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_w = (in_w + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    // Handle edge case for 0 or negative dimensions (return empty or minimal 1 size logic)
    // Standard PyTorch would likely error or return shape 0 if calculated as such.
    if (out_d < 0) out_d = 0;
    if (out_h < 0) out_h = 0;
    if (out_w < 0) out_w = 0;

    auto output = torch::empty({batch, channel, out_d, out_h, out_w}, input.options());

    if (out_d > 0 && out_h > 0 && out_w > 0) {
        int total_threads = batch * channel * out_d * out_h * out_w;
        const int block_size = 256;
        const int num_blocks = (total_threads + block_size - 1) / block_size;

        maxpool3d_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            batch, channel,
            in_d, in_h, in_w,
            out_d, out_h, out_w,
            kernel_size, stride, padding, dilation
        );
    }

    return output;
}
"""

