import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for min reduction
# This kernel optimizes the reduction by parallelizing over the output elements.
# It handles the memory access pattern efficiently when the reduction dimension 
# allows for coalesced reads across the inner dimension (which is true for dim=1 in the provided problem).
min_reduce_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void min_reduce_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                  int outer_size, int reduce_size, int inner_size) {
    // We flatten the parallelization domain to the total number of output elements.
    // Each thread is responsible for computing one output value.
    // The input tensor is logically viewed as (outer, reduce, inner).
    // The output tensor is logically viewed as (outer, inner).

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = outer_size * inner_size;

    if (idx < total_output_elements) {
        // Map linear index 'idx' back to (outer_index, inner_index) coordinates
        // idx = o * inner_size + i
        int i = idx % inner_size;
        int o = idx / inner_size;

        float min_val = FLT_MAX;

        // Calculate the starting offset in the input tensor for this thread.
        // We iterate over the 'reduce' dimension (size = reduce_size).
        // The flattened input index is: o * (reduce_size * inner_size) + r * inner_size + i
        // We use 'long long' for the offset to prevent overflow for large tensors (approx > 2GB).
        long long input_offset = (long long)o * reduce_size * inner_size + i;

        for (int r = 0; r < reduce_size; ++r) {
            float val = input[input_offset];
            if (val < min_val) {
                min_val = val;
            }
            // Stride to the next element along the reduction dimension
            input_offset += inner_size;
        }

        output[idx] = min_val;
    }
}

torch::Tensor min_reduce_cuda(torch::Tensor input, int dim) {
    // Ensure the input is contiguous in memory for correct pointer arithmetic
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    // Handle Python's negative dimension indexing (e.g., -1)
    if (dim < 0) dim += input.dim();

    // Calculate the logical dimensions for the kernel:
    // outer_size: product of dimensions before 'dim'
    // reduce_size: the size of the dimension 'dim'
    // inner_size: product of dimensions after 'dim'
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= input.size(i);
    }

    int reduce_size = input.size(dim);

    int inner_size = 1;
    for (int i = dim + 1; i < input.dim(); ++i) {
        inner_size *= input.size(i);
    }

    // Create the output tensor with the reduction dimension removed
    auto sizes = input.sizes().vec();
    sizes.erase(sizes.begin() + dim);
    auto output = torch::empty(sizes, input.options());

    int total_output_elements = outer_size * inner_size;

    // Launch the kernel
    if (total_output_elements > 0) {
        const int block_size = 256;
        const int num_blocks = (total_output_elements + block_size - 1) / block_size;

        min_reduce_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            reduce_size,
            inner_size
        );
    }

    return output;
}
"""

min_reduce_cpp_source = "torch::Tensor min_reduce_cuda(torch::Tensor input, int dim);"

# Compile and load the inline C++/CUDA extension
min_reduce_op = load_inline(
    name="min_reduce_op",
