import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the Softsign activation
# Softsign(x) = x / (1 + |x|)
# We use vectorized memory access (float4) to improve memory bandwidth utilization.
softsign_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void softsign_kernel(const float* __restrict__ input, float* __restrict__ output, int64_t n) {
    // Calculate global thread index
    // We cast to int64_t to prevent overflow for very large tensors, 
    // although 32-bit int suffices for up to ~2B elements.
    int64_t idx = (static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x) * 4;

    if (idx < n) {
        // Check if we can perform a full vectorized read/write (4 floats)
        if (idx + 3 < n) {
            // Reinterpret cast to float4 for vectorized load
            float4 v = *reinterpret_cast<const float4*>(&input[idx]);
            float4 res;

            // Compute Softsign element-wise
            // fast math intrinsic fabsf is used
            res.x = v.x / (1.0f + fabsf(v.x));
            res.y = v.y / (1.0f + fabsf(v.y));
            res.z = v.z / (1.0f + fabsf(v.z));
            res.w = v.w / (1.0f + fabsf(v.w));

            // Vectorized store
            *reinterpret_cast<float4*>(&output[idx]) = res;
        } else {
            // Handle boundary conditions (remaining 1-3 elements)
            for (int i = 0; i < 4; ++i) {
                if (idx + i < n) {
                    float val = input[idx + i];
                    output[idx + i] = val / (1.0f + fabsf(val));
                }
            }
        }
    }
}

torch::Tensor softsign_cuda(torch::Tensor input) {
    // Ensure input is contiguous for valid pointer arithmetic and vectorization
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(input.device().is_cuda(), "Input tensor must be on CUDA");

    auto n = input.numel();
