import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused KL Divergence
kl_div_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Fused KL Divergence Kernel
// Computes sum(targets * (log(targets) - log(predictions)))
// Handles the reduction efficiently on GPU
__global__ void fused_kl_div_kernel(
    const float* __restrict__ predictions, 
    const float* __restrict__ targets, 
    float* output, 
    int numel
) {
    // Grid-stride loop setup
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    int stride = blockDim.x * gridDim.x;

    float local_sum = 0.0f;

    // Iterate over the data
    for (int i = idx; i < numel; i += stride) {
        float p = predictions[i];
        float t = targets[i];

        // KL Divergence formula: y_true * (log(y_true) - log(y_pred))
        // If target is 0, the term is 0 (limit x->0 of x*log(x) is 0)
        // We assume predictions > 0 (output of softmax)
        if (t > 0.0f) {
            local_sum += t * (logf(t) - logf(p));
        }
    }

    // Block-level reduction using shared memory
    extern __shared__ float sdata[];
    sdata[tid] = local_sum;
    __syncthreads();

    // Reduce within the block
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Atomic accumulation of block results to global memory
    if (tid == 0) {
        atomicAdd(output, sdata[0]);
    }
}

torch::Tensor fused_kl_div_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure inputs are on CUDA and contiguous
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.sizes() == targets.sizes(), "Input shapes must match");

    predictions = predictions.contiguous();
    targets = targets.contiguous();

    int numel = predictions.numel();

    // Allocate output scalar on GPU
    auto output = torch::zeros({1}, predictions.options());

    // Kernel configuration
    const int block_size = 256;
    // Use a fixed grid size large enough to saturate typical GPUs, 
    // relying on the grid-stride loop to handle arbitrary sizes.
    const int grid_size = 2048; 

    fused_kl_div_kernel<<<grid_size, block_size, block_size * sizeof(float)>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        output.data_ptr<float>(),
        numel
    );

    // Apply 'batchmean' reduction: divide sum by batch size (dimension 0)
    int batch_size = predictions.size(0);
    return output / static_cast<float>(batch_size);
}
"""

