# Compile the inline CUDA code
cross_entropy_op = load_inline(
    name="cross_entropy_op",
    cpp_sources=cross_entropy_cpp_source,
    cuda_sources=cross_entropy_source,
    functions=["cross_entropy_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
)

