# Define the custom CUDA kernel for mean reduction along dimension 1 of a 3D tensor.
# This kernel is optimized for the specific input shape (batch, dim1, dim2) where dim1 is reduced.
# It uses a 2D grid of threads to parallelize over the batch and dim2 dimensions,
# ensuring coalesced memory access patterns for reading from the input tensor.

mean_dim1_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mean_dim1_kernel(const float* __restrict__ x, float* __restrict__ out, int batch, int dim, int m_dim) {
    // Map grid to output (batch, m_dim)
    // x corresponds to m_dim (dim2), y corresponds to batch
    int m = blockIdx.x * blockDim.x + threadIdx.x;
    int b = blockIdx.y * blockDim.y + threadIdx.y;

    if (b < batch && m < m_dim) {
        float sum = 0.0f;
        // x shape is (batch, dim, m_dim)
        // We want to sum over 'dim'.
        // Flat index = b * (dim * m_dim) + d * m_dim + m
        // Note: We use size_t for the offset calculation to avoid potential 32-bit integer overflow 
        // for large tensors, although standard int fits exactly for the given dims ~2.1B elements.
        size_t offset = (size_t)b * dim * m_dim + m;

        // Stride is m_dim. 
        // Threads in a warp have contiguous 'm' values, so they read contiguous memory addresses 
        // at each step 'd'. This ensures memory coalescing.
        for (int d = 0; d < dim; ++d) {
            sum += x[offset];
            offset += m_dim;
        }

        out[b * m_dim + m] = sum / (float)dim;
    }
}

torch::Tensor mean_dim1_cuda(torch::Tensor x) {
    // Check inputs
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    x = x.contiguous();

    int batch = x.size(0);
    int dim = x.size(1);
    int m_dim = x.size(2);

    auto out = torch::empty({batch, m_dim}, x.options());

    // Configure kernel launch
    // Block size 32x16 = 512 threads.
    // 32 along x-dimension aligns with warps for coalesced access along m_dim.
    dim3 threads(32, 16);
    dim3 blocks((m_dim + threads.x - 1) / threads.x, (batch + threads.y - 1) / threads.y);

    mean_dim1_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch, dim, m_dim);

    return out;
}
"""

