#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_asym_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_height,
    int out_width,
    int kernel_h,
    int stride,
    int padding,
    int dilation) {

    // Grid mapping:
    // Block X: Output Width
    // Grid Y: Output Height
    // Grid Z: Batch * Channels (Flattened)

    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y;
    int nc_idx = blockIdx.z;

    if (w_out >= out_width || h_out >= out_height || nc_idx >= batch_size * channels) return;

    int n = nc_idx / channels;
    int c = nc_idx % channels;

    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c];
    }

    // Calculate offsets
    // Input layout: (N, C, H, W)
    int input_offset_base = (n * channels + c) * height * width;
    const float* input_ptr = input + input_offset_base;

    // Weight layout: (C, 1, K, 1) which is effectively (C, K) contiguous in memory
    const float* weight_ptr = weight + c * kernel_h;

    // Convolution loop
    // Kernel is (K, 1). We only iterate vertically.
    // Horizontal window size is 1.

    #pragma unroll
    for (int k = 0; k < kernel_h; ++k) {
        int h_in = h_out * stride + k * dilation - padding;

        // For width: kernel_w is 1.
        // Standard formula: w_in = w_out * stride + kw * dilation - padding
        // Here kw=0.
        int w_in = w_out * stride - padding;

        if (h_in >= 0 && h_in < height && w_in >= 0 && w_in < width) {
            sum += input_ptr[h_in * width + w_in] * weight_ptr[k];
        }
    }

    // Output layout: (N, C, H_out, W_out)
    int out_idx = (n * channels + c) * out_height * out_width + h_out * out_width + w_out;
    output[out_idx] = sum;
}

