__global__ void avg_pool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch, int channels, int in_h, int in_w,
    int out_h, int out_w,
    int kernel_size, int stride, int padding) {

    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int numel = batch * channels * out_h * out_w;

    if (idx < numel) {
        // Map linear index to output coordinates (n, c, h_out, w_out)
        int w_out = idx % out_w;
        int h_out = (idx / out_w) % out_h;
        int c = (idx / (out_w * out_h)) % channels;
        int n = idx / (out_w * out_h * channels);

        // Calculate the top-left corner of the pooling window in the input
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        float sum = 0.0f;

        // Iterate over the pooling kernel
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h_in = h_start + kh;
                int w_in = w_start + kw;

                // Check boundaries (padding implies implicit zeros)
                if (h_in >= 0 && h_in < in_h && w_in >= 0 && w_in < in_w) {
                    int in_idx = ((n * channels + c) * in_h + h_in) * in_w + w_in;
                    sum += input[in_idx];
                }
            }
        }

        // Standard AvgPool2d divides by the size of the kernel window
        output[idx] = sum / (float)(kernel_size * kernel_size);
    }
}

torch::Tensor avg_pool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding) {
