    input = input.contiguous();

    int batch = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    // Calculate output dimensions
    int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    // Allocate output tensor
    auto output = torch::empty({batch, channels, out_h, out_w}, input.options());

    int total_threads = batch * channels * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    // Launch the kernel
    avg_pool2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, channels, in_h, in_w,
        out_h, out_w,
        kernel_size, stride, padding
    );

    return output;
}
