import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code for GELU
# We implement both a scalar version and a vectorized (float4) version for performance.
gelu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// M_SQRT1_2 is 1/sqrt(2)
#ifndef M_SQRT1_2
#define M_SQRT1_2 0.70710678118654752440f
#endif

// Vectorized GELU kernel using float4 for memory coalescing and better bandwidth usage
// GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
__global__ void gelu_kernel_vec(const float* __restrict__ x, float* __restrict__ out, int n_vec) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n_vec) {
        // Load 4 float elements at once
        float4 v = reinterpret_cast<const float4*>(x)[idx];
        float4 r;

        // Compute GELU for each component
        r.x = 0.5f * v.x * (1.0f + erff(v.x * M_SQRT1_2));
        r.y = 0.5f * v.y * (1.0f + erff(v.y * M_SQRT1_2));
        r.z = 0.5f * v.z * (1.0f + erff(v.z * M_SQRT1_2));
        r.w = 0.5f * v.w * (1.0f + erff(v.w * M_SQRT1_2));

        reinterpret_cast<float4*>(out)[idx] = r;
    }
}

// Fallback scalar GELU kernel
__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float v = x[idx];
        out[idx] = 0.5f * v * (1.0f + erff(v * M_SQRT1_2));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    // Ensure the input tensor is contiguous in memory
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    auto size = x.numel();
    auto out = torch::empty_like(x);

    // Determine if we can use the vectorized float4 kernel
    // Requirements: size divisible by 4, and pointers aligned to 16 bytes
    bool vectorized = false;
    if (size % 4 == 0) {
        auto ptr_x = reinterpret_cast<uintptr_t>(x.data_ptr<float>());
        auto ptr_out = reinterpret_cast<uintptr_t>(out.data_ptr<float>());
        if (ptr_x % 16 == 0 && ptr_out % 16 == 0) {
            vectorized = true;
        }
    }

    const int block_size = 256;

    if (vectorized) {
        int n_vec = size / 4;
        const int num_blocks = (n_vec + block_size - 1) / block_size;
        gelu_kernel_vec<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), n_vec);
    } else {
        const int num_blocks = (size + block_size - 1) / block_size;
        gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    }

    return out;
}
"""

gelu_cpp_source = "torch::Tensor gelu_cuda(torch::Tensor x);"

# Compile the inline CUDA code
gelu_op = load_inline(
    name="gelu_op",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

