from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for RMS Normalization
rms_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void rms_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int N,
    int C,
    int S,
    float eps) {

    // Grid layout:
    // y dimension corresponds to the batch dimension (N)
    // x dimension covers the spatial dimension (S)
    int n = blockIdx.y;
    int s = blockIdx.x * blockDim.x + threadIdx.x;

    if (n < N && s < S) {
        // Calculate the base offset for the column corresponding to (n, s)
        // The data layout is (N, C, S) flattened.
        // We need to iterate over C.
        // base index = n * (C * S) + s
        // The c-th element is at base + c * S
        int base_offset = n * C * S + s;

        float sum_sq = 0.0f;

        // First pass: Calculate sum of squares
        // Access pattern: x[base + c*S]. 
        // Adjacent threads (s, s+1) access x[base + c*S] and x[base+1 + c*S].
        // This is a unit-stride access pattern (coalesced) for each c.
        for (int c = 0; c < C; ++c) {
            float val = x[base_offset + c * S];
            sum_sq += val * val;
        }

        // Calculate RMS
        float rms = rsqrtf((sum_sq / C) + eps);

        // Second pass: Normalize and store
        for (int c = 0; c < C; ++c) {
            out[base_offset + c * S] = x[base_offset + c * S] * rms;
        }
    }
}

torch::Tensor rms_norm_cuda(torch::Tensor x, float eps) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");

    // Assume input shape is (N, C, ...)
    int N = x.size(0);
    int C = x.size(1);
    // Combine all remaining dimensions into spatial dimension S
    int S = x.numel() / (N * C);

    auto out = torch::empty_like(x);

    const int block_size = 256;
    dim3 dim_block(block_size);
    // Grid y is N, Grid x covers S
    dim3 dim_grid((S + block_size - 1) / block_size, N);

    rms_norm_kernel<<<dim_grid, dim_block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, S, eps
    );

    return out;
}
"""

rms_norm_cpp_source = "torch::Tensor rms_norm_cuda(torch::Tensor x, float eps);"

# Compile the inline CUDA code
rms_norm_op = load_inline(
    name="rms_norm_op",
    cpp_sources=rms_norm_cpp_source,
    cuda_sources=rms_norm_source,
    functions=["rms_norm_cuda"],
    verbose=False,
)

