# Define the custom CUDA kernel for 3x3 convolution
# This kernel is specialized for kernel_size=3, stride=1, padding=0, dilation=1, groups=1
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_3x3_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int B, int IC, int H, int W, int OC, int H_out, int W_out) 
{
    // Output spatial coordinates mapped to thread/block
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;

    // Batch and Output Channel are handled by the z-dimension of the grid
    int z_idx = blockIdx.z; 
    int oc = z_idx % OC;
    int b = z_idx / OC;

    // Boundary checks
    if (b < B && oc < OC && h_out < H_out && w_out < W_out) {
        float val = 0.0f;

        // Pre-calculate base offsets
        int input_batch_offset = b * (IC * H * W);
        int weight_oc_offset = oc * (IC * 9);

        // Loop over input channels
        for (int ic = 0; ic < IC; ++ic) {
            int input_ic_offset = input_batch_offset + ic * (H * W);
            int weight_ic_offset = weight_oc_offset + ic * 9;

            // Unrolled 3x3 convolution loop
            // Access pattern: input[b, ic, h+i, w+j] * weight[oc, ic, i, j]

            // Row 0
            val += input[input_ic_offset + (h_out + 0) * W + (w_out + 0)] * weight[weight_ic_offset + 0];
            val += input[input_ic_offset + (h_out + 0) * W + (w_out + 1)] * weight[weight_ic_offset + 1];
            val += input[input_ic_offset + (h_out + 0) * W + (w_out + 2)] * weight[weight_ic_offset + 2];

            // Row 1
            val += input[input_ic_offset + (h_out + 1) * W + (w_out + 0)] * weight[weight_ic_offset + 3];
            val += input[input_ic_offset + (h_out + 1) * W + (w_out + 1)] * weight[weight_ic_offset + 4];
            val += input[input_ic_offset + (h_out + 1) * W + (w_out + 2)] * weight[weight_ic_offset + 5];

            // Row 2
            val += input[input_ic_offset + (h_out + 2) * W + (w_out + 0)] * weight[weight_ic_offset + 6];
            val += input[input_ic_offset + (h_out + 2) * W + (w_out + 1)] * weight[weight_ic_offset + 7];
            val += input[input_ic_offset + (h_out + 2) * W + (w_out + 2)] * weight[weight_ic_offset + 8];
        }

        // Write result to global memory
        int output_idx = b * (OC * H_out * W_out) + oc * (H_out * W_out) + h_out * W_out + w_out;
        output[output_idx] = val;
    }
}

torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight) {
