    int W_out = W - K + 1;

    auto output = torch::zeros({B, OC, H_out, W_out}, input.options());

    // Configure Kernel
    dim3 block(16, 16);
    dim3 grid((W_out + block.x - 1) / block.x, 
              (H_out + block.y - 1) / block.y, 
              B * OC);

    conv2d_3x3_kernel<<<grid, block>>>(
        input.contiguous().data_ptr<float>(),
        weight.contiguous().data_ptr<float>(),
        output.data_ptr<float>(),
        B, IC, H, W, OC, H_out, W_out
    );

    return output;
