import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for masked cumulative sum
masked_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void masked_cumsum_kernel(
    const float* __restrict__ x, 
    const bool* __restrict__ mask, 
    float* __restrict__ out, 
    int rows, 
    int cols) 
{
    // Each block processes one row.
    // gridDim.x = rows, blockDim.x = 256 (or similar)
    int row = blockIdx.x;
    if (row >= rows) return;

    int row_offset = row * cols;
    float current_sum = 0.0f;

    // Shared memory to store the reduction results of each warp.
    // Assuming block size <= 1024, we have max 32 warps.
    __shared__ float warp_sums[32]; 

    // Loop over the row in chunks of blockDim.x
    for (int col_base = 0; col_base < cols; col_base += blockDim.x) {
        int idx_in_block = threadIdx.x;
        int col = col_base + idx_in_block;

        // 1. Load data and apply mask on the fly
        float val = 0.0f;
        if (col < cols) {
            val = x[row_offset + col];
            if (!mask[row_offset + col]) {
                val = 0.0f;
            }
        }

        // 2. Warp-level inclusive scan using shuffle instructions
        unsigned int active_mask = 0xffffffff;
        for (int offset = 1; offset < 32; offset *= 2) {
            float n = __shfl_up_sync(active_mask, val, offset);
            if ((idx_in_block % 32) >= offset) {
                val += n;
            }
        }

        // 3. Store the inclusive sum of each warp into shared memory
        int warp_id = idx_in_block / 32;
        int lane_id = idx_in_block % 32;
        if (lane_id == 31) {
            warp_sums[warp_id] = val;
        }
        __syncthreads();

        // 4. Scan the warp sums (performed by the first warp only)
        // There are blockDim.x / 32 items in warp_sums
        if (warp_id == 0) {
            float w_val = (lane_id < (blockDim.x / 32)) ? warp_sums[lane_id] : 0.0f;
            for (int offset = 1; offset < 32; offset *= 2) {
                float n = __shfl_up_sync(active_mask, w_val, offset);
                if (lane_id >= offset) w_val += n;
            }
            if (lane_id < (blockDim.x / 32)) {
                warp_sums[lane_id] = w_val;
            }
        }
        __syncthreads();

        // 5. Add the base from the previous warp to each element within a warp
        float block_val = val;
        if (warp_id > 0) {
            block_val += warp_sums[warp_id - 1];
        }

        // 6. Add the running sum from previous chunks
        block_val += current_sum;

        // 7. Store result to global memory
        if (col < cols) {
            out[row_offset + col] = block_val;
        }

        // 8. Update current_sum with the total sum of this chunk for the next iteration
        // The last element of warp_sums (after scan in step 4) contains the total sum of this chunk
        current_sum += warp_sums[(blockDim.x / 32) - 1];

        __syncthreads();
    }
}

torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int dim) {
    // Ensure inputs are contiguous
    if (!x.is_contiguous()) x = x.contiguous();
