#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int d_in, int h_in, int w_in,
    int d_out, int h_out, int w_out,
    int k_d, int k_h, int k_w,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups) {

    // Flattened index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * d_out * h_out * w_out;

    if (idx >= total_elements) return;

    // Decode index to (n, oc, od, oh, ow)
    // Layout: N, C, D, H, W
    int tmp = idx;
    int ow = tmp % w_out; tmp /= w_out;
    int oh = tmp % h_out; tmp /= h_out;
    int od = tmp % d_out; tmp /= d_out;
    int oc = tmp % out_channels; tmp /= out_channels;
    int n = tmp;

    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[oc];
    }

    // Group logic
    int out_group_size = out_channels / groups;
    int in_group_size = in_channels / groups;
    int g_idx = oc / out_group_size;
    int oc_in_group = oc % out_group_size;

    // Input channels corresponding to this output group
    int ic_start = g_idx * in_group_size;
    int ic_end = ic_start + in_group_size;

    // Pre-calculate weight stride factors
    // Weight shape: (in_channels, out_channels/groups, k_d, k_h, k_w)
    int w_stride_ic = out_group_size * k_d * k_h * k_w;
    int w_stride_oc = k_d * k_h * k_w;
    int w_stride_kd = k_h * k_w;
    int w_stride_kh = k_w;

    // Calculate loop bounds for input spatial dims
    // Relation: od = id * stride - pad + k
    // id * stride = od + pad - k
    // Since 0 <= k < k_d, we search for valid ids.

    // Min id: when k is max (k_d-1) => id >= ceil((od + pad - k_d + 1) / stride)
    int start_id = (od + pad_d - (k_d - 1) + stride_d - 1) / stride_d;
    if (start_id < 0) start_id = 0;

    // Max id: when k is min (0) => id <= floor((od + pad) / stride)
    int end_id = (od + pad_d) / stride_d;
    if (end_id >= d_in) end_id = d_in - 1;

    int start_ih = (oh + pad_h - (k_h - 1) + stride_h - 1) / stride_h;
    if (start_ih < 0) start_ih = 0;
    int end_ih = (oh + pad_h) / stride_h;
    if (end_ih >= h_in) end_ih = h_in - 1;

    int start_iw = (ow + pad_w - (k_w - 1) + stride_w - 1) / stride_w;
    if (start_iw < 0) start_iw = 0;
    int end_iw = (ow + pad_w) / stride_w;
    if (end_iw >= w_in) end_iw = w_in - 1;

    // Input stride factors
    long long in_stride_n = (long long)in_channels * d_in * h_in * w_in;
    long long in_stride_c = d_in * h_in * w_in;
    long long in_stride_d = h_in * w_in;
    long long in_stride_h = w_in;

    long long input_base = n * in_stride_n;

    for (int id = start_id; id <= end_id; ++id) {
        int kd_idx = od + pad_d - id * stride_d;

        for (int ih = start_ih; ih <= end_ih; ++ih) {
            int kh_idx = oh + pad_h - ih * stride_h;

            for (int iw = start_iw; iw <= end_iw; ++iw) {
                int kw_idx = ow + pad_w - iw * stride_w;

                int weight_spatial_offset = kd_idx * w_stride_kd + kh_idx * w_stride_kh + kw_idx;

                for (int ic = ic_start; ic < ic_end; ++ic) {
                    long long in_idx = input_base + (long long)ic * in_stride_c + (long long)id * in_stride_d + ih * in_stride_h + iw;

                    int w_idx = ic * w_stride_ic + oc_in_group * w_stride_oc + weight_spatial_offset;

                    sum += input[in_idx] * weight[w_idx];
                }
            }
        }
    }

    output[idx] = sum;
}

