import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 3D Transposed Convolution
# This kernel implements a "gather" approach where each thread computes one output pixel
# by summing contributions from relevant input pixels and weights.
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int opad_d, int opad_h, int opad_w) {

    // Calculate total number of output elements
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_d * out_h * out_w;

    if (idx < total_elements) {
        // Decode linear index to (n, co, oz, oy, ox)
        // Tensor layout is (N, C, D, H, W)
        int tmp = idx;
        int ox = tmp % out_w; tmp /= out_w;
        int oy = tmp % out_h; tmp /= out_h;
        int oz = tmp % out_d; tmp /= out_d;
        int co = tmp % out_channels; tmp /= out_channels;
        int n = tmp;

        // Initialize accumulator with bias if present
        float sum = (bias != nullptr) ? bias[co] : 0.0f;

        // The convolution transpose operation can be viewed as a direct convolution 
        // if we map output coordinates back to input coordinates.
        // Relationship: out_coord = in_coord * stride + kernel_coord - padding
        // Inverse: in_coord = (out_coord + padding - kernel_coord) / stride
        // We iterate over the kernel dimensions and check if the mapped input coordinate is valid.

        // Precompute base offsets for efficiency
        int input_batch_offset = n * (in_channels * in_d * in_h * in_w);

        // Loop over input channels
        for (int ci = 0; ci < in_channels; ++ci) {

            // Weight layout for ConvTranspose3d (groups=1): (in_channels, out_channels, k_d, k_h, k_w)
            int weight_base = ((ci * out_channels + co) * k_d * k_h * k_w);
            int input_channel_offset = input_batch_offset + ci * (in_d * in_h * in_w);

            for (int kz = 0; kz < k_d; ++kz) {
                int dist_z = oz + pad_d - kz;
                // Check if this kernel position corresponds to a valid strided input
                if (dist_z % stride_d == 0) {
                    int iz = dist_z / stride_d;
                    if (iz >= 0 && iz < in_d) {

                        for (int ky = 0; ky < k_h; ++ky) {
                            int dist_y = oy + pad_h - ky;
                            if (dist_y % stride_h == 0) {
                                int iy = dist_y / stride_h;
                                if (iy >= 0 && iy < in_h) {

                                    for (int kx = 0; kx < k_w; ++kx) {
                                        int dist_x = ox + pad_w - kx;
                                        if (dist_x % stride_w == 0) {
                                            int ix = dist_x / stride_w;
                                            if (ix >= 0 && ix < in_w) {

                                                int input_idx = input_channel_offset + iz * (in_h * in_w) + iy * in_w + ix;
                                                int weight_idx = weight_base + kz * (k_h * k_w) + ky * k_w + kx;

                                                sum += input[input_idx] * weight[weight_idx];
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv_transpose3d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    std::vector<int> stride,
    std::vector<int> padding,
    std::vector<int> output_padding,
    int groups) {

    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    if (bias.defined()) {
        TORCH_CHECK(bias.is_cuda(), "Bias must be a CUDA tensor");
    }
    TORCH_CHECK(groups == 1, "Custom kernel currently supports groups=1 only");

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_d = input.size(2);
