import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Transposed Convolution
conv_transpose_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int k_h, int k_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w) {

    // Grid Mapping:
    // x: Output Width
    // y: Output Height
    // z: Batch * Out_Channels

    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int b_c = blockIdx.z;

    if (w_out >= out_w || h_out >= out_h || b_c >= batch_size * out_channels) {
        return;
    }

    int c_out = b_c % out_channels;
    int b = b_c / out_channels;

    float val = (bias != nullptr) ? bias[c_out] : 0.0f;

    // Transposed Convolution Logic (Output-centric):
    // Standard Conv: out[h_out] = sum(in[h_in] * w[k]) where h_out = h_in * stride - pad + k
    // Transposed Conv: The relationship is inverted.
    // h_out = h_in * stride + k - pad
    // Therefore, for a fixed h_out, we sum over valid h_in and k.
    // h_in = (h_out + pad - k) / stride

    // Weight Tensor Shape in PyTorch ConvTranspose2d: [in_channels, out_channels, k_h, k_w]
    // (Assuming groups=1)

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kh = 0; kh < k_h; ++kh) {
            int h_numerator = h_out + pad_h - kh;

            // Check if h_numerator is non-negative and divisible by stride (valid input pixel exists)
            if (h_numerator >= 0 && h_numerator % stride_h == 0) {
                int h_in = h_numerator / stride_h;

                if (h_in < in_h) {
                    for (int kw = 0; kw < k_w; ++kw) {
                        int w_numerator = w_out + pad_w - kw;

                        if (w_numerator >= 0 && w_numerator % stride_w == 0) {
                            int w_in = w_numerator / stride_w;

                            if (w_in < in_w) {
                                // Calculate flat indices
                                int in_idx = ((b * in_channels + ic) * in_h + h_in) * in_w + w_in;
                                int w_idx = ((ic * out_channels + c_out) * k_h + kh) * k_w + kw;

                                val += input[in_idx] * weight[w_idx];
                            }
                        }
                    }
                }
            }
        }
    }

    int out_idx = ((b * out_channels + c_out) * out_h + h_out) * out_w + w_out;
    output[out_idx] = val;
}

torch::Tensor conv_transpose2d_cuda_func(
    torch::Tensor input, 
    torch::Tensor weight, 
    torch::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w) {

    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto in_h = input.size(2);
    const auto in_w = input.size(3);

    // PyTorch ConvTranspose2d weight shape: [in_channels, out_channels/groups, k_h, k_w]
    // Assuming groups=1 for this architecture
    const auto out_channels = weight.size(1); 
    const auto k_h = weight.size(2);
    const auto k_w = weight.size(3);

    // Output Height/Width calculation for Transposed Conv
    // H_out = (H_in - 1) * stride - 2 * padding + dilation * (kernel - 1) + output_padding + 1
    // Dilation=1, output_padding=0 (defaults for the provided Model)
    auto out_h = (in_h - 1) * stride_h - 2 * pad_h + (k_h - 1) + 1;
    auto out_w = (in_w - 1) * stride_w - 2 * pad_w + (k_w - 1) + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<float>();
    }

    // Configure Grid and Block
    // Threads map to spatial output dimensions
    dim3 block_size(16, 16, 1);
    dim3 grid_size(
        (out_w + block_size.x - 1) / block_size.x,
        (out_h + block_size.y - 1) / block_size.y,
        batch_size * out_channels
    );

    conv_transpose2d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, out_h, out_w,
        k_h, k_w,
