import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Tiled Matrix Multiplication (C = A.T @ B)
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TS 32

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    // Inputs:
    // A: shape (K, M), stored row-major. We treat it as A.T of shape (M, K) logically.
    // B: shape (K, N), stored row-major.
    // C: shape (M, N), stored row-major.

    // We compute C = A.T * B
    // Equivalent to: C[m, n] = sum_k (A[k, m] * B[k, n])

    // Grid configuration:
    // x dimension -> N (columns of C)
    // y dimension -> M (rows of C)

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // The starting row (M-dimension) and col (N-dimension) for this block
    int row_start = by * TS;
    int col_start = bx * TS;

    // Global coordinates for the result element computed by this thread
    int row = row_start + ty;
    int col = col_start + tx;

    // Shared memory for tiles
    __shared__ float sA[TS][TS];
    __shared__ float sB[TS][TS];

    float sum = 0.0f;

    // Loop over the K dimension in chunks of TS
    for (int k = 0; k < K; k += TS) {
        // Cooperative loading of tiles into shared memory

        // Load tile from A
        // We need A rows k..k+TS and cols row_start..row_start+TS
        // A is (K, M). Access: A[row_idx, col_idx]
        // We use (ty, tx) to map threads to the tile 1:1.
        // To ensure coalesced access, the inner dimension (M) should vary with tx.
        // A_index = (k + ty) * M + (row_start + tx)
        sA[ty][tx] = A[(k + ty) * M + (row_start + tx)];

        // Load tile from B
        // We need B rows k..k+TS and cols col_start..col_start+TS
        // B is (K, N). Access: B[row_idx, col_idx]
        // Coalesced access: inner dimension (N) varies with tx.
        // B_index = (k + ty) * N + (col_start + tx)
        sB[ty][tx] = B[(k + ty) * N + (col_start + tx)];

        // Ensure data is loaded
        __syncthreads();

        // Compute partial dot product for this tile
        // sum += A[k+kk, row] * B[k+kk, col]
        // In shared memory sA:
        //   We loaded A[k+r, row_start+c] into sA[r][c]
        //   We need value at global row (k+kk) and global col (row_start+ty) -> sA[kk][ty]
        // In shared memory sB:
        //   We loaded B[k+r, col_start+c] into sB[r][c]
        //   We need value at global row (k+kk) and global col (col_start+tx) -> sB[kk][tx]

        #pragma unroll
        for (int kk = 0; kk < TS; ++kk) {
            sum += sA[kk][ty] * sB[kk][tx];
        }

        // Ensure computation is done before reloading shared memory
        __syncthreads();
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A is (K, M)
    // B is (K, N)
    // Returns C (M, N)

    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    // Block size 32x32 = 1024 threads
    dim3 block(32, 32);
    // Grid covers M and N
    dim3 grid((N + 31) / 32, (M + 31) / 32);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
matmul_op = load_inline(
    name="matmul_op",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A^T * B) using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication A.T @ B using custom CUDA kernel.
        """
        return self.matmul_op.matmul_cuda(A, B)

