#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int k_h,
    int k_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w,
    int groups,
    bool use_bias
) {
    // One thread per output pixel
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_h * out_w;

    if (idx < total_elements) {
        // Decompose linear index to (n, oc, oh, ow)
        int temp = idx;
        int ow = temp % out_w; temp /= out_w;
        int oh = temp % out_h; temp /= out_h;
        int oc = temp % out_channels; temp /= out_channels;
        int n = temp;

        // Group parameters
        // PyTorch ConvTranspose2d weight shape: (in_channels, out_channels/groups, kH, kW)
        // Groups partition both input and output channels.
        int out_channels_per_group = out_channels / groups;
        int in_channels_per_group = in_channels / groups;

        int group_id = oc / out_channels_per_group;
        int oc_in_group = oc % out_channels_per_group;

        // Start accumulator with bias if present
        float sum = 0.0f;
        if (use_bias && bias != nullptr) {
            sum = bias[oc];
        }

        // Transposed Convolution Logic:
        // Instead of iterating input region (like Conv2d), we iterate kernel dimensions (kh, kw)
        // and reverse map to find the input pixel (ih, iw) that contributes to (oh, ow).
        // Forward mapping: oh = ih * stride - pad + kh * dilation
        // Reverse mapping: ih * stride = oh + pad - kh * dilation

        for (int kh = 0; kh < k_h; ++kh) {
            for (int kw = 0; kw < k_w; ++kw) {

                int num_h = oh + pad_h - kh * dil_h;
                int num_w = ow + pad_w - kw * dil_w;

                // Check if the calculated spatial position is valid and lands on a strided input pixel
                if (num_h >= 0 && num_w >= 0) {
                    if (num_h % stride_h == 0 && num_w % stride_w == 0) {
                        int ih = num_h / stride_h;
                        int iw = num_w / stride_w;

                        // Check input boundaries
                        if (ih < in_h && iw < in_w) {
                            // Sum over all input channels associated with this group
                            int ic_start = group_id * in_channels_per_group;

                            for (int i = 0; i < in_channels_per_group; ++i) {
                                int ic = ic_start + i;

                                // Input Linear Index: (n, ic, ih, iw)
                                int input_idx = ((n * in_channels + ic) * in_h + ih) * in_w + iw;

                                // Weight Linear Index: (ic, oc_in_group, kh, kw)
                                // Note: PyTorch ConvTranspose2d stores weights as [in_channels, out_channels/groups, kH, kW]
                                int weight_idx = ((ic * out_channels_per_group + oc_in_group) * k_h + kh) * k_w + kw;

                                sum += input[input_idx] * weight[weight_idx];
                            }
                        }
                    }
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
