    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    // weight shape: [in_channels, out_channels/groups, kH, kW]
    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int k_h = weight.size(2);
    int k_w = weight.size(3);

    // Calculate Output Dimensions
    // H_out = (H_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1
    // (Assuming output_padding is 0 as per prompt architecture)
    int out_h = (in_h - 1) * stride_h - 2 * pad_h + dil_h * (k_h - 1) + 1;
