import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Lower Triangular Matrix Multiplication
# This kernel optimizes the matrix multiplication A * B where both A and B are lower triangular.
# It uses shared memory tiling and skips computations for tiles that are known to be zero based on the triangular structure.
# The computational complexity is reduced from O(N^3) to roughly O(N^3/6).
tril_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void tril_matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    // Grid indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Local indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and col
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // If the block is strictly in the upper triangle (bx > by), the result is 0.
    // For the product of two lower triangular matrices, the result is lower triangular.
    // An output block (by, bx) is in the upper triangle if col_start > row_start, i.e., bx > by.
    if (bx > by) {
        if (row < N && col < N) {
            C[row * N + col] = 0.0f;
        }
        return;
    }

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float val = 0.0f;

    // Iterate over tiles.
    // Standard MatMul: m goes from 0 to (N-1)/TILE_SIZE.
    // Optimized for Lower Triangular A and B:
    // A is lower triangular -> A[row, k] != 0 only if k <= row. Block-wise: valid tiles are m <= by.
    // B is lower triangular -> B[k, col] != 0 only if k >= col. Block-wise: valid tiles are m >= bx.
    // So we only need to iterate m from bx to by.

    int m_start = bx;
    int m_end = by;

    for (int m = m_start; m <= m_end; ++m) {
        // Load tile from A
        int a_col = m * TILE_SIZE + tx;
        if (row < N && a_col < N)
            As[ty][tx] = A[row * N + a_col];
        else
            As[ty][tx] = 0.0f;

        // Load tile from B
        int b_row = m * TILE_SIZE + ty;
        if (b_row < N && col < N)
            Bs[ty][tx] = B[b_row * N + col];
        else
            Bs[ty][tx] = 0.0f;

        __syncthreads();

        // Compute partial dot product
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            val += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        // Mask upper triangle elements within the diagonal blocks (where bx == by)
        if (col > row) {
            val = 0.0f;
        }
        C[row * N + col] = val;
    }
}

torch::Tensor tril_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    tril_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

tril_matmul_cpp_source = "torch::Tensor tril_matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
tril_matmul_op = load_inline(
    name="tril_matmul_op",
    cpp_sources=tril_matmul_cpp_source,
    cuda_sources=tril_matmul_source,
    functions=["tril_matmul_cuda"],
    verbose=True,
    extra_cflags=['-O3'],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) where A and B are lower triangular matrices
    using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.tril_matmul_op = tril_matmul_op

