    // x: Output Length (tiled)
    // y: Output Channels
    // z: Batch Size

    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y;
    int n = blockIdx.z;

    // Bounds check
    if (l_out >= length_out || c_out >= out_channels || n >= batch_size) return;

    // Initialize accumulator with bias if present
    float val = (bias != nullptr) ? bias[c_out] : 0.0f;

    // Calculate base pointers for input (specific batch) and weight (specific out channel)
    // Input Layout: (N, C_in, L_in)
    // Weight Layout: (C_out, C_in, K)

    const float* input_n = input + n * (in_channels * length_in);
    const float* weight_c = weight + c_out * (in_channels * kernel_size);

    // Compute convolution
    for (int c_in = 0; c_in < in_channels; ++c_in) {
        int input_c_offset = c_in * length_in;
        int weight_c_offset = c_in * kernel_size;

        #pragma unroll
        for (int k = 0; k < kernel_size; ++k) {
            int l_in = l_out * stride + k * dilation;

            // Check input boundary (valid padding 0)
            if (l_in >= 0 && l_in < length_in) {
                float x = input_n[input_c_offset + l_in];
                float w = weight_c[weight_c_offset + k];
                val += x * w;
            }
        }
    }

    // Write output
    // Output Layout: (N, C_out, L_out)
    int out_idx = n * (out_channels * length_out) + c_out * length_out + l_out;
    output[out_idx] = val;
