import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the specific matrix multiplication (A.T @ B.T)
# A is (K, M), B is (N, K)
# Result C is (M, N)
# C[m, n] = sum_k A[k, m] * B[n, k]
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BM 32
#define BN 32
#define BK 32

__global__ void matmul_transposed_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // Grid maps to Output (M, N)
    // blockIdx.y -> M dimension
    // blockIdx.x -> N dimension
    int by = blockIdx.y;
    int bx = blockIdx.x;

    // Thread maps to position in tile
    int ty = threadIdx.y;
    int tx = threadIdx.x;

    // Shared memory with padding to avoid bank conflicts
    __shared__ float sA[BK][BM + 1];
    __shared__ float sB[BN][BK + 1];

    float val = 0.0f;

    // Loop over the K dimension (inner dimension of the product)
    for (int k_idx = 0; k_idx < K; k_idx += BK) {

        // Linear thread index for loading data
        int tid = ty * blockDim.x + tx;

        // Load tile from A into sA
        // We need A[k..k+BK, m_blk..m_blk+BM]
        // In A (K, M), this corresponds to rows [k_idx..k_idx+BK] and cols [by*BM..]
        // Map threads to load this tile (BK x BM)
        int load_a_row = tid / BM; // 0..31
        int load_a_col = tid % BM; // 0..31

        if (load_a_row < BK && load_a_col < BM) {
            int global_k = k_idx + load_a_row;
            int global_m = by * BM + load_a_col;

            if (global_k < K && global_m < M)
                sA[load_a_row][load_a_col] = A[global_k * M + global_m];
            else
                sA[load_a_row][load_a_col] = 0.0f;
        }

        // Load tile from B into sB
        // We need B[n_blk..n_blk+BN, k..k+BK]
        // In B (N, K), this corresponds to rows [bx*BN..] and cols [k_idx..k_idx+BK]
        // Map threads to load this tile (BN x BK)
        int load_b_row = tid / BK; // 0..31
        int load_b_col = tid % BK; // 0..31

        if (load_b_row < BN && load_b_col < BK) {
            int global_n = bx * BN + load_b_row;
            int global_k = k_idx + load_b_col;

            if (global_n < N && global_k < K)
                sB[load_b_row][load_b_col] = B[global_n * K + global_k];
            else
                sB[load_b_row][load_b_col] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum for the tile
        // C[m, n] += sum_k(A[k, m] * B[n, k])
        // Corresponds to sA[k][m_local] * sB[n_local][k]
        // Our thread (ty, tx) corresponds to C[m_local=ty, n_local=tx]
        for (int k = 0; k < BK; ++k) {
            val += sA[k][ty] * sB[tx][k];
        }

        __syncthreads();
    }

    // Store result
    int global_m = by * BM + ty;
    int global_n = bx * BN + tx;

    if (global_m < M && global_n < N) {
        C[global_m * N + global_n] = val;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(0);
    int K_inner = B.size(1);

    TORCH_CHECK(K == K_inner, "Inner dimensions must match");

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(BN, BM);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    matmul_transposed_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, N, K
    );

    return C;
}
"""

matmul_cpp_source = "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B);"

custom_matmul = load_inline(
    name="custom_matmul",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["custom_matmul_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = custom_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication A.T @ B.T using custom CUDA kernel.
        Args:
            A: Input tensor of shape (K, M).
            B: Input tensor of shape (N, K).
        Returns:
            Output tensor of shape (M, N).
        """
        return self.matmul.custom_matmul_cuda(A, B)

