__global__ void conv3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_d, int in_h, int in_w,
    int k_d, int k_h, int k_w,
    int out_d, int out_h, int out_w,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int groups) {

    int total_elements = batch_size * out_channels * out_d * out_h * out_w;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Decompose linear index to (n, oc, od, oh, ow)
        int temp = idx;
        int ow = temp % out_w; temp /= out_w;
        int oh = temp % out_h; temp /= out_h;
        int od = temp % out_d; temp /= out_d;
        int oc = temp % out_channels; temp /= out_channels;
        int n = temp;

        float val = 0.0f;

        // Group handling
        int out_c_per_group = out_channels / groups;
        int in_c_per_group = in_channels / groups;
        int g = oc / out_c_per_group;
        int ic_start = g * in_c_per_group;

        // Base input spatial coordinates
        int id_base = od * stride_d - pad_d;
        int ih_base = oh * stride_h - pad_h;
        int iw_base = ow * stride_w - pad_w;

        // Convolution loop
        for (int ic_local = 0; ic_local < in_c_per_group; ++ic_local) {
            int ic = ic_start + ic_local;

            for (int kd = 0; kd < k_d; ++kd) {
                int id = id_base + kd * dil_d;
                if (id >= 0 && id < in_d) {
                    for (int kh = 0; kh < k_h; ++kh) {
                        int ih = ih_base + kh * dil_h;
                        if (ih >= 0 && ih < in_h) {
                            for (int kw = 0; kw < k_w; ++kw) {
                                int iw = iw_base + kw * dil_w;
