                                    // Flattened: oc * (in_c_per_group * k_d * k_h * k_w) + ...
                                    int w_idx = ((((oc * in_c_per_group + ic_local) * k_d + kd) * k_h + kh) * k_w) + kw;

                                    // Input layout: (N, C, D, H, W)
                                    int in_idx = ((((n * in_channels + ic) * in_d + id) * in_h + ih) * in_w) + iw;

                                    val += input[in_idx] * weight[w_idx];
