import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for cumulative product
# We implement a parallel scan (prefix product) kernel.
# Since the operation is independent per row (assuming we scan along the last dimension),
# we map each CUDA block to a row. 
# Within each block, we process the row in chunks (tiles) of size BLOCK_SIZE.
# We use a shared-memory based Hillis-Steele scan for each tile and carry the running product forward.

cumprod_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__global__ void cumprod_kernel(const float* __restrict__ x, float* __restrict__ out, int batch_size, int feature_size) {
    // Each block processes one independent row (or batch element)
    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Calculate pointers for the current row
    int row_offset = row * feature_size;
    const float* row_in = x + row_offset;
    float* row_out = out + row_offset;

    // Running product accumulator for the current row
    float running_prod = 1.0f;

    // Process the row in tiles of size BLOCK_SIZE
    for (int base = 0; base < feature_size; base += BLOCK_SIZE) {
        int tid = threadIdx.x;
        int idx = base + tid;

        // Load data into register (handle boundary conditions)
        float val = 1.0f;
        if (idx < feature_size) {
            val = row_in[idx];
        }

        // Shared memory for block-level scan
        __shared__ float sdata[BLOCK_SIZE];
        sdata[tid] = val;
        __syncthreads();

        // Perform inclusive scan in shared memory using Hillis-Steele algorithm
        #pragma unroll
        for (int stride = 1; stride < BLOCK_SIZE; stride *= 2) {
            float temp = 1.0f;
            if (tid >= stride) {
                temp = sdata[tid - stride];
            }
            __syncthreads(); // Barrier to ensure all threads have read
            if (tid >= stride) {
                sdata[tid] *= temp;
            }
            __syncthreads(); // Barrier to ensure all threads have updated
        }

        // Calculate final value for this element:
        // scan of current tile * product of all previous tiles
        float current_val = sdata[tid] * running_prod;

        // Write output
        if (idx < feature_size) {
            row_out[idx] = current_val;
        }

        // Update running_prod for the next tile.
        // The last element of sdata contains the inclusive product of the entire current tile.
        float tile_total = sdata[BLOCK_SIZE - 1];
        running_prod *= tile_total;

        // Ensure all threads are done with sdata before next iteration
        __syncthreads();
    }
}

torch::Tensor cumprod_cuda_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(x.dim() == 2, "Kernel expects flattened 2D input (Batch, Feature)");

    int batch_size = x.size(0);
    int feature_size = x.size(1);

    auto out = torch::empty_like(x);

    dim3 grid(batch_size);
    dim3 block(BLOCK_SIZE);

    cumprod_kernel<<<grid, block>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, feature_size);

    return out;
}
"""

cumprod_cpp_source = "torch::Tensor cumprod_cuda_forward(torch::Tensor x);"

# Compile the inline CUDA code
cumprod_op = load_inline(
    name="cumprod_cuda_op",
    cpp_sources=cumprod_cpp_source,
    cuda_sources=cumprod_source,
    functions=["cumprod_cuda_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim
        self.cumprod_op = cumprod_op

    def forward(self, x):
        # The custom kernel is optimized for scanning along the last dimension (contiguous memory).
        # We need to ensure the dimension we want to scan ('dim') is the last dimension.

        ndim = x.dim()
        # Handle negative dim indexing
        dim = self.dim if self.dim >= 0 else self.dim + ndim

        # Check if we need to transpose to put 'dim' at the end
        if dim != ndim - 1:
            # Create a permutation that swaps 'dim' with the last dimension
            perm = list(range(ndim))
            perm[dim], perm[-1] = perm[-1], perm[dim]
            x_perm = x.permute(perm).contiguous()
        else:
            x_perm = x.contiguous()

        # Flatten all batch dimensions into a single dimension to treat as (Batch, Length)
        input_shape = x_perm.shape
        feature_size = input_shape[-1]
        x_reshaped = x_perm.view(-1, feature_size)

        # Execute the custom CUDA kernel
        out_reshaped = self.cumprod_op.cumprod_cuda_forward(x_reshaped)

        # Reshape back to the permuted shape
        out_perm = out_reshaped.view(input_shape)

        # If we permuted the input, we must permute the output back to original order
        if dim != ndim - 1:
            perm = list(range(ndim))
            perm[dim], perm[-1] = perm[-1], perm[dim]
            out = out_perm.permute(perm)
        else:
            out = out_perm

        return out

