import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for L1 normalization
# The kernel performs a row-wise L1 normalization: x / mean(abs(x), dim=1)
# This involves:
# 1. Calculating the sum of absolute values for each row.
# 2. Computing the mean (sum / dim).
# 3. Scaling the input row by 1 / mean (or dim / sum).
# We fuse these steps into a single kernel to minimize memory bandwidth usage.

l1_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper for warp-level reduction
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) 
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void l1_normalize_kernel(const float* __restrict__ x, float* __restrict__ out, int rows, int cols) {
    int row_idx = blockIdx.x;
    if (row_idx >= rows) return;

    // Pointers to the start of the current row
    const float* row_in = x + row_idx * cols;
    float* row_out = out + row_idx * cols;

    float sum_abs = 0.0f;

    // Phase 1: Accumulate sum of absolute values
    // Each thread sums a subset of columns using a grid-stride loop
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        sum_abs += fabsf(row_in[i]);
    }

    // Phase 2: Reduction to find the total sum for the row

    // Step 2a: Warp-level reduction
    sum_abs = warpReduceSum(sum_abs);

    // Step 2b: Block-level reduction using shared memory
    // Shared memory to store partial sums from each warp
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    // The first thread of each warp writes the warp's sum to shared memory
    if (lane == 0) {
        shared[wid] = sum_abs;
    }

    __syncthreads();

    // Step 2c: Reduce the partial sums from shared memory (only one warp needed)
    float total_sum = 0.0f;
    if (threadIdx.x < 32) {
        int num_warps = (blockDim.x + 31) / 32;
        // Only load valid partial sums
        if (threadIdx.x < num_warps) {
            total_sum = shared[threadIdx.x];
        }
        total_sum = warpReduceSum(total_sum);
    }

    // Step 2d: Broadcast total sum to all threads in the block
    if (threadIdx.x == 0) shared[0] = total_sum;
    __syncthreads();

    float row_sum = shared[0];

    // Phase 3: Apply normalization and write output
    // The operation is x / (sum / N)  => x * (N / sum)
    // We compute the scaling factor once.

    // Handle potential division by zero (if row is all zeros, row_sum is 0). 
    // Standard float division by zero yields Inf, and 0 * Inf is NaN, which matches PyTorch behavior for 0/0.
    float scale = (float)cols / row_sum;

    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        row_out[i] = row_in[i] * scale;
    }
}

torch::Tensor l1_normalize_cuda(torch::Tensor x) {
    // Ensure input is contiguous for efficient memory access
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);

    int rows = x_contig.size(0);
    int cols = x_contig.size(1);

    // Launch one block per row
    // Block size of 256 is generally efficient for occupancy
    const int block_size = 256;
    dim3 grid(rows);
    dim3 block(block_size);

    l1_normalize_kernel<<<grid, block>>>(x_contig.data_ptr<float>(), out.data_ptr<float>(), rows, cols);

    return out;
}
"""

l1_norm_cpp_source = "torch::Tensor l1_normalize_cuda(torch::Tensor x);"

# Compile the inline CUDA code
l1_normalize = load_inline(
