import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Group Normalization
# Optimized using vectorized float4 memory access and block-level reductions.
gn_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector_types.h>

__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__inline__ __device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;

    __syncthreads();

    // Read from shared memory only if that warp existed
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0;

    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void group_norm_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int num_groups,
    int C_per_G,
    int HW,
    float epsilon) {

    // One block per (sample, group) instance
    // Total instances = batch_size * num_groups
    int instance_idx = blockIdx.x; 

    // Determine which group this is to select correct gamma/beta indices
    int g = instance_idx % num_groups;

    // Calculate memory offset
    int segment_len = C_per_G * HW;
    long long offset = (long long)instance_idx * segment_len;

    const float* x_ptr = input + offset;
    float* y_ptr = output + offset;

    // ---------------------------------------------------
    // 1. Statistics Phase: Calculate Mean and Variance
    // ---------------------------------------------------
    float sum = 0.0f;
    float sum_sq = 0.0f;

    // Interpret segment as array of float4 for vectorized load
    // Assumes HW is multiple of 4 (512*512=262144 is divisible by 4)
    int vec_len = segment_len / 4;
    const float4* x_vec_ptr = reinterpret_cast<const float4*>(x_ptr);

    for (int i = threadIdx.x; i < vec_len; i += blockDim.x) {
        float4 val = x_vec_ptr[i];
        sum += val.x + val.y + val.z + val.w;
        sum_sq += val.x*val.x + val.y*val.y + val.z*val.z + val.w*val.w;
    }

    // Reduction across the block
    sum = blockReduceSum(sum);
    sum_sq = blockReduceSum(sum_sq);

    __shared__ float s_mean;
    __shared__ float s_inv_std;

    if (threadIdx.x == 0) {
        float mean = sum / segment_len;
        float var = (sum_sq / segment_len) - (mean * mean);
        if (var < 0.0f) var = 0.0f;
        s_mean = mean;
        s_inv_std = rsqrtf(var + epsilon);
    }
    __syncthreads();

    float mean = s_mean;
    float inv_std = s_inv_std;

    // ---------------------------------------------------
    // 2. Normalization Phase: Apply Norm and Affine Transform
    // ---------------------------------------------------
    // We iterate channel-by-channel within the group because 
    // gamma and beta change per channel.

    int hw_vec = HW / 4; 
    float4* y_vec_ptr = reinterpret_cast<float4*>(y_ptr);

    for (int c_local = 0; c_local < C_per_G; c_local++) {
        // Calculate global channel index
        int c_global = g * C_per_G + c_local;

        float gamma = weight[c_global];
        float beta = bias[c_global];

        // Offset for this channel within the group segment (in float4 vectors)
        int c_offset_vec = c_local * hw_vec; 

        // Loop over spatial dimensions
        for (int i = threadIdx.x; i < hw_vec; i += blockDim.x) {
            int idx = c_offset_vec + i;
            float4 val = x_vec_ptr[idx];
            float4 out_val;

            // Apply normalization and affine transform
            out_val.x = (val.x - mean) * inv_std * gamma + beta;
            out_val.y = (val.y - mean) * inv_std * gamma + beta;
            out_val.z = (val.z - mean) * inv_std * gamma + beta;
            out_val.w = (val.w - mean) * inv_std * gamma + beta;

            y_vec_ptr[idx] = out_val;
        }
    }
}

torch::Tensor group_norm_cuda(torch::Tensor input, int num_groups, torch::Tensor weight, torch::Tensor bias, float eps) {
    const auto batch_size = input.size(0);
    const auto num_channels = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);
    const auto HW = H * W;
    const auto C_per_G = num_channels / num_groups;

    auto output = torch::empty_like(input);

    const int blocks = batch_size * num_groups;
    const int threads = 256; 

    // Enforce contiguous memory for valid reinterpret_cast to float4
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    group_norm_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        num_groups,
        C_per_G,
        HW,
        eps
    );

    return output;
}
"""

gn_cpp_source = "torch::Tensor group_norm_cuda(torch::Tensor input, int num_groups, torch::Tensor weight, torch::Tensor bias, float eps);"

# Compile and load the custom kernel
gn_op = load_inline(
    name="group_norm_op",
    cpp_sources=gn_cpp_source,
    cuda_sources=gn_cuda_source,
    functions=["group_norm_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized Model with custom CUDA Group Normalization.
    """
    def __init__(self, num_features: int, num_groups: int):
        super(ModelNew, self).__init__()
        self.num_groups = num_groups
        self.num_features = num_features
        self.eps = 1e-5

        # Initialize parameters consistent with nn.GroupNorm defaults
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.gn_op = gn_op

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is on CUDA for the kernel
        if not x.is_cuda:
            x = x.cuda()

        return self.gn_op.group_norm_cuda(x, self.num_groups, self.weight, self.bias, self.eps)

