import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 2D convolution
conv2d_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int k_h,
    int k_w,
    int s_h,
    int s_w,
    int p_h,
    int p_w,
    int d_h,
    int d_w,
    int out_h,
    int out_w) {

    // Grid Mapping:
    // z: batch_idx * out_channels + out_channel_idx
    // y: height output blocks
    // x: width output blocks

    int b_k = blockIdx.z;
    int n = b_k / out_channels;
    int k = b_k % out_channels;

    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (h_out < out_h && w_out < out_w) {
        float val = 0.0f;

        // Pointers to the specific batch and output channel
        // Input: (N, C, H, W)
        // Weight: (K, C, KH, KW)

        int input_batch_offset = n * in_channels * in_h * in_w;
        int weight_out_offset = k * in_channels * k_h * k_w;

        for (int c = 0; c < in_channels; ++c) {
            int input_channel_offset = input_batch_offset + c * in_h * in_w;
            int weight_channel_offset = weight_out_offset + c * k_h * k_w;

            for (int i = 0; i < k_h; ++i) {
                int h_in = h_out * s_h - p_h + i * d_h;

                // Boundary check for H
                if (h_in >= 0 && h_in < in_h) {
                    for (int j = 0; j < k_w; ++j) {
                        int w_in = w_out * s_w - p_w + j * d_w;

                        // Boundary check for W
                        if (w_in >= 0 && w_in < in_w) {
                            val += input[input_channel_offset + h_in * in_w + w_in] * 
                                   weight[weight_channel_offset + i * k_w + j];
                        }
                    }
                }
            }
        }

        if (bias != nullptr) {
            val += bias[k];
        }

        // Output: (N, K, H_out, W_out)
        int out_idx = n * out_channels * out_h * out_w + 
                      k * out_h * out_w + 
                      h_out * out_w + 
                      w_out;
        output[out_idx] = val;
    }
}

torch::Tensor conv2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int s_h, int s_w,
    int p_h, int p_w,
    int d_h, int d_w) {

    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);

    const int out_channels = weight.size(0);
    const int k_h = weight.size(2);
    const int k_w = weight.size(3);

    const int out_h = (in_h + 2 * p_h - d_h * (k_h - 1) - 1) / s_h + 1;
    const int out_w = (in_w + 2 * p_w - d_w * (k_w - 1) - 1) / s_w + 1;

    auto output = torch::empty({batch_size, out_channels, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<float>();
    }

    dim3 block_dim(16, 16);
    dim3 grid_dim(
        (out_w + block_dim.x - 1) / block_dim.x,
        (out_h + block_dim.y - 1) / block_dim.y,
        batch_size * out_channels
    );

    conv2d_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, k_h, k_w,
        s_h, s_w, p_h, p_w,
        d_h, d_w,
        out_h, out_w
    );

    return output;
}
"""

conv2d_cpp_source = (
    "torch::Tensor conv2d_cuda_forward("
    "torch::Tensor input, "
    "torch::Tensor weight, "
    "torch::optional<torch::Tensor> bias, "
    "int s_h, int s_w, "
    "int p_h, int p_w, "
    "int d_h, int d_w);"
)

# Compile the inline CUDA code
custom_conv2d = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_cuda_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # We rely on nn.Conv2d to handle parameter initialization and storage
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

        # Ensure stride, padding, dilation are tuples
        self.stride = stride if isinstance(stride, tuple) else (stride, stride)
        self.padding = padding if isinstance(padding, tuple) else (padding, padding)
        self.dilation = dilation if isinstance(dilation, tuple) else (dilation, dilation)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Call the custom CUDA kernel
        return custom_conv2d.conv2d_cuda_forward(
            x, 
            self.conv2d.weight, 
            self.conv2d.bias, 
            self.stride[0], self.stride[1],
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1]
        )

