import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 3D Average Pooling
avg_pool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm>

__global__ void avg_pool3d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch,
    const int channels,
    const int in_d, const int in_h, const int in_w,
    const int out_d, const int out_h, const int out_w,
    const int k,
    const int s,
    const int p,
    const int numel) 
{
    // Linear index for the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < numel) {
        // Decompose linear index into (n, c, od, oh, ow)
        // Output layout: N, C, D_out, H_out, W_out
        int temp = idx;
        int w_idx = temp % out_w;
        temp /= out_w;
        int h_idx = temp % out_h;
        temp /= out_h;
        int d_idx = temp % out_d;
        temp /= out_d;
        int c_idx = temp % channels;
        int n_idx = temp / channels;

        // Calculate the top-left-front corner of the pooling window in input coordinates
        int id_start = d_idx * s - p;
        int ih_start = h_idx * s - p;
        int iw_start = w_idx * s - p;

        // Determine loop bounds to ensure we stay within input dimensions
        // This avoids conditional checks inside the inner loops
        int z_start = max(0, -id_start);
        int z_end = min(k, in_d - id_start);
        int y_start = max(0, -ih_start);
        int y_end = min(k, in_h - ih_start);
        int x_start = max(0, -iw_start);
        int x_end = min(k, in_w - iw_start);

        float sum = 0.0f;

        // Compute base offset for the current batch and channel
        // Use long long to prevent overflow for large tensors (indices > 2^31)
        long long nc_offset = ((long long)n_idx * channels + c_idx) * ((long long)in_d * in_h * in_w);

        // Iterate over the valid valid window area
        for (int z = z_start; z < z_end; ++z) {
            long long d_offset = (long long)(id_start + z) * in_h;
            for (int y = y_start; y < y_end; ++y) {
                long long h_offset = (d_offset + (ih_start + y)) * in_w;
                for (int x = x_start; x < x_end; ++x) {
                    sum += input[nc_offset + h_offset + (iw_start + x)];
                }
            }
        }

        // Standard AvgPool3d behavior: divide by kernel_size^3 (count_include_pad=True)
        output[idx] = sum / (k * k * k);
    }
}

torch::Tensor avg_pool3d_cuda_forward(torch::Tensor input, int kernel_size, int stride, int padding) {
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(input.dim() == 5, "Input must be 5D (N, C, D, H, W)");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_d = input.size(2);
    int in_h = input.size(3);
    int in_w = input.size(4);

    // Calculate output dimensions
    int out_d = (in_d + 2 * padding - kernel_size) / stride + 1;
    int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    if (out_d <= 0 || out_h <= 0 || out_w <= 0) {
        return torch::empty({batch_size, channels, 0, 0, 0}, input.options());
    }

    auto output = torch::empty({batch_size, channels, out_d, out_h, out_w}, input.options());

    int numel = output.numel();

    if (numel == 0) {
        return output;
    }

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    avg_pool3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        kernel_size, stride, padding,
        numel
    );

    return output;
}
"""

avg_pool3d_cpp_source = (
    "torch::Tensor avg_pool3d_cuda_forward(torch::Tensor input, int kernel_size, int stride, int padding);"
)

# Compile the inline CUDA code
avg_pool3d_custom = load_inline(
    name="avg_pool3d_custom",
    cpp_sources=avg_pool3d_cpp_source,
    cuda_sources=avg_pool3d_source,
    functions=["avg_pool3d_cuda_forward"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs 3D Average Pooling using a custom CUDA kernel.
    """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super(ModelNew, self).__init__()
        # Store parameters to pass to the custom kernel
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Custom CUDA Average Pooling to the input tensor.
        """
        return avg_pool3d_custom.avg_pool3d_cuda_forward(x, self.kernel_size, self.stride, self.padding)

