import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Swish Activation
# Swish(x) = x * sigmoid(x) = x / (1 + exp(-x))
swish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void swish_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized path: Process 4 floats at a time using float4
    // This significantly improves memory bandwidth utilization
    int vec_size = size / 4;
    const float4* input_f4 = reinterpret_cast<const float4*>(input);
    float4* output_f4 = reinterpret_cast<float4*>(output);

    for (int i = idx; i < vec_size; i += stride) {
        float4 in = input_f4[i];
        float4 out;

        // Compute Swish for each component
        // Using expf with --use_fast_math provides high throughput
        out.x = in.x / (1.0f + expf(-in.x));
        out.y = in.y / (1.0f + expf(-in.y));
        out.z = in.z / (1.0f + expf(-in.z));
        out.w = in.w / (1.0f + expf(-in.w));

        output_f4[i] = out;
    }

    // Scalar path: Handle remaining elements if size is not divisible by 4
    int remainder_start = vec_size * 4;
    for (int i = remainder_start + idx; i < size; i += stride) {
        float val = input[i];
        output[i] = val / (1.0f + expf(-val));
    }
}

torch::Tensor swish_cuda(torch::Tensor input) {
    // Ensure input is contiguous to support safe pointer arithmetic and vectorization
    auto x = input.contiguous();
    auto out = torch::empty_like(x);

    int size = x.numel();
    const int block_size = 256;

    // Grid Stride Loop setup:
    // We choose a grid size large enough to saturate the GPU, but not excessively large.
    // 2048 blocks * 256 threads = 524,288 threads in flight.
    // The loop inside the kernel handles the large tensor size (approx 1.6 billion elements).
    const int num_blocks = 2048; 

    swish_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

swish_cpp_source = "torch::Tensor swish_cuda(torch::Tensor input);"

# Compile the inline CUDA code
swish_op = load_inline(
    name="swish_op",
    cpp_sources=swish_cpp_source,
    cuda_sources=swish_source,
    functions=["swish_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    # Enable fast math for faster expf calculations
    extra_cuda_cflags=["-O3", "--use_fast_math"]
)

