import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for HardSigmoid
# We use float4 vectorization to improve memory bandwidth utilization,
# as this operation is element-wise and typically memory-bound.
hardsigmoid_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void hardsigmoid_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // 1. Vectorized processing loop (float4)
    // We process 4 elements at a time to maximize memory throughput.
    int vec_size = size / 4;
    const float4* input_vec = reinterpret_cast<const float4*>(input);
    float4* output_vec = reinterpret_cast<float4*>(output);

    // HardSigmoid constants: x * (1/6) + 0.5
    const float scale = 0.16666667f;
    const float bias = 0.5f;

    for (int i = idx; i < vec_size; i += stride) {
        float4 v = input_vec[i];
        float4 r;

        // Use fmaf (Fused Multiply-Add) for speed and precision
        // Formula: clamp(x * scale + bias, 0, 1)

        r.x = fminf(fmaxf(fmaf(v.x, scale, bias), 0.0f), 1.0f);
        r.y = fminf(fmaxf(fmaf(v.y, scale, bias), 0.0f), 1.0f);
        r.z = fminf(fmaxf(fmaf(v.z, scale, bias), 0.0f), 1.0f);
        r.w = fminf(fmaxf(fmaf(v.w, scale, bias), 0.0f), 1.0f);

        output_vec[i] = r;
    }

    // 2. Scalar tail processing loop
    // Handle any remaining elements that didn't fit into the float4 blocks.
    int tail_start = vec_size * 4;
    for (int i = tail_start + idx; i < size; i += stride) {
        float v = input[i];
        output[i] = fminf(fmaxf(fmaf(v, scale, bias), 0.0f), 1.0f);
    }
}

torch::Tensor hardsigmoid_cuda(torch::Tensor input) {
    // Ensure the input tensor is contiguous for raw pointer access
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    auto output = torch::empty_like(input);
    int size = input.numel();

    if (size == 0) return output;

    const int block_size = 256;

    // Calculate grid size based on the number of float4 vectors
    int vec_size = size / 4;
    int grid_size = (vec_size + block_size - 1) / block_size;

    // Clamp grid size to a reasonable limit to ensure efficient hardware scheduling
    // and avoid overhead from too many blocks for smaller inputs.
    // 2048 blocks is usually sufficient to saturate modern GPUs.
    if (grid_size > 2048) grid_size = 2048;
    if (grid_size == 0) grid_size = 1; // Ensure at least one block runs for small tails

    hardsigmoid_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

