# Define the custom CUDA kernel for 2D convolution
# This kernel implements a direct convolution approach handling stride, padding, and dilation.
# It supports asymmetric kernels and parallelizes over the output elements.
conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int h_in,
    int w_in,
    int h_out,
    int w_out,
    int k_h,
    int k_w,
    int stride,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w
) {
    // Flattened index for output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * h_out * w_out;

    if (idx < total_elements) {
        // Decode linear index to (n, c_out, h, w)
        int w = idx % w_out;
        int temp = idx / w_out;
        int h = temp % h_out;
        temp = temp / h_out;
        int c_out = temp % out_channels;
        int n = temp / out_channels;

        float val = 0.0f;

        // Add bias if it exists
        if (bias != nullptr) {
            val = bias[c_out];
        }

        // Perform convolution sum
        for (int c_in = 0; c_in < in_channels; ++c_in) {
            for (int i = 0; i < k_h; ++i) {
                for (int j = 0; j < k_w; ++j) {
                    // Calculate input indices based on padding, stride, dilation
                    int h_in_idx = h * stride - pad_h + i * dil_h;
                    int w_in_idx = w * stride - pad_w + j * dil_w;

                    // Boundary check
                    if (h_in_idx >= 0 && h_in_idx < h_in && w_in_idx >= 0 && w_in_idx < w_in) {
                        int input_offset = ((n * in_channels + c_in) * h_in + h_in_idx) * w_in + w_in_idx;
                        int weight_offset = ((c_out * in_channels + c_in) * k_h + i) * k_w + j;
                        val += input[input_offset] * weight[weight_offset];
                    }
                }
            }
        }
        output[idx] = val;
    }
}

torch::Tensor conv2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int h_in = input.size(2);
    int w_in = input.size(3);

    int out_channels = weight.size(0);
    int k_h = weight.size(2);
    int k_w = weight.size(3);

    // Calculate output dimensions
    int h_out = (h_in + 2 * pad_h - dil_h * (k_h - 1) - 1) / stride + 1;
    int w_out = (w_in + 2 * pad_w - dil_w * (k_w - 1) - 1) / stride + 1;

    // Allocate output tensor
    auto output = torch::zeros({batch_size, out_channels, h_out, w_out}, input.options());

    // Handle optional bias (pass nullptr if empty)
    const float* bias_ptr = nullptr;
    if (bias.numel() > 0) {
        bias_ptr = bias.data_ptr<float>();
    }

    int total_elements = batch_size * out_channels * h_out * w_out;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        h_in, w_in, h_out, w_out,
        k_h, k_w, stride,
        pad_h, pad_w, dil_h, dil_w
    );

    return output;
}
