# This kernel optimizes for the provided architecture parameters using shared memory for weights
# and parallelizing over Batch, Output Channels, and Output Length.
conv1d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int batch_size,
    int in_channels,
    int out_channels,
    int length_in,
    int length_out,
    int kernel_size,
    int stride,
    int padding,
    bool has_bias
) {
    // Dynamic shared memory to store weights for the current output channel
    // Size required: in_channels * kernel_size * sizeof(float)
    extern __shared__ float s_weight[];

    // Grid dimensions:
    // z: batch_size
    // y: out_channels
    // x: blocks covering length_out
    int n = blockIdx.z;       
    int cout = blockIdx.y;    
    int tid = threadIdx.x;
    int l_out = blockIdx.x * blockDim.x + tid; 

    // Load weights into shared memory for the specific output channel handled by this block
    // Weight shape: (out_channels, in_channels, kernel_size)
    // We flatten the inner dimensions for copying.
    int num_weights_per_cout = in_channels * kernel_size;
    int weight_offset_base = cout * num_weights_per_cout;

    // Cooperative loading of weights
    for (int i = tid; i < num_weights_per_cout; i += blockDim.x) {
        s_weight[i] = weight[weight_offset_base + i];
    }

    __syncthreads();

    if (l_out < length_out) {
        float acc = 0.0f;

        // Offset for the specific batch n in input x
        // Input shape: (N, C, L) -> Flattened index = n*C*L + c*L + l
        int input_n_offset = n * in_channels * length_in;

        // Convolution operation
        for (int cin = 0; cin < in_channels; ++cin) {
            int input_cin_offset = input_n_offset + cin * length_in;
            int weight_cin_offset = cin * kernel_size; // Offset within shared memory buffer

            for (int k = 0; k < kernel_size; ++k) {
                int l_in = l_out * stride + k - padding;

                // Boundary check for padding
                if (l_in >= 0 && l_in < length_in) {
                    acc += x[input_cin_offset + l_in] * s_weight[weight_cin_offset + k];
                }
            }
        }

        if (has_bias) {
            acc += bias[cout];
        }

        // Write output
        // Output shape: (N, Cout, Lout)
        int out_idx = n * out_channels * length_out + cout * length_out + l_out;
        y[out_idx] = acc;
    }
}

