import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for triangular matrix multiplication
triangular_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32

__global__ void triangular_matmul_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int N) 
{
    // Grid configuration:
    // bx (blockIdx.x) corresponds to columns
    // by (blockIdx.y) corresponds to rows
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread coordinates within the block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global coordinates for the element C[row, col]
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Optimization: Skip blocks that are entirely in the lower triangle.
    // Since we are computing Upper * Upper = Upper, C is upper triangular.
    // If BlockRow > BlockCol, the entire block is below the diagonal.
    if (by > bx) {
        return;
    }

    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    float sum = 0.0f;

    // Loop over the tiles m that contribute to the dot product.
    // C[row, col] = sum(A[row, k] * B[k, col])
    // Non-zero contributions require:
    // 1. A[row, k] != 0  => k >= row (A is upper triangular)
    // 2. B[k, col] != 0  => k <= col (B is upper triangular)
    //
    // In terms of blocks (size BS):
    // k is roughly in [m*BS, (m+1)*BS)
    // We need m*BS <= col  => m <= bx
    // We need (m+1)*BS > row => m >= by
    // So we iterate m from by to bx.
    // This reduces the complexity roughly by a factor of 6 compared to dense GEMM.

    int m_start = by;
    int m_end = bx;

    for (int m = m_start; m <= m_end; ++m) {
        // Load tile from A into shared memory
        // We need A[row, m*BS + tx]
        int a_col = m * BLOCK_SIZE + tx;
        if (row < N && a_col < N) {
             As[ty][tx] = A[row * N + a_col];
        } else {
             As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory
        // We need B[m*BS + ty, col]
        int b_row = m * BLOCK_SIZE + ty;
        if (b_row < N && col < N) {
             Bs[ty][tx] = B[b_row * N + col];
        } else {
             Bs[ty][tx] = 0.0f;
        }

        // Wait for all threads to load data
        __syncthreads();

        // Compute partial sum for this tile
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        // Wait for computation to finish before overwriting shared memory in next iteration
        __syncthreads();
    }

    // Write result to global memory
    // We initialized C to zeros in the host wrapper.
    // If row > col, the mathematical result is 0. 
    // Since C is initialized to 0, we simply don't write anything if row > col.
    if (row < N && col < N) {
        if (row <= col) {
            C[row * N + col] = sum;
        }
    }
}

torch::Tensor triangular_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are on CUDA
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");

    // Ensure inputs are contiguous for correct pointer arithmetic
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);

    // Allocate output tensor initialized to zeros
    auto C = torch::zeros({N, N}, A.options());

    // Configure grid and block dimensions
    dim3 block_dim(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid_dim((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    // Launch kernel
    triangular_matmul_kernel<<<grid_dim, block_dim>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

triangular_matmul_cpp_source = (
    "torch::Tensor triangular_matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
triangular_matmul = load_inline(
    name="triangular_matmul",
    cpp_sources=triangular_matmul_cpp_source,
    cuda_sources=triangular_matmul_source,
    functions=["triangular_matmul_cuda"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)

