import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for LogSoftmax
# We use a vectorized implementation (float4) to maximize memory bandwidth.
# We perform the operation in 3 passes over the row:
# 1. Find Max (for numerical stability)
# 2. Compute Sum of Exp(x - Max)
# 3. Write Output: x - Max - Log(Sum)
# Since the row size is large (393216), we use one block per row with 1024 threads.
log_softmax_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

#define FLT_MAX 3.402823466e+38F

template<typename T>
__inline__ __device__ T warpReduceMax(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = max(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

template<typename T>
__inline__ __device__ T blockReduceMax(T val) {
    static __shared__ T shared[32]; // Shared mem for 32 partial warp maxes
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceMax(val); // Reduction within warp

    if (lane == 0) shared[wid] = val; // Store warp max
    __syncthreads();

    // Read back partials to first warp
    int num_warps = blockDim.x / 32;
    val = (threadIdx.x < num_warps) ? shared[lane] : -FLT_MAX;

    if (wid == 0) val = warpReduceMax(val); // Final reduction

    return val; // Result in thread 0
}

template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

template<typename T>
__inline__ __device__ T blockReduceSum(T val) {
    static __shared__ T shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    int num_warps = blockDim.x / 32;
    val = (threadIdx.x < num_warps) ? shared[lane] : 0;

    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void log_softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int cols) {
    // Each block processes one row (batch item)
    int row = blockIdx.x;
    int tid = threadIdx.x;

    // Calculate pointers for the current row
    const float* row_in = input + row * cols;
    float* row_out = output + row * cols;

    // --- Pass 1: Find Row Max ---
    float local_max = -FLT_MAX;

    // Vectorized load (float4) for better bandwidth utilization
    int vec_cols = cols / 4;
    const float4* row_in_vec = reinterpret_cast<const float4*>(row_in);

    // Grid-stride loop (though essentially just striding by blockDim here)
    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 val = row_in_vec[i];
        local_max = fmaxf(local_max, val.x);
        local_max = fmaxf(local_max, val.y);
        local_max = fmaxf(local_max, val.z);
        local_max = fmaxf(local_max, val.w);
    }

    // Reduce max across the block
    __shared__ float s_max;
    float row_max = blockReduceMax(local_max);
    if (tid == 0) s_max = row_max;
    __syncthreads();
    row_max = s_max; // Broadcast max to all threads

    // --- Pass 2: Compute Sum of Exp ---
    float local_sum = 0.0f;
    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 val = row_in_vec[i];
        local_sum += expf(val.x - row_max) + expf(val.y - row_max) + expf(val.z - row_max) + expf(val.w - row_max);
    }

    // Reduce sum across the block
    __shared__ float s_sum;
    float row_sum = blockReduceSum(local_sum);
    if (tid == 0) s_sum = row_sum;
    __syncthreads();
    row_sum = s_sum; // Broadcast sum

    // --- Pass 3: Compute Log and Write Output ---
    float log_sum = logf(row_sum);
    float4* row_out_vec = reinterpret_cast<float4*>(row_out);

    for (int i = tid; i < vec_cols; i += blockDim.x) {
        float4 val = row_in_vec[i];
        float4 out_val;
        // log_softmax = x - max - log(sum_exp)
        out_val.x = val.x - row_max - log_sum;
        out_val.y = val.y - row_max - log_sum;
        out_val.z = val.z - row_max - log_sum;
        out_val.w = val.w - row_max - log_sum;
        row_out_vec[i] = out_val;
    }
}

torch::Tensor log_softmax_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int dim = input.size(1);

    const int block_size = 1024;
    const int num_blocks = batch_size;

    log_softmax_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), dim);

    return output;
}
"""

log_softmax_cpp_source = "torch::Tensor log_softmax_cuda(torch::Tensor input);"

# Compile the inline CUDA code
log_softmax_op = load_inline(
    name="log_softmax_op",
    cpp_sources=log_softmax_cpp_source,
    cuda_sources=log_softmax_source,
    functions=["log_softmax_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a LogSoftmax activation using a custom CUDA kernel.
    """
    def __init__(self, dim: int = 1):
        super(ModelNew, self).__init__()
        self.dim = dim
