# Define the custom CUDA kernel for sum reduction over dimension 1.
# This kernel is optimized for the memory layout of reducing the middle dimension of a 3D tensor.
sum_reduce_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void sum_reduce_dim1_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                       int batch, int dim1, int dim2) {
    // The kernel parallelizes over the non-reduced dimensions (batch and dim2).
    // Each thread computes the sum for one column along dim1.
    // Mapping: idx -> (b, d2)

    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total_threads = (long long)batch * dim2;

    if (idx < total_threads) {
        int b = idx / dim2;
        int d2 = idx % dim2;

        // Calculate the starting memory offset for the reduction column.
        // Input shape is (batch, dim1, dim2). We access input[b, :, d2].
        // Memory layout is row-major (contiguous).
        // Offset = b * (dim1 * dim2) + 0 * dim2 + d2.
        // We use long long to prevent 32-bit integer overflow for large tensor sizes.
        long long input_offset = (long long)b * dim1 * dim2 + d2;

        float sum = 0.0f;

        // Iterate over the reduction dimension (dim1).
        // The stride between elements in this dimension is dim2.
        // This access pattern allows threads in a warp (consecutive d2) to load consecutive memory addresses,
        // resulting in coalesced global memory accesses.
        for (int i = 0; i < dim1; ++i) {
            sum += input[input_offset];
            input_offset += dim2; 
        }

        // Output shape is (batch, 1, dim2). The flattened index corresponds exactly to idx.
        output[idx] = sum;
    }
}

torch::Tensor sum_reduce_cuda(torch::Tensor input, int dim) {
    // Check constraints: Input must be CUDA, 3D, float32, and reduction dim must be 1.
    // This custom op specifically replaces the torch.sum(x, dim=1, keepdim=True) for the given architecture.
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(input.dim() == 3, "Input tensor must be 3D");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "Input tensor must be float32");
    TORCH_CHECK(dim == 1, "Custom kernel only supports reduction over dimension 1");

    int batch = input.size(0);
    int dim1 = input.size(1);
    int dim2 = input.size(2);

    // Allocate output tensor with shape (batch, 1, dim2)
    auto output = torch::empty({batch, 1, dim2}, input.options());

    const int block_size = 256;
    long long total_work = (long long)batch * dim2;
    int num_blocks = (total_work + block_size - 1) / block_size;

    sum_reduce_dim1_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, dim1, dim2
    );

    return output;
}
"""

