    const float4* in_vec = reinterpret_cast<const float4*>(input);
    float4* out_vec = reinterpret_cast<float4*>(output);

    for (int64_t i = idx; i < n_vec; i += stride) {
        float4 v = in_vec[i];
        float4 r;

        // Softplus: log(1 + exp(x))
        // Numerical stability: if x > 20, softplus(x) approx x. 
        // This avoids overflow in exp() and matches PyTorch default threshold.

        r.x = (v.x > 20.0f) ? v.x : log1pf(expf(v.x));
        r.y = (v.y > 20.0f) ? v.y : log1pf(expf(v.y));
