        r.w = (v.w > 20.0f) ? v.w : log1pf(expf(v.w));

        out_vec[i] = r;
    }

    // Handle remaining elements (tail)
    // The start index for tail handling in the original float array
    int64_t tail_start = n_vec * 4;
    for (int64_t i = tail_start + idx; i < n; i += stride) {
        float val = input[i];
        output[i] = (val > 20.0f) ? val : log1pf(expf(val));
    }
