from torch.utils.cpp_extension import load_inline

# CUDA kernel source code for Transposed Convolution
conv_transpose_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int k_h,
    int k_w,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    // Map thread to output position
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int bc = blockIdx.z; // encoded batch and out_channel

    if (w_out >= out_w || h_out >= out_h) return;

    int n = bc / out_channels;
    int c_out = bc % out_channels;

    if (n >= batch_size) return;

    float sum = 0.0f;
    if (has_bias) {
        sum = bias[c_out];
    }

    // For Transposed Conv, we gather contributions from the input.
    // An output pixel (h_out, w_out) is influenced by input pixel (h_in, w_in)
    // if: h_out = h_in * stride + k_h * dilation - padding
    // Rearranging for h_in: h_in * stride = h_out + padding - k_h * dilation

    // We iterate over input channels and the kernel window to find valid input pixels
    for (int c_in = 0; c_in < in_channels; ++c_in) {
        for (int p = 0; p < k_h; ++p) {
            for (int q = 0; q < k_w; ++q) {

                int h_unscaled = h_out + padding - p * dilation;
                int w_unscaled = w_out + padding - q * dilation;

                // Check if the position aligns with the stride
                if ((h_unscaled % stride == 0) && (w_unscaled % stride == 0)) {
                    int h_in = h_unscaled / stride;
                    int w_in = w_unscaled / stride;

                    // Check bounds
                    if (h_in >= 0 && h_in < in_h && w_in >= 0 && w_in < in_w) {
                        // Input layout: (N, Cin, Hin, Win)
                        int in_idx = ((n * in_channels + c_in) * in_h + h_in) * in_w + w_in;

                        // Weight layout for ConvTranspose2d: (Cin, Cout, Kh, Kw)
                        int w_idx = ((c_in * out_channels + c_out) * k_h + p) * k_w + q;

                        sum += input[in_idx] * weight[w_idx];
                    }
                }
            }
        }
    }

    // Output layout: (N, Cout, Hout, Wout)
    int out_idx = ((n * out_channels + c_out) * out_h + h_out) * out_w + w_out;
    output[out_idx] = sum;
