import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for reverse cumulative sum (suffix sum)
# This kernel optimizes the operation: torch.cumsum(x.flip(dim), dim).flip(dim)
# which is equivalent to a suffix sum along the specified dimension.
# The kernel assumes the operation is performed on the last dimension (contiguous).
reverse_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void reverse_cumsum_kernel(const float* __restrict__ x, float* __restrict__ y, int rows, int cols) {
    // Each block processes one row (one segment of the last dimension)
    int row = blockIdx.x;
    if (row >= rows) return;

    // Pointer arithmetic for the specific row
    const float* row_x = x + row * cols;
    float* row_y = y + row * cols;

    float running_sum = 0.0f;

    // Shared memory for block-level scan. Size fixed to 1024 floats (4KB).
    // This allows us to process 1024 elements in parallel efficiently.
    __shared__ float s_data[1024];

    // Process the row in chunks of 1024 elements, starting from the end (right to left)
    // This direction is natural for suffix sum: we accumulate sum from the right.
    for (int chunk_end = cols; chunk_end > 0; chunk_end -= 1024) {
        int chunk_start = chunk_end - 1024;
        if (chunk_start < 0) chunk_start = 0;
        int valid_count = chunk_end - chunk_start;

        int tid = threadIdx.x;
        float val = 0.0f;

        // Load data from global memory
        if (tid < valid_count) {
            val = row_x[chunk_start + tid];
        }

        // Initialize shared memory
        s_data[tid] = val;
        // Zero-pad if the chunk is smaller than block size
        if (tid >= valid_count) s_data[tid] = 0.0f;

        __syncthreads();

        // Perform in-place inclusive prefix sum (Hillis-Steele scan) in shared memory
        // This computes the prefix sum relative to the start of the chunk
        #pragma unroll
        for (int stride = 1; stride < 1024; stride *= 2) {
            float v = 0.0f;
            if (tid >= stride) v = s_data[tid - stride];
            __syncthreads();
            if (tid >= stride) s_data[tid] += v;
            __syncthreads();
        }

        // The total sum of the current chunk is at the last valid index
        float chunk_total = s_data[valid_count - 1]; 

        // Write the result to global memory
        if (tid < valid_count) {
            float inclusive = s_data[tid];
            // To get the suffix sum at position 'tid' within the chunk:
            // Suffix = (ChunkTotal - ExclusivePrefix)
            // ExclusivePrefix = Inclusive - OriginalValue
            // Suffix = ChunkTotal - Inclusive + OriginalValue
            // Then add running_sum from all chunks to the right.
            float suffix = (chunk_total - inclusive) + val + running_sum;
            row_y[chunk_start + tid] = suffix;
        }

        // Accumulate the total sum of this chunk to running_sum for the next chunk (to the left)
        running_sum += chunk_total;

        // Barrier to ensure all threads are done before starting next iteration
        __syncthreads();
    }
}

torch::Tensor reverse_cumsum_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");

    // Ensure contiguous memory layout for correct pointer arithmetic
    x = x.contiguous();

    // Treat the input as a 2D tensor where we scan along the last dimension.
    // If input is (N, C), rows=N, cols=C.
    // If input is (N, M, C), rows=N*M, cols=C.
    int64_t cols = x.size(-1);
    int64_t rows = x.numel() / cols;

    auto y = torch::empty_like(x);

    // Configure kernel launch: one block per row, 1024 threads per block
    // 32768 rows fits easily within grid limits (approx 2 billion).
    dim3 grid(rows);
    dim3 block(1024);

    reverse_cumsum_kernel<<<grid, block>>>(x.data_ptr<float>(), y.data_ptr<float>(), rows, cols);

    return y;
}
"""

reverse_cumsum_cpp_source = "torch::Tensor reverse_cumsum_cuda(torch::Tensor x);"

# Compile the inline CUDA code
reverse_cumsum_op = load_inline(
    name="reverse_cumsum_op",
    cpp_sources=reverse_cumsum_cpp_source,
    cuda_sources=reverse_cumsum_source,
    functions=["reverse_cumsum_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized Model performing reverse cumulative sum using a custom CUDA kernel.
    """
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.reverse_cumsum_op = reverse_cumsum_op

    def forward(self, x):
        # Resolve dimension index
        dim = self.dim if self.dim >= 0 else self.dim + x.ndim

        # If the operation is on the last dimension, apply the kernel directly
        # The kernel is optimized for row-wise processing (contiguous segments).
        if dim == x.ndim - 1:
            return self.reverse_cumsum_op.reverse_cumsum_cuda(x)
        else:
            # If not on the last dimension, transpose the target dimension to the end
            # This allows reusing the efficient contiguous kernel.
            # While transpose involves copy, it is still generally faster than
            # the original multi-pass approach (flip, cumsum, flip) + allocations.
            x_t = x.transpose(dim, -1).contiguous()
            y_t = self.reverse_cumsum_op.reverse_cumsum_cuda(x_t)
            return y_t.transpose(dim, -1)

