import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused L2 Normalization
# This kernel performs the reduction (sum of squares) and the element-wise division in a single kernel launch.
# It assigns one CUDA thread block to each row of the input batch, avoiding intermediate memory allocations
# and reducing global memory traffic compared to separate reduction and division kernels.
l2_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Helper function for warp-level reduction
__inline__ __device__ float warp_reduce(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void l2_normalize_kernel(const float* __restrict__ x, float* __restrict__ out, int dim) {
    // Each block processes one row of the batch
    int batch_id = blockIdx.x;
    int tid = threadIdx.x;

    // Calculate pointers for the current row
    const float* row_x = x + batch_id * dim;
    float* row_out = out + batch_id * dim;

    float sum_sq = 0.0f;

    // 1. Compute Sum of Squares (Grid-Stride Loop logic within block)
    // Using __ldg for read-only data cache optimization
    for (int i = tid; i < dim; i += blockDim.x) {
        float val = __ldg(&row_x[i]);
        sum_sq += val * val;
    }

    // 2. Block Reduction to find total sum of squares for the row

    // Reduce within warp
    sum_sq = warp_reduce(sum_sq);

    // Shared memory for inter-warp reduction (max 32 warps for 1024 threads)
    __shared__ float sdata[32];

    int lane = tid % 32;
    int warp_id = tid / 32;

    // First thread of each warp writes warp-sum to shared memory
    if (lane == 0) {
        sdata[warp_id] = sum_sq;
    }

    __syncthreads();

    // Reduce the warp sums using the first warp
    float total_sum = 0.0f;
    if (warp_id == 0) {
        int num_warps = blockDim.x / 32;
        // Load warp sums safely
        if (tid < num_warps) {
            total_sum = sdata[tid];
        }

        // Reduce intra-warp again to get the block sum
        total_sum = warp_reduce(total_sum);

        // Store total sum back to shared memory so all threads can access it
        if (tid == 0) {
            sdata[0] = total_sum;
        }
    }

    __syncthreads();

    // 3. Compute Inverse Norm
    // sdata[0] contains the sum of squares for the row. 
    // We use reciprocal square root for speed.
    float inv_norm = rsqrtf(sdata[0]);

    // 4. Apply Normalization and Write Output
    // Re-read input, multiply by inv_norm, write to output
    for (int i = tid; i < dim; i += blockDim.x) {
        row_out[i] = __ldg(&row_x[i]) * inv_norm;
    }
}

torch::Tensor l2_normalize_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 2, "x must be a 2D tensor");

    int batch_size = x.size(0);
    int dim = x.size(1);

    auto out = torch::empty_like(x);

    // Launch configuration:
    // One block per row (batch element). 
    // 256 threads per block is a good balance for occupancy.
    const int block_size = 256;
    const int grid_size = batch_size;

    l2_normalize_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), dim);

    return out;
}
"""

l2_norm_cpp_source = "torch::Tensor l2_normalize_cuda(torch::Tensor x);"

# Compile the inline CUDA code
l2_norm_module = load_inline(
    name="l2_norm_module",
    cpp_sources=l2_norm_cpp_source,
