import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code for Transposed Convolution
# This kernel assumes stride=1, padding=0, dilation=1, groups=1.
# It uses shared memory tiling to optimize input memory access.
conv_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16
#define MAX_K 7

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int kernel_size) {

    // Shared memory tile
    // We load a tile of input that covers the output tile
    // Output tile: 16x16
    // Required input size = (TILE_DIM + kernel_size - 1) x (TILE_DIM + kernel_size - 1)
    // For K=3, this is 18x18.
    __shared__ float tile[TILE_DIM + MAX_K - 1][TILE_DIM + MAX_K - 1];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z;

    int n = bz / out_channels;
    int k = bz % out_channels;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global output coordinates
    int out_x = bx * TILE_DIM + tx;
    int out_y = by * TILE_DIM + ty;

    // Dimensions of shared memory buffer needed
    int tile_h_dim = TILE_DIM + kernel_size - 1;
    int tile_w_dim = TILE_DIM + kernel_size - 1;

    // Top-left of the input region corresponding to this output block
    // Formula: h_in = h_out - p. Max p is kernel_size-1.
    // So for the top-left output pixel (by*TILE_DIM), the top-most input needed is at - (kernel_size - 1).
    int start_h = by * TILE_DIM - (kernel_size - 1);
    int start_w = bx * TILE_DIM - (kernel_size - 1);

    float val = 0.0f;

    // Iterate over input channels
    for (int c = 0; c < in_channels; ++c) {
        // 1. Cooperatively load input tile into shared memory
        int tid = ty * TILE_DIM + tx;
        int num_threads = TILE_DIM * TILE_DIM;
        int total_elements = tile_h_dim * tile_w_dim;

        for (int i = tid; i < total_elements; i += num_threads) {
            int r = i / tile_w_dim;
            int c_smem = i % tile_w_dim;

            int global_h = start_h + r;
            int global_w = start_w + c_smem;

            float in_val = 0.0f;
            // Boundary checks for input (handle implicit zero padding)
            if (global_h >= 0 && global_h < in_h && global_w >= 0 && global_w < in_w) {
                // Input layout: (N, Cin, H, W)
                in_val = input[((n * in_channels + c) * in_h + global_h) * in_w + global_w];
            }
            tile[r][c_smem] = in_val;
        }
        __syncthreads();

        // 2. Compute convolution for this input channel
        if (out_y < out_h && out_x < out_w) {
            for (int p = 0; p < kernel_size; ++p) {
                for (int q = 0; q < kernel_size; ++q) {
                    // Weight layout: (in_channels, out_channels, k, k)
                    int w_idx = ((c * out_channels + k) * kernel_size + p) * kernel_size + q;
                    float w = weight[w_idx];

                    // Determine index in shared memory
                    // h_in = out_y - p
                    // local_r = h_in - start_h 
                    //         = (by*TILE_DIM + ty - p) - (by*TILE_DIM - (K-1))
                    //         = ty + K - 1 - p
                    int smem_y = ty + kernel_size - 1 - p;
                    int smem_x = tx + kernel_size - 1 - q;

                    val += tile[smem_y][smem_x] * w;
                }
            }
        }
        __syncthreads();
    }

    if (out_y < out_h && out_x < out_w) {
        // Output layout: (N, Cout, Hout, Wout)
        int out_idx = ((n * out_channels + k) * out_h + out_y) * out_w + out_x;
        output[out_idx] = val;
    }
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight, int kernel_size) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_channels = weight.size(1);

    // For stride=1, padding=0, output size is H + K - 1
    int out_h = in_h + kernel_size - 1;
    int out_w = in_w + kernel_size - 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    dim3 block(TILE_DIM, TILE_DIM);
    dim3 grid((out_w + TILE_DIM - 1) / TILE_DIM, (out_h + TILE_DIM - 1) / TILE_DIM, batch_size * out_channels);

    conv_transpose2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, out_h, out_w, kernel_size
    );

    return output;
