import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Hinge Loss
# This kernel fuses the element-wise multiplication, subtraction, scalar clamp (ReLU),
# and a partial reduction (block-wise sum) to avoid large memory allocations.
hinge_loss_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void hinge_loss_kernel(
    const scalar_t* __restrict__ predictions,
    const scalar_t* __restrict__ targets,
    scalar_t* __restrict__ out,
    const int64_t size,
    const int64_t M) {

    // Dynamic shared memory for block reduction
    extern __shared__ char smem[];
    scalar_t* s_data = reinterpret_cast<scalar_t*>(smem);

    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned int stride = blockDim.x * gridDim.x;

    scalar_t local_sum = 0;

    // Grid-stride loop covering all elements
    for (int64_t i = idx; i < size; i += stride) {
        // Broadcast logic:
        // predictions is (N, M), targets is (M,) (or broadcastable to last dim)
        // We assume broadcast across the rows of predictions.
        int64_t target_idx = i % M;

        scalar_t p = predictions[i];
        scalar_t t = targets[target_idx];

        // Hinge Loss calculation: max(0, 1 - p * t)
        scalar_t val = static_cast<scalar_t>(1.0) - p * t;
        if (val < 0) {
            val = 0;
        }

        local_sum += val;
    }

    s_data[tid] = local_sum;
    __syncthreads();

    // Block reduction (sum) in shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }

    // Write result of this block to global memory
    if (tid == 0) {
        out[blockIdx.x] = s_data[0];
    }
}

torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Input validation
    TORCH_CHECK(predictions.is_cuda, "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda, "targets must be a CUDA tensor");

    predictions = predictions.contiguous();
    targets = targets.contiguous();

    const int64_t size = predictions.numel();
    // Logic for M based on PyTorch broadcasting rules for the given architecture:
    // predictions (32768, 32768), targets (32768) -> targets broadcast to last dim.
    const int64_t M = targets.numel();

    // Configuration
    const int threads = 256;
    const int blocks = 1024; // Fixed grid size sufficient for large inputs

    // Output buffer for partial sums (one per block)
    auto out = torch::empty({blocks}, predictions.options());

    AT_DISPATCH_FLOATING_TYPES(predictions.scalar_type(), "hinge_loss_kernel", ([&] {
        hinge_loss_kernel<scalar_t><<<blocks, threads, threads * sizeof(scalar_t)>>>(
            predictions.data_ptr<scalar_t>(),
            targets.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            size,
            M
        );
    }));

    // Final reduction and mean calculation
    // Sum the partial block sums and divide by total elements.
    return out.sum() / static_cast<double>(size);
}
"""

hinge_loss_cpp_source = "torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets);"

# Compile the inline CUDA code
hinge_loss_ext = load_inline(
    name="hinge_loss_ext",
    cpp_sources=hinge_loss_cpp_source,
    cuda_sources=hinge_loss_source,
    functions=["hinge_loss_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized Model that computes Hinge Loss using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.hinge_loss_ext = hinge_loss_ext

    def forward(self, predictions, targets):
        # Ensure inputs are on CUDA (if not already)
        if not predictions.is_cuda:
            predictions = predictions.cuda()
        if not targets.is_cuda:
            targets = targets.cuda()

        return self.hinge_loss_ext.hinge_loss_cuda(predictions, targets)

