# Define the custom CUDA kernel for 3D Convolution
conv3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int in_depth, int in_height, int in_width,
    int out_channels,
    int out_depth, int out_height, int out_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    // Flattened index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int vol_spatial = out_depth * out_height * out_width;
    int vol_batch = out_channels * vol_spatial;
    int total_elements = batch_size * vol_batch;

    if (idx >= total_elements) return;

    // Decode index for NCDHW layout: N, C_out, D_out, H_out, W_out
    int n = idx / vol_batch;
    int rem = idx % vol_batch;

    int c_out = rem / vol_spatial;
    rem = rem % vol_spatial;

    int d_out = rem / (out_height * out_width);
    rem = rem % (out_height * out_width);

    int h_out = rem / out_width;
    int w_out = rem % out_width;

    // Input coordinates base
    int d_in_start = d_out * stride - padding;
    int h_in_start = h_out * stride - padding;
    int w_in_start = w_out * stride - padding;

    float val = 0.0f;

    // Direct convolution loop
    for (int c_in = 0; c_in < in_channels; ++c_in) {
        for (int kd = 0; kd < kernel_size; ++kd) {
            int d_in = d_in_start + kd * dilation;
            if (d_in >= 0 && d_in < in_depth) {
                for (int kh = 0; kh < kernel_size; ++kh) {
                    int h_in = h_in_start + kh * dilation;
                    if (h_in >= 0 && h_in < in_height) {
                        for (int kw = 0; kw < kernel_size; ++kw) {
                            int w_in = w_in_start + kw * dilation;
                            if (w_in >= 0 && w_in < in_width) {

                                int input_idx = n * (in_channels * in_depth * in_height * in_width) +
                                                c_in * (in_depth * in_height * in_width) +
                                                d_in * (in_height * in_width) +
                                                h_in * (in_width) +
                                                w_in;

                                int weight_idx = c_out * (in_channels * kernel_size * kernel_size * kernel_size) +
                                                 c_in * (kernel_size * kernel_size * kernel_size) +
                                                 kd * (kernel_size * kernel_size) +
                                                 kh * (kernel_size) +
                                                 kw;

                                val += input[input_idx] * weight[weight_idx];
                            }
                        }
                    }
                }
            }
        }
    }

    if (bias != nullptr) {
        val += bias[c_out];
    }

    output[idx] = val;
}

torch::Tensor conv3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation) {

    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto in_depth = input.size(2);
    const auto in_height = input.size(3);
    const auto in_width = input.size(4);

    const auto out_channels = weight.size(0);
    const auto kernel_size = weight.size(2);

    auto out_depth = (in_depth + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto out_height = (in_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto out_width = (in_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.numel() > 0) {
        bias_ptr = bias.data_ptr<float>();
    }

    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    conv3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, in_depth, in_height, in_width,
        out_channels, out_depth, out_height, out_width,
        kernel_size, stride, padding, dilation
    );

    return output;
}
"""

conv3d_cpp_source = "torch::Tensor conv3d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding, int dilation);"

# Compile the inline CUDA code
conv3d_op = load_inline(
    name="conv3d_op",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.kernel_size = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels

        # Initialize weights
        self.weight = nn.Parameter(torch.Tensor(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Fallback to PyTorch for grouped convolution as our custom kernel assumes groups=1
        if self.groups != 1:
            return F.conv3d(x, self.weight, self.bias, self.stride, self.padding, self.dilation, self.groups)

        # Ensure contiguous inputs for CUDA kernel
        x = x.contiguous()
        # Handle bias: pass empty tensor if None
        bias_tensor = self.bias if self.bias is not None else torch.empty(0, device=x.device)

        return conv3d_op.conv3d_cuda(
            x, 
            self.weight, 
            bias_tensor, 
            self.stride, 
            self.padding, 
            self.dilation
        )

