import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for the specific 3D convolution
# (kernel_size x kernel_size x 1)
conv3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv3d_custom_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int d_in, int h_in, int w_in,
    int d_out, int h_out, int w_out,
    int kernel_size,
    bool has_bias) {

    // Mapping dimensions to the problem description:
    // D corresponds to 'height'
    // H corresponds to 'width'
    // W corresponds to 'depth'
    // Kernel operates on D and H (kernel_size), and W (1).

    // Grid configuration:
    // x: flattened spatial output dimensions (d_out * h_out * w_out)
    // y: output channels (M)
    // z: batch size (N)

    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int m = blockIdx.y;
    int n = blockIdx.z;

    int total_spatial = d_out * h_out * w_out;

    if (spatial_idx >= total_spatial) return;

    // Unflatten spatial_idx to (d, h, w)
    // w is the fastest moving dimension (stride 1)
    // h is the next (stride w_out)
    // d is the slowest (stride h_out * w_out)

    int w = spatial_idx % w_out;
    int rem = spatial_idx / w_out;
    int h = rem % h_out;
    int d = rem / h_out;

    // Calculate base offsets
    // Input tensor shape: (N, Cin, Din, Hin, Win)
    // Weight tensor shape: (M, Cin, K, K, 1)

    long long input_n_offset = (long long)n * in_channels * d_in * h_in * w_in;
    long long weight_m_offset = (long long)m * in_channels * kernel_size * kernel_size;

    float val = 0.0f;

    // Convolution loop
    for (int c = 0; c < in_channels; ++c) {
        long long input_c_offset = input_n_offset + (long long)c * d_in * h_in * w_in;
        long long weight_c_offset = weight_m_offset + (long long)c * kernel_size * kernel_size;

        for (int ki = 0; ki < kernel_size; ++ki) {
            for (int kj = 0; kj < kernel_size; ++kj) {
                // Determine input spatial coordinates
                // Stride is 1, Padding is 0, Dilation is 1
                int in_d = d + ki;
                int in_h = h + kj;
                // in_w = w (since kernel size in w dimension is 1)

                long long in_idx = input_c_offset + (long long)in_d * h_in * w_in + (long long)in_h * w_in + w;
                long long w_idx = weight_c_offset + ki * kernel_size + kj;

                val += input[in_idx] * weight[w_idx];
            }
        }
    }

    if (has_bias) {
        val += bias[m];
    }

    // Output tensor shape: (N, M, Dout, Hout, Wout)
    long long out_idx = (long long)n * out_channels * total_spatial + (long long)m * total_spatial + spatial_idx;
    output[out_idx] = val;
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size) {

    // Input: (N, C, D, H, W)
    // Weight: (M, C, K, K, 1)

    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int d_in = input.size(2);
    const int h_in = input.size(3);
    const int w_in = input.size(4);

    const int out_channels = weight.size(0);

    // Calculate output dimensions
    // Assuming stride=1, padding=0, dilation=1
    const int d_out = d_in - kernel_size + 1;
    const int h_out = h_in - kernel_size + 1;
    const int w_out = w_in; // Kernel size is 1 in this dimension

    auto output = torch::zeros({batch_size, out_channels, d_out, h_out, w_out}, input.options());

    const int total_spatial = d_out * h_out * w_out;
    const int block_size = 256;
    const int grid_x = (total_spatial + block_size - 1) / block_size;

    dim3 grid(grid_x, out_channels, batch_size);
    dim3 block(block_size);

    bool has_bias = bias.defined();
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;

    conv3d_custom_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        d_in, h_in, w_in,
        d_out, h_out, w_out,
        kernel_size,
        has_bias
    );

    return output;
}
"""

conv3d_cpp_source = (
    "torch::Tensor conv3d_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int kernel_size);"
)

conv3d_op = load_inline(
    name="conv3d_op",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model with custom CUDA kernel for 3D convolution.
    Performs convolution with kernel (kernel_size, kernel_size, 1).
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        # Initialize weights matching the shape (Out, In, K, K, 1)
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size, 1))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()
        self.conv3d_op = conv3d_op

    def reset_parameters(self):
        # Kaiming uniform initialization adapted for the specific kernel shape
        # Fan-in = in_channels * kernel_size * kernel_size * 1
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.weight, -bound, bound)
        if self.bias is not None:
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width, depth).
        """
        # Handle bias being None by passing an empty tensor (undefined on C++ side)
        bias_tensor = self.bias if self.bias is not None else torch.Tensor()

        return self.conv3d_op.conv3d_forward_cuda(x, self.weight, bias_tensor, self.kernel_size)

