import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for row-wise exclusive cumsum
# This kernel fuses the concatenation, slicing, and cumulative sum operations
# into a single pass to minimize memory reads/writes.
exclusive_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void exclusive_cumsum_dim1_kernel(const float* __restrict__ x, float* __restrict__ out, int B, int N) {
    // x: Input tensor of shape (B, N)
    // out: Output tensor of shape (B-1, N+1)

    // Each block processes one row. We process rows 0 to B-2.
    int row = blockIdx.x; 
    if (row >= B - 1) return;

    // Pointers to the start of the current row in input and output
    const float* row_x = x + row * N;
    float* row_out = out + row * (N + 1);

    // Initialize the first element of the row to 0 (exclusive scan property)
    if (threadIdx.x == 0) {
        row_out[0] = 0.0f;
    }

    float running_sum = 0.0f;

    // Shared memory for storing warp sums during block-level scan
    // Max 32 warps allowed (for block size up to 1024)
    __shared__ float s_warp_sums[32];

    // Iterate over the row in chunks of size blockDim.x
    for (int base = 0; base < N; base += blockDim.x) {
        int tid = threadIdx.x;
        int i = base + tid;

        float val = 0.0f;
        if (i < N) {
            val = row_x[i];
        }

        // 1. Warp-level inclusive scan (Hillis-Steele via shuffle)
        float warp_val = val;
        unsigned int mask = 0xffffffff;

        #pragma unroll
        for (int offset = 1; offset < 32; offset <<= 1) {
            float n = __shfl_up_sync(mask, warp_val, offset);
            if ((tid & 31) >= offset) warp_val += n;
        }

        // 2. Store the last element of each warp's scan to shared memory
        if ((tid & 31) == 31) {
            s_warp_sums[tid >> 5] = warp_val;
        }
        __syncthreads();

        // 3. Scan the warp sums (performed by the first warp)
        if (tid < 32) {
            float w_val = 0.0f;
            int num_warps = blockDim.x >> 5;
            if (tid < num_warps) {
                w_val = s_warp_sums[tid];
            }

            #pragma unroll
            for (int offset = 1; offset < 32; offset <<= 1) {
                float n = __shfl_up_sync(mask, w_val, offset);
                if ((tid & 31) >= offset) w_val += n;
            }

            if (tid < num_warps) {
                s_warp_sums[tid] = w_val;
            }
        }
        __syncthreads();

        // 4. Add the base from the previous warp to the current thread's value
        float block_val = warp_val;
        int warp_id = tid >> 5;
        if (warp_id > 0) {
            block_val += s_warp_sums[warp_id - 1];
        }

        // 5. Write the result to global memory
        // block_val is the inclusive sum of the current chunk.
        // We add running_sum from previous chunks.
        // The output index is shifted by +1 because out[0] is 0.
        if (i < N) {
            row_out[i + 1] = running_sum + block_val;
        }

        // 6. Update running_sum with the total sum of this chunk
        int num_warps = blockDim.x >> 5;
        float chunk_total = s_warp_sums[num_warps - 1];
        running_sum += chunk_total;

        __syncthreads();
    }
}

torch::Tensor exclusive_cumsum_dim1(torch::Tensor x) {
    // Check inputs
    TORCH_CHECK(x.is_cuda, "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");

    auto B = x.size(0);
    auto N = x.size(1);

    // If batch size is less than or equal to 1, result is empty (due to slicing [:-1])
    if (B <= 1) {
        return torch::empty({0, N + 1}, x.options());
    }

    // Allocate output tensor directly
    auto out = torch::empty({B - 1, N + 1}, x.options());

    // Launch kernel
    // One block per row, 256 threads per block
    int threads = 256;
    int blocks = B - 1;
    exclusive_cumsum_dim1_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(), B, N);

    return out;
}
"""

exclusive_cumsum_cpp_source = (
    "torch::Tensor exclusive_cumsum_dim1(torch::Tensor x);"
)

# Compile the inline CUDA code
exclusive_cumsum_op = load_inline(
    name="exclusive_cumsum_op",
    cpp_sources=exclusive_cumsum_cpp_source,
    cuda_sources=exclusive_cumsum_source,
    functions=["exclusive_cumsum_dim1"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized model performing exclusive cumulative sum.
    Specifically optimized for dim=1 using a custom CUDA kernel.
    """

    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.exclusive_cumsum_op = exclusive_cumsum_op

    def forward(self, x):
        # Use custom CUDA kernel if applicable (dim=1, float32, cuda)
        if self.dim == 1 and x.is_cuda and x.dtype == torch.float32:
            # Ensure input is contiguous for the kernel
            x = x.contiguous()
            return self.exclusive_cumsum_op.exclusive_cumsum_dim1(x)
        else:
            # Fallback to original implementation for other dimensions or devices
            exclusive_cumsum = torch.cat((torch.zeros_like(x.select(self.dim, 0).unsqueeze(self.dim)), x), dim=self.dim)[:-1]
            return torch.cumsum(exclusive_cumsum, dim=self.dim)

