import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for depthwise convolution
dw_conv_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void dw_conv_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int in_h,
    const int in_w,
    const int out_h,
    const int out_w,
    const int kernel_size,
    const int stride,
    const int padding) {

    // Calculate global thread index
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_elements = batch_size * channels * out_h * out_w;

    if (idx < total_elements) {
        // Map linear index to (n, c, oh, ow)
        int temp = idx;
        const int ow = temp % out_w;
        temp /= out_w;
        const int oh = temp % out_h;
        temp /= out_h;
        const int c = temp % channels;
        const int n = temp; 

        // Initialize sum. Fuse bias addition here if bias exists.
        float sum = 0.0f;
        if (bias != nullptr) {
            sum = bias[c];
        }

        // Depthwise convolution loop: C_out == C_in, groups == C
        // Weight shape (PyTorch): [out_channels, 1, k, k] which is [C, 1, k, k]
        // Effectively we pair input channel c with weight filter c.
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                const int h_in = oh * stride - padding + kh;
                const int w_in = ow * stride - padding + kw;

                // Boundary checks (padding)
                if (h_in >= 0 && h_in < in_h && w_in >= 0 && w_in < in_w) {
                    // Input index: (n, c, h_in, w_in)
                    const int input_idx = ((n * channels + c) * in_h + h_in) * in_w + w_in;
                    // Weight index: (c, 0, kh, kw) flattened -> c * K*K + kh * K + kw
                    const int weight_idx = (c * kernel_size + kh) * kernel_size + kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor dw_conv_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding) {

    const int batch_size = input.size(0);
    const int channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int kernel_size = weight.size(2); // Assuming square kernel

    const int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    const int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    // Allocate output tensor
    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());

    // Handle optional bias
    const float* bias_ptr = nullptr;
    if (bias.numel() > 0) {
        bias_ptr = bias.data_ptr<float>();
    }

    const int total_elements = batch_size * channels * out_h * out_w;
    const int threads = 256;
    const int blocks = (total_elements + threads - 1) / threads;

    dw_conv_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_h,
        in_w,
        out_h,
        out_w,
        kernel_size,
        stride,
        padding
    );

    return output;
}
"""

dw_conv_cpp_source = (
    "torch::Tensor dw_conv_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding);"
)

# Compile the inline CUDA code
dw_conv_op = load_inline(
    name="dw_conv_op",
    cpp_sources=dw_conv_cpp_source,
    cuda_sources=dw_conv_source,
    functions=["dw_conv_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        # Initialize standard Conv2d to manage weights and bias parameters.
        # groups=in_channels ensures depthwise convolution structure.
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size, stride=stride, padding=padding, groups=in_channels, bias=bias)
        self.stride = stride
        self.padding = padding
        self.dw_conv_op = dw_conv_op

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the depthwise 2D convolution using the custom CUDA kernel.
        """
        # Retrieve weights and bias from the nn.Module
        weight = self.conv2d.weight
        bias = self.conv2d.bias

        # If bias is None, create an empty tensor to pass to C++ (signal for nullptr)
        if bias is None:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return self.dw_conv_op.dw_conv_cuda(x, weight, bias, self.stride, self.padding)

