import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Max reduction along a dimension
# This kernel is optimized for reducing a dimension that is NOT the last dimension (strided reduction).
# It relies on the inner dimension being large enough (e.g., > 32) to ensure coalesced memory access 
# across threads in a warp. For dim=1 in (128, 4096, 4095), this is highly efficient.

reduce_max_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void reduce_max_kernel(const float* __restrict__ inp, float* __restrict__ out, 
                                  int outer, int reduce, int inner, int total_out) {
    // Flattened index of the output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_out) {
        // Map linear index 'idx' to logical output coordinates (outer_idx, inner_idx)
        // Output logical shape is [outer, inner] (flattened from original rank-1)
        int inner_idx = idx % inner;
        int outer_idx = idx / inner;

        // Calculate the initial offset in the input array.
        // Input logical shape is [outer, reduce, inner].
        // We start reading at indices: [outer_idx, 0, inner_idx].
        // We use 'long long' to prevent overflow for large tensors (indices > 2^31).
        long long input_offset = (long long)outer_idx * reduce * inner + inner_idx;

        float max_val = -FLT_MAX;

        // Iterate over the dimension to reduce
        for (int i = 0; i < reduce; ++i) {
            float val = inp[input_offset];
            if (val > max_val) {
                max_val = val;
            }
            // Stride to the next element along the reduction dimension
            input_offset += inner;
        }

        out[idx] = max_val;
    }
}

torch::Tensor reduce_max_cuda(torch::Tensor inp, int dim) {
    // Ensure input is contiguous in memory to support raw pointer arithmetic
    inp = inp.contiguous();

    int ndim = inp.dim();
    // Handle negative dimension index
    if (dim < 0) dim += ndim;

    // Calculate logical dimensions: Outer x Reduce x Inner
    int outer = 1;
    for (int i = 0; i < dim; ++i) outer *= inp.size(i);

    int reduce = inp.size(dim);

    int inner = 1;
    for (int i = dim + 1; i < ndim; ++i) inner *= inp.size(i);

    // Determine output shape
    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(inp.size(i));
    }

    auto out = torch::empty(out_sizes, inp.options());

    int total_out = outer * inner;

    const int block_size = 256;
    const int grid_size = (total_out + block_size - 1) / block_size;

    reduce_max_kernel<<<grid_size, block_size>>>(
        inp.data_ptr<float>(),
        out.data_ptr<float>(),
        outer, reduce, inner, total_out
    );

    return out;
}
"""

reduce_max_cpp_source = (
    "torch::Tensor reduce_max_cuda(torch::Tensor inp, int dim);"
)

# Compile the inline CUDA code
reduce_max_module = load_inline(
    name="reduce_max_module",
    cpp_sources=reduce_max_cpp_source,
    cuda_sources=reduce_max_cuda_source,
    functions=["reduce_max_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.reduce_max_module = reduce_max_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies optimized Max reduction over the specified dimension.
        """
        return self.reduce_max_module.reduce_max_cuda(x, self.dim)

