import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for SELU activation
# We use vectorized memory access (float4) for performance optimization on the large input tensors.
selu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// SELU Constants
#define ALPHA 1.6732632423543772848170429916717f
#define SCALE 1.0507009873554804934193349852946f

__global__ void selu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    // Check for 16-byte alignment to enable vectorized float4 access
    bool aligned = (reinterpret_cast<uintptr_t>(input) % 16 == 0) && 
                   (reinterpret_cast<uintptr_t>(output) % 16 == 0);

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    if (aligned) {
        // Vectorized path
        int vec_size = size / 4;
        const float4* in_vec = reinterpret_cast<const float4*>(input);
        float4* out_vec = reinterpret_cast<float4*>(output);

        for (int i = idx; i < vec_size; i += stride) {
            float4 v = in_vec[i];

            // Apply SELU logic component-wise
            // f(x) = scale * x if x > 0 else scale * alpha * (exp(x) - 1)
            // expm1f(x) computes exp(x) - 1 accurately

            v.x = (v.x > 0.0f) ? (SCALE * v.x) : (SCALE * ALPHA * expm1f(v.x));
            v.y = (v.y > 0.0f) ? (SCALE * v.y) : (SCALE * ALPHA * expm1f(v.y));
            v.z = (v.z > 0.0f) ? (SCALE * v.z) : (SCALE * ALPHA * expm1f(v.z));
            v.w = (v.w > 0.0f) ? (SCALE * v.w) : (SCALE * ALPHA * expm1f(v.w));

            out_vec[i] = v;
        }

        // Handle tail elements (0 to 3 elements)
        // We let the first thread of the first block handle the remainder to avoid complex divergence
        if (idx == 0) {
            for (int i = vec_size * 4; i < size; ++i) {
                float val = input[i];
