avg_pool_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool1d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_length,
    const int output_length,
    const int kernel_size,
    const int stride,
    const int padding) 
{
    // Global thread index
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_elements = batch_size * channels * output_length;

    if (idx < total_elements) {
        // Map linear index to (batch, channel, output_pos) coordinates
        // Layout is (N, C, L)
        const int out_pos = idx % output_length;
        const int c = (idx / output_length) % channels;
        const int b = idx / (output_length * channels);

        // Calculate the starting index of the window in the input tensor for the spatial dimension
        // Formula: start = out_pos * stride - padding
        const int in_start = out_pos * stride - padding;

        float sum = 0.0f;

        // Calculate the pointer offset for the current batch and channel
        const int input_offset = (b * channels + c) * input_length;

        // Iterate over the kernel window
        #pragma unroll
        for (int k = 0; k < kernel_size; ++k) {
            int in_pos = in_start + k;

            // Check boundaries for padding (implicit zero padding)
            if (in_pos >= 0 && in_pos < input_length) {
                sum += input[input_offset + in_pos];
            }
        }

        // Write result: Average = sum / kernel_size
        // Standard PyTorch AvgPool1d (with count_include_pad=True default) divides by kernel_size
        output[idx] = sum / static_cast<float>(kernel_size);
    }
}

