# Define the custom CUDA kernel for Transposed 1D Convolution
conv_transpose1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int length_in,
    int length_out,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    // Map threads to output elements
    // Grid dimensions: 
    // x: length_out
    // y: out_channels
    // z: batch_size

    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y;
    int n = blockIdx.z;

    // Boundary check
    if (l_out >= length_out || c_out >= out_channels || n >= batch_size) {
        return;
    }

    float val = 0.0f;

    // Add bias if present
    if (bias != nullptr) {
        val = bias[c_out];
    }

    // Transposed Convolution Operation
    // We iterate over the kernel positions k.
    // For a given output position l_out, we want to find the corresponding input position l_in
    // such that: l_in * stride + k * dilation - padding = l_out
    // This implies: l_in * stride = l_out - k * dilation + padding

    for (int k = 0; k < kernel_size; ++k) {
        int numerator = l_out - k * dilation + padding;

        // Check valid conditions:
        // 1. Numerator must be non-negative (implicit in logic for valid indices usually, but good for safety)
        // 2. Numerator must be divisible by stride to map to an integer input index
        if (numerator >= 0 && (numerator % stride == 0)) {
            int l_in = numerator / stride;

            // Check if calculated input index is within bounds
            if (l_in >= 0 && l_in < length_in) {
                // Accumulate dot product over input channels
                for (int c_in = 0; c_in < in_channels; ++c_in) {
                    // Calculate offsets for 1D arrays
                    // Input: (N, C_in, L_in)
                    int input_idx = n * (in_channels * length_in) + c_in * length_in + l_in;

                    // Weight: (C_in, C_out, K) - standard PyTorch layout for ConvTranspose1d
                    int weight_idx = c_in * (out_channels * kernel_size) + c_out * kernel_size + k;

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    // Write result
    // Output: (N, C_out, L_out)
    int output_idx = n * (out_channels * length_out) + c_out * length_out + l_out;
    output[output_idx] = val;
}

torch::Tensor conv_transpose1d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int dilation) {

    // Get tensor dimensions
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto length_in = input.size(2);

    auto out_channels = weight.size(1);
    auto kernel_size = weight.size(2);

    // Calculate output length according to ConvTranspose formula
    auto length_out = (length_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1;

    // Allocate output tensor
    auto output = torch::zeros({batch_size, out_channels, length_out}, input.options());

    // Handle bias
    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = bias.data_ptr<float>();
    }

    // Configure CUDA grid
    const int block_size = 256;
    dim3 grid_dim((length_out + block_size - 1) / block_size, out_channels, batch_size);

    // Launch kernel
    conv_transpose1d_kernel<<<grid_dim, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels, length_in, length_out,
        kernel_size, stride, padding, dilation
    );

    return output;
}
"""

conv_transpose1d_cpp_source = (
    "torch::Tensor conv_transpose1d_cuda_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding, int output_padding, int dilation);"
)

# Compile the inline CUDA code
conv_transpose_op = load_inline(
    name="conv_transpose1d_custom",
    cpp_sources=conv_transpose1d_cpp_source,
    cuda_sources=conv_transpose1d_source,
    functions=["conv_transpose1d_cuda_forward"],
    verbose=True,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.output_padding = 0  # Default for nn.ConvTranspose1d and Model

        # Manually register parameters to replicate nn.ConvTranspose1d structure
        # Weight shape for ConvTranspose1d: (in_channels, out_channels, kernel_size) when groups=1
        self.weight = nn.Parameter(torch.Tensor(in_channels, out_channels, kernel_size))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        # Initialize weights similar to PyTorch default
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in != 0:
                bound = 1 / (fan_in ** 0.5)
                nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 1D convolution using custom CUDA kernel.
        """
        # Ensure inputs are contiguous for direct pointer access in CUDA
        x = x.contiguous()

        # Prepare bias tensor (pass empty tensor if bias is None)
        bias_tensor = self.bias if self.bias is not None else torch.empty(0, device=x.device, dtype=x.dtype)

        return conv_transpose_op.conv_transpose1d_cuda_forward(
            x,
            self.weight,
            bias_tensor,
            self.stride,
            self.padding,
            self.output_padding,
            self.dilation
        )

