import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA Kernel for C = A * B^T
// A: (M, K)
// B: (N, K)
// C: (M, N)
//
// Optimizations:
// 1. Tiled Shared Memory (Block blocking) to reduce global memory bandwidth usage.
// 2. Coalesced Global Memory Accesses for both A and B.
// 3. Shared Memory Padding to avoid bank conflicts.

__global__ void matmul_ab_t_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // Tile size (BLOCK_SIZE)
    const int BS = 32;

    // Block and Thread indices
    int bx = blockIdx.x; // Block index for N (columns of C)
    int by = blockIdx.y; // Block index for M (rows of C)
    int tx = threadIdx.x; // Thread index within block (col)
    int ty = threadIdx.y; // Thread index within block (row)

    // Global coordinates for the result C element being computed
    int row = by * BS + ty;
    int col = bx * BS + tx;

    // Accumulator
    float val = 0.0f;

    // Shared memory buffers
    // Padding [33] instead of [32] to avoid bank conflicts during transposed access
    __shared__ float sA[32][33];
    __shared__ float sB[32][33];

    // Loop over the K dimension in chunks of BS
    for (int k = 0; k < K; k += BS) {

        // 1. Load tile from A into shared memory
        // We need A[row, k...k+BS].
        // Global read: A[row * K + (k + tx)]
        // Since 'row' is constant for a warp (assuming warp along x for visualization, though mapped to ty here),
        // and 'tx' varies, we are reading contiguous memory (k+tx). This is coalesced.
        if (row < M && (k + tx) < K) {
            sA[ty][tx] = A[row * K + (k + tx)];
        } else {
            sA[ty][tx] = 0.0f;
        }

        // 2. Load tile from B into shared memory
        // We need B rows corresponding to the columns of C we are computing.
        // The block covers C columns [bx*BS ... bx*BS+BS].
        // So we need B rows [bx*BS ... bx*BS+BS].
        // To ensure coalesced reading, we read B in a way that fits global memory layout.
        // We have thread (ty, tx).
        // Let's have thread (ty, tx) load: B[(bx*BS + ty) * K + (k + tx)].
        // This corresponds to row `bx*BS + ty` of B.
        // Note: This row of B corresponds to column `bx*BS + ty` of C.
        // However, this thread (ty, tx) is responsible for C at column `bx*BS + tx`.
        // So we are loading data that will be used by *other* threads in the block (specifically threads with threadIdx.x == ty).
        // We store this into sB in a transposed manner to facilitate access during computation.
        // sB[tx][ty] = loaded_value.
        // This stores B[bx*BS+ty, k+tx] at sB[tx][ty].
        // Bank Conflict Check (Write): 
        // Index = tx * 33 + ty. 'tx' varies 0..31 in warp. Stride 33 is coprime to 32. No conflicts.

        int b_row = bx * BS + ty;
        int b_col = k + tx;

        if (b_row < N && b_col < K) {
            sB[tx][ty] = B[b_row * K + b_col];
        } else {
            sB[tx][ty] = 0.0f;
        }

        __syncthreads();

        // 3. Compute partial dot product for this tile
        // We calculate dot product of A[row, :] and B[col, :].
        // Loop 'i' from 0 to BS.
        // Term: A[row, k+i] * B[col, k+i].
        // Shared Memory Mapping:
        // A[row, k+i] is located at sA[ty][i].
        // B[col, k+i]: Our current global C column is `col` = bx*BS + tx.
        // So we need row `bx*BS + tx` from B.
        // In our loading step, row `bx*BS + r` was stored in sB column `r` (sB[:][r]).
        // Specifically, B[bx*BS+ty, k+tx] -> sB[tx][ty].
        // So B[bx*BS+tx, k+i] (row `tx`, col `i` inside tile) is at sB[i][tx].
        // Bank Conflict Check (Read):
        // Access sB[i][tx]. 'i' is constant (loop var). 'tx' varies 0..31.
        // Index = i * 33 + tx. Stride 1. No conflicts.

        #pragma unroll
        for (int i = 0; i < BS; ++i) {
            val += sA[ty][i] * sB[i][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A: (M, K)
    // B: (N, K)

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    auto C = torch::zeros({M, N}, A.options());

    const int BS = 32;
    dim3 block(BS, BS);
    dim3 grid((N + BS - 1) / BS, (M + BS - 1) / BS);

    matmul_ab_t_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, N, K
    );

    return C;
}
"""

cpp_source = "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
custom_matmul_op = load_inline(
    name="custom_matmul_op",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["custom_matmul_cuda"],
    verbose=True,
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    """
    Optimized model using custom CUDA kernel for Matrix Multiplication (C = A * B^T)
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = custom_matmul_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication using custom CUDA kernel.

        Args:
            A: Input tensor of shape (M, K).
            B: Input tensor of shape (N, K).

        Returns:
            Output tensor of shape (M, N).
        """
        # The original model computed torch.matmul(A, B.T)
        # Our custom kernel takes A and B (N, K) and computes A * B^T internally
        return self.matmul_op.custom_matmul_cuda(A, B)

