import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 1D Transposed Convolution
conv_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_stride1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch,
    int in_channels,
    int out_channels,
    int length_in,
    int kernel_size,
    int length_out) {

    // Dynamic shared memory for input tile
    extern __shared__ float s_mem[];

    // Thread and Block indices
    int tx = threadIdx.x; // mapped to output length tile (0..31)
    int ty = threadIdx.y; // mapped to output channel tile (0..7)
    int bx = blockIdx.x;  // tile index along length
    int by = blockIdx.y;  // tile index along out_channels
    int b  = blockIdx.z;  // batch index

    int tile_w = blockDim.x; // 32

    // Global output coordinates
    int c_out_global = by * blockDim.y + ty;
    int t_out_global = bx * tile_w + tx;

    // Shared memory layout: [in_channels, tile_w + kernel_size - 1]
    // The width includes the necessary halo for the convolution window
    int smem_width = tile_w + kernel_size - 1;

    // Calculate global input start index corresponding to this tile
    // For ConvTranspose1d (stride 1, full padding logic): 
    // Out[t] depends on In[t-k].
    // The tile computes Out[t] for t in [bx*32, bx*32+31].
    // Max index needed: t (when k=0). Min index needed: t - (K-1) (when k=K-1).
    // Start loading from:
    int t_start_load = bx * tile_w - (kernel_size - 1);

    const float* input_b = input + b * in_channels * length_in;

    // Cooperative loading of Input tile into Shared Memory
    int tid = ty * tile_w + tx;
    int num_threads = blockDim.x * blockDim.y;
    int total_elements = in_channels * smem_width;

    for (int i = tid; i < total_elements; i += num_threads) {
        int ch = i / smem_width;
        int t_offset = i % smem_width;
        int t_in_idx = t_start_load + t_offset;

        float val = 0.0f;
        // Boundary check for input (padding 0)
        if (t_in_idx >= 0 && t_in_idx < length_in) {
            val = input_b[ch * length_in + t_in_idx];
        }
        s_mem[ch * smem_width + t_offset] = val;
    }

    __syncthreads();

    // Compute Convolution
    if (c_out_global < out_channels && t_out_global < length_out) {
        float acc = 0.0f;

        // Add bias if present
        if (bias != nullptr) {
            acc = bias[c_out_global];
        }

        // Accumulate over input channels and kernel positions
        for (int cin = 0; cin < in_channels; ++cin) {
            // Weight layout is (In, Out, K)
            // Flattened index base for this (cin, cout) pair
            int w_offset_base = cin * (out_channels * kernel_size) + c_out_global * kernel_size;

            // Pointer to the specific channel row in shared memory
            float* s_mem_cin = s_mem + cin * smem_width;

            // Convolution sum: out[t] += in[t-k] * w[k]
            // In shared memory, 't' (relative to tile start) is at index:
            //   (t_out_global - t_start_load) = tx + kernel_size - 1
            // So in[t-k] is at index: tx + kernel_size - 1 - k

            #pragma unroll
            for (int k = 0; k < kernel_size; ++k) {
                float w_val = weight[w_offset_base + k];
                float in_val = s_mem_cin[tx + (kernel_size - 1) - k];
                acc += in_val * w_val;
            }
        }

        // Write result
        int out_idx = b * out_channels * length_out + c_out_global * length_out + t_out_global;
        output[out_idx] = acc;
    }
}

torch::Tensor conv_transpose1d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int dilation) {

    // Performance constraints checks
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(stride == 1, "Optimized kernel requires stride=1");
    TORCH_CHECK(padding == 0, "Optimized kernel requires padding=0");
    TORCH_CHECK(dilation == 1, "Optimized kernel requires dilation=1");
    TORCH_CHECK(groups == 1, "Optimized kernel requires groups=1");

    int batch = input.size(0);
    int in_channels = input.size(1);
    int length_in = input.size(2);
    int out_channels = weight.size(1); // Weight shape: (in, out, k)
    int kernel_size = weight.size(2);

    // Output length for stride=1, padding=0
    int length_out = length_in + kernel_size - 1 + output_padding; 

    auto output = torch::zeros({batch, out_channels, length_out}, input.options());

    // Kernel Launch Configuration
    const int tile_w = 32;
    const int tile_c = 8;

    dim3 block(tile_w, tile_c);
    dim3 grid((length_out + tile_w - 1) / tile_w, (out_channels + tile_c - 1) / tile_c, batch);

    // Shared memory: InChannels * (TileWidth + KernelSize - 1) * sizeof(float)
    // For 128 channels, K=3, Tile=32 -> 128 * 34 * 4 bytes ~= 17 KB (fits well in L1/Shared)
    size_t smem_size = in_channels * (tile_w + kernel_size - 1) * sizeof(float);

    const float* bias_ptr = (bias.defined()) ? bias.data_ptr<float>() : nullptr;

    conv_transpose1d_stride1_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch,
        in_channels,
        out_channels,
        length_in,
        kernel_size,
        length_out
    );

    return output;
}
"""

conv_transpose_cpp_source = (
    "torch::Tensor conv_transpose1d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding, int output_padding, int groups, int dilation);"
