# Define the custom CUDA kernel for 2D Transposed Convolution
conv_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_cuda_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int k_h, int k_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups) 
{
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_h * out_w;

    if (index >= total_elements) return;

    // Output layout: (N, C_out, H_out, W_out)
    int pw = index % out_w;
    int tmp = index / out_w;
    int ph = tmp % out_h;
    tmp = tmp / out_h;
    int poc = tmp % out_channels;
    int pn = tmp / out_channels;

    float val = 0.0f;
    if (bias != NULL) {
        val = bias[poc];
    }

    int channels_per_group_out = out_channels / groups;
    int channels_per_group_in = in_channels / groups;
    int group_id = poc / channels_per_group_out;
    int oc_in_group = poc % channels_per_group_out;

    // Start index of input channels for this group
    int ic_start = group_id * channels_per_group_in;

    // Pre-calculate strides for manual indexing
    int input_stride_n = in_channels * in_h * in_w;
    int input_stride_c = in_h * in_w;
    int input_stride_h = in_w;

    int weight_stride_ic = channels_per_group_out * k_h * k_w;
    int weight_stride_oc = k_h * k_w;
    int weight_stride_h = k_w;

    const float* input_batch = input + pn * input_stride_n;

    // Iterate over kernel dimensions to find contributing input pixels
    for (int kh = 0; kh < k_h; ++kh) {
        // Inverse relationship: ph = pih * stride_h - pad_h + kh * dil_h
        // pih = (ph + pad_h - kh * dil_h) / stride_h
        int h_prime = ph + pad_h - kh * dil_h;

        // Check if a valid input index exists for this kernel position
        if (h_prime >= 0 && (h_prime % stride_h == 0)) {
            int pih = h_prime / stride_h;

            if (pih >= 0 && pih < in_h) {
                for (int kw = 0; kw < k_w; ++kw) {
                    int w_prime = pw + pad_w - kw * dil_w;

                    if (w_prime >= 0 && (w_prime % stride_w == 0)) {
                        int piw = w_prime / stride_w;

                        if (piw >= 0 && piw < in_w) {

                            // Accumulate over input channels in the group
                            for (int i = 0; i < channels_per_group_in; ++i) {
                                int ic = ic_start + i;

                                int in_idx = ic * input_stride_c + pih * input_stride_h + piw;
                                float in_val = input_batch[in_idx];

                                // Weight shape: (in_channels, out_channels/groups, k_h, k_w)
                                int w_idx = ic * weight_stride_ic + oc_in_group * weight_stride_oc + kh * weight_stride_h + kw;
                                float w_val = weight[w_idx];

                                val += in_val * w_val;
                            }
                        }
                    }
                }
            }
        }
    }

    output[index] = val;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int out_pad_h, int out_pad_w,
    int dil_h, int dil_w,
    int groups)
{
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_h = input.size(2);
    auto in_w = input.size(3);

    auto out_channels_per_group = weight.size(1);
    auto k_h = weight.size(2);
    auto k_w = weight.size(3);
    auto out_channels = out_channels_per_group * groups;

    // Calculate output dimensions
    auto out_h = (in_h - 1) * stride_h - 2 * pad_h + dil_h * (k_h - 1) + out_pad_h + 1;
    auto out_w = (in_w - 1) * stride_w - 2 * pad_w + dil_w * (k_w - 1) + out_pad_w + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::empty({batch_size, out_channels, out_h, out_w}, options);

    const int block_size = 256;
    int total_elements = batch_size * out_channels * out_h * out_w;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* bias_ptr = (bias.defined() && bias.numel() > 0) ? bias.data_ptr<float>() : NULL;

    conv_transpose2d_cuda_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, out_h, out_w,
        k_h, k_w,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w,
        groups
    );

    return output;
}
"""

