import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 4D Tensor-Matrix multiplication
# This implements a Tiled Matrix Multiplication (GEMM)
# A is treated as (M, K), B is (K, N), C is (M, N)
# M = b * i * j, K = l, N = k
custom_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_WIDTH 16

__global__ void matmul_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // We map M (rows of result) to blockIdx.x because M can be large 
    // and gridDim.x limit is 2^31-1, whereas gridDim.y limit is 65535.
    // We map N (cols of result) to blockIdx.y.

    // Global row and col indices
    // blockDim.y and blockDim.x are both TILE_WIDTH (16)
    int row = blockIdx.x * TILE_WIDTH + threadIdx.y;
    int col = blockIdx.y * TILE_WIDTH + threadIdx.x;

    float val = 0.0f;

    __shared__ float As[TILE_WIDTH][TILE_WIDTH];
    __shared__ float Bs[TILE_WIDTH][TILE_WIDTH];

    int num_tiles = (K + TILE_WIDTH - 1) / TILE_WIDTH;

    for (int t = 0; t < num_tiles; ++t) {

        // Load A tile into shared memory
        // We want A[row][t*TILE + tx]
        // This corresponds to A[row * K + current_col]
        // Global memory access coalescence: row is constant for warp sections, tx varies. Coalesced.
        int tiled_col = t * TILE_WIDTH + threadIdx.x;

        if (row < M && tiled_col < K) {
            As[threadIdx.y][threadIdx.x] = A[row * K + tiled_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load B tile into shared memory
        // We want B[t*TILE + ty][col]
        // This corresponds to B[current_row * N + col]
        // Global memory access coalescence: current_row depends on ty, col depends on tx. Coalesced.
        int tiled_row = t * TILE_WIDTH + threadIdx.y;

        if (tiled_row < K && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tiled_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product for this tile
        // Standard matmul tile accumulation
        for (int k = 0; k < TILE_WIDTH; ++k) {
            val += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Checks
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 4, "A must be 4D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(3) == B.size(0), "Inner dimensions must match");

    int b = A.size(0);
    int i = A.size(1);
    int j = A.size(2);
    int l = A.size(3);
    int k = B.size(1);

    // Flatten A dimensions: (b, i, j, l) -> (M, K)
    int M = b * i * j;
    int K_dim = l;
    int N = k;

    auto C = torch::zeros({b, i, j, k}, A.options());

    dim3 block(TILE_WIDTH, TILE_WIDTH);
    // Grid X covers M (rows), Grid Y covers N (cols)
    dim3 grid((M + TILE_WIDTH - 1) / TILE_WIDTH, (N + TILE_WIDTH - 1) / TILE_WIDTH);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K_dim
    );

    return C;
}
"""

custom_matmul_cpp_source = (
    "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
custom_matmul_op = load_inline(
    name="custom_matmul",
    cpp_sources=custom_matmul_cpp_source,
    cuda_sources=custom_matmul_source,
    functions=["custom_matmul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = custom_matmul_op

    def forward(self, A, B):
        """
        Performs the 4D tensor-matrix multiplication using custom CUDA kernel.
        """
        return self.matmul_op.custom_matmul_cuda(A, B)

