    int in_channels_per_group = in_channels / groups;
    int group_id = c_out / out_channels_per_group;
    int c_out_rel = c_out % out_channels_per_group;

    // Initialize accumulator with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[c_out];
    }

    // Weight Layout: (in_channels, out_channels/groups, k_d, k_h, k_w)
    // Input Layout: (batch, in_channels, in_depth, in_height, in_width)

    // Calculate strides for efficient indexing
    int w_stride_cin = out_channels_per_group * k_d * k_h * k_w;
    int w_stride_cout = k_d * k_h * k_w;

    int i_stride_n = in_channels * in_depth * in_height * in_width;
    int i_stride_cin = in_depth * in_height * in_width;
    int i_stride_d = in_height * in_width;
    int i_stride_h = in_width;

    // The output position (oz, oy, ox) is computed from input (iz, iy, ix) by:
    // oz = iz * stride - pad + k
    // We reverse this to iterate over relevant kernel positions 'k' that contribute to 'oz'
    // such that the corresponding 'iz' is valid and an integer.
    // iz = (oz + pad - k) / stride
    // Conditions:
    // 1. (oz + pad - k) % stride == 0  => k % stride == (oz + pad) % stride
    // 2. 0 <= iz < in_size

    int start_kd = (d_out + pad_d) % stride_d;
    int start_kh = (h_out + pad_h) % stride_h;
    int start_kw = (w_out + pad_w) % stride_w;

    int cin_start = group_id * in_channels_per_group;
    int i_base_batch = b * i_stride_n;
    int w_base_cout = c_out_rel * w_stride_cout;

    for (int kd = start_kd; kd < k_d; kd += stride_d) {
        int iz = (d_out + pad_d - kd) / stride_d;
        if (iz < 0 || iz >= in_depth) continue;
        int i_offset_d = iz * i_stride_d;

        for (int kh = start_kh; kh < k_h; kh += stride_h) {
            int iy = (h_out + pad_h - kh) / stride_h;
            if (iy < 0 || iy >= in_height) continue;
            int i_offset_h = iy * i_stride_h;

            for (int kw = start_kw; kw < k_w; kw += stride_w) {
                int ix = (w_out + pad_w - kw) / stride_w;
                if (ix < 0 || ix >= in_width) continue;

                int w_spatial = (kd * k_h + kh) * k_w + kw;
                int w_idx_base = w_base_cout + w_spatial;
                int i_idx_base = i_base_batch + i_offset_d + i_offset_h + ix;

                // Sum contribution from all input channels in the group
                for (int c = 0; c < in_channels_per_group; ++c) {
                    float w_val = weight[(cin_start + c) * w_stride_cin + w_idx_base];
                    float i_val = input[(cin_start + c) * i_stride_cin + i_idx_base];
                    val += w_val * i_val;
                }
            }
        }
    }

    output[idx] = val;
}

