#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int k_h,
    int k_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w,
    int groups) {

    // Output coordinates mapped to threads and blocks
    // Block: (16, 16) -> (ow, oh)
    // Grid: (ceil(out_w/16), ceil(out_h/16), batch_size * out_channels)

    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int bc = blockIdx.z; // Combined batch and output channel index

    // Boundary check for output spatial dimensions
    if (ow >= out_w || oh >= out_h) return;

    // Decode batch and output channel from blockIdx.z
    int oc = bc % out_channels;
    int n = bc / out_channels;

    // Group convolution logic
    int in_channels_per_group = in_channels / groups;
    int out_channels_per_group = out_channels / groups;
    int group_id = oc / out_channels_per_group;
    int input_c_start = group_id * in_channels_per_group;

    // Initialize with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[oc];
    }

    // Direct convolution loop
    for (int ic_g = 0; ic_g < in_channels_per_group; ++ic_g) {
        int ic = input_c_start + ic_g;
        for (int ki = 0; ki < k_h; ++ki) {
            for (int kj = 0; kj < k_w; ++kj) {
                // Calculate input spatial coordinates
                int in_row = oh * stride_h - pad_h + ki * dil_h;
                int in_col = ow * stride_w - pad_w + kj * dil_w;

                // Check padding boundaries
                if (in_row >= 0 && in_row < in_h && in_col >= 0 && in_col < in_w) {
                    // Input index: (n, ic, in_row, in_col)
                    int input_idx = ((n * in_channels + ic) * in_h + in_row) * in_w + in_col;

                    // Weight index: (oc, ic_g, ki, kj)
                    // PyTorch Weight Shape: [out_channels, in_channels/groups, k_h, k_w]
                    int weight_idx = ((oc * in_channels_per_group + ic_g) * k_h + ki) * k_w + kj;

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    // Write to output: (n, oc, oh, ow)
    int out_idx = ((n * out_channels + oc) * out_h + oh) * out_w + ow;
    output[out_idx] = val;
}

torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_channels = weight.size(0);
    int k_h = weight.size(2);
    int k_w = weight.size(3);

    // Calculate output dimensions
    int out_h = (in_h + 2 * pad_h - dil_h * (k_h - 1) - 1) / stride_h + 1;
    int out_w = (in_w + 2 * pad_w - dil_w * (k_w - 1) - 1) / stride_w + 1;

    // Allocate output tensor
    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = bias.data_ptr<float>();
    }

    // Launch configuration
    // Use 16x16 threads per block to tile the output spatially
    dim3 block(16, 16);
    dim3 grid((out_w + 15) / 16, (out_h + 15) / 16, batch_size * out_channels);

    conv2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_h, in_w, out_h, out_w,
        k_h, k_w,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w,
        groups
    );

    return output;
}
"""

