custom_conv2d = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized implementation of the original Model using custom CUDA convolution kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Helper to ensure tuple format for kernel parameters
        def to_pair(x):
            if isinstance(x, (list, tuple)):
                return x
            return (x, x)

        self.kernel_size = to_pair(kernel_size)
        self.stride = to_pair(stride)
        self.padding = to_pair(padding)
        self.dilation = to_pair(dilation)
        self.groups = groups

        # Manually register parameters to replicate nn.Conv2d behavior
        self.weight = nn.Parameter(torch.Tensor(
            out_channels, in_channels // groups, *self.kernel_size
        ))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()
        self.conv_op = custom_conv2d

    def reset_parameters(self):
        # Kaiming initialization
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in != 0:
                bound = 1 / (fan_in**0.5)
                nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 2D convolution using the custom CUDA kernel.
        """
        bias_tensor = self.bias
        if bias_tensor is None:
            # Pass an empty tensor if bias is not used, as C++ expects a tensor object
            bias_tensor = torch.empty(0, device=x.device, dtype=x.dtype)

        return self.conv_op.conv2d_cuda(
            x, self.weight, bias_tensor,
            self.stride[0], self.stride[1],
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1],
            self.groups
        )

