import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
# Implements a Matrix-Vector Multiplication optimized for large K.
# - Uses float4 vectorized loads to maximize memory bandwidth.
# - Uses warp-level primitives for efficient reduction.
# - Assigns one thread block per row of A to compute the dot product.
mvm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void mvm_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K) {
    // Each block computes one element of C (dot product of one row of A with B)
    int row = blockIdx.x;
    if (row >= M) return;

    int tid = threadIdx.x;
    int lane = tid % 32;
    int warpId = tid / 32;

    float sum = 0.0f;

    // Vectorized load optimization using float4
    // We assume K is divisible by 4 and pointers are aligned (standard in PyTorch)
    int K_vec = K / 4;
    const float4* A_ptr = reinterpret_cast<const float4*>(A + row * K);
    const float4* B_ptr = reinterpret_cast<const float4*>(B);

    // Grid-stride loop (effectively striding by block size within the row)
    for (int i = tid; i < K_vec; i += blockDim.x) {
        float4 a_val = A_ptr[i];
        float4 b_val = B_ptr[i];
        sum += a_val.x * b_val.x + a_val.y * b_val.y + a_val.z * b_val.z + a_val.w * b_val.w;
    }

    // Warp Reduction
    sum = warpReduceSum(sum);

    // Shared memory for intermediate warp results
    extern __shared__ float sdata[];

    // First thread of each warp writes to shared memory
    if (lane == 0) {
        sdata[warpId] = sum;
    }

    __syncthreads();

    // Block Reduction
    // Only the first warp is needed to reduce the partial sums from shared memory
    if (warpId == 0) {
        int num_warps = blockDim.x / 32;
        float val = (tid < num_warps) ? sdata[tid] : 0.0f;

        // Final warp reduction
        val = warpReduceSum(val);

        // Write result
        if (tid == 0) {
            C[row] = val;
        }
    }
}

torch::Tensor mvm_cuda(torch::Tensor A, torch::Tensor B) {
    // Checks
    TORCH_CHECK(A.is_cuda, "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda, "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");

    // Ensure inputs are contiguous for pointer arithmetic and vectorization
    if (!A.is_contiguous()) A = A.contiguous();
    if (!B.is_contiguous()) B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);

    TORCH_CHECK(K % 4 == 0, "K must be divisible by 4 for float4 optimization");

    auto C = torch::empty({M, 1}, A.options());

    // Kernel configuration
    const int threads = 256;
    const int blocks = M;
    const int shared_mem = (threads / 32) * sizeof(float);

    mvm_kernel<<<blocks, threads, shared_mem>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
"""

mvm_cpp_source = "torch::Tensor mvm_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
mvm_module = load_inline(
    name="mvm_module",
