        self.mvm = mvm_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix-vector multiplication using custom CUDA kernel.
        """
        return self.mvm.mvm_cuda(A, B)

