import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Triplet Margin Loss
# This kernel fuses the calculation of Euclidean distances for (anchor, positive) and (anchor, negative),
# applies the margin logic, and computes the loss per sample in one pass.
# It avoids allocating intermediate tensors for differences (which would be 2x size of input)
# and distances.

triplet_margin_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Warp reduction helper
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = warpSize / 2; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void triplet_margin_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ output,
    const int dim,
    const float margin) {

    // Each block processes one triplet in the batch
    int batch_idx = blockIdx.x;

    // Calculate global memory offsets for this batch item
    size_t offset = (size_t)batch_idx * dim;
    const float* a_ptr = anchor + offset;
    const float* p_ptr = positive + offset;
    const float* n_ptr = negative + offset;

    float sum_sq_p = 0.0f;
    float sum_sq_n = 0.0f;

    // Grid-stride loop (effectively block-stride since gridDim.x = batch_size)
    // Iterate over the feature dimension
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float a = a_ptr[i];
        float p = p_ptr[i];
        float n = n_ptr[i];

        float dp = a - p;
        float dn = a - n;

        sum_sq_p += dp * dp;
        sum_sq_n += dn * dn;
    }

    // Reduction within the block

    // 1. Warp-level reduction
    sum_sq_p = warpReduceSum(sum_sq_p);
    sum_sq_n = warpReduceSum(sum_sq_n);

    // 2. Block-level reduction using shared memory
    // We allocate enough shared memory for one value per warp.
    // Assuming block size of 256 or 512, max warps = 32 (for 1024 threads)
    __shared__ float shared_p[32];
    __shared__ float shared_n[32];

    int lane = threadIdx.x % warpSize;
    int wid = threadIdx.x / warpSize;

    // First thread of each warp writes result to shared memory
    if (lane == 0) {
        shared_p[wid] = sum_sq_p;
        shared_n[wid] = sum_sq_n;
    }

    __syncthreads();

    // 3. Final reduction by the first warp
    if (wid == 0) {
        // Load partial sums from shared memory
        // Check bounds if block size corresponds to fewer than 32 warps
        float val_p = (threadIdx.x < blockDim.x / warpSize) ? shared_p[threadIdx.x] : 0.0f;
        float val_n = (threadIdx.x < blockDim.x / warpSize) ? shared_n[threadIdx.x] : 0.0f;

        val_p = warpReduceSum(val_p);
        val_n = warpReduceSum(val_n);

        if (threadIdx.x == 0) {
            // Compute Euclidean distances
            // Add epsilon for numerical stability (matching PyTorch behavior)
            float dist_p = sqrtf(val_p + 1e-6f);
            float dist_n = sqrtf(val_n + 1e-6f);

