# Define the custom CUDA kernel for argmin
argmin_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void argmin_kernel(const float* __restrict__ x, int64_t* __restrict__ out, 
                              int dim_size, int inner_size, int total_output) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output) {
        // Map linear index to logical (outer, inner) coordinates
        // The tensor is viewed as (outer, dim_size, inner_size)
        // We are reducing along dim_size.
        int i = idx % inner_size;
        int o = idx / inner_size;

        // Calculate the base offset for this reduction column.
        // We want to access x[o, r, i] for r in 0..dim_size-1.
        // The flattened index is: o * (dim_size * inner_size) + r * inner_size + i.
        // Base offset (r=0): o * dim_size * inner_size + i.
        // We use int64_t to prevent overflow for large tensors.
        int64_t offset = static_cast<int64_t>(o) * dim_size * inner_size + i;

        float min_val = x[offset];
        int64_t min_idx = 0;

        // Loop over the reduction dimension.
        // Access pattern: x[base], x[base + inner_size], x[base + 2*inner_size], ...
        // Note: For inner_size > 1 (which is 4095 here), threads in a warp access 
        // adjacent elements in memory (coalesced reads) for the same 'r', 
        // because adjacent threads have adjacent 'i'.
        for (int r = 1; r < dim_size; ++r) {
            float val = x[offset + r * inner_size];
            if (val < min_val) {
                min_val = val;
                min_idx = r;
            }
        }

        out[idx] = min_idx;
    }
}

torch::Tensor argmin_cuda(torch::Tensor x, int64_t dim) {
    // Ensure input is contiguous and on CUDA
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    x = x.contiguous();

    // Handle negative dimension
    if (dim < 0) dim += x.dim();

    auto sizes = x.sizes();

    // Calculate flattened dimensions: outer, reduce_dim, inner
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) outer_size *= sizes[i];

    int dim_size = sizes[dim];

    int inner_size = 1;
    for (int i = dim + 1; i < x.dim(); ++i) inner_size *= sizes[i];

    // Determine output shape (dimension 'dim' is squeezed)
    std::vector<int64_t> out_shape;
    for (int i = 0; i < x.dim(); ++i) {
        if (i != dim) out_shape.push_back(sizes[i]);
    }

    auto out = torch::empty(out_shape, x.options().dtype(torch::kLong));

    int total_output = outer_size * inner_size;
    if (total_output == 0) return out;

    const int block_size = 256;
    const int num_blocks = (total_output + block_size - 1) / block_size;

    argmin_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<int64_t>(),
        dim_size,
        inner_size,
        total_output
    );

    return out;
}
"""

