import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BM 64
#define BN 64
#define BK 32
#define TM 4
#define TN 4

__global__ void skinny_matmul_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int K) 
{
    // A: (M, K)
    // B: (K, M)
    // C: (M, M)
    // Grid dimensions: (M / BN, M / BM)

    int bx = blockIdx.x;
    int by = blockIdx.y;

    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15
    int tid = ty * blockDim.x + tx; // 0..255

    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    // Load A into shared memory
    // A tile is (BM, BK) i.e. (64, 32)
    // Load using 256 threads. Each thread loads 8 elements.
    // A is row-major (M, K).
    // Access pattern optimization:
    // A[row][col] is stored at A[row*K + col].
    // Since K=32 is small and fixed, we can linearize the load for perfect coalescing.
    // The tile requires rows [by*BM, by*BM + BM)
    int a_tile_row_start = by * BM;

    #pragma unroll
    for (int i = 0; i < 8; ++i) {
        int idx = tid + i * 256; // range 0..2047
        int r = idx / BK;        // range 0..63
        int c = idx % BK;        // range 0..31

        // Global address: (a_tile_row_start + r) * K + c
        // This corresponds to a linear memory block starting at a_tile_row_start * K
        As[r][c] = A[(a_tile_row_start + r) * K + c];
    }

    // Load B into shared memory
    // B tile is (BK, BN) i.e. (32, 64)
    // B is (K, M).
    // We need columns [bx*BN, bx*BN + BN) for all K rows.
    // Memory address B[row][col] = B[row*M + col]
    // To coalesce global reads, threads should read adjacent columns.
    // We map threads to load chunks of rows.
    // Each thread loads 8 elements.
    // We can load 4 rows in parallel (256 threads / 64 columns = 4 rows per iter)
    int b_col_start = bx * BN;

    #pragma unroll
    for (int i = 0; i < 8; ++i) {
        // We cover 32 rows total. i ranges 0..7.
        // Each iteration processes 4 rows.
        // tid / 64 gives offset 0..3
        int row = i * 4 + (tid / 64);
        int col = tid % 64;

        Bs[row][col] = B[row * M + b_col_start + col];
    }

    __syncthreads();

    // Compute Matrix Multiply on Registers
    // Each thread computes a (TM, TN) sub-tile of C.
    // TM=4, TN=4.
    float results[TM * TN] = {0.0f};

    int ty_tm = ty * TM;
    int tx_tn = tx * TN;

    // Loop over K is eliminated since BK=K=32.
    // We just iterate k from 0 to 31.
    #pragma unroll
    for (int k = 0; k < BK; ++k) {
        float a_reg[TM];
        float b_reg[TN];

        // Load values from shared memory to registers
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            a_reg[i] = As[ty_tm + i][k];
        }
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            b_reg[j] = Bs[k][tx_tn + j];
        }

        // Outer product update
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                results[i * TN + j] += a_reg[i] * b_reg[j];
            }
        }
    }

    // Store results to global memory C
    int global_row = by * BM + ty_tm;
    int global_col = bx * BN + tx_tn;

    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            if (global_row + i < M && global_col + j < M) {
                C[(global_row + i) * M + (global_col + j)] = results[i * TN + j];
            }
        }
    }
}

torch::Tensor skinny_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    TORCH_CHECK(A.size(1) == 32, "This kernel is optimized for K=32");

    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::zeros({M, M}, A.options());

    dim3 block(16, 16);
    dim3 grid((M + 63) / 64, (M + 63) / 64);

    skinny_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, K
    );

    return C;
}
"""

cpp_source = "torch::Tensor skinny_matmul_cuda(torch::Tensor A, torch::Tensor B);"

skinny_matmul = load_inline(
    name="skinny_matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["skinny_matmul_cuda"],
    verbose=False,
    extra_cflags=['-O3'],
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = skinny_matmul

    def forward(self, A, B):
        return self.matmul_op.skinny_matmul_cuda(A, B)

