from torch.utils.cpp_extension import load_inline

# Define Custom CUDA Kernel
mse_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mse_kernel(const float* __restrict__ predictions, 
                           const float* __restrict__ targets, 
                           float* __restrict__ out, 
                           int64_t n) {
    // Shared memory for block reduction
    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;
    unsigned int gridSize = blockDim.x * gridDim.x;
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    float local_sum = 0.0f;

    // Grid-stride loop: processes the data even if n > grid_size * block_size
    for (int64_t i = idx; i < n; i += gridSize) {
        float diff = predictions[i] - targets[i];
        local_sum += diff * diff;
    }

    sdata[tid] = local_sum;
    __syncthreads();

    // Block reduction (assumes block_size is power of 2, e.g., 256)
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Atomic accumulation to global output
    if (tid == 0) {
        atomicAdd(out, sdata[0]);
    }
}

torch::Tensor mse_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure inputs are contiguous
    if (!predictions.is_contiguous()) predictions = predictions.contiguous();
    if (!targets.is_contiguous()) targets = targets.contiguous();

    auto n = predictions.numel();
    auto out = torch::zeros({}, predictions.options()); // Scalar output initialized to 0

    const int block_size = 256;
    // Cap the grid size to avoid excessive overhead on large inputs; use loops inside kernel instead
    int num_blocks = (n + block_size - 1) / block_size;
    if (num_blocks > 2048) num_blocks = 2048;

    mse_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        out.data_ptr<float>(),
        n
    );

    // Compute mean
    return out / static_cast<float>(n);
}
"""

