#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int kernel_size,
    int stride,
    int padding) {

    // Grid dimensions:
    // x: Output Width
    // y: Output Height
    // z: Batch Size * Out Channels

    int w_out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int nc_idx = blockIdx.z;

    if (w_out_idx >= out_w || h_out_idx >= out_h) return;

    int o = nc_idx % out_channels;
    int n = nc_idx / out_channels;

    // Depthwise logic for groups = in_channels
    // Each input channel connects to (out_channels / in_channels) output channels.
    // Assuming out_channels is a multiple of in_channels.
    int multiplier = out_channels / in_channels;
    int i = o / multiplier;

    // Input layout: (N, C, H, W)
    int input_offset = (n * in_channels + i) * (in_h * in_w);

    // Weight layout: (Out_C, 1, K, K) for depthwise
    int weight_offset = o * (kernel_size * kernel_size);

    float sum = 0.0f;

    for (int ky = 0; ky < kernel_size; ++ky) {
        int h_in = h_out_idx * stride - padding + ky;
        if (h_in >= 0 && h_in < in_h) {
            for (int kx = 0; kx < kernel_size; ++kx) {
                int w_in = w_out_idx * stride - padding + kx;
                if (w_in >= 0 && w_in < in_w) {
                    float val = input[input_offset + h_in * in_w + w_in];
                    float w_val = weight[weight_offset + ky * kernel_size + kx];
                    sum += val * w_val;
                }
            }
        }
    }

    if (bias != nullptr) {
        sum += bias[o];
    }

    // Output layout: (N, Out_C, Out_H, Out_W)
    int output_offset = (nc_idx * out_h * out_w) + (h_out_idx * out_w) + w_out_idx;
    output[output_offset] = sum;
}

