#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void maxpool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_height,
    int out_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    // The grid z-dimension maps to (batch, channel)
    int nc = blockIdx.z;
    int n = nc / channels;
    int c = nc % channels;

    // The grid x and y dimensions map to the output spatial dimensions
    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;

    if (ow < out_width && oh < out_height && n < batch_size && c < channels) {

        // Calculate offsets for input and output
        int input_offset = (n * channels + c) * (height * width);
        int output_offset = (n * channels + c) * (out_height * out_width) + oh * out_width + ow;

        float max_val = -FLT_MAX;

        // Calculate the starting position of the window in the input
        int h_start = oh * stride - padding;
        int w_start = ow * stride - padding;

        // Iterate over the kernel window
        for (int kx = 0; kx < kernel_size; ++kx) {
            for (int ky = 0; ky < kernel_size; ++ky) {
                int h_in = h_start + kx * dilation;
                int w_in = w_start + ky * dilation;

                // Check bounds (handle padding)
                if (h_in >= 0 && h_in < height && w_in >= 0 && w_in < width) {
                    float val = input[input_offset + h_in * width + w_in];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }
        output[output_offset] = max_val;
    }
