import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for cumulative sum along the last dimension
# This kernel is optimized for row-wise contiguous scans.
scan_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void scan_last_dim_kernel(const float* __restrict__ input, float* __restrict__ output, int batch_size, int scan_size) {
    // Each block processes one row (one batch item)
    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Calculate pointers to the start of the row
    // Using long long for offset calculation to be safe against large tensors, 
    // though 32768^2 fits in int32.
    long long offset = (long long)row * scan_size;
    const float* row_in = input + offset;
    float* row_out = output + offset;

    float running_sum = 0.0f;
    int tid = threadIdx.x;

    // Warp configuration
    const int WARP_SIZE = 32;
    // Assumes blockDim.x is a multiple of WARP_SIZE (e.g., 256)
    const int WARPS_PER_BLOCK = blockDim.x / WARP_SIZE;

    // Shared memory to store total sum of each warp
    extern __shared__ float warp_totals[]; 

    // Iterate over the row in chunks of size blockDim.x
    for (int base = 0; base < scan_size; base += blockDim.x) {
        int idx = base + tid;
        float val = (idx < scan_size) ? row_in[idx] : 0.0f;

        // 1. Inclusive scan within the warp (Hillis-Steele via Shuffle)
        float warp_sum = val;
        unsigned int mask = 0xffffffff;

        #pragma unroll
        for (int offset = 1; offset < WARP_SIZE; offset <<= 1) {
            float n = __shfl_up_sync(mask, warp_sum, offset);
            if ((tid & (WARP_SIZE - 1)) >= offset) warp_sum += n;
        }

        // 2. The last thread of each warp stores the warp's total to shared memory
        int warp_id = tid / WARP_SIZE;
        int lane_id = tid % WARP_SIZE;

        if (lane_id == WARP_SIZE - 1) {
            warp_totals[warp_id] = warp_sum;
        }
        __syncthreads();

        // 3. Scan the warp totals (executed by the first warp only)
        // We scan the 'warp_totals' array which has size WARPS_PER_BLOCK
        if (warp_id == 0) {
            float block_val = (lane_id < WARPS_PER_BLOCK) ? warp_totals[lane_id] : 0.0f;
            float block_scan = block_val;

            #pragma unroll
            for (int offset = 1; offset < WARP_SIZE; offset <<= 1) { 
                // We use loop limit WARP_SIZE safely as WARPS_PER_BLOCK <= 32 for max threads 1024
                float n = __shfl_up_sync(mask, block_scan, offset);
                if (lane_id >= offset) block_scan += n;
            }
            if (lane_id < WARPS_PER_BLOCK) warp_totals[lane_id] = block_scan;
        }
        __syncthreads();

        // 4. Propagate offsets:
        // - Add offset from previous warps in the current chunk (warp_totals[warp_id - 1])
        // - Add running_sum from previous chunks
        float prev_warp_sum = (warp_id > 0) ? warp_totals[warp_id - 1] : 0.0f;
        float res = warp_sum + prev_warp_sum + running_sum;

        // 5. Write result to global memory
        if (idx < scan_size) {
            row_out[idx] = res;
        }

        // 6. Update running_sum with the total of the current chunk
        // The last element of used warp_totals contains the inclusive sum of the current chunk
        running_sum += warp_totals[WARPS_PER_BLOCK - 1];
        __syncthreads();
    }
}

torch::Tensor cumsum_cuda(torch::Tensor input) {
    // Helper checks are done in Python, assumes input is (Batch, ScanSize) contiguous float32
    auto output = torch::empty_like(input);

    int batch_size = input.size(0);
    int scan_size = input.size(1);

    const int threads = 256;
    const int blocks = batch_size;
    const int shared_mem = (threads / 32) * sizeof(float); // Space for one float per warp

    scan_last_dim_kernel<<<blocks, threads, shared_mem>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        batch_size, 
        scan_size
    );

    return output;
}
"""

scan_cpp_source = "torch::Tensor cumsum_cuda(torch::Tensor input);"

# Compile the inline CUDA code
scan_cuda_module = load_inline(
    name="scan_cuda_op",
    cpp_sources=scan_cpp_source,
    cuda_sources=scan_cuda_source,
    functions=["cumsum_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a cumulative sum operation using custom CUDA kernels
    when applicable (float32 on CUDA, last dimension).
    """

    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.scan_op = scan_cuda_module

    def forward(self, x):
        # Check if we can use the optimized CUDA kernel:
        # 1. Input is on CUDA
        # 2. Input is float32
        # 3. Scan is requested on the last dimension (contiguous scan)
        if x.is_cuda and x.dtype == torch.float32 and (self.dim == -1 or self.dim == x.ndim - 1):
            if not x.is_contiguous():
                x = x.contiguous()

            # Reshape to 2D (N, LastDim) for the kernel
            original_shape = x.shape
            scan_size = original_shape[-1]
            batch_size = x.numel() // scan_size

            x_flat = x.view(batch_size, scan_size)

            # Invoke custom kernel
            out_flat = self.scan_op.cumsum_cuda(x_flat)

            return out_flat.view(original_shape)

        # Fallback to PyTorch implementation for other cases (e.g., CPU, different dims, types)
        return torch.cumsum(x, dim=self.dim)

