#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void sigmoid_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Process data as float4 vectors to improve memory throughput
    int vec_size = size / 4;
    const float4* input_vec = reinterpret_cast<const float4*>(input);
    float4* output_vec = reinterpret_cast<float4*>(output);

    for (int i = idx; i < vec_size; i += stride) {
        float4 v = input_vec[i];

        // Sigmoid formula: 1.0 / (1.0 + exp(-x))
        // We use expf which is hardware accelerated
        v.x = 1.0f / (1.0f + expf(-v.x));
        v.y = 1.0f / (1.0f + expf(-v.y));
        v.z = 1.0f / (1.0f + expf(-v.z));
        v.w = 1.0f / (1.0f + expf(-v.w));

        output_vec[i] = v;
    }

    // Handle trailing elements if size is not a multiple of 4
    if (idx == 0) {
        int tail_start = vec_size * 4;
        for (int i = tail_start; i < size; ++i) {
            output[i] = 1.0f / (1.0f + expf(-input[i]));
        }
    }
}

