    int blocks = (vec_size + threads - 1) / threads;

    // Cap the grid size to a reasonable limit to avoid scheduler overhead
    // The grid-stride loop in the kernel ensures all data is processed
    if (blocks > 65535) blocks = 65535;

    sigmoid_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}
