maxpool1d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>
#include <cmath>

__global__ void maxpool1d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int width,
    int out_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    // Calculate global thread index
    // Each thread computes one output element. 
    // Total threads = batch_size * channels * out_width
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * out_width;

    if (idx < total_elements) {
        // Decode the linear index into (batch, channel, output_width_index)
        // idx = b * (channels * out_width) + c * out_width + w_out
        int w_out = idx % out_width;
        int temp = idx / out_width;
        int c = temp % channels;
        int b = temp / channels;

        // Calculate the base pointer offset for the current batch and channel in input
        // Input layout is (N, C, L)
        long long input_base = (long long)b * (channels * width) + (long long)c * width;
        const float* input_ptr = input + input_base;

        // Calculate the starting index of the pooling window in the input sequence
        int start_in = w_out * stride - padding;

        // Initialize max value to lowest possible float
        float max_val = -FLT_MAX;

        // Iterate over the kernel window
        #pragma unroll
        for (int k = 0; k < kernel_size; ++k) {
            int p_in = start_in + k * dilation;

            // Check boundary conditions.
            // PyTorch MaxPool ignores padded values (effectively treating them as -inf)
            if (p_in >= 0 && p_in < width) {
                float val = input_ptr[p_in];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }

        // Store the result
        output[idx] = max_val;
    }
}

torch::Tensor maxpool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    // Ensure input is a CUDA tensor
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(input.dim() == 3, "Input tensor must be 3D (batch, features, length)");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int width = input.size(2);

    // Calculate output width using PyTorch's formula
    // L_out = floor((L_in + 2*padding - dilation*(kernel_size-1) - 1)/stride + 1)
    int out_width = std::floor((float)(width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1);

    if (out_width <= 0) {
        return torch::empty({batch_size, channels, 0}, input.options());
    }

    auto output = torch::empty({batch_size, channels, out_width}, input.options());

    // Configure CUDA launch
    int total_elements = batch_size * channels * out_width;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    maxpool1d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        width,
        out_width,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
