#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA Kernel for Pointwise (1x1) Convolution
// Uses shared memory tiling to optimize memory access for NCHW layout
__global__ void conv1x1_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size,
    int in_channels,
    int out_channels,
    int spatial_size) {

    // Tile dimensions
    const int TILE_SIZE = 16;

    // Shared memory to hold tiles of Input and Weights
    // s_w: [TILE_SIZE][TILE_SIZE + 1] to avoid bank conflicts. Rows correspond to Output Channels, Cols to Input Channels.
    __shared__ float s_w[TILE_SIZE][TILE_SIZE + 1];

    // s_in: [TILE_SIZE][TILE_SIZE]. Rows correspond to Input Channels, Cols to Spatial (Pixel) indices.
    __shared__ float s_in[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global indices
    // y-grid maps to Output Channels
    int global_oc = blockIdx.y * TILE_SIZE + ty;
    // x-grid maps to Spatial Locations (Batch * H * W flattened)
    int global_spatial = blockIdx.x * TILE_SIZE + tx;

    float acc = 0.0f;

    // Initialize accumulator with bias if available
    if (bias != nullptr && global_oc < out_channels) {
        acc = bias[global_oc];
    }

    int total_spatial = batch_size * spatial_size;

    // Loop over input channels in chunks of TILE_SIZE
    for (int k = 0; k < in_channels; k += TILE_SIZE) {

        // 1. Load Weights Tile
        // Each thread loads one value. 
        // We need W[global_oc, k..k+15]. 
        // Mapping: ty -> OC offset, tx -> IC offset (within the tile)
        int w_ic = k + tx;
        if (global_oc < out_channels && w_ic < in_channels) {
            // Weights are [OutChannels, InChannels] (contiguous in memory)
            s_w[ty][tx] = w[global_oc * in_channels + w_ic];
        } else {
            s_w[ty][tx] = 0.0f;
        }

        // 2. Load Input Tile
        // We need X[..., k..k+15, global_spatial]
        // Mapping: ty -> IC offset (within the tile), tx -> Spatial offset (within the tile)
        int in_ic = k + ty;
        int in_spatial = global_spatial; 

        float val = 0.0f;
        if (in_ic < in_channels && in_spatial < total_spatial) {
            // Calculate NCHW address manually
            int b = in_spatial / spatial_size;
            int s_off = in_spatial % spatial_size;
            // Address: b*IC*HW + ic*HW + s_off
            int in_idx = b * in_channels * spatial_size + in_ic * spatial_size + s_off;
            val = x[in_idx];
        }
        s_in[ty][tx] = val;

        __syncthreads();

        // 3. Compute
        // Multiply Row of s_w (OC) by Column of s_in (Spatial)
        // Inner dimension is Input Channel (which is the loop variable for s_in rows and s_w cols)

        #pragma unroll
        for (int kk = 0; kk < TILE_SIZE; ++kk) {
            acc += s_in[kk][tx] * s_w[ty][kk];
        }

        __syncthreads();
    }

    // Write output
    if (global_oc < out_channels && global_spatial < total_spatial) {
        int b = global_spatial / spatial_size;
        int s_off = global_spatial % spatial_size;
        // Output NCHW: b*OC*HW + oc*HW + s_off
        int out_idx = b * out_channels * spatial_size + global_oc * spatial_size + s_off;
        out[out_idx] = acc;
    }
