import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for HardTanh
# This kernel uses vectorization (float4) to optimize memory bandwidth usage,
# which is typically the bottleneck for element-wise operations.
hardtanh_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void hardtanh_kernel(const float* __restrict__ x, float* __restrict__ out, int size, float min_val, float max_val) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized load/store using float4 for improved memory throughput
    int vec_size = size / 4;
    const float4* x_vec = reinterpret_cast<const float4*>(x);
    float4* out_vec = reinterpret_cast<float4*>(out);

    for (int i = idx; i < vec_size; i += stride) {
        float4 v = x_vec[i];

        // Apply HardTanh logic element-wise within the vector
        v.x = fminf(fmaxf(v.x, min_val), max_val);
        v.y = fminf(fmaxf(v.y, min_val), max_val);
        v.z = fminf(fmaxf(v.z, min_val), max_val);
        v.w = fminf(fmaxf(v.w, min_val), max_val);

        out_vec[i] = v;
    }

    // Handle the remaining elements (tail) that don't fit into float4
    int tail_start = vec_size * 4;
    for (int i = tail_start + idx; i < size; i += stride) {
        out[i] = fminf(fmaxf(x[i], min_val), max_val);
    }
}

torch::Tensor hardtanh_cuda(torch::Tensor x, float min_val, float max_val) {
    // Ensure the input tensor is on CUDA
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");

    // Ensure contiguous memory for safe reinterpret_cast to float4
    // This is critical for the vectorized implementation
    x = x.contiguous();

    auto out = torch::empty_like(x);
    int size = x.numel();

    if (size == 0) return out;

    const int block_size = 256;

    // Calculate grid size. 
    // We base the grid size on the number of float4 vectors.
    // Cap the grid size to 65535 to avoid excessive launch overhead, 
    // relying on the grid-stride loop in the kernel to handle large tensors.
    int vec_size = size / 4;
    int num_blocks = (vec_size + block_size - 1) / block_size;
    if (num_blocks > 65535) num_blocks = 65535;
    if (num_blocks == 0) num_blocks = 1;

    hardtanh_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        min_val,
        max_val
    );

    return out;
}
"""

