# Define the custom CUDA kernel for Argmax along dimension 1 (specialized for 3D tensors)
argmax_dim1_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void argmax_dim1_kernel(
    const float* __restrict__ x, 
    int64_t* __restrict__ out,
    int batch_size, int dim1_size, int dim2_size,
    int stride0, int stride1, int stride2) {

    // Grid configuration:
    // blockIdx.y corresponds to the batch dimension (N)
    // blockIdx.x * blockDim.x + threadIdx.x corresponds to the dim2 dimension (W)
    // We reduce along dim1 (H)

    int b = blockIdx.y;
    int w = blockIdx.x * blockDim.x + threadIdx.x;

    if (b >= batch_size || w >= dim2_size) return;

    // Calculate the starting pointer for the column x[b, :, w]
    // Flat index = b * stride0 + 0 * stride1 + w * stride2
    const float* col_ptr = x + b * stride0 + w * stride2;

    float max_val = -1e38; // Initialize with a very small number
    int64_t max_idx = 0;

    // Initialize with the first element if dimension is not empty
    if (dim1_size > 0) {
        max_val = *col_ptr;
        max_idx = 0;
        col_ptr += stride1;
    }

    // Iterate over the reduction dimension
    // Note: The memory access here is strided by stride1 (usually width), 
    // but since threads in a warp have adjacent 'w', the reads are coalesced 
    // across the warp for each step of 'i'.
    for (int i = 1; i < dim1_size; ++i) {
        float val = *col_ptr;
        if (val > max_val) {
            max_val = val;
            max_idx = i;
        }
        col_ptr += stride1;
    }

    // Write output
    // Output is (N, W) contiguous
    out[b * dim2_size + w] = max_idx;
}

torch::Tensor argmax_dim1_cuda(torch::Tensor x) {
    // Input validation should be done in Python or caller
    int N = x.size(0);
    int H = x.size(1);
    int W = x.size(2);

    auto out = torch::empty({N, W}, x.options().dtype(torch::kLong));

    int threads = 256;
    int blocks_x = (W + threads - 1) / threads;

    dim3 block(threads);
    dim3 grid(blocks_x, N);

    argmax_dim1_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        out.data_ptr<int64_t>(),
        N, H, W,
        x.stride(0), x.stride(1), x.stride(2)
    );

    return out;
}
"""

argmax_dim1_cpp_source = "torch::Tensor argmax_dim1_cuda(torch::Tensor x);"

