# Define the custom CUDA kernel for 3D Transposed Convolution
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int stride, int padding, int output_padding,
    int groups) 
{
    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_d * out_h * out_w;

    if (idx >= total_elements) return;

    // Decode linear index to (n, c_out, oz, oy, ox)
    int temp = idx;
    int ox = temp % out_w; temp /= out_w;
    int oy = temp % out_h; temp /= out_h;
    int oz = temp % out_d; temp /= out_d;
    int c_out = temp % out_channels; temp /= out_channels;
    int n = temp;

    // Initialize with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[c_out];
    }

    // Determine group indices
    int out_group_size = out_channels / groups;
    int in_group_size = in_channels / groups;
    int g = c_out / out_group_size;
    int c_in_start = g * in_group_size;
    int c_in_end = c_in_start + in_group_size;
    int w_c_out = c_out % out_group_size;

    // Loop over input channels in the group
    for (int c_in = c_in_start; c_in < c_in_end; ++c_in) {

        // Loop over kernel depth
        int target_z = oz + padding;
        for (int kz = 0; kz < k_d; ++kz) {
            int iz_num = target_z - kz;
            // Optimization: if iz_num < 0, it will only get smaller as kz increases
            if (iz_num < 0) break; 

            // Check stride condition
            if (iz_num % stride != 0) continue;
            int iz = iz_num / stride;

            // Check input boundary
            if (iz >= in_d) continue;

            // Loop over kernel height
            int target_y = oy + padding;
            for (int ky = 0; ky < k_h; ++ky) {
                int iy_num = target_y - ky;
                if (iy_num < 0) break;
                if (iy_num % stride != 0) continue;
                int iy = iy_num / stride;
                if (iy >= in_h) continue;

                // Loop over kernel width
                int target_x = ox + padding;
                for (int kx = 0; kx < k_w; ++kx) {
                    int ix_num = target_x - kx;
                    if (ix_num < 0) break;
                    if (ix_num % stride != 0) continue;
                    int ix = ix_num / stride;
                    if (ix >= in_w) continue;

                    // Calculate flat indices
                    int input_idx = n * (in_channels * in_d * in_h * in_w) + 
                                    c_in * (in_d * in_h * in_w) + 
                                    iz * (in_h * in_w) + 
                                    iy * (in_w) + 
                                    ix;

                    // Weight shape: (in_channels, out_group_size, kd, kh, kw)
                    int weight_idx = c_in * (out_group_size * k_d * k_h * k_w) +
                                     w_c_out * (k_d * k_h * k_w) +
                                     kz * (k_h * k_w) +
                                     ky * (k_w) +
                                     kx;

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }
    output[idx] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int stride,
    int padding,
    int output_padding,
    int groups) 
{
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_d = input.size(2);
    auto in_h = input.size(3);
    auto in_w = input.size(4);

    // PyTorch ConvTranspose3d weight shape: (in_channels, out_channels/groups, k, k, k)
    auto out_group_size = weight.size(1);
    auto out_channels = out_group_size * groups;
    auto k_d = weight.size(2);
    auto k_h = weight.size(3);
    auto k_w = weight.size(4);

    // Calculate output dimensions
    // D_out = (D_in - 1) * stride - 2 * padding + dilation * (k - 1) + output_padding + 1
    // Assuming dilation=1 as per standard ConvTranspose3d defaults when not specified
    int dilation = 1; 
    auto out_d = (in_d - 1) * stride - 2 * padding + dilation * (k_d - 1) + output_padding + 1;
    auto out_h = (in_h - 1) * stride - 2 * padding + dilation * (k_h - 1) + output_padding + 1;
    auto out_w = (in_w - 1) * stride - 2 * padding + dilation * (k_w - 1) + output_padding + 1;

    auto output = torch::zeros({batch_size, out_channels, out_d, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.has_value()) {
        bias_ptr = bias->data_ptr<float>();
    }

    int total_elements = batch_size * out_channels * out_d * out_h * out_w;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        k_d, k_h, k_w,
        stride, padding, output_padding, groups
    );

