import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for diagonal matrix multiplication
# Original operation: C = diag(A) @ B
# Optimized operation: C[i, j] = A[i] * B[i, j] (Row scaling)
# This avoids creating the intermediate O(N^2) diagonal matrix and reduces 
# the operation from a dense matrix multiply O(N^2 * M) to an element-wise scale O(N * M).

diag_mm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void diag_mm_kernel(const float* __restrict__ A, 
                               const float* __restrict__ B, 
                               float* __restrict__ Out, 
                               int N, int M) {
    // 2D grid to handle matrix dimensions
    // x index maps to columns (0..M-1)
    // y index maps to rows (0..N-1)
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < N && col < M) {
        int idx = row * M + col;
        // Access A at row index (scalar per row), B and Out at linear index
        Out[idx] = A[row] * B[idx];
    }
}

torch::Tensor diag_mm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 1, "A must be 1D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(0) == B.size(0), "A size must match B rows");

    // Ensure contiguous memory layout for correct pointer arithmetic
    A = A.contiguous();
    B = B.contiguous();

    int N = B.size(0);
    int M = B.size(1);

    auto out = torch::empty_like(B);

    // Configure kernel launch parameters
    // Use 2D blocks (32x32) for coalesced memory access and intuitive mapping
    dim3 threadsPerBlock(32, 32); 
    dim3 numBlocks((M + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (N + threadsPerBlock.y - 1) / threadsPerBlock.y);

    diag_mm_kernel<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        out.data_ptr<float>(),
        N, M
    );

    return out;
}
"""

diag_mm_cpp_source = "torch::Tensor diag_mm_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
diag_mm_module = load_inline(
    name="diag_mm_module",
    cpp_sources=diag_mm_cpp_source,
    cuda_sources=diag_mm_source,
    functions=["diag_mm_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication of a diagonal matrix with another matrix.
    C = diag(A) * B
    Implemented via a custom CUDA kernel that performs row-wise scaling.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.diag_mm = diag_mm_module

    def forward(self, A, B):
        """
        Performs the matrix multiplication.

        Args:
            A (torch.Tensor): A 1D tensor representing the diagonal. Shape: (N,).
            B (torch.Tensor): A 2D tensor. Shape: (N, M).

        Returns:
            torch.Tensor: The result of the matrix multiplication. Shape: (N, M).
        """
        return self.diag_mm.diag_mm_cuda(A, B)

