import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Transposed Convolution (Deconvolution)
conv_transpose2d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int k_h,
    int k_w,
    int stride,
    int padding,
    int dilation) {

    // Calculate global thread index and map to output element
    // Layout: (N, Out_Channels, Out_H, Out_W)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_h * out_w;

    if (idx >= total_elements) return;

    // Decode index -> (n, c_out, h_out, w_out)
    int w_out_idx = idx % out_w;
    int tmp = idx / out_w;
    int h_out_idx = tmp % out_h;
    tmp = tmp / out_h;
    int c_out_idx = tmp % out_channels;
    int n_idx = tmp / out_channels;

    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[c_out_idx];
    }

    // Iterate over input channels and kernel window to accumulate values (Gather approach)
    // Formula relation: h_out = h_in * stride + p * dilation - padding
    // Therefore: h_in = (h_out + padding - p * dilation) / stride

    // Base offsets
    int input_n_offset = n_idx * in_channels * in_h * in_w;
    // Weight shape for ConvTranspose2d is (in_channels, out_channels, k_h, k_w) (assuming groups=1)

    for (int c_in = 0; c_in < in_channels; ++c_in) {
        int input_c_offset = input_n_offset + c_in * in_h * in_w;
        int weight_c_offset = (c_in * out_channels + c_out_idx) * k_h * k_w;

        for (int p = 0; p < k_h; ++p) {
            int h_num = h_out_idx + padding - p * dilation;

            // Check if this kernel position corresponds to a valid input row
            if (h_num >= 0 && (h_num % stride == 0)) {
                int h_in = h_num / stride;
                if (h_in < in_h) {

                    int input_row_offset = input_c_offset + h_in * in_w;
                    int weight_row_offset = weight_c_offset + p * k_w;

                    for (int q = 0; q < k_w; ++q) {
                        int w_num = w_out_idx + padding - q * dilation;

                        // Check if this kernel position corresponds to a valid input col
                        if (w_num >= 0 && (w_num % stride == 0)) {
                            int w_in = w_num / stride;
                            if (w_in < in_w) {
                                val += input[input_row_offset + w_in] * weight[weight_row_offset + q];
                            }
                        }
                    }
                }
            }
        }
    }

    output[idx] = val;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int dilation) {

    TORCH_CHECK(input.is_cuda, "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda, "Weight must be a CUDA tensor");
    TORCH_CHECK(groups == 1, "Only groups=1 is supported in this custom kernel");

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_h = input.size(2);
    auto in_w = input.size(3);

    // Weight layout: (in_channels, out_channels/groups, k_h, k_w)
    // Since groups=1, dim1 is out_channels
    auto out_channels = weight.size(1);
    auto k_h = weight.size(2);
    auto k_w = weight.size(3);

    // Calculate output dimensions
    int out_h = (in_h - 1) * stride - 2 * padding + dilation * (k_h - 1) + output_padding + 1;
    int out_w = (in_w - 1) * stride - 2 * padding + dilation * (k_w - 1) + output_padding + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    const int block_size = 256;
    int total_elements = batch_size * out_channels * out_h * out_w;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* bias_ptr = (bias.defined() && bias.numel() > 0) ? bias.data_ptr<float>() : nullptr;

    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        out_h,
        out_w,
        k_h,
        k_w,
        stride,
        padding,
        dilation
    );

    return output;
}
"""

