import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel source for Fused BatchNorm + GELU + ReLU
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_bn_gelu_relu_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int num_elements,
    int channels,
    float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < num_elements) {
        int c = idx % channels;

        float val = x[idx];
        float m = mean[c];
        float v = var[c];
        float w = weight[c];
        float b = bias[c];

        // Batch Norm: y = (x - mean) / sqrt(var + eps) * weight + bias
        float inv_std = rsqrtf(v + eps);
        float norm = (val - m) * inv_std;
        float bn_out = norm * w + b;

        // GELU (Exact): 0.5 * x * (1 + erf(x / sqrt(2)))
        const float k = 0.70710678f; // 1.0 / sqrt(2.0)
        float gelu_out = 0.5f * bn_out * (1.0f + erff(bn_out * k));

        // ReLU: max(0, x)
        out[idx] = fmaxf(0.0f, gelu_out);
    }
}

torch::Tensor fused_bn_gelu_relu_forward(
    torch::Tensor x, 
    torch::Tensor mean, 
    torch::Tensor var, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    float eps) {

    auto num_elements = x.numel();
    auto channels = x.size(1);
    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_bn_gelu_relu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        num_elements,
        channels,
        eps
    );

    return out;
}
"""

cpp_source = """
torch::Tensor fused_bn_gelu_relu_forward(
    torch::Tensor x, 
    torch::Tensor mean, 
    torch::Tensor var, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    float eps);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name='fused_bn_gelu_relu',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['fused_bn_gelu_relu_forward'],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model that fuses BatchNorm (Apply), GELU, and ReLU into a single custom CUDA kernel.
    Keeps GEMM (cuBLAS) as it is highly optimized.
    """
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        # We keep nn.BatchNorm1d to manage state (running_mean, running_var, weight, bias)
        self.batch_norm = nn.BatchNorm1d(out_features)
        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. GEMM
        x = self.gemm(x)

        # 2. Prepare Statistics for BatchNorm
        if self.training:
            # Calculate batch statistics using PyTorch's optimized reduction
            mean = x.mean(dim=0)
            # BN uses biased variance for the normalization step
            var = x.var(dim=0, unbiased=False)

            # Update running statistics manually to match nn.BatchNorm behavior
            # (Running stats use unbiased variance)
            with torch.no_grad():
                n = x.numel() / x.size(1)
                var_unbiased = var * (n / (n - 1.0))
                momentum = self.batch_norm.momentum
                self.batch_norm.running_mean.mul_(1 - momentum).add_(mean, alpha=momentum)
                self.batch_norm.running_var.mul_(1 - momentum).add_(var_unbiased, alpha=momentum)
        else:
            # Use running stats during inference
            mean = self.batch_norm.running_mean
            var = self.batch_norm.running_var

        # 3. Custom Fused Kernel
        # Replaces: x = bn(x) -> x = gelu(x) -> x = relu(x)
        # This reduces memory reads/writes from 4 full-tensor passes to 2 (1 read, 1 write in the kernel)
        return self.fused_ops.fused_bn_gelu_relu_forward(
            x, 
            mean, 
            var, 
            self.batch_norm.weight, 
            self.batch_norm.bias, 
            self.batch_norm.eps
        )

