import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code
# This kernel fuses:
# 1. Element-wise scaling (x * scale)
# 2. Element-wise residual addition (x + x => equivalent to * 2)
# 3. Element-wise Clamping
# 4. Row-wise LogSumExp reduction
# 5. Element-wise Mish activation and multiplication (x * Mish(x)) on the result
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Helper for softplus: log(1 + exp(x)) with stability check
__device__ inline float softplus_f(float x) {
    if (x > 20.0f) return x;
    return log1pf(expf(x));
}

// Structure for stable LogSumExp reduction maintaining max and sum-of-exps
struct MaxSum {
    float max_val;
    float sum_val;
};

// Combine function for reducing two (max, sum) pairs
// Uses formula: log(exp(x) + exp(y)) = m + log(exp(x-m) + exp(y-m)) where m = max(x,y)
__device__ inline MaxSum combine(MaxSum a, MaxSum b) {
    float new_max = fmaxf(a.max_val, b.max_val);

    // Handle case where initialized with -inf
    if (new_max == -INFINITY) {
        return {-INFINITY, 0.0f};
    }

    float term_a = (a.max_val == -INFINITY) ? 0.0f : a.sum_val * expf(a.max_val - new_max);
    float term_b = (b.max_val == -INFINITY) ? 0.0f : b.sum_val * expf(b.max_val - new_max);

    return {new_max, term_a + term_b};
}

__global__ void fused_process_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int rows,
    int cols,
    float combined_scale,
    float c_min,
    float c_max
) {
    // Each block processes one row
    int row_idx = blockIdx.x;
    if (row_idx >= rows) return;

    MaxSum local = {-INFINITY, 0.0f};

    // Iterate over the row with stride equal to block dimension
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        float val = input[row_idx * cols + i];

        // Fused operations:
        // 1. Scale and Residual Add: x = x * scale_factor; x = x + x  => x * scale_factor * 2
        val = val * combined_scale; 

        // 2. Clamp
        val = fminf(fmaxf(val, c_min), c_max);

        // Accumulate for LogSumExp
        MaxSum curr = {val, 1.0f};
        local = combine(local, curr);
    }

    // Shared memory for reduction within the block
    __shared__ MaxSum sdata[256];
    int tid = threadIdx.x;
    sdata[tid] = local;
    __syncthreads();

    // Tree reduction in shared memory (assuming block size 256)
    if (tid < 128) sdata[tid] = combine(sdata[tid], sdata[tid + 128]); __syncthreads();
    if (tid < 64)  sdata[tid] = combine(sdata[tid], sdata[tid + 64]);  __syncthreads();
    if (tid < 32)  sdata[tid] = combine(sdata[tid], sdata[tid + 32]);  __syncthreads();
    if (tid < 16)  sdata[tid] = combine(sdata[tid], sdata[tid + 16]);  __syncthreads();
    if (tid < 8)   sdata[tid] = combine(sdata[tid], sdata[tid + 8]);   __syncthreads();
    if (tid < 4)   sdata[tid] = combine(sdata[tid], sdata[tid + 4]);   __syncthreads();
    if (tid < 2)   sdata[tid] = combine(sdata[tid], sdata[tid + 2]);   __syncthreads();
    if (tid < 1)   sdata[tid] = combine(sdata[tid], sdata[tid + 1]);   __syncthreads();

    // Write result to global memory
    if (tid == 0) {
        // Calculate LogSumExp result: max + log(sum)
        float x = sdata[0].max_val + logf(sdata[0].sum_val);

        // Fused Post-Processing: x = x * Mish(x)
        // Mish(x) = x * tanh(softplus(x))
        float sp = softplus_f(x);
        float mish_val = x * tanhf(sp);

        output[row_idx] = x * mish_val;
    }
}

torch::Tensor launch_fused_process(torch::Tensor input, float scale, float c_min, float c_max) {
    int rows = input.size(0);
    int cols = input.size(1);
    auto output = torch::empty({rows, 1}, input.options());

    // Launch one block per row with 256 threads per block
    fused_process_kernel<<<rows, 256>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols,
        scale,
        c_min,
        c_max
    );
    return output;
}
"""

cpp_source = "torch::Tensor launch_fused_process(torch::Tensor input, float scale, float c_min, float c_max);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["launch_fused_process"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized Model with custom CUDA kernels replacing:
    - Post-linear scaling and addition
    - Clamping
    - LogSumExp reduction
    - Mish activation and multiplication
    """
    def __init__(self, input_size, hidden_size, scale_factor, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        # We retain the nn.Linear layer as it uses highly optimized cuBLAS routines.
        # Custom GEMM implementation often underperforms libraries for general sizes.
        self.matmul = nn.Linear(input_size, hidden_size)
        self.scale_factor = scale_factor
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. Matrix Multiplication
        x = self.matmul(x)

        # 2. Fused Kernel Execution
        # The kernel fuses: 
        #   x = x * scale
        #   x = x + x  (equivalent to * 2, so combined scale is scale_factor * 2)
        #   clamp(x)
        #   LogSumExp(x, dim=1)
        #   x * Mish(x)
        combined_scale = self.scale_factor * 2.0

        x = self.fused_ops.launch_fused_process(x, combined_scale, self.clamp_min, self.clamp_max)

        return x

