import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused subtraction and Mish activation
# We optimize by fusing the two subtractions and the Mish activation into a single kernel pass.
# Operations: x = x - s1 - s2 => x = x - (s1 + s2) followed by Mish(x).
fused_sub_mish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ __forceinline__ float mish_device(float x) {
    // Mish implementation: x * tanh(ln(1 + exp(x)))
    // softplus(x) = ln(1 + exp(x))
    // For numerical stability:
    // If x > 20, softplus(x) is approx x.
    // If x is large negative, exp(x) is small, softplus is approx 0.

    float sp;
    if (x > 20.0f) {
        sp = x;
    } else {
        sp = log1pf(expf(x));
    }
    return x * tanhf(sp);
}

__global__ void fused_sub_mish_kernel(const float* __restrict__ input, float* __restrict__ output, float total_sub, int numel) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
