import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Bias Add + Division + Swish Activation
# This kernel fuses: x = (x + bias) / divide_value; x = x * sigmoid(x)
# It uses float4 vectorization for memory efficiency on aligned tensors.

fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector_types.h>
#include <cmath>

// Fast sigmoid implementation
__device__ __forceinline__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_post_ops_kernel(float* __restrict__ x, const float* __restrict__ bias_ptr, float divide_value, int size) {
    // Load bias scalar (assuming shape is (1,) based on model definition)
    // Using __ldg for read-only cache optimization
    float bias = __ldg(bias_ptr);
    float inv_div = 1.0f / divide_value;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized processing (float4) to handle 4 elements per thread
    int size4 = size / 4;
    float4* x4 = reinterpret_cast<float4*>(x);

    for (int i = idx; i < size4; i += stride) {
        float4 v = x4[i];

        // Process component x
        v.x = (v.x + bias) * inv_div;
        v.x = v.x * sigmoid_f(v.x);

        // Process component y
        v.y = (v.y + bias) * inv_div;
        v.y = v.y * sigmoid_f(v.y);

        // Process component z
        v.z = (v.z + bias) * inv_div;
        v.z = v.z * sigmoid_f(v.z);

        // Process component w
        v.w = (v.w + bias) * inv_div;
        v.w = v.w * sigmoid_f(v.w);

        x4[i] = v;
    }

    // Handle remainder elements (if size is not a multiple of 4)
    int remainder_start = size4 * 4;
    for (int i = remainder_start + idx; i < size; i += stride) {
        float v = x[i];
        v = (v + bias) * inv_div;
        v = v * sigmoid_f(v);
        x[i] = v;
    }
}

torch::Tensor fused_post_ops_cuda(torch::Tensor x, torch::Tensor bias, float divide_value) {
    // Ensure inputs are on CUDA and contiguous
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    // x needs to be contiguous for direct pointer access and vectorization
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    int size = x.numel();
    const int block_size = 256;
    // Calculate grid size to cover data, assuming float4 processing (4 floats per thread)
    const int num_blocks = (size + block_size * 4 - 1) / (block_size * 4);
    const int grid_size = std::min(num_blocks, 65535); // Cap grid size to avoid launch errors

    fused_post_ops_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        divide_value,
        size
    );

    return x;
}
