import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
# Fuses: Division, MaxPool3d, AdaptiveAvgPool3d, Bias Addition, Summation
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    float divisor,
    int N, int C, int D, int H, int W,
    int pd, int ph, int pw,
    int D_out, int H_out, int W_out
) {
    extern __shared__ float sdata[];

    int n = blockIdx.x;
    if (n >= N) return;

    // Total logical elements in the max-pooled volume across all channels
    // We are summing over C, D_out, H_out, W_out
    int pool_vol = D_out * H_out * W_out;
    int total_elements = C * pool_vol;

    // Strides for input x (N, C, D, H, W)
    // Assumes contiguous NCDHW
    int sH = W;
    int sD = H * W;
    int sC = D * H * W;
    int sN = C * D * H * W;

    const float* x_n = x + n * sN;

    float local_sum = 0.0f;

    // Grid-stride loop over the logical output volume
    for (int idx = threadIdx.x; idx < total_elements; idx += blockDim.x) {
        // Decode index to (c, d_out, h_out, w_out)
        // Layout: C, D_out, H_out, W_out
        int temp = idx;
        int w_out = temp % W_out; temp /= W_out;
        int h_out = temp % H_out; temp /= H_out;
        int d_out = temp % D_out; temp /= D_out;
        int c = temp;

        // Input window start coordinates
        int d_in = d_out * pd;
        int h_in = h_out * ph;
        int w_in = w_out * pw;

        // Find max in window
        float max_val = -FLT_MAX;

        // Pointer to this channel
        const float* x_c = x_n + c * sC;

        // Loop over pool window
        for (int z = 0; z < pd; ++z) {
            for (int y = 0; y < ph; ++y) {
                for (int xx = 0; xx < pw; ++xx) {
                    int cur_d = d_in + z;
                    int cur_h = h_in + y;
                    int cur_w = w_in + xx;

                    // Boundary check
                    if (cur_d < D && cur_h < H && cur_w < W) {
                        float val = x_c[cur_d * sD + cur_h * sH + cur_w];
                        if (val > max_val) max_val = val;
                    }
                }
            }
        }

        // Accumulate max_val
        // Division by divisor is deferred to the end
        local_sum += max_val;
    }

    // Block reduction
    sdata[threadIdx.x] = local_sum;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float grand_sum = sdata[0];

        // Compute bias sum
        float bias_sum_val = 0.0f;
        for (int i = 0; i < C; ++i) {
            bias_sum_val += bias[i];
        }

        // Final calculation
        // Output = Sum_c( GlobalAvg( MaxPool(x)/divisor ) + Bias_c )
        //        = Sum_c( Sum_spatial( MaxPool(x) ) / (divisor * spatial_count) ) + Sum_c(Bias_c)
        //        = GrandSum / (divisor * spatial_count) + BiasSum

        float spatial_count = (float)pool_vol;
        float res = (grand_sum / (divisor * spatial_count)) + bias_sum_val;

        out[n] = res;
    }
}

torch::Tensor fused_op(torch::Tensor x, torch::Tensor bias, float divisor, std::vector<int> pool_size) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    int pd = pool_size[0];
    int ph = pool_size[1];
    int pw = pool_size[2];

    auto N = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    // Calculate output spatial dimensions
    int D_out = D / pd;
    int H_out = H / ph;
    int W_out = W / pw;

    auto out = torch::empty({N, 1, 1, 1}, x.options());

    const int threads = 256;
    const int blocks = N;
    const int shared_mem = threads * sizeof(float);

    fused_ops_kernel<<<blocks, threads, shared_mem>>>(
        x.contiguous().data_ptr<float>(),
        bias.contiguous().data_ptr<float>(),
        out.data_ptr<float>(),
        divisor,
        N, C, D, H, W,
        pd, ph, pw,
        D_out, H_out, W_out
    );

    return out;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_op(torch::Tensor x, torch::Tensor bias, float divisor, std::vector<int> pool_size);"
)

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_op"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, divisor, pool_size, bias_shape, sum_dim):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.divisor = divisor
        self.pool_size = pool_size
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops
        # sum_dim is implicitly handled by the kernel (summing over channels to reduce to N,1,1,1)

    def forward(self, x):
        # We perform convolution using the standard optimized operator
        x = self.conv(x)

        # We replace the sequence: div -> maxpool -> avgpool -> bias -> sum
        # with a single fused CUDA kernel
        return self.fused_ops.fused_op(x, self.bias, self.divisor, self.pool_size)

