import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Scale and Min reduction
# This kernel replaces the operations: x * scale_factor -> min(x, dim=1)
fused_scale_min_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_scale_min_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output, 
    int channels, 
    int spatial_size, 
    float scale, 
    int total_threads) 
{
    // We map one thread to one spatial location (h, w) across the batch (n).
    // Total threads = batch_size * height * width.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_threads) {
        // Decompose linear index 'idx' into batch index 'n' and spatial index 's'
        int s = idx % spatial_size;        // s = h * width + w
        int n = idx / spatial_size;        // batch index

        // The input tensor shape is (N, C, H, W).
        // Flattened view for pointer arithmetic: (N, C, S) where S = H * W.
        // We want to iterate over C for fixed n and s.
        //
        // Memory layout is NCHW (contiguous).
        // Address(n, c, s) = n * (C * S) + c * S + s

        // Base offset for the first channel (c=0)
        int input_offset = n * (channels * spatial_size) + s;

        float min_val = FLT_MAX;

        // Iterate over all channels to find the minimum scaled value
        for (int c = 0; c < channels; ++c) {
            float val = input[input_offset];

            // Apply scaling
            val *= scale;

            if (val < min_val) {
                min_val = val;
            }

            // Move to the next channel. The stride between channels at the same spatial position is 'spatial_size'.
            input_offset += spatial_size;
        }

        // The output tensor shape is (N, 1, H, W).
        // Since we keep dimensions, the output flat index corresponds exactly to 'idx' 
        // (mapping 1-to-1 with the N*S spatial locations).
        output[idx] = min_val;
    }
}

