    const int height = input.size(2);
    const int width = input.size(3);

    const int spatial_size = height * width;
    const int total_threads = batch_size * spatial_size;

    // Output shape: (N, 1, H, W)
    auto output = torch::empty({batch_size, 1, height, width}, input.options());

    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    fused_scale_min_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        channels,
        spatial_size,
        scale,
        total_threads
    );

    return output;
}
"""

