import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused operations
# Operations fused: Subtract -> GlobalAvgPool (Mean) -> LogSumExp (Identity) -> GELU -> ResidualAdd
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float gelu_func(float x) {
    // Exact GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
    const float kAlpha = 0.70710678f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * kAlpha));
}

__global__ void fused_post_gemm_kernel(
    const float* __restrict__ gemm_out,
    const float* __restrict__ input_x,
    const float* __restrict__ subtract,
    float* __restrict__ output,
    int batch_size,
    int features) {

    // Each block processes one row (one batch element)
    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Shared memory for holding partial sums from warps
    // We need enough space for blockDim.x / 32 floats
    extern __shared__ float sdata[];

    // -----------------------------------------------------------
    // Phase 1: Reduction (Mean of (gemm_out - subtract))
    // -----------------------------------------------------------
    float sum = 0.0f;

    // Grid-stride loop over features
    for (int col = threadIdx.x; col < features; col += blockDim.x) {
        float val = gemm_out[row * features + col] - subtract[col];
        sum += val;
    }

    // Warp Reduction
    // Reduce sum within the warp
    unsigned int mask = 0xffffffff;
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(mask, sum, offset);
    }

    // Write warp results to shared memory
    // Thread 0 of each warp writes to sdata[warpId]
    int lane = threadIdx.x % warpSize;
    int warpId = threadIdx.x / warpSize;
    if (lane == 0) {
        sdata[warpId] = sum;
    }

    __syncthreads();

    // Reduce the warp sums using the first warp
    if (warpId == 0) {
        // Load partial sums from shared memory
        // Only threads corresponding to number of warps need to participate
        float block_sum = (lane < (blockDim.x / 32)) ? sdata[lane] : 0.0f;

        for (int offset = (blockDim.x / 32) / 2; offset > 0; offset /= 2) {
            block_sum += __shfl_down_sync(mask, block_sum, offset);
        }

        if (lane == 0) {
            // Compute Mean
            float mean = block_sum / features;

            // Apply GELU
            // Note: The original code does LogSumExp on a dimension of size 1 (after Mean),
            // which mathematically simplifies to Identity: log(exp(x)) = x.
            float val = gelu_func(mean);

            // Store result in shared memory to broadcast to all threads in block
            sdata[0] = val;
        }
    }

    __syncthreads();

    // -----------------------------------------------------------
    // Phase 2: Residual Add (Input + Result) and Write Output
    // -----------------------------------------------------------
    float scalar = sdata[0];

    for (int col = threadIdx.x; col < features; col += blockDim.x) {
        // output = input + scalar
        // input_x corresponds to original_x in the python code
        output[row * features + col] = input_x[row * features + col] + scalar;
    }
}

torch::Tensor fused_post_gemm_cuda(torch::Tensor gemm_out, torch::Tensor input_x, torch::Tensor subtract) {
    auto batch_size = gemm_out.size(0);
    auto features = gemm_out.size(1);

    auto output = torch::empty_like(input_x);

    const int block_size = 256;
    const int num_blocks = batch_size;

    // Calculate shared memory size: one float per warp
    int num_warps = (block_size + 31) / 32;
    size_t shared_mem_size = num_warps * sizeof(float);

    fused_post_gemm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        gemm_out.data_ptr<float>(),
        input_x.data_ptr<float>(),
        subtract.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        features
    );

    return output;
}
"""

cpp_source = "torch::Tensor fused_post_gemm_cuda(torch::Tensor gemm_out, torch::Tensor input_x, torch::Tensor subtract);"

# Compile and load the inline CUDA operator
fused_op = load_inline(
    name="fused_post_gemm",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_post_gemm_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model with custom CUDA kernel for post-GEMM operations.
    Fuses Subtract, Mean, LogSumExp, GELU, and ResidualAdd into a single kernel.
    """
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features, bias=bias)
        self.subtract = nn.Parameter(torch.randn(out_features))
        self.fused_op = fused_op

    def forward(self, x):
        # GEMM (Matrix Multiplication) - kept as cuBLAS/Linear for efficiency
        gemm_out = self.gemm(x)

        # Fused Custom Kernel
        # Performs: 
        # 1. temp = gemm_out - self.subtract
        # 2. mean_val = mean(temp, dim=1)
        # 3. act = GELU(mean_val) (LogSumExp is skipped as it is identity here)
        # 4. out = x + act
        return self.fused_op.fused_post_gemm_cuda(gemm_out, x, self.subtract)

