import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused bias subtraction and tanh activation
# This kernel fuses the operation: x = tanh(x - bias)
# It operates in-place on x to save memory bandwidth.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_bias_sub_tanh_kernel(float* __restrict__ x, const float* __restrict__ bias, int numel, int channels, int spatial_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < numel; i += stride) {
        // Map linear index 'i' to channel index 'c'
        // Layout is NCHW. 
        // i = n * (C * spatial_size) + c * spatial_size + spatial_offset
        // i / spatial_size = n * C + c
        // (i / spatial_size) % C = c
        int c = (i / spatial_size) % channels;

        float val = x[i] - bias[c];
        x[i] = tanhf(val);
    }
}

torch::Tensor fused_bias_sub_tanh_cuda(torch::Tensor x, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (NCHW)");

    int channels = x.size(1);
    int height = x.size(2);
