import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused ReLU and GroupNorm
fused_relu_gn_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float relu(float x) {
    return x > 0.0f ? x : 0.0f;
}

__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__device__ __forceinline__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; // Shared mem for 32 partial sums
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    // Determine number of warps in the block
    int num_warps = blockDim.x / 32;
    val = (threadIdx.x < num_warps) ? shared[lane] : 0.0f;

    if (wid == 0) val = warpReduceSum(val);
    return val;
}

__global__ void fused_relu_gn_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int N, int C, int S, int G, float eps) {

    // Grid dimensions: x=N (batch), y=G (groups)
    int n = blockIdx.x;
    int g = blockIdx.y;

    int channels_per_group = C / G;
    int start_c = g * channels_per_group;

    // Calculate global offset for this (batch, group) block
    // Data layout is N, C, D, H, W (contiguous C, then S=D*H*W)
    long long offset_base = (long long)n * C * S + (long long)start_c * S;
    int group_size = channels_per_group * S;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    // First pass: Calculate sum and sum_squared of ReLU(x)
    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        float val = relu(x[offset_base + i]);
        sum += val;
        sum_sq += val * val;
    }

    // Reduction across the block
    sum = blockReduceSum(sum);
    sum_sq = blockReduceSum(sum_sq);

    __shared__ float mu;
    __shared__ float inv_sigma;

    if (threadIdx.x == 0) {
        mu = sum / group_size;
        float var = (sum_sq / group_size) - (mu * mu);
        inv_sigma = rsqrtf(var + eps);
    }
    __syncthreads();

    // Second pass: Apply Normalization, Gamma, Beta
    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        // Need to determine which channel 'i' belongs to for gamma/beta access
        // i iterates 0 to group_size-1
        // channel_index_local = i / S
        int c_local = i / S;
        int c_global = start_c + c_local;

        float val = relu(x[offset_base + i]);
        float norm = (val - mu) * inv_sigma;
        out[offset_base + i] = norm * gamma[c_global] + beta[c_global];
    }
}

torch::Tensor fused_relu_gn_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, int groups, float eps) {
    auto N = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);
    auto S = D * H * W;

    auto out = torch::empty_like(x);

    // One block per (Batch, Group)
    dim3 grid(N, groups);
    dim3 block(256);

    fused_relu_gn_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, S, groups, eps
    );

    return out;
}
"""

fused_relu_gn_cpp_source = (
    "torch::Tensor fused_relu_gn_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, int groups, float eps);"
)

# Compile the inline CUDA code
