    name="fused_relu_gn",
    cpp_sources=fused_relu_gn_cpp_source,
    cuda_sources=fused_relu_gn_source,
    functions=["fused_relu_gn_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, groups, bias=False):
        super(ModelNew, self).__init__()
        # ConvTranspose3d is complex and cuDNN implementation is highly optimized, 
        # so we keep the standard PyTorch operator.
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, bias=bias)

        # We replace nn.ReLU and nn.GroupNorm with a custom fused kernel.
        # We manually manage the parameters for GroupNorm.
        self.groups = groups
        self.gamma = nn.Parameter(torch.ones(out_channels))
        self.beta = nn.Parameter(torch.zeros(out_channels))

        self.fused_op = fused_ops

    def forward(self, x):
        # Apply standard ConvTranspose3d
        x = self.conv_transpose(x)

        # Apply custom fused ReLU + GroupNorm
        # x shape: (N, C, D, H, W)
        x = self.fused_op.fused_relu_gn_cuda(x, self.gamma, self.beta, self.groups, 1e-5)

