import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source for Fused GEMM + Bias + Multiply + LeakyReLU
# This kernel implements a tiled matrix multiplication (GEMM) to compute X * W^T
# and fuses the subsequent element-wise operations (Bias Add, Scalar Mul, LeakyReLU)
# directly into the kernel to reduce memory bandwidth usage.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void fused_gemm_leaky_relu_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    const float* __restrict__ bias, 
    float* __restrict__ C, 
    int M, int N, int K, 
    float multiplier, 
    float negative_slope) 
{
    // Inputs:
    // A: [M, K] (Input X)
    // B: [N, K] (Weight W, stored as out_features x in_features)
    // bias: [N]
    // C: [M, N] (Output)

    // Grid dimensions:
    // x maps to columns of C (0..N)
    // y maps to rows of C (0..M)

    int bx = blockIdx.x; 
    int by = blockIdx.y; 

    int tx = threadIdx.x; 
    int ty = threadIdx.y; 

    // Global row and column indices for C
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float val = 0.0f;

    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Loop over tiles of the K dimension
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {

        // Load tile of A into shared memory
        // We need A[row, current_k]. Row is constant per thread (ty).
        if (row < M && (t * TILE_SIZE + tx) < K) {
            As[ty][tx] = A[row * K + (t * TILE_SIZE + tx)];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        // We compute dot product of Row(A) and Row(B).
        // To compute C[row, col], we need B[col, current_k].
        // We organize Bs such that Bs[tx][k] contains B[col][current_k+k].
        // Loading pattern:
        // Thread (tx, ty) loads B[(bx*TILE + ty), (t*TILE + tx)]
        // This corresponds to loading row (bx*TILE + ty) of B.
        if ((bx * TILE_SIZE + ty) < N && (t * TILE_SIZE + tx) < K) {
             Bs[ty][tx] = B[(bx * TILE_SIZE + ty) * K + (t * TILE_SIZE + tx)];
        } else {
             Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product for this tile
        // C[row, col] requires A[row, :] and B[col, :]
        // A[row, k] is in As[ty][k]
        // B[col, k] is in Bs[tx][k] (since col depends on tx, and we loaded rows of B into 'ty' slots of Bs)
        for (int k = 0; k < TILE_SIZE; ++k) {
            val += As[ty][k] * Bs[tx][k];
        }

        __syncthreads();
    }

    // Write result to global memory with fused operations
    if (row < M && col < N) {
        // Fused: Add Bias
        val += bias[col];

        // Fused: Multiply
        val *= multiplier;

        // Fused: LeakyReLU
        if (val < 0) {
            val *= negative_slope;
        }

        C[row * N + col] = val;
    }
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    float multiplier, 
    float negative_slope) 
{
    const int M = x.size(0);
    const int K = x.size(1);
    const int N = weight.size(0);

    auto out = torch::empty({M, N}, x.options());

    const dim3 block_size(TILE_SIZE, TILE_SIZE);
    const dim3 num_blocks((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    fused_gemm_leaky_relu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        M, N, K,
        multiplier,
        negative_slope
    );

    return out;
}
"""

cpp_source = """
torch::Tensor fused_forward_cuda(
    torch::Tensor x, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    float multiplier, 
    float negative_slope);
"""

# Compile the inline CUDA code
fused_op = load_inline(
    name="fused_gemm_leaky_relu",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_forward_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces the separate Linear, Mul, and LeakyReLU operations
    with a single fused CUDA kernel.
    """
    def __init__(self, in_features, out_features, multiplier, negative_slope):
        super(ModelNew, self).__init__()
        # We use nn.Linear to maintain parameters (weight/bias) initialization and management
        self.gemm = nn.Linear(in_features, out_features)
        self.multiplier = multiplier
        self.negative_slope = negative_slope
        self.fused_op = fused_op

    def forward(self, x):
        # Call the custom fused kernel
        # x: (batch, in_features)
        # weight: (out_features, in_features)
        # bias: (out_features)
        return self.fused_op.fused_forward_cuda(
            x, 
            self.gemm.weight, 
            self.gemm.bias, 
            self.multiplier, 
            self.negative_slope
        )

