from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Conv2d + Div + LeakyReLU
fused_source_cuda = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_conv_div_leakyrelu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int kernel_size,
    int out_h,
    int out_w,
    float divisor,
    float negative_slope
) {
    // Grid Setup:
    // blockIdx.z -> Batch index (n)
    // blockIdx.y -> Output Channel index (c_out)
    // blockIdx.x * blockDim.x + threadIdx.x -> Spatial Linear Index (h_out * out_w + w_out)

    int n = blockIdx.z;
    int c_out = blockIdx.y;
    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Boundary check for spatial dimensions
    if (spatial_idx >= out_h * out_w) return;

    // Map spatial index back to h_out, w_out
    int h_out = spatial_idx / out_w;
    int w_out = spatial_idx % out_w;

    // Initialize accumulator with bias if available
    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c_out];
    }

    // Convolution Logic (Stride=1, Padding=0 as per original architecture)
    // To optimize, we pre-calculate base offsets

    // Offset for the current batch image in input: n * (C_in * H_in * W_in)
    int input_batch_offset = n * in_channels * in_h * in_w;

    // Offset for the current output channel filters in weight: c_out * (C_in * K * K)
    int weight_cout_offset = c_out * in_channels * kernel_size * kernel_size;

    for (int c_in = 0; c_in < in_channels; ++c_in) {
        int input_cin_offset = input_batch_offset + c_in * in_h * in_w;
        int weight_cin_offset = weight_cout_offset + c_in * kernel_size * kernel_size;

        for (int i = 0; i < kernel_size; ++i) {
            for (int j = 0; j < kernel_size; ++j) {
                int h_in = h_out + i; // valid convolution mapping
                int w_in = w_out + j;

                // Load input and weight
                float in_val = input[input_cin_offset + h_in * in_w + w_in];
                float w_val = weight[weight_cin_offset + i * kernel_size + j];

                sum += in_val * w_val;
            }
        }
    }

    // --- Fused Operations ---

    // 1. Division by constant
    sum = sum / divisor;

    // 2. LeakyReLU
    if (sum < 0) {
        sum = sum * negative_slope;
    }

    // Write to Global Memory
    // Output offset: n * (C_out * H_out * W_out) + c_out * (H_out * W_out) + spatial_idx
    int output_offset = n * out_channels * out_h * out_w + c_out * out_h * out_w + spatial_idx;
    output[output_offset] = sum;
}

torch::Tensor fused_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float divisor,
    float negative_slope,
    int kernel_size
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_channels = weight.size(0);
    // Calculate output dimensions for valid padding (padding=0, stride=1)
    int out_h = in_h - kernel_size + 1;
    int out_w = in_w - kernel_size + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    // Kernel Launch Configuration
    int total_spatial = out_h * out_w;
    const int threads_per_block = 256;
    int blocks_spatial = (total_spatial + threads_per_block - 1) / threads_per_block;

    // Grid Dimensions: (Spatial Blocks, Output Channels, Batch Size)
    dim3 grid(blocks_spatial, out_channels, batch_size);
    dim3 block(threads_per_block);

    fused_conv_div_leakyrelu_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        kernel_size,
        out_h,
        out_w,
        divisor,
        negative_slope
    );

    return output;
