import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code for fused BatchNorm + Tanh + MaxPool2d
# This kernel optimizes memory bandwidth by fusing three element-wise/window-based operations
# into a single kernel pass, avoiding intermediate global memory reads/writes.
fused_bn_tanh_maxpool_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_bn_tanh_maxpool_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int height_in,
    int width_in,
    int height_out,
    int width_out,
    float epsilon) 
{
    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = batch_size * channels * height_out * width_out;

    if (idx < total_output_elements) {
        // Decode linear index into (n, c, h_out, w_out)
        int w_out = idx % width_out;
        int temp = idx / width_out;
        int h_out = temp % height_out;
        temp = temp / height_out;
        int c = temp % channels;
        int n = temp; 

        // Load Batch Norm parameters for the current channel
        // BN Formula: y = (x - mean) / sqrt(var + eps) * weight + bias
        // Optimization: y = x * scale + shift
        float m = bn_mean[c];
        float v = bn_var[c];
        float w = bn_weight[c];
        float b = bn_bias[c];

        float inv_std = rsqrtf(v + epsilon);
        float scale = w * inv_std;
        float shift = b - m * scale;

        // MaxPool2d window calculation (Kernel=2, Stride=2)
        int h_start = h_out * 2;
        int w_start = w_out * 2;

        float max_val = -1e20f; // Initialize with a very small number

        // Unrolled loop for 2x2 window
        #pragma unroll
        for (int i = 0; i < 2; ++i) {
            #pragma unroll
            for (int j = 0; j < 2; ++j) {
                int h_curr = h_start + i;
                int w_curr = w_start + j;

                // Boundary check (handles odd input dimensions correctly)
                if (h_curr < height_in && w_curr < width_in) {
                    int input_idx = ((n * channels + c) * height_in + h_curr) * width_in + w_curr;
                    float val = input[input_idx];

                    // Apply Fused Operations: BN -> Tanh
                    val = val * scale + shift;
                    val = tanhf(val);

                    // Apply MaxPool
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }
        output[idx] = max_val;
    }
}

torch::Tensor fused_bn_tanh_maxpool_forward(
    torch::Tensor input,
    torch::Tensor bn_mean,
    torch::Tensor bn_var,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    double epsilon) 
{
    // Ensure inputs are on CUDA
    TORCH_CHECK(input.is_cuda, "Input must be on CUDA");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(bn_mean.is_cuda, "Mean must be on CUDA");
    TORCH_CHECK(bn_var.is_cuda, "Var must be on CUDA");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int height_in = input.size(2);
    int width_in = input.size(3);

    // Calculate output dimensions for MaxPool2d(2, 2)
    int height_out = height_in / 2;
    int width_out = width_in / 2;

    auto output = torch::empty({batch_size, channels, height_out, width_out}, input.options());

    int total_output = batch_size * channels * height_out * width_out;
    const int block_size = 256;
    const int num_blocks = (total_output + block_size - 1) / block_size;

    fused_bn_tanh_maxpool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bn_mean.data_ptr<float>(),
        bn_var.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels, height_in, width_in, height_out, width_out, (float)epsilon
    );

    return output;
}
"""

fused_cpp_source = "torch::Tensor fused_bn_tanh_maxpool_forward(torch::Tensor input, torch::Tensor bn_mean, torch::Tensor bn_var, torch::Tensor bn_weight, torch::Tensor bn_bias, double epsilon);"

# Compile and load the fused operator
fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_bn_tanh_maxpool_source,
    functions=['fused_bn_tanh_maxpool_forward'],
    verbose=True
