import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source for fused BatchNorm + AvgPool
# This kernel performs the operation of:
# 1. AvgPool3d(kernel_size=4, stride=4) (Equivalent to two consecutive AvgPool3d(2) layers)
# 2. BatchNorm3d (Applied after pooling for efficiency, valid for inference/fixed stats)
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_bn_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    float eps) {

    // Grid maps to Output tensor dimensions
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * Dout * Hout * Wout;

    if (idx < total_elements) {
        // Decompose linear index into (n, c, d_out, h_out, w_out)
        int temp = idx;
        int w_out = temp % Wout; temp /= Wout;
        int h_out = temp % Hout; temp /= Hout;
        int d_out = temp % Dout; temp /= Dout;
        int c = temp % C; 
        int n = temp / C;

        // Calculate corresponding top-left corner in Input tensor
        // Stride is 4 effectively (2 * 2)
        int d_in_start = d_out * 4;
        int h_in_start = h_out * 4;
        int w_in_start = w_out * 4;

        // Strides for Input tensor (N, C, Din, Hin, Win)
        int input_depth_stride = Hin * Win;
        int input_height_stride = Win;
        int input_channel_stride = Din * input_depth_stride;
        int input_batch_stride = C * input_channel_stride;

        int input_offset = n * input_batch_stride + c * input_channel_stride;
        const float* input_slice = input + input_offset;

        float sum = 0.0f;

        // Accumulate 4x4x4 block
        #pragma unroll
        for (int z = 0; z < 4; ++z) {
            #pragma unroll
            for (int y = 0; y < 4; ++y) {
                #pragma unroll
                for (int x = 0; x < 4; ++x) {
                    int d_in = d_in_start + z;
                    int h_in = h_in_start + y;
                    int w_in = w_in_start + x;

                    int in_idx = d_in * input_depth_stride + h_in * input_height_stride + w_in;
                    sum += input_slice[in_idx];
                }
            }
        }

        // Average
        float avg = sum / 64.0f;

        // Apply BatchNorm: y = (x - mean) / sqrt(var + eps) * weight + bias
        float m = mean[c];
        float v = var[c];
        float w = weight[c];
        float b = bias[c];

        float res = (avg - m) * rsqrtf(v + eps) * w + b;

        output[idx] = res;
    }
}

torch::Tensor fused_bn_pool_cuda(
    torch::Tensor input,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps) {

    // Ensure contiguous memory for pointers
    if (!input.is_contiguous()) input = input.contiguous();

    int N = input.size(0);
    int C = input.size(1);
    int Din = input.size(2);
    int Hin = input.size(3);
    int Win = input.size(4);

    // Output dimensions: (In - 4) // 4 + 1
    int Dout = (Din - 4) / 4 + 1;
    int Hout = (Hin - 4) / 4 + 1;
    int Wout = (Win - 4) / 4 + 1;

    auto output = torch::empty({N, C, Dout, Hout, Wout}, input.options());

    int total_elements = N * C * Dout * Hout * Wout;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_bn_pool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        N, C, Din, Hin, Win, Dout, Hout, Wout, eps
    );

    return output;
}
"""

fused_cpp_source = "torch::Tensor fused_bn_pool_cuda(torch::Tensor input, torch::Tensor mean, torch::Tensor var, torch::Tensor weight, torch::Tensor bias, float eps);"

# Compile the inline CUDA code
