import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused Bias + GELU + Softmax
# This kernel optimizes the post-GEMM operations by:
# 1. Fusing Bias addition, GELU activation, and Softmax into one kernel.
# 2. Utilizing Shared Memory to cache the row data, reducing Global Memory I/O.
# 3. Performing efficient block-level reductions for Softmax statistics.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_bias_gelu_softmax_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int features) {

    // Dynamic shared memory layout:
    // [0 ... features-1]: Row data cache
    // [features ... features+31]: Warp reduction buffer
    extern __shared__ float s_data[]; 
    float* row_cache = s_data;
    float* reduce_buffer = &s_data[features];

    int row = blockIdx.x;
    int tid = threadIdx.x;
    int lane = tid % 32;
    int warp = tid / 32;

    if (row >= batch_size) return;

    // Pointers for this row
    const float* row_input = input + row * features;
    float* row_output = output + row * features;

    // -----------------------------------------------------------
    // Phase 1: Load, Add Bias, Gelu, Compute Max
    // -----------------------------------------------------------
    float thread_max = -1e37f; // Initialize with a very small number

    for (int i = tid; i < features; i += blockDim.x) {
        float val = row_input[i] + bias[i];

        // GELU Approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
        // 0.70710678f is 1/sqrt(2)
        float cdf = 0.5f * (1.0f + erff(val * 0.70710678f));
        val = val * cdf;

        row_cache[i] = val; // Store fused gelu result in shared mem
        if (val > thread_max) {
            thread_max = val;
        }
    }

    // Warp Reduce Max
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        thread_max = fmaxf(thread_max, __shfl_down_sync(0xFFFFFFFF, thread_max, offset));
    }

    // Write warp max to shared memory buffer
    if (lane == 0) {
        reduce_buffer[warp] = thread_max;
    }
    __syncthreads();

    // Block Reduce Max (Lead warp reduces the warp maxes)
    float row_max = -1e37f;
    if (warp == 0) {
        // We have 32 warps (1024 threads)
        row_max = (tid < 32) ? reduce_buffer[tid] : -1e37f; 

        #pragma unroll
        for (int offset = 16; offset > 0; offset /= 2) {
            row_max = fmaxf(row_max, __shfl_down_sync(0xFFFFFFFF, row_max, offset));
        }

        // Broadcast max to all via shared mem
        if (tid == 0) {
            reduce_buffer[0] = row_max; 
        }
    }
    __syncthreads();
    row_max = reduce_buffer[0];

    // -----------------------------------------------------------
    // Phase 2: Compute Exp and Sum
    // -----------------------------------------------------------
    float thread_sum = 0.0f;

    for (int i = tid; i < features; i += blockDim.x) {
        float val = row_cache[i];
        val = expf(val - row_max); // Stable softmax
        row_cache[i] = val;        // Store exp values to reuse
        thread_sum += val;
    }

    // Warp Reduce Sum
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        thread_sum += __shfl_down_sync(0xFFFFFFFF, thread_sum, offset);
    }

    if (lane == 0) {
        reduce_buffer[warp] = thread_sum;
    }
    __syncthreads();

    // Block Reduce Sum
    float row_sum = 0.0f;
    if (warp == 0) {
        row_sum = (tid < 32) ? reduce_buffer[tid] : 0.0f;

        #pragma unroll
        for (int offset = 16; offset > 0; offset /= 2) {
            row_sum += __shfl_down_sync(0xFFFFFFFF, row_sum, offset);
        }

        if (tid == 0) {
            reduce_buffer[0] = row_sum;
        }
    }
    __syncthreads();
    row_sum = reduce_buffer[0];

    // -----------------------------------------------------------
    // Phase 3: Normalize and Store
    // -----------------------------------------------------------
    float inv_sum = 1.0f / row_sum;

    for (int i = tid; i < features; i += blockDim.x) {
        row_output[i] = row_cache[i] * inv_sum;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor bias) {
    auto batch_size = input.size(0);
    auto features = input.size(1);
    auto output = torch::empty_like(input);

    // Launch configuration
    const int threads = 1024;
    const int blocks = batch_size;

    // Shared memory needs: features * float (data) + 32 * float (reduction buffer)
    int shared_mem_size = (features + 32) * sizeof(float);

    fused_bias_gelu_softmax_kernel<<<blocks, threads, shared_mem_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        features
    );

    return output;
}
"""

