# Define the custom CUDA kernel for the fused post-convolution operations.
# This kernel fuses three element-wise operations:
# 1. min(x, constant_value)
# 2. x + bias (with channel-wise broadcasting)
# 3. x * scaling_factor
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_ops_kernel(
    float* __restrict__ x,
    const float* __restrict__ bias,
    float constant_value,
    float scaling_factor,
    int numel,
    int channels,
    int spatial_size)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < numel) {
        // x tensor layout is (N, C, H, W)
        // bias tensor layout is (C, 1, 1) -> effectively (C)

        // We need to determine the channel index 'c' corresponding to the current element 'idx'
        // The spatial dimensions (H * W) are contiguous in memory for each channel.
        // spatial_size = H * W

        // global_channel_idx = idx / spatial_size calculates the flat channel index (ignoring batch structure effectively)
        // c = global_channel_idx % channels extracts the channel index within the batch

        int c = (idx / spatial_size) % channels;

        float val = x[idx];

        // Operation 1: Element-wise min with constant (Clamping upper bound)
        val = fminf(val, constant_value);

        // Operation 2: Add bias (Broadcasted along channels)
        val = val + bias[c];

        // Operation 3: Multiply by scaling factor
        val = val * scaling_factor;

        // Write back to global memory
        x[idx] = val;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias, float constant_value, float scaling_factor) {
    int numel = x.numel();
    if (numel == 0) return x;

    int channels = x.size(1);
    int height = x.size(2);
    int width = x.size(3);
    int spatial_size = height * width;

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    // Ensure bias is contiguous for valid pointer arithmetic in the kernel
    auto bias_contig = bias.contiguous();

    fused_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias_contig.data_ptr<float>(),
        constant_value,
        scaling_factor,
        numel,
        channels,
        spatial_size
    );

    return x;
}
