import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused Mish activation
# Mish(x) = x * tanh(softplus(x))
# This fuses the element-wise operations: exp, log1p, tanh, mul
mish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void mish_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];

        // Softplus: log(1 + exp(x))
        // Mish: x * tanh(softplus(x))

        // Numerical stability optimization:
        // For large x, softplus(x) approx x
        // For large negative x, exp(x) -> 0, so softplus(x) -> 0

        float sp;
        if (x > 20.0f) {
            sp = x;
        } else {
            sp = log1pf(expf(x));
        }

        output[idx] = x * tanhf(sp);
    }
}

torch::Tensor mish_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA");

    // Ensure input is contiguous for linear access
    input = input.contiguous();

    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    mish_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}
