import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fusing BatchNorm (inference), Scale, and Softmax
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void fused_bn_scale_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int M,
    float eps) {

    // Dynamic shared memory to cache the row and intermediate values
    extern __shared__ float shared_mem[];
    float* s_data = shared_mem; 
    // Reduction buffer at the end of s_data (need space for max 32 warps)
    float* s_reduce = &s_data[M];

    int tid = threadIdx.x;
    int row = blockIdx.x;
    int lane = tid % 32;
    int warpId = tid / 32;

    float local_max = -1e38f;

    // 1. Load, BN, Scale, Store to Shared, Track Local Max
    for (int i = tid; i < M; i += blockDim.x) {
        float val = x[row * M + i];

        // Batch Norm Inference Logic:
        // y = (x - mean) / sqrt(var + eps) * gamma + beta
        float mu = mean[i];
        float sigma2 = var[i];
        float gam = weight[i];
        float bet = bias[i];

        val = (val - mu) * rsqrtf(sigma2 + eps) * gam + bet;

        // Scale
        val = val * scale[0];

        s_data[i] = val;
        local_max = fmaxf(local_max, val);
    }

    // Block Reduce Max
    local_max = warpReduceMax(local_max);
    if (lane == 0) s_reduce[warpId] = local_max;
    __syncthreads();

    if (tid == 0) {
        float block_max = -1e38f;
        int num_warps = blockDim.x / 32;
        for (int i = 0; i < num_warps; i++) {
            block_max = fmaxf(block_max, s_reduce[i]);
        }
        s_reduce[0] = block_max; 
    }
    __syncthreads();

    float global_max = s_reduce[0];

    // 2. Compute Sum Exp
    float local_sum = 0.0f;
    for (int i = tid; i < M; i += blockDim.x) {
        float val = s_data[i];
        val = expf(val - global_max);
        s_data[i] = val; // Store exponentiated value
        local_sum += val;
    }

    // Block Reduce Sum
    local_sum = warpReduceSum(local_sum);
    if (lane == 0) s_reduce[warpId] = local_sum;
    __syncthreads();

    if (tid == 0) {
        float block_sum = 0.0f;
        int num_warps = blockDim.x / 32;
        for (int i = 0; i < num_warps; i++) {
            block_sum += s_reduce[i];
        }
        s_reduce[0] = block_sum;
    }
    __syncthreads();

    float global_sum = s_reduce[0];
    float inv_sum = 1.0f / global_sum;

    // 3. Write Output
    for (int i = tid; i < M; i += blockDim.x) {
        out[row * M + i] = s_data[i] * inv_sum;
    }
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x, 
    torch::Tensor mean, 
    torch::Tensor var, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    torch::Tensor scale, 
