    auto M = x.size(1);
    auto out = torch::empty_like(x);

    const int block_size = 256;
    // Shared mem needs M floats for data + 32 floats for reduction buffer (max warps for 1024 threads is 32)
    const int shared_mem_size = (M + 32) * sizeof(float);

    fused_bn_scale_softmax_kernel<<<N, block_size, shared_mem_size>>>(
