import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused post-processing
# This kernel fuses:
# 1. Global Average Pooling (Mean over spatial dims)
# 2. Bias Addition
# 3. LogSumExp (over channel dim)
# 4. Multiplication (scalar)
# This avoids multiple kernel launches and memory reads/writes of intermediate tensors.

fused_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel 1: Spatial Mean Reduction + Bias Add
// Reduces [N, C, H, W] -> [N, C]
// Each block handles one (n, c) pair reducing H*W pixels.
template <typename scalar_t>
__global__ void spatial_mean_bias_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int C,
    int H,
    int W) {

    int n = blockIdx.x;
    int c = blockIdx.y;
    int tid = threadIdx.x;

    size_t num_pixels = (size_t)H * W;
    size_t input_offset = (size_t)n * C * num_pixels + c * num_pixels;

    float sum = 0.0f;
    // Grid-stride loop (though usually threads cover logic, this handles arbitrary H*W)
    for (size_t i = tid; i < num_pixels; i += blockDim.x) {
        sum += static_cast<float>(input[input_offset + i]);
    }

    extern __shared__ float sdata[];
    sdata[tid] = sum;
    __syncthreads();

    // Block reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = sdata[0] / static_cast<float>(num_pixels);
        // Add bias and store
        output[n * C + c] = static_cast<scalar_t>(mean + static_cast<float>(bias[c]));
    }
}

// Kernel 2: LogSumExp + Scalar Multiplication
// Reduces [N, C] -> [N, 1]
// Each block handles one 'n', reducing over 'C'.
template <typename scalar_t>
__global__ void lse_mul_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    int C) {

    int n = blockIdx.x;
    int tid = threadIdx.x;

    // Load data
    float val = -1e30f; // -inf for padding
    if (tid < C) {
        val = static_cast<float>(input[n * C + tid]);
    }

    extern __shared__ float sdata_lse[];

    // Step 1: Find Max (for numerical stability)
    sdata_lse[tid] = val;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata_lse[tid] = fmaxf(sdata_lse[tid], sdata_lse[tid + s]);
        }
        __syncthreads();
    }
    float max_val = sdata_lse[0];
    __syncthreads();

    // Step 2: Sum exp(val - max)
    float exp_val = 0.0f;
    if (tid < C) {
        exp_val = expf(val - max_val);
    }
    sdata_lse[tid] = exp_val;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata_lse[tid] += sdata_lse[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float lse = max_val + logf(sdata_lse[0]);
        // Multiply by 10.0 and store
        output[n] = static_cast<scalar_t>(lse * 10.0f);
