import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations: 
# Softmax(dim=1) -> Subtract -> Swish -> Max(dim=1)
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ sub,
    float* __restrict__ out,
    int N, int C, int D, int H, int W) {

    // Spatial volume of one 3D feature map (D * H * W)
    int spatial_vol = D * H * W;

    // Global thread index
    // Each thread handles one spatial location (d, h, w) for a specific batch item n
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * spatial_vol;

    if (idx < total_threads) {
        // Map linear index to (n, spatial_idx)
        int n = idx / spatial_vol;
        int spatial_idx = idx % spatial_vol;

        // Calculate stride to jump to the next channel at the same spatial position
        // Memory layout is (N, C, D, H, W)
        // Element index = n * (C * spatial_vol) + c * spatial_vol + spatial_idx
        int channel_stride = spatial_vol;

        // Pointer to the start of the channel vector for this spatial location
        const float* x_ptr = x + n * C * spatial_vol + spatial_idx;

        // ----------------------------------------------------------------
        // Step 1: Softmax (across C)
        // ----------------------------------------------------------------

        // Find Max for numerical stability
        float max_val = -1e30f;
        for (int c = 0; c < C; ++c) {
            float val = x_ptr[c * channel_stride];
            if (val > max_val) {
                max_val = val;
            }
        }

        // Compute Sum of Exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            sum_exp += expf(x_ptr[c * channel_stride] - max_val);
        }

        // Precompute reciprocal of sum
        float inv_sum_exp = 1.0f / sum_exp;

        // ----------------------------------------------------------------
        // Step 2, 3, 4: Softmax -> Subtract -> Swish -> Reduce Max
        // ----------------------------------------------------------------

        float global_max = -1e30f;

        for (int c = 0; c < C; ++c) {
            float val = x_ptr[c * channel_stride];

            // Softmax value
            float s = expf(val - max_val) * inv_sum_exp;

            // Subtract (sub is shape (C))
            float sub_val = sub[c];
            float y = s - sub_val;

            // Swish: y * sigmoid(y) = y / (1 + exp(-y))
            float z = y / (1.0f + expf(-y));

            // Max Reduction
            if (z > global_max) {
                global_max = z;
            }
        }

        // Write output
        // Output shape is (N, D, H, W) flattened, which maps exactly to thread idx
        out[idx] = global_max;
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor sub) {
    // x: (N, C, D, H, W)
    // sub: (C)

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    auto out = torch::empty({N, D, H, W}, x.options());

    int total_threads = N * D * H * W;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        sub.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W
    );

    return out;
}
"""

cpp_source = "torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor sub);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_forward_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA kernel for post-pooling operations.
    Replaces Softmax + Subtract + Swish + Max with a single fused kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, pool_kernel_size, pool_stride, pool_padding):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)
        self.max_pool = nn.MaxPool3d(kernel_size=pool_kernel_size, stride=pool_stride, padding=pool_padding)
        self.subtract = nn.Parameter(torch.randn(out_channels))
        self.fused_ops = fused_ops

    def forward(self, x):
        # Heavy 3D convolution and Pooling are efficiently handled by cuDNN backing PyTorch
        x = self.conv_transpose(x)
        x = self.max_pool(x)

        # Ensure contiguous memory for the custom kernel to handle pointer arithmetic correctly
        if not x.is_contiguous():
            x = x.contiguous()

        # Fused operation: Softmax -> Subtract -> Swish -> Max
        return self.fused_ops.fused_forward_cuda(x, self.subtract)

