fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_mul_leaky_gelu_kernel(
    float* __restrict__ x, 
    const float* __restrict__ multiplier, 
    int total_elements, 
    int plane_size, 
    int channels, 
    float negative_slope) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // x layout is (N, C, H, W)
        // plane_size = H * W
        // To find channel c: (idx / plane_size) % channels

        int c = (idx / plane_size) % channels;

        float val = x[idx];

        // Operation 1: Multiply by learnable scalar per channel
        val *= multiplier[c];

        // Operation 2: LeakyReLU
        // f(x) = x if x >= 0 else x * negative_slope
        if (val < 0.0f) {
            val *= negative_slope;
        }

        // Operation 3: GELU (Exact)
        // GELU(x) = x * 0.5 * (1 + erf(x / sqrt(2)))
        // 1/sqrt(2) approx 0.70710678
        const float kAlpha = 0.70710678f;
        val = val * 0.5f * (1.0f + erff(val * kAlpha));

        x[idx] = val;
    }
}

