class ModelNew(nn.Module):
    """
    Optimized architecture using a custom CUDA kernel to fuse Swish, Bias Add, and GroupNorm.
    """
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        # nn.Linear uses cuBLAS which is highly optimized for Matrix Multiplication.
        # We keep this as is.
        self.matmul = nn.Linear(in_features, out_features)

        # Original bias parameter
        self.bias = nn.Parameter(torch.randn(bias_shape))

        # GroupNorm layer (provides weight and bias parameters)
        self.group_norm = nn.GroupNorm(num_groups, out_features)

        self.fused_ops = fused_ops

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).
        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_features).
        """
        # 1. Matrix Multiplication (Compute Bound)
        x = self.matmul(x)

        # 2. Fused Kernel (Memory Bound optimization)
        # Combines: Swish(x) -> Add Bias -> GroupNorm
        # x is (N, C)
        # self.bias is (C)
        # self.group_norm.weight/bias are (C)
        return self.fused_ops.fused_forward_cuda(
            x, 
            self.bias, 
            self.group_norm.weight, 
            self.group_norm.bias, 
            self.group_norm.num_groups
        )

