import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Swish activation and scaling
# This fuses: x = x * sigmoid(x) * scaling_factor
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Helper for sigmoid
__device__ inline float sigmoid_dev(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_swish_scale_kernel(float* __restrict__ x, float scale, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Use float4 for vectorized memory access to improve bandwidth
    int vec_size = size / 4;
    float4* x_vec = reinterpret_cast<float4*>(x);

    for (int i = idx; i < vec_size; i += stride) {
        float4 v = x_vec[i];

        // Apply Swish (x * sigmoid(x)) and scale
        v.x = v.x * sigmoid_dev(v.x) * scale;
        v.y = v.y * sigmoid_dev(v.y) * scale;
        v.z = v.z * sigmoid_dev(v.z) * scale;
        v.w = v.w * sigmoid_dev(v.w) * scale;

        x_vec[i] = v;
    }

    // Handle remaining elements for sizes not divisible by 4
    int rem_start = vec_size * 4;
    for (int i = rem_start + idx; i < size; i += stride) {
        float v_val = x[i];
        x[i] = v_val * sigmoid_dev(v_val) * scale;
    }
}

torch::Tensor fused_swish_scale_cuda(torch::Tensor x, float scale) {
    // Ensure input is on CUDA and contiguous
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");

    int size = x.numel();
    const int block_size = 256;

    // Calculate grid size. 
    // We process 4 elements per thread in the main loop.
    int vec_size = size / 4;
    int num_blocks = (vec_size + block_size - 1) / block_size;

    // Cap grid size to a reasonable number to avoid launch overhead 
    // The grid-stride loop in the kernel ensures full coverage
    if (num_blocks > 2048) num_blocks = 2048;

    fused_swish_scale_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), scale, size);

    return x;
}
"""

