import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
# Operations fused: Tanh -> HardSwish -> Residual Add -> LogSumExp (channel dim)
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ x_conv,
    const float* __restrict__ x_norm,
    float* __restrict__ out,
    int N, int C, int H, int W) {

    // Flatten spatial dimensions
    int spatial_size = H * W;
    int total_output_elements = N * spatial_size;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Map linear index back to (n, h, w) components
        // The output is (N, 1, H, W), so idx corresponds to the spatial location across batch
        int n = idx / spatial_size;
        int rem = idx % spatial_size; // corresponds to h * W + w

        // Calculate base memory offset for this spatial location
        // Input layout is NCHW. We iterate over C.
        // Address: n * (C * H * W) + c * (H * W) + rem
        //        = n * C * spatial_size + c * spatial_size + rem
        int base_offset = n * C * spatial_size + rem;
        int stride = spatial_size;

        // Online LogSumExp accumulation variables
        // We compute log(sum(exp(x_i))) along the channel dimension.
        // To ensure numerical stability, we track the max value seen so far (alpha).
        float max_val = -1e20f; // Initialize with a very small number
        float sum_exp = 0.0f;

        for (int c = 0; c < C; ++c) {
            int ptr = base_offset + c * stride;

            float xc = x_conv[ptr];
            float xn = x_norm[ptr];

            // 1. Tanh
            float t = tanhf(xn);

            // 2. HardSwish: x * ReLU6(x+3)/6
            // Here input x is the output of Tanh (t)
            float z = t + 3.0f;
            float relu6 = z < 0.0f ? 0.0f : (z > 6.0f ? 6.0f : z);
            float hs = t * relu6 * 0.166666667f; // Multiply by 1/6

            // 3. Residual Addition
            float val = xc + hs;

            // 4. Online LogSumExp update
            if (val > max_val) {
                // If new value is larger, adjust existing sum_exp to the new max
                sum_exp = sum_exp * expf(max_val - val) + 1.0f;
                max_val = val;
            } else {
                // Otherwise just add to sum_exp relative to current max
                sum_exp += expf(val - max_val);
            }
        }

        // Final LogSumExp computation
        out[idx] = max_val + logf(sum_exp);
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x_conv, torch::Tensor x_norm) {
    TORCH_CHECK(x_conv.is_cuda, "x_conv must be a CUDA tensor");
    TORCH_CHECK(x_norm.is_cuda, "x_norm must be a CUDA tensor");
    TORCH_CHECK(x_conv.sizes() == x_norm.sizes(), "Input tensors must have the same shape");

    int N = x_conv.size(0);
    int C = x_conv.size(1);
    int H = x_conv.size(2);
    int W = x_conv.size(3);

    // Output shape is [N, 1, H, W] because LogSumExp reduces dimension 1 (channels)
    auto out = torch::empty({N, 1, H, W}, x_conv.options());

    int total_output_elements = N * H * W;
    const int threads = 256;
    const int blocks = (total_output_elements + threads - 1) / threads;

    fused_ops_kernel<<<blocks, threads>>>(
        x_conv.data_ptr<float>(),
        x_norm.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W
    );

    return out;
}
"""

cpp_source = """
torch::Tensor fused_forward_cuda(torch::Tensor x_conv, torch::Tensor x_norm);
"""

# Compile the inline CUDA extension
fused_ops = load_inline(
    name="fused_ops_extension",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_forward_cuda"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model using a fused CUDA kernel for the post-convolution operations.
    Retains PyTorch's optimized Conv2d and GroupNorm, but fuses Tanh, HardSwish, 
    Residual Addition, and LogSumExp into a single bandwidth-efficient kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, groups, eps=1e-5):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(groups, out_channels, eps=eps)
        self.fused_ops = fused_ops

    def forward(self, x):
        # Convolution
        x_conv = self.conv(x)

        # Group Normalization (kept as PyTorch op as it's highly optimized and complex to fuse purely)
        x_norm = self.group_norm(x_conv)

        # Fused Kernel:
        # Inputs: x_conv, x_norm
        # Computes: LogSumExp(x_conv + HardSwish(Tanh(x_norm)), dim=1)
        return self.fused_ops.fused_forward_cuda(x_conv, x_norm)

