import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused MaxPool + Tanh + Scaling + Bias
# We exploit the mathematical property that for a strictly increasing function f (like tanh)
# and a positive scaling factor s: max(f(x)*s + b) == f(max(x))*s + b.
# This allows us to perform the reduction (MaxPool) *before* the expensive element-wise operations (Tanh),
# significantly reducing the number of tanh calculations and memory I/O.
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_pool_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    float scaling_factor,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int pool_k) {

    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        // Map linear index to output coordinates (n, c, h_out, w_out)
        // Layout is NCHW
        int w_out = idx % W_out;
        int temp = idx / W_out;
        int h_out = temp % H_out;
        temp = temp / H_out;
        int c = temp % C;
        int n = temp / C;

        // Calculate input window top-left corner
        // Assuming stride == pool_k (standard MaxPool2d behavior)
        int h_start = h_out * pool_k;
        int w_start = w_out * pool_k;

        // Find max in the pooling window
        float max_val = -FLT_MAX;

        // Calculate base offset for this (n, c) slice in input
        int input_slice_offset = n * (C * H_in * W_in) + c * (H_in * W_in);

        #pragma unroll
        for (int i = 0; i < pool_k; ++i) {
            #pragma unroll
            for (int j = 0; j < pool_k; ++j) {
                int h_in = h_start + i;
                int w_in = w_start + j;

                // Boundary check
                if (h_in < H_in && w_in < W_in) {
                    float val = x[input_slice_offset + h_in * W_in + w_in];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }

        // Apply pointwise operations on the pooled value
        // tanh(x)
        float res = tanhf(max_val);
        // * scaling_factor
        res = res * scaling_factor;
        // + bias (broadcasting over channel)
        res = res + bias[c]; 

        out[idx] = res;
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor, int pool_k) {
    int N = x.size(0);
    int C = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    // Output dimensions: floor((Input - Kernel) / Stride + 1)
    // We assume stride == pool_kernel_size
    int H_out = (H_in - pool_k) / pool_k + 1;
    int W_out = (W_in - pool_k) / pool_k + 1;

    auto out = torch::empty({N, C, H_out, W_out}, x.options());

    int total_elements = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_pool_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        scaling_factor,
        N, C, H_in, W_in,
        H_out, W_out,
        pool_k
    );

    return out;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor, int pool_k);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scaling_factor = scaling_factor
        # bias_shape is (out_channels, 1, 1), so it's effectively a vector of size out_channels
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.pool_kernel_size = pool_kernel_size
        self.fused_ops = fused_ops

    def forward(self, x):
        # Perform convolution (highly optimized by cuDNN usually)
        x = self.conv(x)

        # Use custom fused kernel for the rest:
        # 1. MaxPool
        # 2. Tanh
        # 3. Scaling
        # 4. Bias Addition
        # This fuses 4 operations into 1 kernel launch and minimizes memory access.
        # It also optimizes compute by doing Tanh once per output pixel instead of once per input pixel.
        return self.fused_ops.fused_forward_cuda(x, self.bias, self.scaling_factor, self.pool_kernel_size)

