import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Softmax + Sigmoid
# This kernel fuses the channel-wise Softmax and element-wise Sigmoid operations
# to reduce global memory reads/writes and kernel launch overhead.
# It handles the memory layout of PyTorch tensors (N, C, D, H, W) efficiently
# by assigning threads to spatial locations and looping over channels.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_softmax_sigmoid_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                             int channels, int spatial_size, int total_threads) {
    // Each thread handles one spatial location (n, d, h, w) across all channels.
    // Index 'idx' corresponds to the flattened spatial dimension N * D * H * W.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_threads) {
        // Calculate offsets based on memory layout (N, C, D, H, W) -> (N, C, S)
        // idx = n * S + s
        int s = idx % spatial_size;
        int n = idx / spatial_size;

        // Base pointer index for this spatial location:
        // offset = n * (C * S) + c * S + s
        // We factor out (n * C * S + s) as base, and iterate c * S.
        int base_offset = n * (channels * spatial_size) + s;
        int stride = spatial_size; // Stride to jump between channels

        // Pass 1: Find Max (for Softmax numerical stability)
        float max_val = -1e38f;
        for (int c = 0; c < channels; ++c) {
            float val = input[base_offset + c * stride];
            if (val > max_val) {
                max_val = val;
            }
        }

        // Pass 2: Calculate Sum of Exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < channels; ++c) {
            sum_exp += expf(input[base_offset + c * stride] - max_val);
        }

        // Pass 3: Compute Softmax value, apply Sigmoid, and write output
        // Sigmoid(Softmax(x)) = 1 / (1 + exp(- (exp(x-max)/sum) ))
        float inv_sum = 1.0f / sum_exp;
        for (int c = 0; c < channels; ++c) {
            float val = input[base_offset + c * stride];
            float softmax_val = expf(val - max_val) * inv_sum;
            float sigmoid_val = 1.0f / (1.0f + expf(-softmax_val));
            output[base_offset + c * stride] = sigmoid_val;
        }
    }
}

torch::Tensor fused_softmax_sigmoid_cuda(torch::Tensor input) {
    // Input tensor shape: (N, C, D, H, W)

    // Ensure input is contiguous to guarantee the stride math in kernel is correct
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    const int N = input.size(0);
    const int C = input.size(1);
    const int D = input.size(2);
    const int H = input.size(3);
    const int W = input.size(4);

    const int spatial_size = D * H * W;
    const int total_threads = N * spatial_size;

    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    fused_softmax_sigmoid_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        C,
        spatial_size,
        total_threads
    );

    return output;
}
"""

cpp_source = """
torch::Tensor fused_softmax_sigmoid_cuda(torch::Tensor input);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_softmax_sigmoid",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_softmax_sigmoid_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution,
    followed by a fused custom CUDA kernel for Softmax and Sigmoid.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias=True):
        super(ModelNew, self).__init__()
        # We keep the standard ConvTranspose3d as it is backed by highly optimized cuDNN kernels.
        # Custom implementation of Conv3d is rarely faster than cuDNN.
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                 stride=stride, padding=padding, 
                                                 output_padding=output_padding, bias=bias)
        self.fused_ops = fused_ops

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, D, H, W).
        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, D, H, W).
        """
