        if not x.is_contiguous():
            x = x.contiguous()

        # 2. Fused: HardSwish -> GroupNorm -> Mean
        # This avoids writing the massive intermediate tensors to global memory
        return fused_ops.fused_forward_cuda(x, self.gamma, self.beta, self.num_groups)

