import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused scaling and global average pooling
# This kernel fuses the scalar multiplication and the two global average pooling operations
# (since the second pooling is redundant) into a single kernel to reduce memory bandwidth usage.
fused_scale_mean_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_scale_mean_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int inner_size,
    float multiplier) {

    // Each block processes one channel of one sample (one HxW map)
    // blockIdx.x corresponds to the flattened index (n * C + c)
    int idx = blockIdx.x;

    // Offset to the start of the HxW plane for this channel
    int offset = idx * inner_size;

    float sum = 0.0f;
    // Grid-stride loop (iterating over the H*W plane)
    // Even though we launch enough blocks for N*C, we loop inside to handle the spatial dimensions
    for (int i = threadIdx.x; i < inner_size; i += blockDim.x) {
        sum += input[offset + i];
    }

    // Shared memory for reduction within the block
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    sdata[tid] = sum;
    __syncthreads();

    // Block reduction (summing up partial sums from threads)
    // Assumes block_size is a power of 2 (we use 256)
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write the result
    if (tid == 0) {
        // Compute mean: sum / inner_size
        // Apply multiplier: mean * multiplier
        output[idx] = (sdata[0] / static_cast<float>(inner_size)) * multiplier;
    }
