import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for the optimized operations
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

// Kernel 1: Broadcast Multiplication
// Performs: out = x * m
// where x is (N, C, D, H, W) and m is (C).
// Supports broadcasting m across N, D, H, W dimensions.
__global__ void broadcast_mul_kernel(const float* __restrict__ x, 
                                     const float* __restrict__ m, 
                                     float* __restrict__ out, 
                                     int numel, 
                                     int C, int S) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        // x layout: N, C, S (where S = D*H*W)
        // flat index idx = n * (C*S) + c * S + s
        // We calculate c to index into m
        int c = (idx / S) % C;
        out[idx] = x[idx] * m[c];
    }
}

// Kernel 2: Fused Clamp + Mul + Max Reduction
// Performs: out = max(clamp(x, min, max) * m, dim=1)
// Input x: (N, C, D, H, W)
// Input m: (C)
// Output out: (N, D, H, W)
__global__ void fused_tail_kernel(const float* __restrict__ x,
                                  const float* __restrict__ m,
                                  float* __restrict__ out,
                                  int N, int C, int S,
                                  float clamp_min, float clamp_max) {
    // Each thread computes one output element at position (n, s)
    // where s corresponds to spatial index (d, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output = N * S;

    if (idx < total_output) {
        int n = idx / S;
        int s = idx % S;

        // Calculate the base pointer offset for input x at (n, c=0, s)
        // Memory layout is N, C, S.
        // Offset = n * (C * S) + 0 * S + s
        int base_offset = n * C * S + s;

        float max_val = -FLT_MAX;

        // Iterate over channel dimension C
        for (int c = 0; c < C; ++c) {
            // Access x[n, c, s]. Since we vary c, we jump by stride S.
            float val = x[base_offset + c * S];

            // Fused Clamp
            if (val < clamp_min) val = clamp_min;
            else if (val > clamp_max) val = clamp_max;

            // Fused Multiply
            val *= m[c];

            // Fused Max Reduction
            if (val > max_val) max_val = val;
        }

        out[idx] = max_val;
    }
}

// C++ Wrapper for Broadcast Mul
torch::Tensor broadcast_mul_cuda(torch::Tensor x, torch::Tensor m) {
    int numel = x.numel();
    int C = x.size(1);
    // Spatial size S = D * H * W
    int S = x.size(2) * x.size(3) * x.size(4);

    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    broadcast_mul_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        m.data_ptr<float>(),
        out.data_ptr<float>(),
        numel, C, S
    );
    return out;
}

// C++ Wrapper for Fused Tail Operations
torch::Tensor fused_tail_cuda(torch::Tensor x, torch::Tensor m, float clamp_min, float clamp_max) {
    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    int S = D * H * W;

    // Output shape is (N, D, H, W) -> (N, S) logic
    auto options = torch::TensorOptions().dtype(x.dtype()).device(x.device());
    auto out = torch::empty({N, D, H, W}, options);

    int total_output = N * S;
    const int block_size = 256;
    const int num_blocks = (total_output + block_size - 1) / block_size;

    fused_tail_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        m.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, S,
        clamp_min, clamp_max
    );
    return out;
}
"""

cpp_source = """
torch::Tensor broadcast_mul_cuda(torch::Tensor x, torch::Tensor m);
torch::Tensor fused_tail_cuda(torch::Tensor x, torch::Tensor m, float clamp_min, float clamp_max);
"""

# Compile and load the custom kernels
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["broadcast_mul_cuda", "fused_tail_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized version of Model using custom CUDA kernels.
    Replaces element-wise operations and reductions with fused kernels.
    """
    def __init__(self, in_channels, out_channels, kernel_size, multiplier_shape, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        self.instance_norm = nn.InstanceNorm3d(out_channels)
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.ops = custom_ops

    def forward(self, x):
        # Convolution is computationally heavy and highly optimized in cuDNN, so we keep it.
        x = self.conv(x)

        # Helper to treat multiplier as flat vector for CUDA kernels
        m_flat = self.multiplier.view(-1)

        # 1. Custom Broadcast Multiplication
        # Replaces: x = x * self.multiplier
        x = self.ops.broadcast_mul_cuda(x, m_flat)

        # Instance Norm is complex to fuse naively without two-pass or shared mem, keep PyTorch impl
        x = self.instance_norm(x)

        # 2. Fused Kernel for Tail Operations
        # Replaces:
        # x = torch.clamp(x, self.clamp_min, self.clamp_max)
        # x = x * self.multiplier
        # x = torch.max(x, dim=1)[0]
        # This kernel fuses memory-bound operations to reduce global memory traffic.
        x = self.ops.fused_tail_cuda(x, m_flat, self.clamp_min, self.clamp_max)

        return x

