import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused LeakyReLU -> Mul -> LeakyReLU -> MaxPool3d
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_kernel(
    const float* __restrict__ input,
    const float* __restrict__ multiplier,
    float* __restrict__ output,
    int N, int C, int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out) {

    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * D_out * H_out * W_out;

    if (idx < total_elements) {
        // Compute output indices (n, c, d_out, h_out, w_out)
        // Order: N, C, D, H, W
        int temp = idx;
        int w_out = temp % W_out; temp /= W_out;
        int h_out = temp % H_out; temp /= H_out;
        int d_out = temp % D_out; temp /= D_out;
        int c = temp % C;
        int n = temp;

        // Map to input start indices (stride = 2, padding = 0 implicitly handled by start index)
        int d_in = d_out * 2;
        int h_in = h_out * 2;
        int w_in = w_out * 2;

        // Fetch channel multiplier (broadcast over N, D, H, W)
        float mult = multiplier[c];

        // Initialize max value
        float max_val = -FLT_MAX;

        // Input strides for address calculation
        int stride_w = 1;
        int stride_h = W_in;
        int stride_d = H_in * W_in;
        int stride_c = D_in * H_in * W_in;
        int stride_n = C * D_in * H_in * W_in;

        // Base input offset for this window
        int base_offset = n * stride_n + c * stride_c + d_in * stride_d + h_in * stride_h + w_in;

        // Iterate over 2x2x2 pooling window
        #pragma unroll
        for (int z = 0; z < 2; ++z) {
            #pragma unroll
            for (int y = 0; y < 2; ++y) {
                #pragma unroll
                for (int x = 0; x < 2; ++x) {
                    // Check input boundaries
                    if (d_in + z < D_in && h_in + y < H_in && w_in + x < W_in) {
                        int offset = base_offset + z * stride_d + y * stride_h + x;
                        float val = input[offset];

                        // First LeakyReLU (negative_slope = 0.2)
                        val = (val >= 0.0f) ? val : val * 0.2f;

                        // Multiply by learnable parameter
                        val = val * mult;

                        // Second LeakyReLU (negative_slope = 0.2)
                        val = (val >= 0.0f) ? val : val * 0.2f;

                        // Max Pooling reduction
                        if (val > max_val) {
                            max_val = val;
                        }
                    }
                }
            }
        }

        output[idx] = max_val;
    }
}

torch::Tensor launch_fused_kernel(torch::Tensor input, torch::Tensor multiplier) {
    // Ensure inputs are contiguous
    input = input.contiguous();
    multiplier = multiplier.contiguous();

    int N = input.size(0);
    int C = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // MaxPool3d (k=2, s=2) output size = floor(input / 2)
    int D_out = D_in / 2;
    int H_out = H_in / 2;
    int W_out = W_in / 2;

    // Allocate output tensor
    auto output = torch::empty({N, C, D_out, H_out, W_out}, input.options());

    int total_elements = N * C * D_out * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    if (total_elements > 0) {
        fused_kernel<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            multiplier.data_ptr<float>(),
            output.data_ptr<float>(),
            N, C, D_in, H_in, W_in,
            D_out, H_out, W_out
        );
    }

    return output;
}
"""

cpp_source = "torch::Tensor launch_fused_kernel(torch::Tensor input, torch::Tensor multiplier);"

