    name="fused_module",
    cpp_sources=cpp_source,
    cuda_sources=fused_source,
    functions=["launch_fused_kernel"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, multiplier_shape):
        super(ModelNew, self).__init__()
        # Use standard ConvTranspose3d for the convolution part
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)
        # Learnable parameter
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        # Custom fused operator module
        self.fused_ops = fused_module

    def forward(self, x):
        # Perform 3D Transposed Convolution (Memory intensive, expanding)
        x = self.conv_transpose(x)

        # Apply fused kernel: LeakyReLU -> Mul -> LeakyReLU -> MaxPool3d
        # This reduces global memory traffic by performing all element-wise and reduction ops in one kernel launch.
        x = self.fused_ops.launch_fused_kernel(x, self.multiplier)

