import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Instance Normalization and Division
fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void fused_instance_norm_div_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    int batch_size,
    int channels,
    int spatial_size,
    float epsilon,
    float divide_by) {

    // Each block handles one (batch, channel) plane
    int n = blockIdx.x;
    int c = blockIdx.y;

    if (n >= batch_size || c >= channels) return;

    // Offset to the start of the specific feature map
    int offset = n * channels * spatial_size + c * spatial_size;

    extern __shared__ float sdata[];
    int tid = threadIdx.x;

    // 1. Calculate Mean
    float sum = 0.0f;
    // Stride loop to cover all pixels if spatial_size > blockDim.x
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        sum += static_cast<float>(input[offset + i]);
    }

    sdata[tid] = sum;
    __syncthreads();

    // Parallel reduction in shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float mean = sdata[0] / spatial_size;
    __syncthreads(); // Ensure mean is computed before variance calculation

    // 2. Calculate Variance
    float var_sum = 0.0f;
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        float val = static_cast<float>(input[offset + i]) - mean;
        var_sum += val * val;
    }

    sdata[tid] = var_sum;
    __syncthreads();

    // Parallel reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float variance = sdata[0] / spatial_size;

    // 3. Compute fused scale factor
    // Logic: x_new = ((x - mean) / sqrt(var + eps)) / divide_by
    //        x_new = (x - mean) * (1.0 / (sqrt(var + eps) * divide_by))
    float inv_std = rsqrtf(variance + epsilon);
    float scale = inv_std / divide_by;

    // 4. Apply Normalization and Division
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        float val = static_cast<float>(input[offset + i]);
        output[offset + i] = static_cast<scalar_t>((val - mean) * scale);
    }
}

torch::Tensor fused_instance_norm_div_cuda(torch::Tensor input, float divide_by, float epsilon) {
    // Input is expected to be (N, C, H, W)
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    auto spatial_size = height * width;

    auto output = torch::empty_like(input);

    // Launch configuration
    // Grid dimensions: One block per feature map (N * C)
    dim3 grid(batch_size, channels);
    dim3 block(256);

    // Allocate shared memory for reduction (float per thread)
    size_t shared_mem_size = block.x * sizeof(float);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "fused_instance_norm_div_cuda", ([&] {
        fused_instance_norm_div_kernel<scalar_t><<<grid, block, shared_mem_size>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch_size,
            channels,
            spatial_size,
            epsilon,
            divide_by
        );
    }));

    return output;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_instance_norm_div_cuda(torch::Tensor input, float divide_by, float epsilon);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_instance_norm_div_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model with fused Instance Normalization and Division using a custom CUDA kernel.
    The Convolution layer is kept as nn.Conv2d to leverage highly optimized cuDNN implementations.
    """
    def __init__(self, in_channels, out_channels, kernel_size, divide_by):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.divide_by = float(divide_by)
        self.fused_ops = fused_ops
        # Default eps for InstanceNorm2d is 1e-5
        self.eps = 1e-5 

