import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations:
# LogSumExp -> LeakyReLU -> LeakyReLU -> GELU -> GELU
# This kernel fuses the reduction (LogSumExp) and the subsequent element-wise activations
# to minimize memory bandwidth and kernel launch overhead.

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

#ifndef M_SQRT1_2
#define M_SQRT1_2 0.70710678118654752440f
#endif

// Warp reduction for finding maximum
__device__ __forceinline__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

// Block reduction for finding maximum
__device__ __forceinline__ float blockReduceMax(float val) {
    static __shared__ float shared[32]; // Shared memory for 32 warps
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceMax(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    // Read from shared memory only if within the first warp
    // Threads outside the active warp count in the block init to -INFINITY
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : -INFINITY;

    if (wid == 0) val = warpReduceMax(val);

    return val;
}

// Warp reduction for summation
__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Block reduction for summation
__device__ __forceinline__ float blockReduceSum(float val) {
    static __shared__ float shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0.0f;

    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void fused_post_linear_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    // Each block processes one row (Batch dimension)
    int bid = blockIdx.x;
    if (bid >= rows) return;

    const float* row_ptr = input + bid * cols;

    // 1. Find the Maximum value in the row for numerical stability of LogSumExp (Pass 1)
    float local_max = -INFINITY;
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        local_max = fmaxf(local_max, row_ptr[i]);
    }
    float row_max = blockReduceMax(local_max);

    // Broadcast the max value to all threads in the block
    __shared__ float s_max;
    if (threadIdx.x == 0) s_max = row_max;
    __syncthreads();
    row_max = s_max;

    // 2. Compute Sum of Exponentials: sum(exp(x - max)) (Pass 2)
    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        local_sum += expf(row_ptr[i] - row_max);
    }
    float row_sum = blockReduceSum(local_sum);

    // 3. Compute LogSumExp and apply activations (only thread 0 needs to write output)
    if (threadIdx.x == 0) {
        // LogSumExp
        // LSE = max + log(sum(exp(x-max)))
        float val = row_max + logf(row_sum);

        // LeakyReLU 1 (negative_slope=0.01)
        if (val < 0.0f) val *= 0.01f;

        // LeakyReLU 2 (negative_slope=0.01)
        if (val < 0.0f) val *= 0.01f;

        // GELU 1
        // approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
        float cdf1 = 0.5f * (1.0f + erff(val * M_SQRT1_2));
        val = val * cdf1;

        // GELU 2
        float cdf2 = 0.5f * (1.0f + erff(val * M_SQRT1_2));
        val = val * cdf2;

        output[bid] = val; // Output shape is (N, 1), so stride is trivial
    }
}

torch::Tensor fused_post_linear_cuda(torch::Tensor input) {
    // Input is output of Linear layer: [Batch, OutFeatures]
    auto rows = input.size(0);
    auto cols = input.size(1);

    auto output = torch::empty({rows, 1}, input.options());

    const int block_size = 256;
    dim3 dimBlock(block_size);
    dim3 dimGrid(rows);

    fused_post_linear_kernel<<<dimGrid, dimBlock>>>(input.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_post_linear_cuda(torch::Tensor input);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
