import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused HardSwish + ReLU
# Mathematical derivation for fusion:
# y = ReLU(HardSwish(x))
# HardSwish(x) = x * (min(max(x + 3, 0), 6) / 6)
#
# Case 1: x >= 3
#   x + 3 >= 6, so min(..., 6) is 6. HardSwish(x) = x * 1 = x.
#   Since x >= 3 > 0, ReLU(x) = x.
#   Result: x
#
# Case 2: 0 <= x < 3
#   3 <= x + 3 < 6. HardSwish(x) = x * (x + 3) / 6.
#   Since x >= 0 and (x+3) > 0, the result is positive. ReLU keeps it.
#   Result: x * (x + 3) / 6
#
# Case 3: -3 <= x < 0
#   0 <= x + 3 < 3. HardSwish(x) = x * (x + 3) / 6.
#   Since x < 0 and (x+3) >= 0, the result is negative or zero. ReLU clamps to 0.
#   Result: 0
#
# Case 4: x < -3
#   x + 3 < 0. max(..., 0) is 0. HardSwish(x) = 0. ReLU(0) = 0.
#   Result: 0
#
# Combined logic:
# if x < 0: return 0
# if x >= 3: return x
# else: return x * (x + 3) / 6

fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_hardswish_relu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        if (val < 0.0f) {
            out[idx] = 0.0f;
        } else if (val >= 3.0f) {
            out[idx] = val;
        } else {
            // 0 <= val < 3
            out[idx] = val * (val + 3.0f) * 0.16666667f; // Multiply by 1/6
        }
    }
}

