from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels:
# 1. Element-wise scaling
# 2. 3D Global Average Pooling
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Kernel for element-wise scaling: out = in * scale
__global__ void scale_kernel(const float* __restrict__ input, float* __restrict__ output, float scale, int numel) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        output[idx] = input[idx] * scale;
    }
}

torch::Tensor scale_cuda(torch::Tensor input, float scale) {
    auto output = torch::empty_like(input);
    int numel = input.numel();
    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    scale_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), scale, numel);
    return output;
}

// Kernel for Global Average Pooling 3D
// Reduces spatial dimensions (D, H, W) to (1, 1, 1) per (N, C)
__global__ void global_avg_pool_3d_kernel(const float* __restrict__ input, float* __restrict__ output, int spatial_size) {
    // Grid dimensions: x = Batch (N), y = Channel (C)
    // Block dimensions: x = 256 threads

    int n = blockIdx.x;
    int c = blockIdx.y;
    int tid = threadIdx.x;

    // Total channels (stride for batch)
    int C = gridDim.y;

    // Calculate offset for the specific (n, c) volume
    // Input layout is contiguous [N, C, D, H, W]
    // The start index for a given n, c is: n * (C * spatial_size) + c * spatial_size
    long long offset = static_cast<long long>(n) * C * spatial_size + static_cast<long long>(c) * spatial_size;

    const float* input_slice = input + offset;

    float sum = 0.0f;

    // Grid-stride loop to sum up all elements in the spatial volume
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        sum += input_slice[i];
    }

    // Shared memory for block reduction
    extern __shared__ float sdata[];
    sdata[tid] = sum;
    __syncthreads();

    // Parallel reduction in shared memory
    // Block size is 256 (power of 2), so we can unroll or use standard loop
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write the average to the output
    if (tid == 0) {
        // Output layout is [N, C, 1, 1, 1], which flattens to n*C + c
        int out_idx = n * C + c;
        output[out_idx] = sdata[0] / static_cast<float>(spatial_size);
    }
}

torch::Tensor global_avg_pool_3d_cuda(torch::Tensor input) {
    // Ensure input is contiguous for pointer arithmetic
    input = input.contiguous();

    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);
    int spatial_size = D * H * W;

    // Output shape: [N, C, 1, 1, 1]
    auto output = torch::empty({N, C, 1, 1, 1}, input.options());

    // One block per (N, C) pair
    dim3 grid(N, C);
    dim3 block(256);
    // Allocate shared memory for the block (256 floats)
    size_t shared_mem_size = block.x * sizeof(float);

    global_avg_pool_3d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        spatial_size
    );

    return output;
}
"""

