import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel to reduce the weights along dimension 0 (hidden_size)
// and apply the scaling factor and division by 2.
// This fuses the summation of weights and the scalar operations.
// Grid: (I + 255) / 256, Block: 256
__global__ void reduce_weight_kernel(const float* __restrict__ weight, 
                                     float* __restrict__ out, 
                                     int H, int I, float scaling_factor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < I) {
        float sum = 0.0f;
        // Coalesced read: threads in a warp read adjacent columns.
        // We iterate over rows.
        for (int h = 0; h < H; ++h) {
            sum += weight[h * I + idx];
        }
        // Apply scaling factor and divide by 2 here
        out[idx] = sum * 0.5f * scaling_factor;
    }
}

// Kernel to perform matrix-vector multiplication (Batch dot product)
// Computes dot product of each row of x with the reduced weight vector.
// Grid: B, Block: 256
__global__ void batch_dot_kernel(const float* __restrict__ x, 
                                 const float* __restrict__ vec, 
                                 float* __restrict__ out, 
                                 int I) {
    int b = blockIdx.x; // Each block handles one batch element

    float sum = 0.0f;

    // Grid-stride loop (though usually I fits in memory, this is safe)
    for (int i = threadIdx.x; i < I; i += blockDim.x) {
        sum += x[b * I + i] * vec[i];
    }

    // Warp-level reduction using shuffle
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // Block-level reduction using shared memory
    static __shared__ float shared_sums[32]; // Space for 32 warps
    int lane = threadIdx.x % 32;
    int warp = threadIdx.x / 32;

    if (lane == 0) {
        shared_sums[warp] = sum;
    }

    __syncthreads();

    // Final reduction by the first warp
    if (warp == 0) {
        // Load partial sums from shared memory
        // Only lanes corresponding to active warps need to load
        sum = (lane < (blockDim.x / 32)) ? shared_sums[lane] : 0.0f;

        for (int offset = 16; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }

        // Write result
        if (lane == 0) {
            out[b] = sum;
        }
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor weight, float scaling_factor) {
    int B = x.size(0);
    int I = x.size(1);
    int H = weight.size(0);

    // Allocate output tensors
    auto options = x.options();
    auto w_red = torch::empty({I}, options);
    auto out = torch::empty({B, 1}, options);

    // 1. Reduce Weights
    int threads_w = 256;
    int blocks_w = (I + threads_w - 1) / threads_w;

    reduce_weight_kernel<<<blocks_w, threads_w>>>(
        weight.data_ptr<float>(), 
        w_red.data_ptr<float>(), 
        H, I, scaling_factor
    );

    // 2. Batch Dot Product (GEMV)
    // One block per batch item
    int threads_b = 256;
    int blocks_b = B;

    batch_dot_kernel<<<blocks_b, threads_b>>>(
        x.data_ptr<float>(), 
        w_red.data_ptr<float>(), 
        out.data_ptr<float>(), 
        I
    );

    return out;
}
"""

