import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernel for Fused GELU + GroupNorm
# This kernel fuses the element-wise GELU activation and the GroupNorm operation.
# It reads the input once, applies GELU on the fly, computes statistics (mean/var)
# in a single pass over the spatial/group dimensions, and then normalizes and writes the output.
# This reduces memory bandwidth usage significantly compared to separate kernels.

fused_gelu_gn_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_gelu_gn_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int N, int C, int group_size, int hw_size, float eps) {

    // Grid Layout:
    // blockIdx.x corresponds to Batch index (n)
    // blockIdx.y corresponds to Group index (g)

    int n = blockIdx.x;
    int g = blockIdx.y;
    int tid = threadIdx.x;
    int bsz = blockDim.x;

    // Calculate dimensions
    // group_size: channels per group (C / num_groups)
    // hw_size: H * W
    // count: total elements per group instance = group_size * hw_size
    int count = group_size * hw_size;

    // Accumulators for mean and variance
    float sum = 0.0f;
    float sum_sq = 0.0f;

    // FIRST PASS: Calculate Sum and Sum of Squares of GELU(x)
    // We iterate over all pixels and channels belonging to this group
    for (int i = tid; i < count; i += bsz) {
        // Map linear index i to (channel_in_group, pixel_idx)
        int c_local = i / hw_size; 
        int px = i % hw_size;

        // Absolute channel index
        int c = g * group_size + c_local;

        // Global input index
        // x layout is [N, C, H, W], so stride for n is C*hw_size
        int idx = n * (C * hw_size) + c * hw_size + px;

        float val = x[idx];

        // Apply GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        float gelu_val = val * 0.5f * (1.0f + erff(val * 0.70710678f));

        sum += gelu_val;
        sum_sq += gelu_val * gelu_val;
    }

    // Shared Memory Reduction within block
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sq = sdata + bsz;

    s_sum[tid] = sum;
    s_sq[tid] = sum_sq;
    __syncthreads();

    // Parallel tree reduction
    for (int s = bsz / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sq[tid] += s_sq[tid + s];
        }
        __syncthreads();
    }

    // Compute stats
    float mean = s_sum[0] / count;
    float var = s_sq[0] / count - mean * mean;
    float inv_std = rsqrtf(max(var, 0.0f) + eps);

    // SECOND PASS: Normalize, Apply Affine (Gamma/Beta), and Write Output
    for (int i = tid; i < count; i += bsz) {
        int c_local = i / hw_size;
        int px = i % hw_size;
        int c = g * group_size + c_local;

        int idx = n * (C * hw_size) + c * hw_size + px;

        // We re-read and re-compute GELU. 
        // This is compute-bound but saves storing the intermediate GELU tensor to memory.
        float val = x[idx];
        float gelu_val = val * 0.5f * (1.0f + erff(val * 0.70710678f));

        float norm = (gelu_val - mean) * inv_std;

        // Gamma and Beta are per-channel
        out[idx] = norm * gamma[c] + beta[c];
    }
}

torch::Tensor fused_gelu_gn_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps) {
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    int group_size = C / num_groups;
    int hw_size = H * W;

    auto out = torch::empty_like(x);

    // Grid dimensions: one block per (Batch, Group) pair
    dim3 grid(N, num_groups);
    dim3 block(256);

    // Shared memory size: 2 arrays of size blockDim.x (for sum and sum_sq)
    int shared_mem = 2 * 256 * sizeof(float);

    fused_gelu_gn_kernel<<<grid, block, shared_mem>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, group_size, hw_size, eps
    );

    return out;
}
