import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Min Reduction and Softmax
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_min_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W) {

    // Grid Layout:
    // blockIdx.x = h (Height)
    // blockIdx.y = n (Batch)
    // blockIdx.z = w_chunk (Width tiled)

    int h = blockIdx.x;
    int n = blockIdx.y;
    int w_start = blockIdx.z * blockDim.x;
    int w = w_start + threadIdx.x;

    // Bounds check for Width
    if (w >= W) return;

    // Strides for Input Tensor (Layout: N, C, D, H, W)
    // We compute offsets manually to ensure clarity
    int stride_h = W;
    int stride_d = H * W;
    int stride_c = D * H * W;
    int stride_n = C * D * H * W;

    // Strides for Output Tensor (Layout: N, C, H, W)
    int out_stride_c = H * W;
    int out_stride_n = C * H * W;

    // Base pointers for the specific pixel (n, h, w)
    const float* in_base = input + n * stride_n + h * stride_h + w;
    float* out_base = output + n * out_stride_n + h * stride_h + w;

    // Shared Memory Allocation:
    // We need to store 'C' values for the current pixel (thread) to perform Softmax.
    // To avoid bank conflicts when accessing by threads (which correspond to 'w'),
    // we pad the stride. Layout: [C][BlockDim + 1].
    // Access: smem[c * smem_stride + threadIdx.x]
    extern __shared__ float smem[];
    int smem_stride = blockDim.x + 1;

    // -----------------------------------------------------------
    // Step 1: Minimum Reduction along Dimension 2 (Depth D)
    // -----------------------------------------------------------
    // Each thread calculates the min over D for all channels C corresponding to its pixel w.

    for (int c = 0; c < C; ++c) {
        float min_val = 1e38f; // Initialize with a large number
        const float* d_ptr = in_base + c * stride_c;

        for (int d = 0; d < D; ++d) {
            // Read input in a coalesced manner (w is contiguous in memory)
            // d_ptr[d * stride_d] corresponds to input[n, c, d, h, w]
            float val = d_ptr[d * stride_d];
            if (val < min_val) min_val = val;
        }
        // Store result in shared memory
        smem[c * smem_stride + threadIdx.x] = min_val;
    }

    // No __syncthreads() needed here because each thread operates completely 
    // independently on its own column 'w' in shared memory.

    // -----------------------------------------------------------
    // Step 2: Softmax along Dimension 1 (Channel C)
    // -----------------------------------------------------------

    // A. Find Max (for numerical stability)
    float max_val = -1e38f;
    for (int c = 0; c < C; ++c) {
        float val = smem[c * smem_stride + threadIdx.x];
        if (val > max_val) max_val = val;
    }

    // B. Compute Exponentials and Sum
    float sum_exp = 0.0f;
    for (int c = 0; c < C; ++c) {
        float val = smem[c * smem_stride + threadIdx.x];
        val = expf(val - max_val);
        smem[c * smem_stride + threadIdx.x] = val; // Store exp value back
        sum_exp += val;
    }

    // C. Normalize and Write Output
    float inv_sum = 1.0f / (sum_exp + 1e-8f); // Epsilon to prevent div by zero
    for (int c = 0; c < C; ++c) {
        float val = smem[c * smem_stride + threadIdx.x];
        // Coalesced write: out_base points to output[n, 0, h, w]
        // out_base[c * out_stride_c] -> output[n, c, h, w]
        out_base[c * out_stride_c] = val * inv_sum;
    }
}

torch::Tensor fused_min_softmax_cuda(torch::Tensor input) {
    // Input Shape: (N, C, D, H, W)
    auto N = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    // Output Shape: (N, C, H, W) (Reduced D, Softmaxed C)
    auto output = torch::empty({N, C, H, W}, input.options());

    // Kernel Configuration
    // We map threads to Width (W) to ensure coalesced memory access.
    int threads = 32; // BlockDim.x
    int blocks_z = (W + threads - 1) / threads;

    dim3 grid(H, N, blocks_z);

    // Shared Memory Size: C * (BlockDim + 1) * sizeof(float)
    // +1 padding to reduce bank conflicts
    int smem_size = C * (threads + 1) * sizeof(float);

    fused_min_softmax_kernel<<<grid, threads, smem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W
    );

    return output;
}
"""

fused_cpp_source = "torch::Tensor fused_min_softmax_cuda(torch::Tensor input);"

# Compile and load the inline CUDA function
fused_op = load_inline(
    name="fused_min_softmax",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_min_softmax_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces the standard torch.min and torch.softmax sequence
    with a custom fused CUDA kernel for better memory efficiency and performance.
    """
    def __init__(self, in_channels, out_channels, kernel_size, dim):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.dim = dim
        self.fused_op = fused_op

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, D, H, W)
        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, H, W)
        """
        x = self.conv(x)

        # The original model performed:
        # x = torch.min(x, dim=self.dim)[0]  (where self.dim is typically 2 -> D)
        # x = torch.softmax(x, dim=1)        (along channels)
        # We replace this with a fused kernel.

        return self.fused_op.fused_min_softmax_cuda(x)

