import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused activations
# This kernel fuses: Swish -> Div(2) -> Clamp(-1,1) -> Tanh -> Clamp(-1,1)
# It uses float4 vectorization for improved memory bandwidth efficiency.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ __forceinline__ float activation_op(float x) {
    // Swish: x = x * sigmoid(x)
    float val = x * sigmoid_f(x);

    // Divide by 2.0
    val = val * 0.5f;

    // Clamp between -1.0 and 1.0
    val = fminf(fmaxf(val, -1.0f), 1.0f);

    // Tanh activation
    val = tanhf(val);

    // Clamp between -1.0 and 1.0
    val = fminf(fmaxf(val, -1.0f), 1.0f);

    return val;
}

__global__ void fused_activation_kernel_vec4(const float* __restrict__ input, float* __restrict__ output, int size) {
    // Calculate global index for float4 vector
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int vec_size = size / 4;

    if (idx < vec_size) {
        // Reinterpret pointers as float4
        const float4* in_ptr = reinterpret_cast<const float4*>(input);
        float4* out_ptr = reinterpret_cast<float4*>(output);

        float4 v = in_ptr[idx];
        float4 r;

        // Process each component
        r.x = activation_op(v.x);
        r.y = activation_op(v.y);
        r.z = activation_op(v.z);
        r.w = activation_op(v.w);

        out_ptr[idx] = r;
    }
}

__global__ void fused_activation_kernel_scalar(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = activation_op(input[idx]);
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    // Check pointer alignment for float4 (16 bytes)
    bool is_aligned = (reinterpret_cast<uintptr_t>(input.data_ptr<float>()) % 16 == 0) &&
                      (reinterpret_cast<uintptr_t>(output.data_ptr<float>()) % 16 == 0);

    const int block_size = 256;

    // Use vectorized kernel if size is divisible by 4 and pointers are aligned
    if (is_aligned && (size % 4 == 0)) {
        int vec_size = size / 4;
        int num_blocks = (vec_size + block_size - 1) / block_size;
        fused_activation_kernel_vec4<<<num_blocks, block_size>>>(
            input.data_ptr<float>(), 
            output.data_ptr<float>(), 
            size
        );
    } else {
        // Fallback to scalar kernel
        int num_blocks = (size + block_size - 1) / block_size;
        fused_activation_kernel_scalar<<<num_blocks, block_size>>>(
            input.data_ptr<float>(), 
            output.data_ptr<float>(), 
            size
        );
    }

    return output;
