#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Device function to calculate Mish: x * tanh(softplus(x))
__device__ __forceinline__ float mish_func(float x) {
    // Softplus approximation for numerical stability: x > 20 -> x, else ln(1 + e^x)
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void fused_bias_double_mish_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int features,
    int numel) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < numel) {
        float val = input[idx];

        // Fused Bias Add
        // Input is [Batch, Features] (row-major).
        // Bias is [Features].
        // We broadcast the bias across the batch dimension.
        if (bias != nullptr) {
            val += bias[idx % features];
        }

        // Fused Double Mish
        val = mish_func(val); // First Mish
        val = mish_func(val); // Second Mish

        output[idx] = val;
    }
}

