    int numel = input_contig.numel();
    auto output = torch::empty_like(input_contig);

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    // Handle bias pointer: check if defined and has elements
    const float* bias_ptr = (bias.defined() && bias.numel() > 0) ? bias.data_ptr<float>() : nullptr;

    fused_bias_double_mish_kernel<<<num_blocks, block_size>>>(
        input_contig.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        features,
        numel
    );

    return output;
}
