import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused affine transformation
# This kernel performs the operation: out = x * w + b
# It is used to apply the fused Scaling + Batch Normalization operation efficiently.
# Optimizations:
# 1. Fuses element-wise scaling, normalization, and affine transform into one kernel.
# 2. Uses float4 vectorization for improved memory bandwidth utilization.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_affine_kernel(
    const float* __restrict__ inp,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    int size,
    int features) {

    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Cast pointers to float4 for vectorized access
    // We assume features (4096) is divisible by 4 and pointers are aligned
    const float4* inp_vec = reinterpret_cast<const float4*>(inp);
    float4* out_vec = reinterpret_cast<float4*>(out);
    const float4* w_vec = reinterpret_cast<const float4*>(w);
    const float4* b_vec = reinterpret_cast<const float4*>(b);

    int num_vec = size / 4;
    int features_vec = features / 4;

    // Grid-stride loop
    for (int i = idx; i < num_vec; i += stride) {
        float4 v = inp_vec[i];

        // Determine the channel index for the current vector
        int col = i % features_vec;

        // Load fused weights and biases for these channels
        float4 weight = w_vec[col];
        float4 bias = b_vec[col];

        // Apply affine transform element-wise within the vector
        v.x = v.x * weight.x + bias.x;
        v.y = v.y * weight.y + bias.y;
        v.z = v.z * weight.z + bias.z;
        v.w = v.w * weight.w + bias.w;

        out_vec[i] = v;
    }
}

torch::Tensor fused_affine_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    int features = x.size(1);

    const int block_size = 256;
    // Process 4 elements per thread
    int num_vec = size / 4;
    int num_blocks = std::min(65535, (num_vec + block_size - 1) / block_size);

    fused_affine_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        features
    );

    return out;
}
"""

cpp_source = "torch::Tensor fused_affine_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_affine_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses the Scaling and BatchNorm operations into a single
    affine transformation kernel, reducing memory access overhead.
    """
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        # Keep Gemm as is (PyTorch uses optimized cuBLAS)
        self.gemm = nn.Linear(in_features, out_features)
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)

    def forward(self, x):
        # 1. Linear Layer (Compute Bound)
        x = self.gemm(x)

        # 2. Fused Scale + BatchNorm (Memory Bound)
        # Instead of doing x*scale -> memory -> BN(stats) -> memory -> BN(apply),
        # we calculate stats on x directly and fuse the application into one kernel pass.

        if self.training:
            # Calculate batch statistics on x (read x once)
            var, mean = torch.var_mean(x, dim=0, unbiased=False)

            # Adjust stats to account for the 'scale' parameter that happens before BN
            scale_factor = self.scale
            mean_scaled = mean * scale_factor
            var_scaled = var * (scale_factor ** 2)

            # Update running stats manually to replicate BN behavior
            n = x.size(0)
            m = self.bn.momentum
            if m is not None:
                # BN running stats use unbiased variance
                var_unbiased_scaled = var_scaled * (n / (n - 1.0))
                with torch.no_grad():
                    self.bn.running_mean.mul_(1 - m).add_(mean_scaled, alpha=m)
                    self.bn.running_var.mul_(1 - m).add_(var_unbiased_scaled, alpha=m)

            # Calculate fused affine coefficients for the kernel
            # Mathematical fusion of: y = x*s; z = (y - mean_y)/std_y * gamma + beta
            # Result: z = x * w_eff + b_eff
            inv_std = torch.rsqrt(var_scaled + self.bn.eps)
            w_eff = scale_factor * inv_std * self.bn.weight
            b_eff = self.bn.bias - mean_scaled * inv_std * self.bn.weight

            # Apply fused transform (read x once, write out once)
            return fused_ops.fused_affine_cuda(x, w_eff, b_eff)

        else:
            # Inference mode: Use running stats
            mean_running = self.bn.running_mean
            var_running = self.bn.running_var

            inv_std = torch.rsqrt(var_running + self.bn.eps)
            w_eff = self.scale * inv_std * self.bn.weight
            b_eff = self.bn.bias - mean_running * inv_std * self.bn.weight

            return fused_ops.fused_affine_cuda(x, w_eff, b_eff)

