import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations: Softmax -> Add -> Mul -> Sigmoid
# We fuse these operations to reduce global memory round-trips and kernel launch overhead.
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const float scale,
    const int N,
    const int C,
    const int HW) {

    // idx corresponds to a unique spatial location (pixel) across the entire batch
    // Grid size covers all N * H * W pixels.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_pixels = N * HW;

    if (idx < total_pixels) {
        // Determine the batch index (n) and spatial offset (rem = h * W + w)
        int n = idx / HW;
        int rem = idx % HW;

        // Calculate the base pointer offset for the channel column of this pixel
        // Tensor layout is NCHW.
        // The c-th channel for pixel (n, rem) is at:
        // index = n * (C * HW) + c * HW + rem
        // For a Warp of threads with consecutive 'rem', memory accesses are coalesced
        // because they access adjacent memory locations (stride 1).
        int base_offset = n * C * HW + rem;
        int stride = HW;

        // 1. Find Max for Softmax numerical stability
        float max_val = -1e37f;
        for (int c = 0; c < C; ++c) {
            float val = x[base_offset + c * stride];
            if (val > max_val) {
                max_val = val;
            }
        }

        // 2. Compute Sum of Exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            float val = x[base_offset + c * stride];
            sum_exp += expf(val - max_val);
        }

        // Optimization: Precompute inverse sum for division
        float inv_sum = 1.0f / sum_exp;

        // 3. Compute Softmax, Add Bias, Scale, Sigmoid
        for (int c = 0; c < C; ++c) {
            int offset = base_offset + c * stride;
            float val = x[offset];

            // Softmax
            float res = expf(val - max_val) * inv_sum;

            // Add Bias (bias is shaped (C, 1, 1), so essentially a vector of size C)
            res = res + bias[c];

            // Scale
            res = res * scale;

            // Sigmoid: 1 / (1 + exp(-x))
            out[offset] = 1.0f / (1.0f + expf(-res));
        }
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias, float scale) {
    TORCH_CHECK(x.is_cuda, "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda, "bias must be a CUDA tensor");

    // Ensure contiguous memory for correct pointer arithmetic in the kernel
    x = x.contiguous();
    bias = bias.contiguous();

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int HW = H * W;

    auto out = torch::empty_like(x);

    // Grid configuration: One thread per spatial pixel
    int total_pixels = N * HW;
    const int block_size = 256;
    const int num_blocks = (total_pixels + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        scale,
        N, C, HW
    );

    return out;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias, float scale);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    """
    Optimized Model that uses a custom CUDA kernel to fuse Softmax, Bias addition, Scaling, and Sigmoid.
    The ConvTranspose2d layer is retained from PyTorch (cuDNN) as it is highly optimized.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape)) 
        self.scaling_factor = scaling_factor
        self.fused_ops = fused_ops

    def forward(self, x):
        # Heavy computation (Convolution) is kept as is
        x = self.conv_transpose(x)

        # Fused kernel replaces:
        # x = torch.softmax(x, dim=1)
        # x = x + self.bias
        # x = x * self.scaling_factor
        # x = torch.sigmoid(x)
        return self.fused_ops.fused_ops_cuda(x, self.bias, self.scaling_factor)

