import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused ReLU + HardSwish logic
# Original Logic:
#   x = self.conv(x)
#   x = torch.relu(x)
#   x = x * torch.clamp((x + 3) / 6, 0, 1)
#
# Optimized Logic (Kernel):
#   We fuse the ReLU and the specific HardSwish chain into one element-wise operation.
#   Let v be the input value (output of conv).
#   1. Apply ReLU: val = max(v, 0)
#   2. Apply Logic: result = val * clamp((val + 3) / 6, 0, 1)
#
#   Simplification for val >= 0:
#     - If val > 3: (val + 3) / 6 > 1. Clamp result is 1. Result = val.
#     - If 0 <= val <= 3: 0.5 <= (val + 3) / 6 <= 1. Clamp result is (val + 3) / 6. Result = val * (val + 3) / 6.
#     - If v < 0: val = 0. Result = 0.
#
# This reduces memory bandwidth usage significantly compared to separate calls.

fused_activation_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_activation_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float in_val = input[idx];

        // ReLU
        float val = (in_val > 0.0f) ? in_val : 0.0f;

        // Fused HardSwish logic
        if (val > 3.0f) {
            output[idx] = val;
        } else {
            // Multiply by 1/6 (approx 0.16666667f)
            output[idx] = val * (val + 3.0f) * 0.16666667f;
        }
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_activation_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

fused_activation_cpp_source = (
    "torch::Tensor fused_activation_cuda(torch::Tensor input);"
)

# Compile the inline CUDA code
fused_activation_module = load_inline(
    name="fused_activation_module",
    cpp_sources=fused_activation_cpp_source,
    cuda_sources=fused_activation_source,
    functions=["fused_activation_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a convolution and applies a fused CUDA activation 
    (ReLU + custom HardSwish).
    """
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        # We retain nn.Conv2d as it uses highly optimized cuDNN kernels which are difficult 
        # to beat with simple custom CUDA without significant engineering (e.g., tiling, GEMM).
        # We focus optimization on fusing the activation sequence.
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.fused_ops = fused_activation_module

    def forward(self, x):
        x = self.conv(x)
        # Apply the fused custom kernel
        return self.fused_ops.fused_activation_cuda(x)

