import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused LayerNorm + GELU + Scaling
# This kernel performs channel-wise normalization, affine transformation, GELU activation, and scalar multiplication
# in a single pass over the data, minimizing memory bandwidth usage.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ln_gelu_scale_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int N,
    int C,
    int Spatial,
    float eps,
    float scaling_factor) {

    // Calculate global thread index
    // We map one thread to one spatial location (d, h, w) in a specific batch item (n)
    // The thread loops over the channel dimension (c)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of spatial locations across the batch
    if (idx < N * Spatial) {
        // Decompose linear index into batch index 'n' and spatial index 's'
        int n = idx / Spatial;
        int s = idx % Spatial;

        // Calculate the base offset in memory for this spatial location
        // The input tensor layout is (N, C, D, H, W), which we view as (N, C, Spatial)
        // Stride for N is (C * Spatial)
        // Stride for C is (Spatial)
        int offset_base = n * C * Spatial + s;

        // 1. Calculate Mean over C channels
        float sum = 0.0f;
        for (int c = 0; c < C; ++c) {
            // Strided access: jump by 'Spatial' to get the next channel for this pixel
            sum += x[offset_base + c * Spatial];
        }
        float mean = sum / C;

        // 2. Calculate Variance over C channels
        float sum_sq_diff = 0.0f;
        for (int c = 0; c < C; ++c) {
            float val = x[offset_base + c * Spatial];
            float diff = val - mean;
            sum_sq_diff += diff * diff;
        }
        float var = sum_sq_diff / C;
        float inv_std = rsqrtf(var + eps);

        // 3. Normalize, Apply Affine Transform, GELU, and Scale
        for (int c = 0; c < C; ++c) {
            int current_idx = offset_base + c * Spatial;
            float val = x[current_idx];

            // Layer Normalization
            float normalized = (val - mean) * inv_std;
            float affine = normalized * gamma[c] + beta[c];

            // GELU Activation (Exact Erf implementation)
            // Formula: 0.5 * x * (1 + erf(x / sqrt(2)))
            // 1/sqrt(2) is approximately 0.70710678
            float gelu = 0.5f * affine * (1.0f + erff(affine * 0.70710678f));

            // Scaling
            out[current_idx] = gelu * scaling_factor;
        }
    }
}

torch::Tensor fused_ln_gelu_scale_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps,
    float scaling_factor) {

    // Ensure input is contiguous for correct pointer arithmetic
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    auto N = x.size(0);
    auto C = x.size(1);

    // Calculate total spatial size (D * H * W)
    int64_t Spatial = 1;
    for (int i = 2; i < x.dim(); ++i) {
        Spatial *= x.size(i);
    }

    auto out = torch::empty_like(x);

    // Launch configuration:
    // Threads = N * Spatial (one thread per pixel per batch item)
    int64_t total_threads = N * Spatial;
    const int threads_per_block = 256;
    const int blocks = (total_threads + threads_per_block - 1) / threads_per_block;

    fused_ln_gelu_scale_kernel<<<blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, Spatial, eps, scaling_factor
    );

    return out;
}
"""

cpp_source = """
torch::Tensor fused_ln_gelu_scale_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps,
    float scaling_factor);
"""

# Compile and load the inline CUDA extension
fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['fused_ln_gelu_scale_cuda'],
    verbose=False,
    extra_cflags=['-O3']
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution followed by 
    a fused Custom CUDA kernel for Layer Normalization, GELU, and Scaling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias=True, eps=1e-5, scaling_factor=1.0):
        super(ModelNew, self).__init__()
        # Convolution is computationally intensive and cuDNN is highly optimized; keeping it as is.
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, bias=bias)

