import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Spatial Mean Subtraction
# This kernel computes the mean over the spatial dimensions (D, H, W) for each channel and sample,
# and subtracts it from the input.
spatial_mean_sub_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void spatial_mean_sub_kernel(const scalar_t* __restrict__ input, scalar_t* __restrict__ output, int size_spatial) {
    // Grid Setup:
    // blockIdx.x represents a single (batch, channel) slice.
    // We treat the spatial dimensions (D, H, W) as a flattened array of size 'size_spatial'.

    extern __shared__ float sdata[]; // Shared memory for reduction (accumulate in float for precision)

    int tid = threadIdx.x;
    int offset = blockIdx.x * size_spatial;

    // Pointers to the current slice
    const scalar_t* input_ptr = input + offset;
    scalar_t* output_ptr = output + offset;

    // 1. Calculate Sum
    float sum = 0.0f;
    for (int i = tid; i < size_spatial; i += blockDim.x) {
        sum += static_cast<float>(input_ptr[i]);
    }

    sdata[tid] = sum;
    __syncthreads();

    // 2. Block Reduction to find total sum
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float mean = sdata[0] / size_spatial;

    // 3. Subtract Mean
    for (int i = tid; i < size_spatial; i += blockDim.x) {
        output_ptr[i] = static_cast<scalar_t>(static_cast<float>(input_ptr[i]) - mean);
    }
}

torch::Tensor spatial_mean_sub_cuda(torch::Tensor input) {
    // Input shape: (N, C, D, H, W)
    // We want to reduce over (D, H, W)

    auto N = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    int size_spatial = D * H * W;
    int num_slices = N * C; // Total number of spatial volumes to process independently

    auto output = torch::empty_like(input);

    const int block_size = 256;
    int shared_mem_size = block_size * sizeof(float);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "spatial_mean_sub_cuda", ([&] {
        spatial_mean_sub_kernel<scalar_t><<<num_slices, block_size, shared_mem_size>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            size_spatial
        );
    }));

    return output;
}
"""

spatial_mean_sub_cpp_source = (
    "torch::Tensor spatial_mean_sub_cuda(torch::Tensor input);"
)

# Compile the inline CUDA code
