import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Helper for block reduction using warp shuffles
__device__ float block_reduce_sum(float val) {
    // Shared memory for 32 partial sums (one per warp)
    // Assuming block size 256 (8 warps)
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    // Warp reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    // Load from shared memory to warp 0
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0.0f;

    // Final warp reduction by warp 0
    if (wid == 0) {
        for (int offset = blockDim.x / 32 / 2; offset > 0; offset /= 2) {
             val += __shfl_down_sync(0xffffffff, val, offset);
        }
    }
    return val;
}

// Kernel 1: Reduce Weights and Bias
// W: (out_features, in_features) - Row major
// b: (out_features)
// w_red: (in_features) - Output reduced weights
// b_red: (1) - Output reduced bias
__global__ void reduce_params_kernel(
    const float* __restrict__ W,
    const float* __restrict__ b,
    float* __restrict__ w_red,
    float* __restrict__ b_red,
    int out_features,
    int in_features) {

    // Each thread handles one column 'k' of the weight matrix.
    // Threads read coalesced (W[0, k], W[0, k+1]...)
    int k = blockIdx.x * blockDim.x + threadIdx.x;

    if (k < in_features) {
        float sum = 0.0f;
        // Iterate over all rows (out_features)
        // Access pattern W[row * in_features + k]
        // This is coalesced because adjacent threads access adjacent memory locations for the same row.
        for (int row = 0; row < out_features; ++row) {
            sum += W[row * in_features + k];
        }
        w_red[k] = sum;
    }

    // Thread 0 calculates the sum of the bias vector
    if (k == 0) {
        float b_sum = 0.0f;
        for (int i = 0; i < out_features; ++i) {
            b_sum += b[i];
        }
        b_red[0] = b_sum;
    }
}

// Kernel 2: Fused Inference (Dot Product + Bias Add)
// X: (batch_size, in_features)
// w_red: (in_features)
// b_red: (1)
// out: (batch_size, 1)
__global__ void fused_inference_kernel(
    const float* __restrict__ X,
    const float* __restrict__ w_red,
    const float* __restrict__ b_red,
    float* __restrict__ out,
    int batch_size,
    int in_features) {

    // Each block handles one batch item (one row of X)
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    float dot = 0.0f;

    // Grid-stride loop (though typically blockDim < in_features, it handles larger dims)
    for (int k = threadIdx.x; k < in_features; k += blockDim.x) {
        dot += X[batch_idx * in_features + k] * w_red[k];
    }

    // Reduce within the block to get the final dot product for this row
    dot = block_reduce_sum(dot);

    // Thread 0 writes the result
    if (threadIdx.x == 0) {
        // Apply the reduced bias
        out[batch_idx] = dot + b_red[0]; 
        // Note: Mathematical equivalents of Max(dim=1), Mean(dim=1), LogSumExp(dim=1) 
        // on a vector of size 1 are identity operations.
    }
}

std::vector<torch::Tensor> fused_forward_cuda(torch::Tensor x, torch::Tensor W, torch::Tensor b) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = W.size(0);

    // Outputs
    auto w_red = torch::empty({in_features}, x.options());
    auto b_red = torch::empty({1}, x.options());
    auto out = torch::empty({batch_size, 1}, x.options());

    const int threads = 256;

    // 1. Launch Parameter Reduction
    int blocks_red = (in_features + threads - 1) / threads;
    reduce_params_kernel<<<blocks_red, threads>>>(
        W.data_ptr<float>(),
        b.data_ptr<float>(),
        w_red.data_ptr<float>(),
        b_red.data_ptr<float>(),
        out_features,
        in_features
    );

    // 2. Launch Inference
    // Each block handles one sample in the batch
    int blocks_inf = batch_size;
    fused_inference_kernel<<<blocks_inf, threads>>>(
        x.data_ptr<float>(),
        w_red.data_ptr<float>(),
        b_red.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features
    );

    return {out};
}
"""

