import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Softmax
# This kernel optimizes the softmax operation by performing row-wise reductions
# using shared memory and warp intrinsics, reducing global memory accesses.
softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Warp reduction helper for maximum
template<typename T>
__inline__ __device__ T warpReduceMax(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = max(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

// Warp reduction helper for summation
template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int cols) {
    // Each block processes one row
    int row = blockIdx.x;
    int tid = threadIdx.x;

    // Base pointers for the current row
    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    // --- Step 1: Find the maximum value in the row ---
    float local_max = -INFINITY;
    // Strided loop to handle columns > block size
    for (int i = tid; i < cols; i += blockDim.x) {
        local_max = max(local_max, row_input[i]);
    }

    // Reduce within warp
    local_max = warpReduceMax(local_max);

    // Shared memory for block-level reduction
    static __shared__ float warp_maxs[32]; // Max 1024 threads / 32 = 32 warps
    static __shared__ float shared_max;

    int lane = tid % 32;
    int warp_id = tid / 32;

    // Store warp results to shared memory
    if (lane == 0) warp_maxs[warp_id] = local_max;
    __syncthreads();

    // Reduce the warp results using the first warp
    if (tid < 32) {
        // Mask out invalid warps if blockDim < 1024
        float val = (tid < (blockDim.x / 32)) ? warp_maxs[tid] : -INFINITY;
        val = warpReduceMax(val);
        if (tid == 0) shared_max = val;
    }
    __syncthreads();

    float row_max = shared_max;

    // --- Step 2: Compute sum of exponentials ---
    float local_sum = 0.0f;
    for (int i = tid; i < cols; i += blockDim.x) {
        local_sum += expf(row_input[i] - row_max);
    }

    // Reduce within warp
    local_sum = warpReduceSum(local_sum);

    // Reuse shared memory for sum reduction
    static __shared__ float shared_sum;

    if (lane == 0) warp_maxs[warp_id] = local_sum;
    __syncthreads();

    if (tid < 32) {
        float val = (tid < (blockDim.x / 32)) ? warp_maxs[tid] : 0.0f;
        val = warpReduceSum(val);
        if (tid == 0) shared_sum = val;
    }
    __syncthreads();

    float row_sum = shared_sum;

    // --- Step 3: Compute final softmax values and write to global memory ---
    for (int i = tid; i < cols; i += blockDim.x) {
        row_output[i] = expf(row_input[i] - row_max) / row_sum;
    }
}

torch::Tensor softmax_cuda(torch::Tensor input) {
    auto rows = input.size(0);
    auto cols = input.size(1);
    auto output = torch::empty_like(input);

    const int threads = 1024;
    const int blocks = rows;

    softmax_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), cols);

    return output;
}
"""

softmax_cpp_source = "torch::Tensor softmax_cuda(torch::Tensor input);"

# Compile and load the inline CUDA operator
softmax_op = load_inline(
    name="softmax_op",
    cpp_sources=softmax_cpp_source,
    cuda_sources=softmax_source,
    functions=["softmax_cuda"],
    verbose=False,
    extra_cflags=['-O3'],
)

class ModelNew(nn.Module):
    """
    Optimized model replacing torch.softmax with a custom CUDA kernel.
    The Linear layer is kept as is (cuBLAS is highly optimized).
    The Dropout layer is kept as is (efficient memory bound op, complex RNG to move to inline CUDA).
    """
    def __init__(self, in_features, out_features, dropout_p):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.dropout = nn.Dropout(dropout_p)
        self.softmax_op = softmax_op

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).
        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_features).
        """
        x = self.matmul(x)
