import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// ------------------------------------------------------------------
// 1. Custom AvgPool3d Kernel
// ------------------------------------------------------------------

__global__ void avg_pool_3d_kernel(const float* __restrict__ input, float* __restrict__ output,
                                   int batch, int channels, 
                                   int in_d, int in_h, int in_w,
                                   int out_d, int out_h, int out_w,
                                   int k) {
    // Flattened index for output
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * out_d * out_h * out_w;

    if (idx >= total) return;

    // Decode index to (n, c, d_out, h_out, w_out)
    int w_out = idx % out_w;
    int rem = idx / out_w;
    int h_out = rem % out_h;
    rem /= out_h;
    int d_out = rem % out_d;
    rem /= out_d;
    int c = rem % channels;
    int n = rem / channels;

    // Map to input start indices
    int d_start = d_out * k;
    int h_start = h_out * k;
    int w_start = w_out * k;

    float sum = 0.0f;

    // Simple loop over the pool window
    // Assumes pool_size matches stride (standard AvgPool3d behavior without parameters)
    for (int z = 0; z < k; ++z) {
        for (int y = 0; y < k; ++y) {
            for (int x = 0; x < k; ++x) {
                int cur_d = d_start + z;
                int cur_h = h_start + y;
                int cur_w = w_start + x;

                // Calculate input index
                int in_idx = ((((n * channels + c) * in_d + cur_d) * in_h + cur_h) * in_w) + cur_w;
                sum += input[in_idx];
            }
        }
    }

    // Write average
    output[idx] = sum / (float)(k * k * k);
}

torch::Tensor avg_pool_cuda(torch::Tensor input, int k) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    // Calculate output dimensions (floor)
    auto out_D = D / k;
    auto out_H = H / k;
    auto out_W = W / k;

    auto output = torch::empty({B, C, out_D, out_H, out_W}, input.options());

    int total_elements = B * C * out_D * out_H * out_W;
    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    avg_pool_3d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        B, C, D, H, W, out_D, out_H, out_W, k
    );

    return output;
}

// ------------------------------------------------------------------
// 2. Fused Clamp + Spatial Softmax + Scale Kernels
// ------------------------------------------------------------------

// Kernel to find Max over spatial dimensions per (Batch, Channel)
__global__ void reduce_max_kernel(const float* __restrict__ x, float* __restrict__ max_buf,
                                  int spatial_size, float min_v, float max_v) {
    int nc = blockIdx.x; // Block for each (n, c) pair
    int tid = threadIdx.x;

    float thread_max = -1e37f; // Init with very small number

    int offset = nc * spatial_size;
    // Stride loop to cover all pixels in this channel
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        float val = x[offset + i];
        // Apply clamp on read
        if (val < min_v) val = min_v;
        if (val > max_v) val = max_v;

        if (val > thread_max) thread_max = val;
    }

    // Block reduction using shared memory
    extern __shared__ float s_max[];
    s_max[tid] = thread_max;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (s_max[tid + s] > s_max[tid]) {
                s_max[tid] = s_max[tid + s];
            }
        }
        __syncthreads();
    }

    if (tid == 0) {
        max_buf[nc] = s_max[0];
    }
}

// Kernel to compute Sum of Exponentials
__global__ void reduce_sum_kernel(const float* __restrict__ x, const float* __restrict__ max_buf,
                                  float* __restrict__ sum_buf,
                                  int spatial_size, float min_v, float max_v) {
    int nc = blockIdx.x;
    int tid = threadIdx.x;

    float global_max = max_buf[nc];
    float thread_sum = 0.0f;

    int offset = nc * spatial_size;
    for (int i = tid; i < spatial_size; i += blockDim.x) {
         float val = x[offset + i];
         if (val < min_v) val = min_v;
         if (val > max_v) val = max_v;

         thread_sum += expf(val - global_max);
    }

    extern __shared__ float s_sum[];
    s_sum[tid] = thread_sum;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        sum_buf[nc] = s_sum[0];
    }
}

// Kernel to apply Softmax Normalization and Scale
__global__ void apply_fused_kernel(const float* __restrict__ x, 
                                   const float* __restrict__ max_buf,
                                   const float* __restrict__ sum_buf,
                                   const float* __restrict__ scale,
                                   float* __restrict__ output,
                                   int spatial_size, int channels, float min_v, float max_v) {
    // Grid Setup: x=SpatialChunks, y=Channels, z=Batch
    int si = blockIdx.x * blockDim.x + threadIdx.x;
    if (si >= spatial_size) return;

    int c = blockIdx.y;
    int b = blockIdx.z;

    int nc = b * channels + c;
    int idx = nc * spatial_size + si;

    float val = x[idx];
    // Re-apply clamp
    if (val < min_v) val = min_v;
    if (val > max_v) val = max_v;

    float m = max_buf[nc];
    float s = sum_buf[nc];
    float sc = scale[c]; // scale is (1, C, 1, 1, 1), so effectively index c

    output[idx] = (expf(val - m) / s) * sc;
}

torch::Tensor fused_post_cuda(torch::Tensor input, torch::Tensor scale, float min_v, float max_v) {
    auto B = input.size(0);
