import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source code for the fused operator
# Fuses LeakyReLU, Add (with broadcasting), Clamp, and GELU into a single kernel.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(
    float* __restrict__ x, 
    const float* __restrict__ sum_tensor, 
    const int numel, 
    const int channels, 
    const int spatial_stride) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < numel) {
        float val = x[idx];

        // 1. LeakyReLU (negative_slope=0.2)
        if (val < 0.0f) {
            val *= 0.2f;
        }

        // 2. Add sum_tensor
        // Logic handles broadcasting of sum_tensor (C, 1, 1, 1) over x (N, C, D, H, W)
        // Index mapping: c = (idx / spatial_stride) % channels
        int c = (idx / spatial_stride) % channels;
        val += sum_tensor[c];

        // 3. Clamp (min=-1.0, max=1.0)
        val = fmaxf(-1.0f, fminf(1.0f, val));

        // 4. GELU
        // Exact formula: 0.5 * x * (1 + erf(x / sqrt(2)))
        const float kSqrt2Inv = 0.7071067811865475f;
        val = 0.5f * val * (1.0f + erff(val * kSqrt2Inv));

        x[idx] = val;
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor sum_tensor) {
    // x: Output of Conv3d (N, C, D, H, W)
    // sum_tensor: Parameter (C, 1, 1, 1) or (C)

    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(sum_tensor.is_cuda(), "sum_tensor must be a CUDA tensor");

    // Ensure inputs are contiguous
    if (!x.is_contiguous()) x = x.contiguous();
    if (!sum_tensor.is_contiguous()) sum_tensor = sum_tensor.contiguous();

    const int numel = x.numel();
    const int channels = x.size(1);
    const int spatial_stride = x.size(2) * x.size(3) * x.size(4);

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    // Launch kernel
    fused_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        sum_tensor.data_ptr<float>(),
        numel,
        channels,
        spatial_stride
    );

    return x;
}
