#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ inline float softplus_safe(float x) {
    if (x > 20.0f) return x;
    return log1pf(expf(x));
}

__device__ inline float mish_op(float x) {
    return x * tanhf(softplus_safe(x));
}

__device__ inline float hardswish_op(float x) {
    if (x <= -3.0f) return 0.0f;
    if (x >= 3.0f) return x;
    return x * (x + 3.0f) / 6.0f;
}

__global__ void fused_kernel(const float* __restrict__ input, float* __restrict__ output,
                             int N, int C, int H, int W,
                             int pool_size, float subtract_val,
                             int H_out, int W_out, int total_elements) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // idx maps to output (n, c, h_out, w_out)
    // Output Layout is N, C, H_out, W_out
    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int c = (idx / (W_out * H_out)) % C;
    int n = idx / (W_out * H_out * C);

    int h_start = h_out * pool_size;
    int w_start = w_out * pool_size;

    // Initialize max_val with a sufficiently small number
    float max_val = -1e37f; 

    // Iterate over the pooling window
    for (int i = 0; i < pool_size; ++i) {
        for (int j = 0; j < pool_size; ++j) {
            int h_in = h_start + i;
            int w_in = w_start + j;

            // Check boundaries (handling cases where H/W might not be perfect multiples if necessary, 
            // though standard floor logic implies valid starts)
            if (h_in < H && w_in < W) {
                // Calculate input index assuming contiguous NCHW layout
                int input_idx = ((n * C + c) * H + h_in) * W + w_in;
                float val = input[input_idx];

                // 1. Subtract
                val = val - subtract_val;

                // 2. HardSwish
                val = hardswish_op(val);

                // 3. MaxPool accumulation
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
    }

    // 4. Apply Mish to the pooled max value
    output[idx] = mish_op(max_val);
}

