fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Fast sigmoid implementation
__inline__ __device__ float sigmoidf_custom(float x) {
    return 1.0f / (1.0f + expf(-x));
}

// Warp Reduce Sum
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Block Reduce Sum
__inline__ __device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; // Shared memory for warp partial sums
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val); // Sum within warp

    if (lane == 0) shared[wid] = val; // Store warp sum

    __syncthreads(); // Wait for all warps

    // Read from shared memory and perform final reduction on warp 0
    // Assuming blockDim.x <= 1024, so max 32 warps
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0.0f;

    if (wid == 0) val = warpReduceSum(val); // Final sum

    return val;
}

__global__ void fused_bias_sigmoid_sum_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M,
    int N) {

    // Each block handles one row (M rows total)
    int row = blockIdx.x;
    if (row >= M) return;

    float sum = 0.0f;

    // Stride loop to cover the row (N elements)
    for (int col = threadIdx.x; col < N; col += blockDim.x) {
        float val = input[row * N + col];
        float b = bias[col];
        // Fused: val + bias -> sigmoid -> accumulate
        sum += sigmoidf_custom(val + b);
    }

    // Reduce sum within the block
    sum = blockReduceSum(sum);

    // Write result
    if (threadIdx.x == 0) {
        output[row] = sum;
    }
}

torch::Tensor fused_bias_sigmoid_sum(torch::Tensor input, torch::Tensor bias) {
    int M = input.size(0);
    int N = input.size(1);

    auto output = torch::zeros({M, 1}, input.options());

    const int threads = 256;
    const int blocks = M; // One block per batch item

    fused_bias_sigmoid_sum_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        M, N
    );

    return output;
}
