import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused post-processing operations
# This kernel fuses: Addition (Bias), Clamp, Scaling, Clamp, Division
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_post_process_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ bias, 
    float* __restrict__ out, 
    int size, 
    int channels, 
    int spatial_size, 
    float scaling_factor) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Calculate channel index c from flat index idx
        // x layout is [N, C, H, W]
        // spatial_size = H * W
        // The index relative to the start of a batch item is (idx % (C * spatial_size))
        // The channel index is ((idx / spatial_size) % channels)

        int c = (idx / spatial_size) % channels;

        float val = x[idx];
        float b = bias[c];

        // 1. Add bias
        val += b;

        // 2. Clamp (min=0.0, max=1.0)
        val = fmaxf(0.0f, fminf(1.0f, val));

        // 3. Scale
        val *= scaling_factor;

        // 4. Clamp (min=0.0, max=1.0)
        val = fmaxf(0.0f, fminf(1.0f, val));

        // 5. Divide
        val /= scaling_factor;

        out[idx] = val;
    }
}

torch::Tensor fused_post_process_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor) {
    // Ensure inputs are contiguous for direct pointer access
    x = x.contiguous();
    bias = bias.contiguous();

    auto size = x.numel();
    auto channels = x.size(1);
    auto height = x.size(2);
