import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernel that fuses Subtraction -> Tanh -> Subtraction -> AvgPool
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float sub1,
    float sub2,
    int pool_size,
    int batch,
    int channels,
    int h_in,
    int w_in,
    int h_out,
    int w_out
) {
    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = batch * channels * h_out * w_out;

    if (idx < total_threads) {
        // Calculate output coordinates (n, c, h_out, w_out) from linear index
        int w_out_idx = idx % w_out;
        int tmp = idx / w_out;
        int h_out_idx = tmp % h_out;
        tmp = tmp / h_out;
        int c_idx = tmp % channels;
        int n_idx = tmp / channels;

        // Calculate top-left corner of the pooling window in input
        int h_in_base = h_out_idx * pool_size;
        int w_in_base = w_out_idx * pool_size;

        // Offset for the specific batch and channel
        int input_offset = n_idx * (channels * h_in * w_in) + c_idx * (h_in * w_in);

        float sum = 0.0f;

        // Iterate over the pooling window
        for (int i = 0; i < pool_size; ++i) {
            for (int j = 0; j < pool_size; ++j) {
                int h = h_in_base + i;
                int w = w_in_base + j;

                // Bounds check
                if (h < h_in && w < w_in) {
                    int in_idx = input_offset + h * w_in + w;
                    float val = input[in_idx];

                    // Fused operations: (x - sub1) -> tanh -> (res - sub2)
                    val = val - sub1;
                    val = tanhf(val);
                    val = val - sub2;

                    sum += val;
                }
            }
        }

        // Compute average
        // Note: Standard AvgPool2d divides by kernel_size^2 even if padding is not used, 
        // unless count_include_pad is False and we are at edges. 
        // Given the architecture parameters and input sizes (126x126 -> 63x63 with k=2), 
        // windows are full, so dividing by pool_size^2 is correct.
        output[idx] = sum / (float)(pool_size * pool_size);
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor input, float sub1, float sub2, int pool_size) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H_in = input.size(2);
    auto W_in = input.size(3);

    // Calculate output dimensions based on AvgPool logic (stride=kernel_size)
    auto H_out = H_in / pool_size;
    auto W_out = W_in / pool_size;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    int total_elements = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        sub1,
        sub2,
        pool_size,
        N, C, H_in, W_in, H_out, W_out
    );

    return output;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_forward_cuda(torch::Tensor input, float sub1, float sub2, int pool_size);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that fuses the subtraction, tanh, subtraction, and average pooling layers 
    into a single CUDA kernel to reduce memory bandwidth usage.
    """
    def __init__(self, in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool):
        super(ModelNew, self).__init__()
        # Conv2d is highly optimized in cuDNN, so we keep it as is.
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.subtract1_value = subtract1_value
        self.subtract2_value = subtract2_value
        self.kernel_size_pool = kernel_size_pool
        self.fused_ops = fused_ops

