#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_min_tanh_tanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int spatial_size) {

    // Each thread handles one spatial location (h, w) for one batch item (n)
    // Output shape is (N, 1, H, W), so total threads needed = N * H * W
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = batch_size * spatial_size;

    if (idx < total_output_elements) {
        // Decompose linear index 'idx' into batch index and spatial index
        int b = idx / spatial_size;
        int s = idx % spatial_size;

        // Input tensor layout is NCHW (Batch, Channels, Height, Width)
        // We want to reduce over the 'Channels' dimension for the specific (b, s).
        // The memory offset for (b, c=0, s) is: b * (channels * spatial_size) + 0 * spatial_size + s
        const float* input_ptr = input + b * channels * spatial_size + s;

        float min_val = FLT_MAX;

        // Loop over channels to find the minimum value
        // Stride between channels at the same spatial location is 'spatial_size'
        for (int c = 0; c < channels; ++c) {
            float val = *input_ptr;
            if (val < min_val) {
                min_val = val;
            }
            input_ptr += spatial_size;
        }

        // Apply tanh twice on the result
        // y = tanh(tanh(min(x)))
        output[idx] = tanhf(tanhf(min_val));
    }
}

