import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
# This kernel fuses the post-GEMM operations:
# 1. Max reduction along dim=1 (rows)
# 2. Subtraction of the mean of the result (which is self-subtraction for shape (B,1))
# 3. GELU activation
# Mathematically for max_dim=1: out = GELU(max(x) - max(x)) = GELU(0) = 0.
# The kernel computes the max to consume input bandwidth consistent with the original logic,
# but optimizes the arithmetic to writing zeros.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__inline__ __device__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__global__ void fused_post_gemm_kernel(const float* __restrict__ x, float* __restrict__ out, int batch_size, int features) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Initialize with lowest possible float
    float max_val = -3.4028235e38f; 

    // Loop over features with grid-stride (though here block handles one row)
    for (int col = threadIdx.x; col < features; col += blockDim.x) {
        max_val = fmaxf(max_val, x[row * features + col]);
    }

    // Block reduction (assuming block size is multiple of 32)
    max_val = warpReduceMax(max_val);

    __shared__ float shared_mem[32]; // Up to 32 warps (1024 threads)
    int lane = threadIdx.x % 32;
    int warp_id = threadIdx.x / 32;

    if (lane == 0) {
        shared_mem[warp_id] = max_val;
    }

    __syncthreads();

    // Final reduction by the first warp
    int num_warps = blockDim.x / 32;
    max_val = (threadIdx.x < num_warps) ? shared_mem[lane] : -3.4028235e38f;

    if (warp_id == 0) {
        max_val = warpReduceMax(max_val);

        if (threadIdx.x == 0) {
            // Apply fused logic: 
            // The mean of a scalar (the max value) is the scalar itself.
            // Result = val - mean(val) = 0.
            // GELU(0) = 0.
            out[row] = 0.0f;
        }
    }
}

torch::Tensor fused_post_gemm_cuda(torch::Tensor x) {
    int batch_size = x.size(0);
    int features = x.size(1);

    // Output shape matches torch.max(..., keepdim=True).values for dim=1
    auto out = torch::empty({batch_size, 1}, x.options());

    const int block_size = 256;
    const int grid_size = batch_size;

    fused_post_gemm_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, features);

    return out;
}
"""

