    Optimized model using custom CUDA kernels for post-GEMM operations.
    """
    def __init__(self, in_features, out_features, max_dim):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.max_dim = max_dim

    def forward(self, x):
        x = self.gemm(x)

        # The custom kernel is optimized for the specific case where max_dim=1 (row-wise reduction).
        if self.max_dim == 1:
            return fused_ops.fused_post_gemm_cuda(x)
