import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused InstanceNorm, Add, and Mul
# This kernel performs:
# 1. Row-wise mean and variance calculation (Instance Normalization logic over features)
# 2. Normalization: (x - mean) / sqrt(var + eps)
# 3. Addition: x + y
# 4. Multiplication: x * y
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_norm_add_mul_kernel(
    float* __restrict__ x,
    const float* __restrict__ y,
    int batch_size,
    int features,
    float eps) {

    // Shared memory for reduction: storing sums and sum_squares
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sum_sq = sdata + blockDim.x;

    int tid = threadIdx.x;
    int bid = blockIdx.x;

    if (bid >= batch_size) return;

    // Pointers for this batch row
    float* x_row = x + bid * features;
    const float* y_row = y + bid * features;

    // 1. Local accumulation
    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // Strided loop to handle feature size > block size
    for (int i = tid; i < features; i += blockDim.x) {
        float val = x_row[i];
        local_sum += val;
        local_sum_sq += val * val;
    }

    s_sum[tid] = local_sum;
    s_sum_sq[tid] = local_sum_sq;
    __syncthreads();

    // 2. Reduction in shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sum_sq[tid] += s_sum_sq[tid + s];
        }
        __syncthreads();
    }

    // 3. Compute stats (only thread 0 needs to compute, but we broadcast implicitly via shared mem if needed)
    // Here we compute on all threads or just let all read s_sum[0]
    float mean = s_sum[0] / features;
    float var = (s_sum_sq[0] / features) - (mean * mean);
    float inv_std = rsqrtf(max(var, 0.0f) + eps);

    // 4. Apply operations
    for (int i = tid; i < features; i += blockDim.x) {
        float val = x_row[i];
        float y_val = y_row[i];

        // Instance Norm
        val = (val - mean) * inv_std;

        // Add & Mul
        val = (val + y_val) * y_val;

        x_row[i] = val;
    }
}

torch::Tensor fused_ops(torch::Tensor x, torch::Tensor y, float eps) {
    int batch_size = x.size(0);
    int features = x.size(1);

    // Launch configuration
    // Each block handles one batch item (row)
    const int block_size = 256;
    int grid_size = batch_size;
    // Need enough shared memory for two float arrays of size block_size
    size_t smem_size = 2 * block_size * sizeof(float);

    fused_norm_add_mul_kernel<<<grid_size, block_size, smem_size>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        batch_size,
        features,
        eps
    );

    return x;
}
"""

