from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused element-wise operations: Min -> Clamp -> Dropout
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    const float* __restrict__ noise,
    float* __restrict__ out,
    float min_val,
    float max_val,
    float p,
    float scale,
    int size,
    bool training) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];

        // Operation 1: x = torch.min(x, min_value)
        val = fminf(val, min_val);

        // Operation 2: x = torch.clamp(x, min=min_value, max=max_value)
        // clamp(v, min, max) is max(min, min(v, max))
        val = fmaxf(min_val, fminf(val, max_val));

        // Operation 3: Dropout
        if (training && p > 0.0f) {
            // noise is a random tensor [0, 1) pre-generated
            // if noise[idx] < p, drop the value
            // otherwise scale it
            if (noise[idx] < p) {
                val = 0.0f;
            } else {
                val = val * scale;
            }
        }

        out[idx] = val;
    }
}

torch::Tensor fused_ops_cuda(
    torch::Tensor input,
    torch::Tensor noise,
    float min_val,
    float max_val,
    float p,
    bool training) {

    auto size = input.numel();
    auto out = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

