import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -----------------------------------------------------------------------------------------
# Custom CUDA Kernels
# -----------------------------------------------------------------------------------------
# We implement two fused kernels:
# 1. fused_bias_sigmoid_cuda: Fuses element-wise bias addition and Sigmoid activation.
#    This reduces global memory reads/writes compared to separate add and sigmoid ops.
# 2. fused_bias_logsumexp_cuda: Fuses bias addition and LogSumExp reduction per row.
#    This performs the reduction in a single pass using shared memory, avoiding
#    intermediate memory traffic and leveraging the small output_size (1024).

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel 1: Fused Bias Addition + Sigmoid
// Grid Stride Loop allows handling arbitrary input sizes.
__global__ void fused_bias_sigmoid_kernel(
    const float* __restrict__ input, 
    const float* __restrict__ bias, 
    float* __restrict__ output, 
    int total_elements, 
    int hidden_size) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    // Iterate over all elements
    for (int i = idx; i < total_elements; i += gridDim.x * blockDim.x) {
        int col = i % hidden_size; // Determine column index for bias broadcasting
        float val = input[i] + bias[col];
        output[i] = 1.0f / (1.0f + expf(-val));
    }
}

// Kernel 2: Fused Bias Addition + LogSumExp
// One block per row (batch element). Thread block performs reduction.
// Designed for output_size <= 1024 (fits in one block).
__global__ void fused_bias_logsumexp_kernel(
    const float* __restrict__ input, 
    const float* __restrict__ bias, 
    float* __restrict__ output, 
    int batch_size, 
    int output_size) 
{
    extern __shared__ float sdata[];

    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= batch_size) return;

    // 1. Load data, add bias, and store in shared memory
    // Initialize with a very small number for max reduction identity
    float val = -1e20f; 
    if (tid < output_size) {
        val = input[row * output_size + tid] + bias[tid];
    }
    sdata[tid] = val;
    __syncthreads();

    // 2. Reduce Max
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }
    float max_val = sdata[0];
    __syncthreads();

    // 3. Compute exp(val - max)
    // We use the register 'val' (original input+bias) to recompute
    float exp_val = 0.0f;
    if (tid < output_size) {
        exp_val = expf(val - max_val);
    }
    sdata[tid] = exp_val;
    __syncthreads();

    // 4. Reduce Sum of Exponentials
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // 5. Final LogSumExp Result
    if (tid == 0) {
        output[row] = max_val + logf(sdata[0]);
    }
}

torch::Tensor fused_bias_sigmoid_cuda(torch::Tensor input, torch::Tensor bias) {
    auto batch_size = input.size(0);
    auto hidden_size = input.size(1);
    auto output = torch::empty_like(input);
    int total_elements = batch_size * hidden_size;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_bias_sigmoid_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        output.data_ptr<float>(), 
        total_elements, 
        hidden_size
    );
    return output;
}

torch::Tensor fused_bias_logsumexp_cuda(torch::Tensor input, torch::Tensor bias) {
    auto batch_size = input.size(0);
    auto output_size = input.size(1);
    auto output = torch::empty({batch_size}, input.options());

    // Launch configuration:
    // Grid size = Batch Size (one block per sample)
    // Block size = 1024 (covers the max output_size of 1024)
    const int block_size = 1024;
    const int num_blocks = batch_size;
    const int shared_mem_size = block_size * sizeof(float);

    fused_bias_logsumexp_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        input.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        output.data_ptr<float>(), 
        batch_size, 
        output_size
    );
    return output;
}
"""

cpp_source = """
torch::Tensor fused_bias_sigmoid_cuda(torch::Tensor input, torch::Tensor bias);
torch::Tensor fused_bias_logsumexp_cuda(torch::Tensor input, torch::Tensor bias);
"""

# Compile the inline CUDA code
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_bias_sigmoid_cuda", "fused_bias_logsumexp_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3", "--use_fast_math"]
)

class ModelNew(nn.Module):
    """
    Optimized Model using custom CUDA kernels for element-wise and reduction operations.
    Matrix Multiplications are handled by PyTorch's optimized cuBLAS calls.
    Bias addition + Activation/Reduction are fused into custom kernels.
    """
    def __init__(self, input_size, hidden_size, output_size):
        super(ModelNew, self).__init__()
        # We maintain the nn.Linear modules to handle weights and initialization correctly.
        # However, we will use the weights manually in the forward pass.
        self.linear1 = nn.Linear(input_size, hidden_size)
        self.linear2 = nn.Linear(hidden_size, output_size)
        self.ops = custom_ops

    def forward(self, x):
        # Optimized Layer 1:
        # 1. Matrix Multiplication: x @ W1^T
        #    We use torch.mm for high-performance cuBLAS GEMM.
        #    We access the weight tensor directly.
        x = torch.mm(x, self.linear1.weight.t())

        # 2. Fused Bias Add + Sigmoid
        #    Custom kernel replaces: x = x + bias; x = sigmoid(x)
        x = self.ops.fused_bias_sigmoid_cuda(x, self.linear1.bias)

        # Optimized Layer 2:
        # 1. Matrix Multiplication: x @ W2^T
        x = torch.mm(x, self.linear2.weight.t())

        # 2. Fused Bias Add + LogSumExp
        #    Custom kernel replaces: x = x + bias; x = logsumexp(x, dim=1)
        x = self.ops.fused_bias_logsumexp_cuda(x, self.linear2.bias)

        return x

