import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fusing addition, HardSwish, and multiplication
# The original forward pass logic is:
# x = conv(x)
# x = x + add_input
# x = x * HardSwish(x)
#
# We fuse the element-wise operations:
# out = (conv_out + add_input) * HardSwish(conv_out + add_input)
#
# Definition of HardSwish(y) = y * ReLU6(y + 3) / 6
# Logic:
# let val = conv_out + add_input
# if val <= -3: hswish = 0
# if val >= 3:  hswish = val
# else:         hswish = val * (val + 3) / 6
# result = val * hswish

fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_ops_kernel(const float* __restrict__ input, 
                                 const float* __restrict__ add_input, 
                                 float* __restrict__ output, 
                                 int64_t size) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] + add_input[idx];

        float hswish = 0.0f;
        if (val >= 3.0f) {
            hswish = val;
        } else if (val > -3.0f) {
            hswish = val * (val + 3.0f) * 0.16666667f; // Multiply by 1/6
        }

        // The model performs x = x * hardswish(x)
        output[idx] = val * hswish;
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor input, torch::Tensor add_input) {
    auto size = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        add_input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}
"""

