    Optimized Model with custom CUDA operators.
    Replaces the element-wise addition and activation sequence with a fused kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                 stride=stride, padding=padding, output_padding=output_padding)
        # Retain bias parameter to match original architecture state dict, even if unused in forward
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops

    def forward(self, x, add_input):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, D, H, W).
            add_input (torch.Tensor): Input tensor to be added after transposed convolution.
        Returns:
            torch.Tensor: Output tensor.
        """
        x = self.conv_transpose(x)

        # Ensure inputs are contiguous for the CUDA kernel
        if not x.is_contiguous():
            x = x.contiguous()
        if not add_input.is_contiguous():
            add_input = add_input.contiguous()

        # Use custom fused kernel for: x = (x + add_input) * HardSwish(x + add_input)
        return self.fused_ops.fused_forward_cuda(x, add_input)

