import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused post-convolution operations.
# This kernel fuses:
# 1. Min reduction along dimension 1 (Channels)
# 2. Sum reduction along dimension 2 (Height)
# 3. GELU activation
# 4. Bias addition
fused_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float gelu_func(float x) {
    // GELU activation: 0.5 * x * (1 + erf(x / sqrt(2)))
    const float kAlpha = 0.70710678f; // 1/sqrt(2)
    return 0.5f * x * (1.0f + erff(x * kAlpha));
}

__global__ void fused_post_conv_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W) {

    // Grid Mapping:
    // blockIdx.x corresponds to batch index 'n'
    // blockIdx.y * blockDim.x + threadIdx.x corresponds to width index 'w'

    int n = blockIdx.x;
    int w = blockIdx.y * blockDim.x + threadIdx.x;

    if (n < N && w < W) {
        float h_sum = 0.0f;

        // Pointer arithmetic for Input [N, C, H, W]
        // We need to perform reductions: sum_h( min_c( input[n, c, h, w] ) )
        // The linear index is: n*(C*H*W) + c*(H*W) + h*W + w

        // Base offset for the current n and w
        long long base_offset = (long long)n * C * H * W + w;
        int stride_c = H * W;
        int stride_h = W;

        // Outer reduction loop: Sum over H
        for (int h = 0; h < H; ++h) {
            float c_min = 3.402823466e+38F; // FLT_MAX

            long long h_offset = base_offset + (long long)h * stride_h;

            // Inner reduction loop: Min over C
            for (int c = 0; c < C; ++c) {
                float val = input[h_offset + (long long)c * stride_c];
                c_min = fminf(c_min, val);
            }
            h_sum += c_min;
        }

        // Apply GELU
        float res = gelu_func(h_sum);

        // Add Bias (scalar broadcast based on shape (1,1,1))
        res += bias[0];

        // Write output
        // Output shape is [N, 1, 1, W]
        // Flattened index: n*W + w
        output[n * W + w] = res;
    }
}

torch::Tensor fused_post_conv_cuda(torch::Tensor input, torch::Tensor bias) {
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto output = torch::empty({N, 1, 1, W}, input.options());

    // Configure Grid
    // We launch threads for N * W parallel tasks.
    dim3 block(256);
    dim3 grid(N, (W + block.x - 1) / block.x);

    fused_post_conv_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}
"""

fused_cpp_source = "torch::Tensor fused_post_conv_cuda(torch::Tensor input, torch::Tensor bias);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=['fused_post_conv_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

