    """
    Optimized model that replaces the sequence of min->sum->gelu->add with a single fused CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        # Keep the ConvTranspose2d as is, it's already well optimized in cuDNN
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride, padding, output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        # Apply fused operation: Min(dim=1) -> Sum(dim=2) -> GELU -> Add Bias
        x = self.fused_ops.fused_post_conv_cuda(x, self.bias)
        return x

