__global__ void fused_relu_add_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ bias, 
    float* __restrict__ out, 
    int size, 
    int channels, 
    int spatial_size) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];

        // ReLU Operation
        val = val > 0.0f ? val : 0.0f;

        // Bias Addition
        // Input tensor layout is (N, C, H, W)
        // We need to determine the channel index 'c' for the current element.
        // The global index maps to: n * (C * spatial_size) + c * spatial_size + spatial_idx

        // Calculate index within a single batch item (removing N dimension offset)
        int idx_in_batch = idx % (channels * spatial_size);

        // Calculate channel index
        int c = idx_in_batch / spatial_size;

        // Add channel-specific bias
        val += bias[c];

        out[idx] = val;
    }
}

