import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused MaxPool1d + Sum + Scale
# This kernel optimizes the post-Linear operations by fusing them into a single kernel,
# reducing memory bandwidth requirements and kernel launch overhead.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_pool_sum_scale_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output, 
    int width, 
    float scale) 
{
    // Each block processes one row (batch element)
    int batch_idx = blockIdx.x;

    // Calculate the starting pointer for this row
    const float* row_ptr = input + batch_idx * width;

    // We process pairs of elements (kernel_size=2, stride=2)
    int num_pairs = width / 2;

    float local_sum = 0.0f;

    // Reinterpret cast to float2 for vectorized loads (efficient memory access)
    // This assumes row_ptr is aligned to 8 bytes, which is standard for PyTorch allocations
    // and the given problem dimensions (out_features=32768, which is even).
    const float2* row_pairs = reinterpret_cast<const float2*>(row_ptr);

    // Grid-stride loop (here, block-stride as we have 1 block per row)
    for (int i = threadIdx.x; i < num_pairs; i += blockDim.x) {
        float2 val = row_pairs[i];
        // Compute MaxPool (max of the pair)
        float m = (val.x > val.y) ? val.x : val.y;
        local_sum += m;
    }

    // Block reduction using shared memory
    extern __shared__ float sdata[];
    sdata[threadIdx.x] = local_sum;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Write the scaled result to global memory
    if (threadIdx.x == 0) {
        output[batch_idx] = sdata[0] * scale;
    }
}

