import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
# Operations: LogSumExp(dim=1) -> Activation(x * sigmoid(x+3)/6) -> Sub(bias) -> Clamp(-1, 1)
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ bias, 
    float* __restrict__ out, 
    int N, int C, int V) {

    // V is the spatial volume: D * H * W
    // We parallelize over the output elements (N * 1 * D * H * W)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * V;

    if (idx < total_elements) {
        int n = idx / V;
        int v = idx % V;

        // The input x has shape (N, C, D, H, W)
        // Flattened layout: N * (C * V) + c * V + v
        // We need to reduce over C dimension.
        // Base offset for this spatial location (n, v)
        int base_offset = n * C * V + v;

        // 1. LogSumExp(dim=1)
        // First pass: find max for numerical stability
        float max_val = x[base_offset];
        for (int c = 1; c < C; ++c) {
            float val = x[base_offset + c * V];
            if (val > max_val) {
                max_val = val;
            }
        }

        // Second pass: compute sum of exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            sum_exp += expf(x[base_offset + c * V] - max_val);
        }

        float lse = max_val + logf(sum_exp);

        // 2. Custom Activation: x * sigmoid(x + 3) / 6
        // x here is the result of lse
        float sig = 1.0f / (1.0f + expf(-(lse + 3.0f)));
        float activated = lse * sig / 6.0f;

        // 3. Subtract bias
        // bias shape is (1, 1, 1, 1), so effectively a scalar subtraction due to broadcasting
        float b = bias[0];
        float res = activated - b;

        // 4. Clamp (-1, 1)
        if (res < -1.0f) res = -1.0f;
        if (res > 1.0f) res = 1.0f;

        out[idx] = res;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias) {
    // x shape: (N, C, D, H, W)
    // bias shape: (1, 1, 1, 1)

    auto N = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);
    int V = D * H * W;

    // Output shape: (N, 1, D, H, W)
    auto out = torch::empty({N, 1, D, H, W}, x.options());

    const int block_size = 256;
    int total_threads = N * V;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, V
    );

    return out;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_ops_cuda(torch::Tensor x, torch::Tensor bias);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution, followed by 
    a fused CUDA kernel for LogSumExp, HardSwish-variant, subtraction, and clamp operations.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape):
        super(ModelNew, self).__init__()
        # Keep ConvTranspose3d as is, it is already highly optimized in cuDNN
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.bias = nn.Parameter(torch.randn(1, 1, 1, 1)) 
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        # Apply the fused kernel for the rest of the operations
        return self.fused_ops.fused_ops_cuda(x, self.bias)

