import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernel for fused AvgPool2d + Sigmoid + Sum
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel fuses AvgPool, Sigmoid, and global Sum reduction
// Input: (N, C, H, W)
// Output: (N) - Sum over C, H_out, W_out
__global__ void fused_pool_sigmoid_sum_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int C, int H, int W,
    int K, int H_out, int W_out) {

    // Grid layout: x -> Batch (N), y -> Channel (C)
    // Each block processes one channel of one batch item.
    int n = blockIdx.x;
    int c = blockIdx.y;

    // Calculate the pointer offset for the specific channel plane
    // Input layout is NCHW
    int input_offset = n * (C * H * W) + c * (H * W);
    const float* input_plane = input + input_offset;

    float local_sum = 0.0f;
    int num_windows = H_out * W_out;

    // Iterate over all pooling windows in this channel
    // Grid-stride loop allows flexibility if num_windows > blockDim.x
    for (int idx = threadIdx.x; idx < num_windows; idx += blockDim.x) {
        // Map linear index to spatial coordinates of the pooled output
        int h_idx = idx / W_out;
        int w_idx = idx % W_out;

        // Determine top-left corner in the input tensor for this window
        int h_start = h_idx * K;
        int w_start = w_idx * K;

        float window_accum = 0.0f;

        // Perform Average Pooling on the KxK window
        for (int i = 0; i < K; ++i) {
            for (int j = 0; j < K; ++j) {
                int h_in = h_start + i;
                int w_in = w_start + j;
                window_accum += input_plane[h_in * W + w_in];
            }
        }

        float avg = window_accum / (float)(K * K);

        // Apply Sigmoid
        float sig = 1.0f / (1.0f + expf(-avg));

        // Accumulate result
        local_sum += sig;
    }

    // Block-level reduction using shared memory
    __shared__ float sdata[256];
    int tid = threadIdx.x;
    sdata[tid] = local_sum;
    __syncthreads();

    // Standard parallel reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // The first thread in the block adds the channel's contribution to the batch sum
    // Since multiple blocks (channels) correspond to the same batch index 'n', we use atomicAdd.
    if (tid == 0) {
        atomicAdd(&output[n], sdata[0]);
    }
}

torch::Tensor fused_forward(torch::Tensor input, int K) {
    // Input is NCHW
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    // Calculate output dimensions for AvgPool (floor division)
    // Matches nn.AvgPool2d default behavior with no padding
    int H_out = H / K;
    int W_out = W / K;

    // Allocate output tensor (N,) initialized to zero
    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({N}, options);

    // Grid dimensions: (N, C)
    // Each block handles one feature map (H, W) for one batch item
    dim3 grid(N, C);
    int threads = 256;

    fused_pool_sigmoid_sum_kernel<<<grid, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        C, H, W, K, H_out, W_out
    );

    return output;
}
"""

cpp_source = "torch::Tensor fused_forward(torch::Tensor input, int K);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model replacing the sequence of AvgPool2d -> Sigmoid -> Sum
    with a single fused CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        # Standard Conv2d is highly optimized (cuDNN), so we keep it.
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.pool_kernel_size = pool_kernel_size
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv(x)
        # Execute fused kernel
        x = self.fused_ops.fused_forward(x, self.pool_kernel_size)
        return x

