import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source
# This kernel fuses the Bias Addition, Minimum clamping, and Constant Subtraction
# into a single pass to save memory bandwidth.
# It includes a vectorized path (float4) for performance on aligned data.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm>

__global__ void fused_bias_min_sub_kernel_float4(
    float4* __restrict__ x, 
    const float4* __restrict__ bias, 
    float constant, 
    int num_vec, 
    int width_vec) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < num_vec; i += stride) {
        // Map linear index to column for bias broadcasting
        // We are processing vectors of 4 floats
        int col = i % width_vec;

        float4 x_val = x[i];
        float4 b_val = bias[col];

        // Perform fused operation: min(x + bias, constant) - constant
        x_val.x = fminf(x_val.x + b_val.x, constant) - constant;
        x_val.y = fminf(x_val.y + b_val.y, constant) - constant;
        x_val.z = fminf(x_val.z + b_val.z, constant) - constant;
        x_val.w = fminf(x_val.w + b_val.w, constant) - constant;

        x[i] = x_val;
    }
}

__global__ void fused_bias_min_sub_kernel_scalar(
    float* __restrict__ x, 
    const float* __restrict__ bias, 
    float constant, 
    int numel, 
    int width) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < numel; i += stride) {
        int col = i % width;
        float val = x[i] + bias[col];
        val = fminf(val, constant);
        x[i] = val - constant;
    }
}

void fused_bias_min_sub_cuda(torch::Tensor x, torch::Tensor bias, float constant) {
    int numel = x.numel();
    int width = x.size(1);

    // Check constraints for vectorization:
    // 1. Width must be divisible by 4 (to ensure rows are aligned to float4)
    // 2. Data must be contiguous in memory
    bool use_float4 = (width % 4 == 0) && x.is_contiguous() && bias.is_contiguous();

    if (use_float4) {
        int num_vec = numel / 4;
        int width_vec = width / 4;
        const int block_size = 256;
        // Calculate grid size
        const int num_blocks = (num_vec + block_size - 1) / block_size;

        fused_bias_min_sub_kernel_float4<<<num_blocks, block_size>>>(
            reinterpret_cast<float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(bias.data_ptr<float>()),
            constant,
            num_vec,
            width_vec
        );
    } else {
        const int block_size = 256;
        const int num_blocks = (numel + block_size - 1) / block_size;

        fused_bias_min_sub_kernel_scalar<<<num_blocks, block_size>>>(
            x.data_ptr<float>(),
            bias.data_ptr<float>(),
            constant,
            numel,
            width
        );
    }
}
"""

cpp_source = """
void fused_bias_min_sub_cuda(torch::Tensor x, torch::Tensor bias, float constant);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops_v1",
    cpp_sources=cpp_source,
