)

class ModelNew(nn.Module):
    """
    Optimized ModelNew that performs Matrix Multiplication using PyTorch (cuBLAS)
    and fuses the Bias Addition, Min, and Subtraction into a custom CUDA kernel.
    """
    def __init__(self, in_features, out_features, constant):
        super(ModelNew, self).__init__()
        # We keep the Linear layer to store weights and bias, but we will control execution manually.
        self.linear = nn.Linear(in_features, out_features)
        self.constant = nn.Parameter(torch.tensor(constant))
