import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused MaxPooling and Sum reduction
# The original architecture performs:
# 1. MaxPool3d(kernel_size=2) (stride defaults to kernel_size=2)
# 2. MaxPool3d(kernel_size=3) (stride defaults to kernel_size=3)
# 3. Sum(dim=1, keepdim=True)
#
# Mathematically, applying MaxPool(k=2, s=2) followed by MaxPool(k=3, s=3) is equivalent 
# to a single MaxPool(k=6, s=6), assuming standard floor behavior for output size calculation.
# We fuse these two pooling operations and the channel summation into a single CUDA kernel.
# This reduces memory bandwidth significantly by avoiding the write/read of intermediate tensors.

fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_pool_sum_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int D_out, int H_out, int W_out) {

    // Grid maps to output spatial locations (N, D_out, H_out, W_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_out = D_out * H_out * W_out;
    int total_threads = N * spatial_out;

    if (idx < total_threads) {
        // Decode index to (n, d_out, h_out, w_out)
        int w_out = idx % W_out;
        int rem = idx / W_out;
        int h_out = rem % H_out;
        rem = rem / H_out;
        int d_out = rem % D_out;
        int n = rem / D_out;

        // Input strides
        int stride_w = 1;
        int stride_h = W;
        int stride_d = H * W;
        int stride_c = D * H * W;
        int stride_n = C * D * H * W;

        // Determine the starting corner of the 6x6x6 pooling window in the input
        // Stride is 6
        int d_start = d_out * 6;
        int h_start = h_out * 6;
        int w_start = w_out * 6;

        // Pointer to the start of the current sample
        const float* input_n = input + n * stride_n;

        float sum_val = 0.0f;

        // Iterate over all channels to perform the sum reduction
        for (int c = 0; c < C; ++c) {
            float max_val = -FLT_MAX;
            const float* input_c = input_n + c * stride_c;

            // Perform MaxPool over the 6x6x6 window
            // Unrolling loops for performance
            #pragma unroll
            for (int i = 0; i < 6; ++i) {
                #pragma unroll
                for (int j = 0; j < 6; ++j) {
                    #pragma unroll
                    for (int k = 0; k < 6; ++k) {
                        int d_in = d_start + i;
                        int h_in = h_start + j;
                        int w_in = w_start + k;

                        // Calculate offset
                        int offset = d_in * stride_d + h_in * stride_h + w_in * stride_w;
                        float val = input_c[offset];
                        if (val > max_val) {
                            max_val = val;
                        }
                    }
                }
            }
            sum_val += max_val;
        }

        // Write the result to output
        // Output shape is (N, 1, D_out, H_out, W_out)
        // We can treat it linearly or use the same indexing logic
        output[idx] = sum_val;
    }
}

torch::Tensor fused_pool_sum_cuda(torch::Tensor input) {
    // Input is expected to be (N, C, D, H, W)
    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    // Calculate output dimensions for MaxPool3d(kernel_size=6, stride=6)
    // floor((Input - Kernel) / Stride) + 1
    int D_out = (D - 6) / 6 + 1;
    int H_out = (H - 6) / 6 + 1;
    int W_out = (W - 6) / 6 + 1;

    // Allocate output tensor
    // Output shape: (N, 1, D_out, H_out, W_out)
    auto output = torch::empty({N, 1, D_out, H_out, W_out}, input.options());

    int total_threads = N * D_out * H_out * W_out;
    int threads_per_block = 256;
    int blocks = (total_threads + threads_per_block - 1) / threads_per_block;

    fused_pool_sum_kernel<<<blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        D_out, H_out, W_out
    );

    return output;
}
"""

cpp_source = "torch::Tensor fused_pool_sum_cuda(torch::Tensor input);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=fused_source,
    functions=["fused_pool_sum_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces the sequential MaxPool3d -> MaxPool3d -> Sum operations
    with a single fused CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding):
        super(ModelNew, self).__init__()
        # We retain ConvTranspose3d as it is compute-bound and highly optimized in CuDNN.
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.fused_ops = fused_ops

    def forward(self, x):
        # Perform the transposed convolution
        x = self.conv_transpose(x)

        # Call the custom fused kernel which performs:
        # MaxPool3d(2) + MaxPool3d(3) + Sum(dim=1)
        # This is equivalent to MaxPool3d(6, stride=6) followed by channel summation.
        return self.fused_ops.fused_pool_sum_cuda(x)

