import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code
# This kernel fuses Mish activation, scalar addition, Hardtanh, and scaling into a single operation.
fused_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Helper device function for Mish activation: x * tanh(ln(1 + e^x))
__device__ __forceinline__ float mish_func(float x) {
    // Numerical stability: for large x, ln(1 + e^x) ~ x
    // 20.0f is a safe threshold for float32 expf overflow
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void fused_ops_kernel(const float* __restrict__ input, float* __restrict__ output, int size, float add_val, float scale) {
    // Grid-stride loop allows processing tensors of arbitrary size with a fixed grid
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < size; i += stride) {
        float x = input[i];

        // 1. Mish Activation
        x = mish_func(x);

        // 2. Add Value
        x = x + add_val;

        // 3. Hardtanh Activation (min=-1, max=1)
        if (x < -1.0f) {
            x = -1.0f;
        } else if (x > 1.0f) {
            x = 1.0f;
        }

        // 4. Scale
        x = x * scale;

        output[i] = x;
    }
}

