torch::Tensor broadcast_add_cuda(torch::Tensor x, torch::Tensor bias, int C);
"""

# Compile and load
optimized_kernels = load_inline(
    name="optimized_kernels",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_gn_min_cuda", "broadcast_add_cuda"],
