    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.num_groups = num_groups
        self.out_features = out_features

    def forward(self, x):
        # 1. GEMM (Standard PyTorch/cuBLAS is optimal)
        x = self.gemm(x)

        # 2. Fused GroupNorm + Min Reduction
        # This replaces:
        #   x = self.group_norm(x)
        #   x = torch.min(x, dim=1, keepdim=True)[0]
        x = optimized_kernels.fused_gn_min_cuda(
            x, 
            self.group_norm.weight, 
            self.group_norm.bias, 
            self.num_groups, 
            self.group_norm.eps
        )

        # 3. Fused Broadcast Addition
        # This replaces:
        #   x = x + self.bias
        # Note: self.bias has shape (1, C, 1, 1), x has shape (N, 1)
        # Result is (1, C, N, 1)
        x = optimized_kernels.broadcast_add_cuda(x, self.bias, self.out_features)

        return x

