// This assumes input dimensions are divisible by 4, which is true for 8192 features.
__global__ void fused_bias_relu_div_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const float inv_divisor,
    const int num_vectors,
    const int bias_len_vecs) 
