    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    // Reinterpret memory as float4 arrays for vectorized load/store
    const float4* in_ptr = reinterpret_cast<const float4*>(input);
    const float4* bias_ptr = reinterpret_cast<const float4*>(bias);
    float4* out_ptr = reinterpret_cast<float4*>(output);

    // Grid-stride loop
    for (int i = idx; i < num_vectors; i += stride) {
        // Load input vector
        float4 in_v = in_ptr[i];

        // Load bias vector
        // The bias is broadcasted across the batch dimension. 
        // We compute the modulo to wrap around for each row in the batch.
        int bias_idx = i % bias_len_vecs;
        float4 b_v = bias_ptr[bias_idx];

        float4 out_v;

        // Perform fused operation: output = ReLU(input + bias) * inv_divisor
        // Process component x
        float val_x = in_v.x + b_v.x;
        out_v.x = (val_x > 0.0f ? val_x : 0.0f) * inv_divisor;

        // Process component y
        float val_y = in_v.y + b_v.y;
        out_v.y = (val_y > 0.0f ? val_y : 0.0f) * inv_divisor;

        // Process component z
        float val_z = in_v.z + b_v.z;
        out_v.z = (val_z > 0.0f ? val_z : 0.0f) * inv_divisor;

        // Process component w
        float val_w = in_v.w + b_v.w;
        out_v.w = (val_w > 0.0f ? val_w : 0.0f) * inv_divisor;

        // Store result
        out_ptr[i] = out_v;
    }
