        // idx = n * (C * spatial_size) + c * spatial_size + spatial_idx

        // Integer division to find the channel index. 
        // Since spatial_size (128*128) is a power of 2, the compiler will optimize this.
        int c = (idx / spatial_size) % channels;

        output[idx] = input[idx] * scale[c] + shift[c];
