    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_bn_scale_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        shift.data_ptr<float>(),
