    functions=["fused_bn_scale_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        self.fused_ops = fused_ops

    def forward(self, x):
        # Perform standard convolution
        x = self.conv(x)

        # Fuse BatchNorm and Scaling into a single Affine Transform: y = x * A + B
        # Standard BN: y = (x - mean) / sqrt(var + eps) * gamma + beta
        # Scaling: z = y * scaling_factor

        # Combined:
        # z = [ (x - mean) / std * gamma + beta ] * scaling_factor
        # z = x * (gamma * scaling_factor / std) + (beta * scaling_factor - mean * gamma * scaling_factor / std)

        if self.bn.training:
             # Fallback for training mode if needed, though speedup usually targets inference
             # Note: For strict equivalence in training, we'd need to compute batch stats.
             # Here we assume optimization is for inference or use running stats.
             x = self.bn(x)
             x = x * self.scaling_factor
             return x

        # Prepare parameters for custom kernel
        mean = self.bn.running_mean
        var = self.bn.running_var
        gamma = self.bn.weight
        beta = self.bn.bias
        eps = self.bn.eps

        std = torch.sqrt(var + eps)

        # A = (gamma * s) / std
        # B = beta * s - mean * A

        scale_A = (gamma * self.scaling_factor) / std
        shift_B = beta * self.scaling_factor - mean * scale_A

        # Invoke custom CUDA kernel
        # Ensure scale and shift are contiguous
        return self.fused_ops.fused_bn_scale_cuda(x, scale_A.contiguous(), shift_B.contiguous())

