__global__ void fused_pool_ht_mean_tanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int height,
    int width,
    int pool_k,
    int pool_s,
    float ht_min,
    float ht_max) {

    // Calculate output dimensions of the pooling layer
    // Floor mode (default for MaxPool2d)
    int out_h = (height - pool_k) / pool_s + 1;
    int out_w = (width - pool_k) / pool_s + 1;
    int num_pooled_pixels = out_h * out_w;

    // Grid is 1D: (N * C)
    // One block per (batch, channel)
    int idx = blockIdx.x;
    if (idx >= batch_size * channels) return;

    int n = idx / channels;
    int c = idx % channels;

    // Pointer to the start of the specific channel (n, c) in input
    const float* in_ptr = input + (n * channels * height * width) + (c * height * width);

    float local_sum = 0.0f;

    // Iterate over all pixels in the pooled output map
    // Each thread takes a stride to cover the output area
    for (int p_idx = threadIdx.x; p_idx < num_pooled_pixels; p_idx += blockDim.x) {
        int ph = p_idx / out_w;
        int pw = p_idx % out_w;

        // Determine input window top-left corner
        int h_start = ph * pool_s;
        int w_start = pw * pool_s;

        float max_val = -1e37f; // Initialize with a very small number

        // MaxPool window loop (pool_k x pool_k)
        for (int i = 0; i < pool_k; ++i) {
            for (int j = 0; j < pool_k; ++j) {
                int h_in = h_start + i;
                int w_in = w_start + j;

                // Boundary check
                if (h_in < height && w_in < width) {
                    float val = in_ptr[h_in * width + w_in];
                    if (val > max_val) max_val = val;
                }
            }
        }

        // Apply Hardtanh
        if (max_val < ht_min) max_val = ht_min;
        else if (max_val > ht_max) max_val = ht_max;

        local_sum += max_val;
    }

    // Shared memory for block reduction
    __shared__ float sdata[256];

    // Initialize shared memory
    // Assumes block size is at least 256 or handled via mask, but here we fix launch at 256
    sdata[threadIdx.x] = local_sum;

    __syncthreads();

    // Block reduction (summation)
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Thread 0 computes mean and applies tanh
    if (threadIdx.x == 0) {
        float mean_val = sdata[0] / static_cast<float>(num_pooled_pixels);
        output[idx] = tanhf(mean_val);
