        int temp = idx;
        int wo = temp % w_out;
        temp /= w_out;
        int ho = temp % h_out;
        temp /= h_out;
        int ch = temp % c;
        int ni = temp / c;

        // Calculate input window starting position
        // Input shape: (N, C, H, W)
        int h_start = ho * pool_k;
        int w_start = wo * pool_k;

        // Base offset for the specific batch item and channel
        int input_offset_base = (ni * c + ch) * h_in * w_in;

        // Load the scale factor for this channel
        float s = scale[ch];

        // Initialize max value accumulator
        float max_val = -FLT_MAX;

        // Iterate over the pooling window (pool_k x pool_k)
        #pragma unroll
        for (int i = 0; i < pool_k; ++i) {
            for (int j = 0; j < pool_k; ++j) {
                int h_curr = h_start + i;
                int w_curr = w_start + j;

                // Calculate input index
                int input_idx = input_offset_base + h_curr * w_in + w_curr;

                // Load input value and apply scale
                float val = input[input_idx] * s;

                // Max reduction
                if (val > max_val) {
                    max_val = val;
                }
            }
        }

        // Apply clamp
        if (max_val < clamp_min) max_val = clamp_min;
        if (max_val > clamp_max) max_val = clamp_max;

        // Store result
        output[idx] = max_val;
    }
}

torch::Tensor fused_scale_pool_clamp_cuda(torch::Tensor input, torch::Tensor scale, int pool_k, float clamp_min, float clamp_max) {
