import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused post-processing operations.
# The original model performs a sequence of element-wise operations after the convolution:
# 1. x = x + bias
# 2. original_x = x (before adding bias, but detached?)
#    Wait, the original code is:
#    x = conv(x)
#    original_x = x.clone().detach()
#    x = x + bias
#    x = x + original_x
#    x = x * original_x
#    x = x + original_x
# 
# Let val = conv output at some index.
# original_x = val
# Step 1: x = val + bias
# Step 2: x = (val + bias) + val = 2*val + bias
# Step 3: x = (2*val + bias) * val = 2*val^2 + bias*val
# Step 4: x = (2*val^2 + bias*val) + val = 2*val^2 + (bias + 1)*val
#
# This fused kernel computes this polynomial directly, avoiding multiple memory accesses and kernel launches.

fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_post_processing_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ bias, 
    float* __restrict__ out, 
    int total_elements, 
    int spatial_size, 
    int channels) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // x tensor layout is [N, C, D, H, W]
        // bias tensor layout is [C, 1, 1, 1] (effectively just C elements linearly)

        // We need to map the linear index 'idx' to the channel index 'c'.
        // spatial_size = D * H * W
        // The index structure is: n * (C * spatial_size) + c * spatial_size + spatial_offset
        // So, (idx / spatial_size) gives (n * C + c)
        // Then, % channels gives c.

        int c = (idx / spatial_size) % channels;

        float val = x[idx];
        float b = bias[c];

        // Compute: 2*val^2 + (b + 1)*val
        out[idx] = 2.0f * val * val + (b + 1.0f) * val;
    }
}

torch::Tensor fused_post_processing_cuda(torch::Tensor x, torch::Tensor bias) {
    // Ensure inputs are on CUDA
    TORCH_CHECK(x.is_cuda, "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda, "bias must be a CUDA tensor");

    // Ensure inputs are contiguous in memory for safe pointer access
    x = x.contiguous();
    bias = bias.contiguous();

    auto out = torch::empty_like(x);

    int total_elements = x.numel();
    int C = x.size(1);
    // Spatial dimensions D * H * W
    int spatial_size = x.size(2) * x.size(3) * x.size(4);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_post_processing_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        total_elements,
        spatial_size,
        C
    );

    return out;
}
"""

fused_cpp_source = "torch::Tensor fused_post_processing_cuda(torch::Tensor x, torch::Tensor bias);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_post_processing",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_post_processing_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized ModelNew that keeps the heavy ConvTranspose3d layer (which is highly optimized in cuDNN)
    but fuses the subsequent element-wise arithmetic operations into a single custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        # Standard convolution
        x = self.conv_transpose(x)
        # Fused custom operation
        return fused_ops.fused_post_processing_cuda(x, self.bias)

