import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code
# This kernel fuses MaxPool3d (2x2x2), LogSumExp (dim=1), and ReLU into a single operation.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>
#include <cmath>

__global__ void fused_pool_lse_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch,
    int channels,
    int in_depth,
    int in_height,
    int in_width,
    int out_depth,
    int out_height,
    int out_width
) {
    // Flattened index representing (n, out_d, out_h, out_w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch * out_depth * out_height * out_width;

    if (idx >= total_elements) return;

    // Decode index into (n, od, oh, ow)
    int temp = idx;
    int ow = temp % out_width; temp /= out_width;
    int oh = temp % out_height; temp /= out_height;
    int od = temp % out_depth; temp /= out_depth;
    int n = temp;

    // Calculate starting offsets in input spatial dimensions for the pooling window (stride 2)
    int id_start = od * 2;
    int ih_start = oh * 2;
    int iw_start = ow * 2;

    // Variables for streaming LogSumExp across channels
    float running_max = -FLT_MAX;
    float running_sum = 0.0f;

    // Precompute sizes for indexing
    int hw_size = in_height * in_width;
    int spatial_size = in_depth * hw_size;

    // Pointer to the start of the current batch in input
    const float* input_ptr = input + n * (channels * spatial_size);

    // Loop over channels to perform MaxPool per channel and accumulate LogSumExp results
    for (int c = 0; c < channels; ++c) {
        float max_pool_val = -FLT_MAX;

        // Iterate over the 2x2x2 pooling window
        #pragma unroll
        for (int z = 0; z < 2; ++z) {
            #pragma unroll
            for (int y = 0; y < 2; ++y) {
                #pragma unroll
                for (int x = 0; x < 2; ++x) {
                    int id = id_start + z;
                    int ih = ih_start + y;
                    int iw = iw_start + x;

                    // Input index within the current channel block
                    int offset_in_channel = id * hw_size + ih * in_width + iw;
                    float val = input_ptr[offset_in_channel];
                    max_pool_val = fmaxf(max_pool_val, val);
                }
            }
        }

        // Streaming LogSumExp update:
        // log(sum(exp(x))) where we maintain running max (m) and sum of exp(x-m)
        if (max_pool_val > running_max) {
            running_sum = running_sum * expf(running_max - max_pool_val) + 1.0f;
            running_max = max_pool_val;
        } else {
            running_sum += expf(max_pool_val - running_max);
        }

        // Move pointer to the next channel
        input_ptr += spatial_size;
    }

    // Final LogSumExp calculation: m + log(sum)
    float res = running_max + logf(running_sum);

    // Fused ReLU activation
    res = fmaxf(0.0f, res);

    // Write output
    output[idx] = res;
}

torch::Tensor fused_forward_cuda(torch::Tensor input) {
    auto batch = input.size(0);
    auto channels = input.size(1);
    auto in_depth = input.size(2);
    auto in_height = input.size(3);
    auto in_width = input.size(4);

    // Calculate output dimensions based on MaxPool3d kernel=2, stride=2
    auto out_depth = in_depth / 2;
    auto out_height = in_height / 2;
    auto out_width = in_width / 2;

    // Output shape: (Batch, 1, out_depth, out_height, out_width) because LogSumExp reduces dim 1
    auto output = torch::empty({batch, 1, out_depth, out_height, out_width}, input.options());

    int total_elements = batch * out_depth * out_height * out_width;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_pool_lse_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, channels,
        in_depth, in_height, in_width,
        out_depth, out_height, out_width
    );

    return output;
}
"""

fused_cpp_source = "torch::Tensor fused_forward_cuda(torch::Tensor input);"

# Compile the inline CUDA code
