import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations: Scaling -> HardTanh -> GELU
# This kernel fuses three element-wise operations into a single kernel to reduce global memory traffic.
# It also utilizes float4 vectorized memory access for higher bandwidth utilization.
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int size,
    float scaling_factor,
    float ht_min,
    float ht_max
) {
    // Determine global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    // We process data in float4 vectors (4 floats per thread) to optimize memory bandwidth.
    // The input dimensions (2048 * 8192) are guaranteed to be divisible by 4.
    int vec_size = size / 4;

    // Reinterpret pointers as float4
    const float4* in_vec = reinterpret_cast<const float4*>(input);
    float4* out_vec = reinterpret_cast<float4*>(output);

    for (int i = idx; i < vec_size; i += stride) {
        float4 v = in_vec[i];
        float4 res;
        float val;

        // Constant for 1/sqrt(2)
        const float rsqrt2 = 0.707106781f;

        // --- Process Component X ---
        val = v.x * scaling_factor;                 // Scaling
        val = fminf(fmaxf(val, ht_min), ht_max);    // HardTanh
        res.x = 0.5f * val * (1.0f + erff(val * rsqrt2)); // GELU

        // --- Process Component Y ---
        val = v.y * scaling_factor;
        val = fminf(fmaxf(val, ht_min), ht_max);
        res.y = 0.5f * val * (1.0f + erff(val * rsqrt2));

        // --- Process Component Z ---
        val = v.z * scaling_factor;
        val = fminf(fmaxf(val, ht_min), ht_max);
        res.z = 0.5f * val * (1.0f + erff(val * rsqrt2));

        // --- Process Component W ---
        val = v.w * scaling_factor;
        val = fminf(fmaxf(val, ht_min), ht_max);
        res.w = 0.5f * val * (1.0f + erff(val * rsqrt2));

        out_vec[i] = res;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor input, float scaling_factor, float ht_min, float ht_max) {
    auto size = input.numel();
    auto out = torch::empty_like(input);

    const int block_size = 256;
    // Calculate number of blocks needed for vectorized size
    const int num_blocks = (size / 4 + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        scaling_factor,
        ht_min,
        ht_max
    );

    return out;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_ops_cuda(torch::Tensor input, float scaling_factor, float ht_min, float ht_max);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=False,
    extra_cuda_cflags=["--use_fast_math"], # Enable fast math for faster exp/erf approximations
)

class ModelNew(nn.Module):
    """
    Optimized Model using cuBLAS for GEMM and a custom fused CUDA kernel for post-processing.
    """
    def __init__(self, in_features, out_features, scaling_factor, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        # We rely on PyTorch's Linear (cuBLAS) for the heavy matrix multiplication
        self.gemm = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor
        self.hardtanh_min = hardtanh_min
        self.hardtanh_max = hardtanh_max
        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. GEMM (Matrix Multiplication + Bias)
        x = self.gemm(x)

        # 2. Fused Post-Processing
        # Replaces: x * scale -> HardTanh -> GELU
        # Reduces memory reads/writes by 3x compared to separate operators
        x = self.fused_ops.fused_ops_cuda(x, self.scaling_factor, self.hardtanh_min, self.hardtanh_max)

