from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused activations and bias addition
# Operations fused: ReLU -> LeakyReLU -> GELU -> Sigmoid -> Add Bias
fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_activations_bias_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int numel,
    const int channels,
    const int spatial_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < numel) {
        float val = x[idx];

        // 1. ReLU
        // x = max(0, x)
        val = fmaxf(0.0f, val);

        // 2. LeakyReLU (negative_slope=0.01)
        // Since step 1 ensures val >= 0, LeakyReLU(val) is effectively identity.
        // val = (val > 0) ? val : 0.01 * val; // Redundant check

        // 3. GELU
        // Approximation using error function: 0.5 * x * (1 + erf(x / sqrt(2)))
        // 1/sqrt(2) approx 0.70710678
        const float kAlpha = 0.7071067811865475f; 
        val = 0.5f * val * (1.0f + erff(val * kAlpha));

        // 4. Sigmoid
        // 1 / (1 + exp(-x))
        val = 1.0f / (1.0f + expf(-val));

        // 5. Add Bias
        // Input layout is (N, C, D, H, W)
        // Bias layout is (C, 1, 1, 1) -> effectively (C)
        // We broadcast bias across N, D, H, W.
        // Calculate channel index c corresponding to linear index idx.
        // idx = n*(C*S) + c*(S) + s_idx
        // idx / S = n*C + c
        // (idx / S) % C = c
        int c = (idx / spatial_size) % channels;
        val = val + bias[c];

        out[idx] = val;
    }
}

torch::Tensor fused_activations_bias_cuda(torch::Tensor x, torch::Tensor bias) {
    // Ensure inputs are contiguous for linear memory access
    auto x_contig = x.contiguous();
    auto bias_contig = bias.contiguous();

    auto out = torch::empty_like(x_contig);

    const int numel = x_contig.numel();
    const int channels = x_contig.size(1);
    // Spatial size = D * H * W
    const int spatial_size = x_contig.size(2) * x_contig.size(3) * x_contig.size(4);

    const int block_size = 256;
    const int grid_size = (numel + block_size - 1) / block_size;

    fused_activations_bias_kernel<<<grid_size, block_size>>>(
        x_contig.data_ptr<float>(),
        bias_contig.data_ptr<float>(),
        out.data_ptr<float>(),
        numel,
        channels,
        spatial_size
    );

    return out;
}
"""

