import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused operation: AvgPool -> GELU -> Scale -> Max
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_pool_gelu_scale_max_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int out_features,
    int pool_kernel_size,
    float scale_factor,
    int num_windows) {

    // Each block handles one batch row
    int bid = blockIdx.x;
    if (bid >= batch_size) return;

    int tid = threadIdx.x;

    // Pointer to the start of the row for this batch index
    // input shape: (batch_size, out_features)
    const float* row_ptr = input + (long long)bid * out_features;

    // Initialize local maximum to the smallest float
    float local_max = -FLT_MAX;

    // Each thread iterates over a subset of the pooled windows
    // Stride is blockDim.x
    for (int w = tid; w < num_windows; w += blockDim.x) {
        int start_idx = w * pool_kernel_size;

        float sum = 0.0f;
        // Compute the average for the current window
        for (int k = 0; k < pool_kernel_size; ++k) {
            sum += row_ptr[start_idx + k];
        }

        float avg = sum / (float)pool_kernel_size;

        // Apply GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        // M_SQRT1_2 is 1/sqrt(2) approx 0.70710678
        float val = avg * 0.5f * (1.0f + erff(avg * 0.7071067811865475f));

        // Apply scaling
        val *= scale_factor;

        // Update local max
        if (val > local_max) {
            local_max = val;
        }
    }

    // Perform block-wide reduction to find the maximum value in the row

    // 1. Warp-level reduction using shuffle
    unsigned int mask = 0xFFFFFFFF;
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        float other = __shfl_down_sync(mask, local_max, offset);
        if (other > local_max) local_max = other;
    }

    // 2. Store warp results in shared memory
    // 256 threads / 32 = 8 warps. 
    static __shared__ float shared_max[32]; 
    int warp_id = tid / warpSize;
    int lane_id = tid % warpSize;

    if (lane_id == 0) {
        shared_max[warp_id] = local_max;
    }

    __syncthreads();

    // 3. First warp reduces the results from shared memory
    if (warp_id == 0) {
        int num_warps = blockDim.x / warpSize;
        float val = (tid < num_warps) ? shared_max[tid] : -FLT_MAX;

        for (int offset = warpSize / 2; offset > 0; offset /= 2) {
            float other = __shfl_down_sync(mask, val, offset);
            if (other > val) val = other;
        }

        // Write the result to global memory
        if (tid == 0) {
            output[bid] = val;
        }
    }
}

torch::Tensor launch_fused_ops(torch::Tensor input, int pool_kernel_size, float scale_factor) {
    int batch_size = input.size(0);
    int out_features = input.size(1);

    // Calculate how many pooled windows fit (AvgPool1d default behavior is floor)
    int num_windows = out_features / pool_kernel_size;

    auto output = torch.empty({batch_size}, input.options());

    // Launch one block per batch item
    int threads = 256;
    int blocks = batch_size;

    fused_pool_gelu_scale_max_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features,
        pool_kernel_size,
        scale_factor,
        num_windows
    );

    return output;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor launch_fused_ops(torch::Tensor input, int pool_kernel_size, float scale_factor);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["launch_fused_ops"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model implementing the pattern "Matmul_AvgPool_GELU_Scale_Max".
    The Matmul is kept as nn.Linear (cuBLAS), while the subsequent element-wise 
    and reduction operations are fused into a single CUDA kernel.
    """
    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.pool_kernel_size = pool_kernel_size
        self.scale_factor = scale_factor
        self.fused_ops = fused_ops

    def forward(self, x):
        # Perform Matrix Multiplication
        x = self.matmul(x)
        # Apply fused AvgPool -> GELU -> Scale -> Max
        return self.fused_ops.launch_fused_ops(x, self.pool_kernel_size, self.scale_factor)

