        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. GEMM
        x = self.gemm(x)

        # 2. Fused GroupNorm + HardTanh
        # This replaces the separate GroupNorm and Hardtanh layers
        x = self.fused_ops.fused_gn_hardtanh_cuda(
            x, 
            self.gamma, 
            self.beta, 
            self.num_groups, 
            self.eps, 
            self.hardtanh_min, 
            self.hardtanh_max
        )
        return x

