import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel to fuse bias addition and all activation functions.
# Fusing these operations reduces global memory read/write traffic significantly compared
# to executing them as separate PyTorch operators.
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Device function for GELU approximation
// PyTorch often uses the Error Function based GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
__device__ __forceinline__ float gelu_func(float x) {
    const float kAlpha = 0.70710678f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * kAlpha));
}

__global__ void fused_activation_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias1,
    const float* __restrict__ bias2,
    float* __restrict__ output,
    int out_features,
    int total_elements
) {
    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate column index for broadcasting biases
        // Input is (Batch, OutFeatures), flattened.
        int col = idx % out_features;

        // 1. Add biases (Linear layer bias + Custom add_value)
        // Original: x = matmul(x) [includes bias] + add_value
        float val = input[idx] + bias1[col] + bias2[col];

        // 2. Swish (SiLU): x * sigmoid(x)
        float sig = 1.0f / (1.0f + expf(-val));
        val = val * sig;

        // 3. Tanh
        val = tanhf(val);

        // 4. GELU
        val = gelu_func(val);

        // 5. Hardtanh: clamp(x, -1, 1)
        val = fmaxf(-1.0f, fminf(1.0f, val));

        // Store result
        output[idx] = val;
    }
}

torch::Tensor fused_activations_cuda(torch::Tensor input, torch::Tensor bias1, torch::Tensor bias2) {
    // input: Result of X * W^T (Batch, OutFeatures)
    // bias1: Linear layer bias (OutFeatures)
    // bias2: Custom parameter add_value (OutFeatures)

    int batch_size = input.size(0);
    int out_features = input.size(1);
    int total_elements = batch_size * out_features;

    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_activation_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias1.data_ptr<float>(),
        bias2.data_ptr<float>(),
        output.data_ptr<float>(),
        out_features,
        total_elements
    );

    return output;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_activations_cuda(torch::Tensor input, torch::Tensor bias1, torch::Tensor bias2);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_activations_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized architecture where the sequence of element-wise operations 
    (Add Biases -> Swish -> Tanh -> GELU -> Hardtanh) is fused into a single CUDA kernel.
    The Matrix Multiplication is kept as a standard call to utilize highly optimized cuBLAS libraries,
    but we separate the bias addition to fuse it with the subsequent activations.
    """
    def __init__(self, in_features, out_features, add_value_shape):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.add_value = nn.Parameter(torch.randn(add_value_shape))
        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. Matrix Multiplication (GEMM)
        # We use F.linear with bias=None to compute X * W^T efficiently.
        # We deliberately skip adding self.matmul.bias here to avoid a separate kernel launch/memory pass.
        mm_out = F.linear(x, self.matmul.weight, bias=None)

        # 2. Fused Operations
        # Takes the GEMM output, adds the linear bias and the custom parameter,
        # and applies all activation functions in a single pass.
        x = self.fused_ops.fused_activations_cuda(mm_out, self.matmul.bias, self.add_value)

        return x

