import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernel source for fused operations: (x - sub) * mul -> ReLU
# This fuses three element-wise operations into a single kernel to reduce memory bandwidth usage.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_sub_mul_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float sub,
    float mul,
    int size) {

    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Check for 16-byte alignment to enable float4 vectorized access
    bool is_aligned = ((reinterpret_cast<uintptr_t>(input) % 16) == 0) &&
                      ((reinterpret_cast<uintptr_t>(output) % 16) == 0);

    if (is_aligned) {
        // Vectorized path using float4
        int vec_size = size / 4;
        const float4* in_vec = reinterpret_cast<const float4*>(input);
        float4* out_vec = reinterpret_cast<float4*>(output);

        // Grid-stride loop for vectors
        for (int i = idx; i < vec_size; i += stride) {
            float4 v = in_vec[i];

            // Component x
            v.x = (v.x - sub) * mul;
            v.x = fmaxf(v.x, 0.0f); // ReLU

            // Component y
            v.y = (v.y - sub) * mul;
            v.y = fmaxf(v.y, 0.0f);

            // Component z
            v.z = (v.z - sub) * mul;
            v.z = fmaxf(v.z, 0.0f);

            // Component w
            v.w = (v.w - sub) * mul;
            v.w = fmaxf(v.w, 0.0f);

            out_vec[i] = v;
        }

        // Handle remaining elements (if size is not a multiple of 4)
        int remainder_start = vec_size * 4;
        for (int i = remainder_start + idx; i < size; i += stride) {
            float v = input[i];
            v = (v - sub) * mul;
            v = fmaxf(v, 0.0f);
            output[i] = v;
        }
    } else {
        // Scalar fallback path
        for (int i = idx; i < size; i += stride) {
            float v = input[i];
            v = (v - sub) * mul;
            v = fmaxf(v, 0.0f);
            output[i] = v;
        }
    }
}

torch::Tensor fused_sub_mul_relu_cuda(torch::Tensor input, float sub, float mul) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    // Estimate blocks needed for vectorized loads (4 elements per thread)
    int num_blocks = (size + block_size * 4 - 1) / (block_size * 4);

    // Cap grid size to avoid excessive overhead, relying on grid-stride loop
    if (num_blocks > 2048) num_blocks = 2048;

    fused_sub_mul_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        sub,
        mul,
        size
    );

    return output;
}
