import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused post-processing
# Fuses: Scale -> MaxPool3d -> GlobalAvgPool -> Clamp
fused_postproc_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_postproc_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int Dp, int Hp, int Wp,
    int pool_k, int pool_s,
    float scale, float clamp_min, float clamp_max
) {
    // Each block processes one (n, c) output channel
    int nc = blockIdx.x;
    if (nc >= N * C) return;

    int c = nc % C;
    int n = nc / C;

    // Calculate offsets
    long long input_offset = (long long)n * (C * D * H * W) + (long long)c * (D * H * W);
    const float* input_ptr = input + input_offset;

    int total_pooled = Dp * Hp * Wp;
    float local_sum = 0.0f;

    // Iterate over all pooled elements using grid-stride style within the block
    for (int idx = threadIdx.x; idx < total_pooled; idx += blockDim.x) {
        int tmp = idx;
        int wp = tmp % Wp; tmp /= Wp;
        int hp = tmp % Hp; 
        int dp = tmp;

        // Determine input window top-left corner
        int d_start = dp * pool_s;
        int h_start = hp * pool_s;
        int w_start = wp * pool_s;

        float max_val = -FLT_MAX;

        // Iterate over the MaxPool window
        for (int id = 0; id < pool_k; ++id) {
            for (int ih = 0; ih < pool_k; ++ih) {
                for (int iw = 0; iw < pool_k; ++iw) {
                    int cur_d = d_start + id;
                    int cur_h = h_start + ih;
                    int cur_w = w_start + iw;

                    // Compute flat index
                    long long offset = (long long)cur_d * (H * W) + (long long)cur_h * W + cur_w;

                    // Apply scale immediately
                    float val = input_ptr[offset] * scale;

                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }
        local_sum += max_val;
    }

    // Block Reduction to sum up all pooled max values
    __shared__ float sdata[256];
    int tid = threadIdx.x;
    if (tid < 256) sdata[tid] = local_sum;
    __syncthreads();

    // Parallel reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Final calculations by thread 0
    if (tid == 0) {
        // Average
        float avg = sdata[0] / (float)total_pooled;

        // Clamp
        if (avg < clamp_min) avg = clamp_min;
        if (avg > clamp_max) avg = clamp_max;

        output[nc] = avg;
    }
}

torch::Tensor launch_fused_postproc(torch::Tensor input, int pool_k, int pool_s, float scale, float clamp_min, float clamp_max) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    // Calculate output dimensions for MaxPool3d
    int Dp = (D - pool_k) / pool_s + 1;
    int Hp = (H - pool_k) / pool_s + 1;
    int Wp = (W - pool_k) / pool_s + 1;

    auto output = torch::empty({N, C, 1, 1, 1}, input.options());

    int threads = 256;
    int blocks = N * C;

    fused_postproc_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        Dp, Hp, Wp,
        pool_k, pool_s,
        scale, clamp_min, clamp_max
    );

    return output;
}
"""

fused_postproc_cpp_source = (
    "torch::Tensor launch_fused_postproc(torch::Tensor input, int pool_k, int pool_s, float scale, float clamp_min, float clamp_max);"
)

fused_postproc = load_inline(
    name="fused_postproc",
    cpp_sources=fused_postproc_cpp_source,
    cuda_sources=fused_postproc_source,
    functions=["launch_fused_postproc"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scale, maxpool_kernel_size):
        super(ModelNew, self).__init__()
        # Keep ConvTranspose3d as is (highly optimized in cuDNN)
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.scale = scale
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = 0.0
        self.clamp_max = 1.0
        self.fused_postproc = fused_postproc

    def forward(self, x):
        # Perform convolution
        x = self.conv_transpose(x)

        # Ensure contiguous memory for custom kernel
        if not x.is_contiguous():
            x = x.contiguous()

        # Fused Scale -> MaxPool -> GlobalAvg -> Clamp
        # Stride for MaxPool is usually equal to kernel_size if not specified
        pool_stride = self.maxpool_kernel_size 

        x = self.fused_postproc.launch_fused_postproc(
            x, 
            self.maxpool_kernel_size, 
            pool_stride, 
            self.scale, 
            self.clamp_min, 
            self.clamp_max
        )
        return x

