import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Double Mish activation
# We fuse the two Mish operations into a single kernel to reduce global memory reads/writes.
# Mish(x) = x * tanh(ln(1 + e^x))
double_mish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ __forceinline__ float mish_func(float x) {
    // Softplus implementation: ln(1 + e^x)
    // Threshold of 20.0f to prevent expf overflow for large inputs.
    // For x > 20, softplus(x) approx x.
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void double_mish_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];

        // First Mish
        float val = mish_func(x);

        // Second Mish (fused)
        val = mish_func(val);

        output[idx] = val;
    }
}

torch::Tensor double_mish_cuda(torch::Tensor input) {
    // Ensure contiguous memory for simplified pointer arithmetic
    auto input_contig = input.contiguous();
    auto output = torch::empty_like(input_contig);

    int size = input_contig.numel();
    const int block_size = 256;
    // Calculate grid size
    const int num_blocks = (size + block_size - 1) / block_size;

    double_mish_kernel<<<num_blocks, block_size>>>(
        input_contig.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

double_mish_cpp_source = (
    "torch::Tensor double_mish_cuda(torch::Tensor input);"
)

# Compile the inline CUDA code
double_mish_module = load_inline(
    name="double_mish_module",
    cpp_sources=double_mish_cpp_source,
    cuda_sources=double_mish_source,
    functions=["double_mish_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

