    """
    Optimized model that replaces the sequential Mish activations 
    with a fused custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        # We keep the standard Conv2d as it is highly optimized by cuDNN
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

