import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations:
# Scale1 -> AvgPool3d -> Add Bias -> Scale2
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_pool_scale_bias_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    const float* __restrict__ scale1,
    const float* __restrict__ scale2,
    float* __restrict__ output,
    int N, int C, 
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int total_elements) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Map linear index to output coordinates (N, C, Dout, Hout, Wout)
        int w_out = idx % Wout;
        int temp = idx / Wout;
        int h_out = temp % Hout;
        temp /= Hout;
        int d_out = temp % Dout;
        temp /= Dout;
        int c = temp % C;
        int n = temp / C;

        // Calculate starting input coordinates for 2x2x2 pooling window
        // Stride is 2
        int d_in = d_out * 2;
        int h_in = h_out * 2;
        int w_in = w_out * 2;

        // Calculate input strides
        int stride_w = 1;
        int stride_h = Win;
        int stride_d = Hin * Win;
        int stride_c = Din * Hin * Win;
        int stride_n = C * Din * Hin * Win;

        // Pointer to the start of the pooling window in input
        const float* in_ptr = input + n * stride_n + c * stride_c + d_in * stride_d + h_in * stride_h + w_in;

        float sum = 0.0f;

        // Manual unroll of the 2x2x2 loop
        // z = 0
        sum += in_ptr[0];                       // (0,0,0)
        sum += in_ptr[1];                       // (0,0,1)
        sum += in_ptr[stride_h];                // (0,1,0)
        sum += in_ptr[stride_h + 1];            // (0,1,1)

        // z = 1 (offset by stride_d)
        const float* in_ptr_z1 = in_ptr + stride_d;
        sum += in_ptr_z1[0];                    // (1,0,0)
        sum += in_ptr_z1[1];                    // (1,0,1)
        sum += in_ptr_z1[stride_h];             // (1,1,0)
        sum += in_ptr_z1[stride_h + 1];         // (1,1,1)

        // Average
        float avg = sum * 0.125f;

        // Apply operations: x * scale1, then + bias, then * scale2
        // Note: scales are scalar tensors, bias is per-channel
        float val = avg * (*scale1);
        val = val + bias[c];
        val = val * (*scale2);

        output[idx] = val;
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor input, torch::Tensor bias, torch::Tensor scale1, torch::Tensor scale2) {
    int N = input.size(0);
    int C = input.size(1);
    int Din = input.size(2);
    int Hin = input.size(3);
    int Win = input.size(4);

    // Calculate output dimensions for AvgPool3d with kernel=2, stride=2
    int Dout = Din / 2;
    int Hout = Hin / 2;
    int Wout = Win / 2;

    auto options = input.options();
    auto output = torch::empty({N, C, Dout, Hout, Wout}, options);

    int total_elements = N * C * Dout * Hout * Wout;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_pool_scale_bias_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale1.data_ptr<float>(),
        scale2.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, Din, Hin, Win, Dout, Hout, Wout, total_elements
    );

    return output;
}
"""

cpp_source = "torch::Tensor fused_forward_cuda(torch::Tensor input, torch::Tensor bias, torch::Tensor scale1, torch::Tensor scale2);"

# Compile the custom operator
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model with custom CUDA kernel fusing Scaling, AvgPool, Bias Add, and Scaling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scale1, scale2, bias_shape):
        super(ModelNew, self).__init__()
        # Keep the ConvTranspose3d as a standard PyTorch module (highly optimized by cuDNN)
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)

        # Parameters
        self.scale1 = nn.Parameter(torch.tensor(scale1))
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scale2 = nn.Parameter(torch.tensor(scale2))

        # Reference to custom CUDA function
        self.fused_op = fused_ops.fused_forward_cuda

    def forward(self, x):
        # Convolution
        x = self.conv_transpose(x)

        # Fused operations: Scale1 -> AvgPool -> Bias -> Scale2
        # Custom kernel expects contiguous input
        if not x.is_contiguous():
            x = x.contiguous()

        x = self.fused_op(x, self.bias, self.scale1, self.scale2)
        return x

