        # x: (N, In), weight: (Out, In) -> t() -> (In, Out)
        gemm_out = torch.mm(x, self.gemm.weight.t())

        # 2. Custom Fused Kernel: Add Bias -> Mul Scale -> Batch Norm
        # This replaces multiple memory passes with a single pass
        return self.fused_ops.fused_forward_cuda(
            gemm_out, 
            self.gemm.bias, 
            self.scale, 
            self.bn.weight, 
            self.bn.bias, 
            self.bn.running_mean, 
            self.bn.running_var, 
            self.eps, 
            self.momentum
        )

