import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for computing spatial statistics (sum and sum of squares)
# This allows us to compute GroupNorm statistics and the final global mean without 
# materializing the large intermediate tensor output of GroupNorm.
stats_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void stats_kernel(const float* __restrict__ x, 
                             float* __restrict__ sums, 
                             float* __restrict__ sum_sqs, 
                             int spatial_size,
                             int C) {
    // blockIdx.x corresponds to channel c
    // blockIdx.y corresponds to batch n
    // Grid dimensions: (C, N, 1)

    int n = blockIdx.y;
    int c = blockIdx.x;

    // Offset to the specific channel plane
    // x is shape (N, C, Spatial)
    // Use long long for offset to prevent potential overflow for very large tensors
    long long offset = (long long)n * C * spatial_size + (long long)c * spatial_size;
    const float* input_ptr = x + offset;

    float local_sum = 0.0f;
    float local_sq_sum = 0.0f;

    // Iterate over spatial dimensions
    // We use a simple grid-stride loop, although with one block per channel,
    // the stride is just blockDim.x.
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float val = input_ptr[i];
        local_sum += val;
        local_sq_sum += val * val;
    }

    // Block reduction using shared memory
    __shared__ float s_sum[256];
    __shared__ float s_sq[256];

    // Initialize shared memory
    if (threadIdx.x < 256) {
        s_sum[threadIdx.x] = local_sum;
        s_sq[threadIdx.x] = local_sq_sum;
    }
    __syncthreads();

    // Reduction tree (assuming block size 256)
    if (threadIdx.x < 128) { s_sum[threadIdx.x] += s_sum[threadIdx.x + 128]; s_sq[threadIdx.x] += s_sq[threadIdx.x + 128]; } __syncthreads();
    if (threadIdx.x < 64)  { s_sum[threadIdx.x] += s_sum[threadIdx.x + 64];  s_sq[threadIdx.x] += s_sq[threadIdx.x + 64]; } __syncthreads();
    if (threadIdx.x < 32)  { s_sum[threadIdx.x] += s_sum[threadIdx.x + 32];  s_sq[threadIdx.x] += s_sq[threadIdx.x + 32]; } __syncthreads();

    // Warp reduction for the last 32 threads
    if (threadIdx.x < 32) {
        volatile float* v_sum = s_sum;
        volatile float* v_sq = s_sq;
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 16]; v_sq[threadIdx.x] += v_sq[threadIdx.x + 16];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 8];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 8];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 4];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 4];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 2];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 2];
        v_sum[threadIdx.x] += v_sum[threadIdx.x + 1];  v_sq[threadIdx.x] += v_sq[threadIdx.x + 1];
    }

    // Write result to global memory
    if (threadIdx.x == 0) {
        int out_idx = n * C + c;
        sums[out_idx] = s_sum[0];
        sum_sqs[out_idx] = s_sq[0];
    }
}

std::vector<torch::Tensor> compute_stats_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    x = x.contiguous(); 

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    int spatial_size = D * H * W;

    auto options = torch::TensorOptions().dtype(x.dtype()).device(x.device());
    auto sums = torch::zeros({N, C}, options);
    auto sum_sqs = torch::zeros({N, C}, options);

    const int threads = 256;
    dim3 blocks(C, N);

    stats_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        sums.data_ptr<float>(),
        sum_sqs.data_ptr<float>(),
        spatial_size,
        C
    );

    return {sums, sum_sqs};
}
"""

stats_cpp_source = "std::vector<torch::Tensor> compute_stats_cuda(torch::Tensor x);"

# Compile the inline CUDA code
stats_module = load_inline(
    name="stats_module",
    cpp_sources=stats_cpp_source,
    cuda_sources=stats_source,
    functions=["compute_stats_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D convolution, then computes the mean of the GroupNormalized output
    without fully materializing the normalized tensor.
    """
    def __init__(self, in_channels, out_channels, kernel_size, num_groups):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(num_groups, out_channels)
        self.num_groups = num_groups
        self.stats_module = stats_module

    def forward(self, x):
        # 1. 3D Convolution (Standard PyTorch/cuDNN is highly optimized)
        x = self.conv(x)

        # Shape: (Batch, Channels, D, H, W)
        N, C, D, H, W = x.shape
        spatial_size = D * H * W

        # 2. Optimized Reduction
        # We replace the sequence GroupNorm -> Mean with a fused analytical calculation.
        # This avoids writing the intermediate (N, C, D, H, W) tensor back to global memory,
        # saving significant memory bandwidth.

        # Calculate sums and squared sums per channel using CUDA kernel
        sums, sum_sqs = self.stats_module.compute_stats_cuda(x)

        # Retrieve GroupNorm Parameters
        gamma = self.group_norm.weight # Shape (C)
        beta = self.group_norm.bias    # Shape (C)
        eps = self.group_norm.eps
        G = self.num_groups
        K = C // G # Channels per group

        # 3. Compute Group Statistics in PyTorch (efficient for small tensors)
        # Reshape stats to (N, G, K) to aggregate per group
        sums_g = sums.view(N, G, K).sum(dim=2)
        sum_sqs_g = sum_sqs.view(N, G, K).sum(dim=2)

        group_elements = K * spatial_size
        mu_g = sums_g / group_elements
        # Biased variance estimate (standard for GroupNorm)
        var_g = (sum_sqs_g / group_elements) - mu_g.pow(2)

        # Numerical stability clamp
        var_g = torch.clamp(var_g, min=0.0)
        rstd_g = torch.rsqrt(var_g + eps) # Shape (N, G)

        # 4. Analytic Calculation of Final Mean
        # Formula: Mean_Final = (1/C) * Sum(Beta) + (1/(C*Spatial)) * Sum_All_Groups [ rstd_g * Sum_Channels_In_Group [ Gamma_c * (Sum_c - Spatial * Mu_g) ] ]

        # Expand group stats to channel dimension
        mu_g_expanded = mu_g.view(N, G, 1).expand(N, G, K).reshape(N, C)
        rstd_g_expanded = rstd_g.view(N, G, 1).expand(N, G, K).reshape(N, C)

        # Calculate the weighted sum term: gamma * (x - mu) * rstd
        # Sum_pixels(gamma * (x - mu) * rstd) = gamma * rstd * (Sum_pixels(x) - Spatial * mu)
        centered_sums = sums - (spatial_size * mu_g_expanded)
        weighted_sums = gamma * rstd_g_expanded * centered_sums

        # Sum over all channels (dim 1) to get numerator for the variable part
        total_weighted_sum = weighted_sums.sum(dim=1) # Shape (N)

        # Calculate final result
        mean_beta = beta.mean()
        result = mean_beta + total_weighted_sum / (C * spatial_size)

        return result

