import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Bias Add + Division + GELU
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper for GELU activation
// GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
__device__ __forceinline__ float gelu_func(float x) {
    const float kAlpha = 0.70710678f; // 1.0 / sqrt(2.0)
    return x * 0.5f * (1.0f + erff(x * kAlpha));
}

__global__ void fused_epilogue_kernel(
    float* __restrict__ in_out, 
    const float* __restrict__ bias, 
    float divisor, 
    int total_elements, 
    int width) {

    // We use float4 for vectorized memory access (128-bit loads/stores)
    // This significantly improves memory bandwidth utilization
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int num_vectors = total_elements / 4;

    if (idx < num_vectors) {
        float4* in_out_ptr = reinterpret_cast<float4*>(in_out);
        const float4* bias_ptr = reinterpret_cast<const float4*>(bias);

        float4 v = in_out_ptr[idx];

        // Calculate the correct bias index.
        // Since width (8192) is a multiple of 4, the vector grid aligns perfectly with rows.
        // 'idx' is the global vector index.
        // The column index for the start of the vector is (idx * 4) % width.
        // The bias vector index is idx % (width / 4).
        int bias_idx = idx % (width / 4);

        float4 b = bias_ptr[bias_idx];

        // Fuse operations: (input + bias) / divisor -> GELU
        v.x = gelu_func((v.x + b.x) / divisor);
        v.y = gelu_func((v.y + b.y) / divisor);
        v.z = gelu_func((v.z + b.z) / divisor);
        v.w = gelu_func((v.w + b.w) / divisor);

        in_out_ptr[idx] = v;
    }
}

torch::Tensor fused_epilogue_cuda(torch::Tensor x, torch::Tensor bias, float divisor) {
    int total_elements = x.numel();
    int width = x.size(1);

    const int block_size = 256;
    // Calculate number of float4 vectors
    int num_vectors = total_elements / 4;
    int num_blocks = (num_vectors + block_size - 1) / block_size;

    fused_epilogue_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        divisor,
        total_elements,
        width
    );

    return x;
}
"""

cpp_source = """
torch::Tensor fused_epilogue_cuda(torch::Tensor x, torch::Tensor bias, float divisor);
"""

# Compile the inline CUDA code
