    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_epilogue_cuda"],
    verbose=False,
    extra_cflags=["-O3"]
)

class ModelNew(nn.Module):
    """
    Optimized model using custom CUDA kernels.
    Performs MatMul via cuBLAS (torch.mm) and fuses Bias+Div+GELU into a single kernel.
    """
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor

    def forward(self, x):
        # 1. Matrix Multiplication
        # We use torch.mm which invokes highly optimized cuBLAS routines.
        # nn.Linear weights are stored as (out_features, in_features), so we transpose.
        # Note: We bypass the bias addition in nn.Linear (which would use addmm) 
        # to fuse it with the subsequent element-wise operations.
        x = torch.mm(x, self.linear.weight.t())

        # 2. Fused Epilogue (Bias Add + Div + GELU)
        # This kernel reduces memory I/O by performing all element-wise ops in one pass.
        # It modifies 'x' in-place.
        x = fused_ops.fused_epilogue_cuda(x, self.linear.bias, self.divisor)

        return x

