import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
# Operations: Mean Pool (dim 2) -> Add Bias -> Softmax (dim 1) -> Tanh -> Scale
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int N,
    const int C,
    const int D,
    const int H,
    const int W,
    const float scaling_factor) {

    // Each thread processes one spatial pixel (n, h, w)
    // Grid maps to flattened spatial dimensions
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_dim = H * W;
    int total_threads = N * spatial_dim;

    if (idx >= total_threads) return;

    // Decode linear index into (n, h, w)
    // idx = n * (H * W) + h * W + w
    int w = idx % W;
    int h = (idx / W) % H;
    int n = idx / spatial_dim;

    // Shared memory for storing channel values for this pixel
    // We need to store C values per thread to compute Softmax
    // Dynamic shared memory size: blockDim.x * C * sizeof(float)
    extern __shared__ float s_data[];
    float* vals = &s_data[threadIdx.x * C];

    // Calculate strides for input tensor (N, C, D, H, W)
    // Standard contiguous layout
    int stride_d = H * W;
    int stride_c = D * H * W;
    int stride_n = C * D * H * W;

    // Base offset for this (n, h, w) location
    int base_offset = n * stride_n + h * W + w;

    // --- Step 1: Mean Pooling over Depth (D) & Bias Addition ---
    for (int c = 0; c < C; ++c) {
        float sum = 0.0f;
        int current_c_offset = base_offset + c * stride_c;

        // Sum over depth dimension
        for (int d = 0; d < D; ++d) {
            sum += x[current_c_offset + d * stride_d];
        }

        // Compute mean and add bias
        // bias tensor is (1, C, 1, 1, 1), so effectively we access bias[c]
        vals[c] = (sum / static_cast<float>(D)) + bias[c];
    }

    // --- Step 2: Softmax over Channels (dim 1) ---

    // Find Max for numerical stability
    float max_val = -1e37f;
    for (int c = 0; c < C; ++c) {
        if (vals[c] > max_val) {
            max_val = vals[c];
        }
    }

    // Compute Exponentials and Sum
    float exp_sum = 0.0f;
    for (int c = 0; c < C; ++c) {
        float val = expf(vals[c] - max_val);
        vals[c] = val; // Store exp value to reuse
        exp_sum += val;
    }

    // --- Step 3: Normalize, Tanh, Scale, and Write Output ---

    float inv_sum = 1.0f / exp_sum;

    // Output stride for Channel dimension in (N, C, 1, H, W)
    // Squeezing dim 2 means effectively (N, C, H, W) layout
    int out_stride_c = H * W;
    int out_base_offset = n * (C * out_stride_c) + h * W + w;

    for (int c = 0; c < C; ++c) {
        float softmax_val = vals[c] * inv_sum;
        float res = tanhf(softmax_val) * scaling_factor;
        out[out_base_offset + c * out_stride_c] = res;
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor) {
    // Check inputs
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    // Get dimensions
    auto N = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    // Allocate output tensor (N, C, 1, H, W)
    auto out = torch::empty({N, C, 1, H, W}, x.options());

    // Kernel Launch Configuration
    const int block_size = 128;
    int total_pixels = N * H * W;
    int grid_size = (total_pixels + block_size - 1) / block_size;

    // Shared memory required: C floats per thread in the block
    int shared_mem_size = block_size * C * sizeof(float);

    fused_ops_kernel<<<grid_size, block_size, shared_mem_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        scaling_factor
    );

    return out;
}
"""

fused_ops_cpp_source = """
torch::Tensor fused_forward_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=['fused_forward_cuda'],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scaling_factor):
        super(ModelNew, self).__init__()
        # Keep the ConvTranspose3d as is, it's highly optimized in cuDNN
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.bias = nn.Parameter(torch.randn(1, out_channels, 1, 1, 1))
        self.scaling_factor = scaling_factor

    def forward(self, x):
        # 1. Transposed Convolution
        x = self.conv_transpose(x)

        # 2. Fused Custom Kernel
        # Replaces: Mean Pool -> Bias Add -> Softmax -> Tanh -> Scaling
        if not x.is_contiguous():
            x = x.contiguous()

        return fused_ops.fused_forward_cuda(x, self.bias, self.scaling_factor)

