import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA source code for fused operations
fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ __forceinline__ float swish_func(float x) {
    return x * (1.0f / (1.0f + expf(-x)));
}

__device__ __forceinline__ float hardswish_func(float x) {
    return x * fminf(fmaxf(x + 3.0f, 0.0f), 6.0f) * 0.166666667f;
}

__global__ void reduce_kernel(
    const float* __restrict__ input,
    float* __restrict__ mean_var,
    int N, int C, int S, int G, int C_per_G) {

    // Grid: (N, G)
    int n = blockIdx.x;
    int g = blockIdx.y;

    // Calculate elements to reduce: C_per_G channels * S spatial pixels
    int count = C_per_G * S;

    float sum = 0.0f;
    float sq_sum = 0.0f;

    int stride = blockDim.x;
    int tid = threadIdx.x;

    // Base offset for this instance n
    // Input is N, C, S
    int input_base_n = n * C * S;

    // Iterate over the chunk for this group
    for (int i = tid; i < count; i += stride) {
        // Map linear index i to (c_rel, s)
        int c_rel = i / S;
        int s = i % S;

        int c = g * C_per_G + c_rel;
        int idx = input_base_n + c * S + s;

        float val = input[idx];
        // Apply Swish on the fly
        val = swish_func(val);

        sum += val;
        sq_sum += val * val;
    }

    // Block Reduction in Shared Memory
    __shared__ float s_sum[256];
    __shared__ float s_sq[256];

    // Initialize shared memory with thread local sums
    s_sum[tid] = sum;
    s_sq[tid] = sq_sum;
    __syncthreads();

    // Tree reduction
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            s_sum[tid] += s_sum[tid + offset];
            s_sq[tid] += s_sq[tid + offset];
        }
        __syncthreads();
    }

    // Write result to global memory
    if (tid == 0) {
        float mu = s_sum[0] / count;
        // Biased variance to match PyTorch GroupNorm default behavior
        float var = (s_sq[0] / count) - (mu * mu);

        int out_idx = n * G * 2 + g * 2;
        mean_var[out_idx] = mu;
        mean_var[out_idx + 1] = var;
    }
}

__global__ void apply_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean_var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    int N, int C, int S, int G, int C_per_G, float eps) {

    // Grid: (C, N)
    int c = blockIdx.x;
    int n = blockIdx.y;
    int g = c / C_per_G;

    // Load Group statistics
    int stats_idx = n * G * 2 + g * 2;
    float mu = mean_var[stats_idx];
    float var = mean_var[stats_idx + 1];
    float inv_std = rsqrtf(var + eps);

    // Load Channel parameters
    float g_val = gamma[c];
    float b_val = beta[c];

    // Base offset for this channel/instance
    int base_idx = n * C * S + c * S;

    int stride = blockDim.x;
    int tid = threadIdx.x;

    // Iterate over spatial dimensions
    for (int s = tid; s < S; s += stride) {
        int idx = base_idx + s;
        float val = input[idx];

        // 1. Swish
        val = swish_func(val);

        // 2. Group Norm
        val = (val - mu) * inv_std;
        val = val * g_val + b_val;

        // 3. HardSwish
        val = hardswish_func(val);

        output[idx] = val;
    }
}

torch::Tensor fused_swish_gn_hardswish_cuda(
    torch::Tensor input, 
    torch::Tensor gamma, 
    torch::Tensor beta, 
    int groups, 
