    int N = input.size(0);
    int C = input.size(1);
    // Flatten spatial dims
    int S = input.size(2) * input.size(3) * input.size(4);

    int C_per_G = C / groups;

    auto mean_var = torch::empty({N, groups, 2}, input.options());
    auto output = torch::empty_like(input);

    const int block_size = 256;

    // Pass 1: Reduction (Compute Mean and Variance of Swish(X))
    dim3 reduce_grid(N, groups);
    reduce_kernel<<<reduce_grid, block_size>>>(
        input.data_ptr<float>(),
        mean_var.data_ptr<float>(),
        N, C, S, groups, C_per_G
    );

    // Pass 2: Apply (Swish -> Normalize -> Affine -> HardSwish)
    dim3 apply_grid(C, N);
    apply_kernel<<<apply_grid, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        mean_var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        N, C, S, groups, C_per_G, eps
    );

    return output;
}
