import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels
# 1. custom_relu_cuda: A simple element-wise ReLU kernel.
# 2. fused_relu_concat_cuda: A kernel that fuses the ReLU activation and concatenation 
#    of two tensors along the channel dimension (dim=1).
#    This reduces memory bandwidth by performing the copy and activation in a single pass.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Simple element-wise ReLU kernel
__global__ void relu_kernel(const float* __restrict__ inp, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = inp[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor custom_relu_cuda(torch::Tensor inp) {
    auto out = torch::empty_like(inp);
    int size = inp.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(inp.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}

// Fused ReLU + Concatenation Kernel
// Inputs: a (N, C1, H, W), b (N, C2, H, W)
// Output: out (N, C1+C2, H, W)
// Logic: Flattens the batch dimension to the grid Y dimension. 
//        Flattens the (C, H, W) dimensions to the grid X dimension/threads.
//        This works efficiently for NCHW layout where C, H, W are contiguous for a given N.
__global__ void fused_relu_concat_kernel(
    const float* __restrict__ a, 
    const float* __restrict__ b, 
    float* __restrict__ out, 
    int size_a_batch, 
    int size_b_batch,
    int total_size_per_batch) 
{
    // n corresponds to the batch index (0 to N-1)
    int n = blockIdx.y;

    // rem corresponds to the linear index within one batch item (0 to (C1+C2)*H*W - 1)
    int rem = blockIdx.x * blockDim.x + threadIdx.x;

    if (rem < total_size_per_batch) {
        float val;

        // Determine which input tensor (a or b) the current thread should read from.
        // Since we are concatenating on dim 1 (Channels), and the layout is NCHW,
        // the memory for 'a' comes first, followed by 'b' for each batch item.
        if (rem < size_a_batch) {
            // Read from tensor a
            val = a[n * size_a_batch + rem];
        } else {
            // Read from tensor b. Adjust index by subtracting size of a's part.
            val = b[n * size_b_batch + (rem - size_a_batch)];
        }

        // Apply ReLU activation directly during the copy/concat operation
        float res = val > 0.0f ? val : 0.0f;

        // Write to output tensor
        int out_idx = n * total_size_per_batch + rem;
        out[out_idx] = res;
    }
}

torch::Tensor fused_relu_concat_cuda(torch::Tensor a, torch::Tensor b) {
    // Check inputs
    int N = a.size(0);
    int C1 = a.size(1);
    int H = a.size(2);
    int W = a.size(3);
    int C2 = b.size(1);

    // Allocate output tensor
    auto out = torch::empty({N, C1 + C2, H, W}, a.options());

    // Calculate strides/sizes for flattened access within a batch
    int size_a_batch = C1 * H * W;
    int size_b_batch = C2 * H * W;
    int total_size_per_batch = size_a_batch + size_b_batch;

    const int block_size = 256;
    // Launch enough blocks in X direction to cover one full image (C_total * H * W)
    const int num_blocks_x = (total_size_per_batch + block_size - 1) / block_size;
    // Launch N blocks in Y direction to cover the batch size
    const int num_blocks_y = N;

    dim3 grid(num_blocks_x, num_blocks_y);
    dim3 block(block_size);

    fused_relu_concat_kernel<<<grid, block>>>(
        a.data_ptr<float>(), 
        b.data_ptr<float>(), 
        out.data_ptr<float>(), 
        size_a_batch, 
        size_b_batch, 
        total_size_per_batch
    );

    return out;
}
"""

cpp_source = """
torch::Tensor custom_relu_cuda(torch::Tensor inp);
torch::Tensor fused_relu_concat_cuda(torch::Tensor a, torch::Tensor b);
"""

# Compile and load the inline CUDA extensions
custom_ops = load_inline(
    name="custom_fire_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["custom_relu_cuda", "fused_relu_concat_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, squeeze_channels, expand1x1_channels, expand3x3_channels):
        """
        Optimized Model using custom CUDA kernels.
        """
        super(ModelNew, self).__init__()

        # Standard Convolution for squeeze layer
        self.squeeze = nn.Conv2d(in_channels, squeeze_channels, kernel_size=1)

        # Standard Convolutions for expand layers
        # Note: We remove the nn.ReLU modules here because we will use custom kernels
        self.expand1x1 = nn.Conv2d(squeeze_channels, expand1x1_channels, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_channels, expand3x3_channels, kernel_size=3, padding=1)

        self.ops = custom_ops

    def forward(self, x):
        # 1. Squeeze Convolution
        x = self.squeeze(x)

        # 2. Custom ReLU Kernel
        x = self.ops.custom_relu_cuda(x)

        # 3. Compute Expand Convolutions (Linear parts)
        # We compute these separately as standard convolutions are highly optimized
        out1 = self.expand1x1(x)
        out2 = self.expand3x3(x)

        # 4. Custom Fused Kernel: ReLU Activation + Concatenation
        # This replaces: ReLU(out1) + ReLU(out2) + torch.cat([out1, out2])
        return self.ops.fused_relu_concat_cuda(out1, out2)

