import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_relu_maxpool_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                          int batch, int channels, int height, int width) {
    int out_h = height / 2;
    int out_w = width / 2;
    int total_elements = batch * channels * out_h * out_w;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Map linear index to (n, c, h_out, w_out)
        // Layout is NCHW
        int w_out = idx % out_w;
        int temp = idx / out_w;
        int h_out = temp % out_h;
        temp /= out_h;
        int c = temp % channels;
        int n = temp / channels;

        // Calculate input offsets
        int h_in = h_out * 2;
        int w_in = w_out * 2;

        // Input strides
        int stride_w = 1;
        int stride_h = width;
        int stride_c = height * width;
        int stride_n = channels * height * width;

        int base_idx = n * stride_n + c * stride_c + h_in * stride_h + w_in;

        // Load 2x2 block
        // Assuming contiguous memory and valid bounds given 2x2 pooling and input sizes
        float v00 = input[base_idx];
        float v01 = input[base_idx + 1];
        float v10 = input[base_idx + stride_h];
        float v11 = input[base_idx + stride_h + 1];

        // Apply ReLU
        v00 = fmaxf(v00, 0.0f);
        v01 = fmaxf(v01, 0.0f);
        v10 = fmaxf(v10, 0.0f);
        v11 = fmaxf(v11, 0.0f);

        // Apply MaxPool
        float max_val = fmaxf(fmaxf(v00, v01), fmaxf(v10, v11));

        output[idx] = max_val;
    }
}

__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = fmaxf(input[idx], 0.0f);
    }
}

torch::Tensor fused_relu_maxpool_cuda(torch::Tensor input) {
    auto batch = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto out_h = height / 2;
    auto out_w = width / 2;

    auto output = torch::empty({batch, channels, out_h, out_w}, input.options());

    int total_elements = batch * channels * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_relu_maxpool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, channels, height, width
    );

    return output;
}

torch::Tensor relu_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

cpp_source = """
