import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// ----------------------------------------------------------------------------
// Custom ReLU Kernel
// ----------------------------------------------------------------------------
__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = fmaxf(input[idx], 0.0f);
    }
}

torch::Tensor custom_relu_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

// ----------------------------------------------------------------------------
// Custom Global Average Pooling (GAP) Kernel
// Performs Mean Pooling over H and W dimensions: (N, C, H, W) -> (N, C)
// ----------------------------------------------------------------------------
__global__ void gap_kernel(const float* __restrict__ x, float* __restrict__ out, int N, int C, int H, int W) {
    // We launch a grid where x-dimension is N and y-dimension is C.
    // Each block handles one (n, c) channel plane.
    int n = blockIdx.x;
    int c = blockIdx.y;
    int tid = threadIdx.x;

    // Calculate offset for the specific channel
    int offset = n * (C * H * W) + c * (H * W);
    int spatial_size = H * W;

    // Load and sum elements for this channel
    float sum = 0.0f;
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        sum += x[offset + i];
    }

    // Shared memory for block reduction
    extern __shared__ float sdata[];
    sdata[tid] = sum;
    __syncthreads();

    // Parallel reduction in shared memory (assumes blockDim.x is power of 2, e.g., 256)
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write result to global memory
    if (tid == 0) {
        out[n * C + c] = sdata[0] / (float)spatial_size;
    }
}

torch::Tensor custom_gap_cuda(torch::Tensor x) {
    // Ensure input is contiguous for pointer arithmetic
    x = x.contiguous();

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto out = torch::empty({N, C}, x.options());

    dim3 grid(N, C);
    int threads = 256;
    int shared_mem_size = threads * sizeof(float);

    gap_kernel<<<grid, threads, shared_mem_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), N, C, H, W);

    return out;
}
"""

cpp_source = """
torch::Tensor custom_relu_cuda(torch::Tensor input);
torch::Tensor custom_gap_cuda(torch::Tensor x);
"""

# Compile the inline CUDA code
custom_ops = load_inline(
    name="custom_ops_regnet",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["custom_relu_cuda", "custom_gap_cuda"],
    verbose=False,
)

class CustomReLU(nn.Module):
    """ Wrapper for the custom CUDA ReLU kernel """
    def __init__(self):
        super(CustomReLU, self).__init__()

    def forward(self, x):
        return custom_ops.custom_relu_cuda(x)

class ModelNew(nn.Module):
    def __init__(self, input_channels, stages, block_widths, output_classes):
        """
        :param input_channels: int, Number of input channels for the first layer
        :param stages: int, Number of stages in the RegNet architecture
        :param block_widths: List[int], Width (number of channels) for each block in the stages
        :param output_classes: int, Number of output classes for classification
        """
        super(ModelNew, self).__init__()

        self.stages = stages
        self.block_widths = block_widths

        layers = []
        current_channels = input_channels

        # Construct the stages with their respective blocks
        for i in range(stages):
            layers.append(self._make_stage(current_channels, block_widths[i]))
            current_channels = block_widths[i]

        self.feature_extractor = nn.Sequential(*layers)

        # Final fully connected layer for classification
        self.fc = nn.Linear(block_widths[-1], output_classes)

    def _make_stage(self, in_channels, out_channels):
        """
        Creates a simple block for each stage, replacing nn.ReLU with CustomReLU.
        """
        return nn.Sequential(
            nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            CustomReLU(),
            nn.Conv2d(out_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            CustomReLU(),
            nn.MaxPool2d(kernel_size=2, stride=2)
        )

    def forward(self, x):
        """
        Forward pass through the RegNet model using custom CUDA kernels.
        """
        x = self.feature_extractor(x)
        # Replaced standard torch.mean(x, dim=[2, 3]) with custom CUDA GAP kernel
        x = custom_ops.custom_gap_cuda(x)
        x = self.fc(x)
        return x

