import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel for the LSTM cell element-wise operations
# This kernel fuses the gate activation functions and the state update logic
lstm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

template <typename scalar_t>
__global__ void lstm_cell_kernel(
    const scalar_t* __restrict__ igates,
    const scalar_t* __restrict__ hgates,
    const scalar_t* __restrict__ c_prev,
    scalar_t* __restrict__ h_next,
    scalar_t* __restrict__ c_next,
    int hidden_size,
    int batch_size) {

    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        // Determine batch index and hidden unit index
        int b = idx / hidden_size;
        int h = idx % hidden_size;

        // The gates are stored in chunks of hidden_size
        // Layout: i (input), f (forget), g (cell), o (output)
        // Stride for the gate tensors is 4 * hidden_size
        int row_start = b * 4 * hidden_size;

        // Calculate pre-activation values
        // igates and hgates already include biases (added in Python via F.linear)
        scalar_t in_gate_in = igates[row_start + h] + hgates[row_start + h];
        scalar_t forget_gate_in = igates[row_start + h + hidden_size] + hgates[row_start + h + hidden_size];
        scalar_t cell_gate_in = igates[row_start + h + 2 * hidden_size] + hgates[row_start + h + 2 * hidden_size];
        scalar_t out_gate_in = igates[row_start + h + 3 * hidden_size] + hgates[row_start + h + 3 * hidden_size];

        // Apply activation functions
        scalar_t in_gate = 1.0 / (1.0 + exp(-in_gate_in));         // sigmoid
        scalar_t forget_gate = 1.0 / (1.0 + exp(-forget_gate_in)); // sigmoid
        scalar_t cell_gate = tanh(cell_gate_in);                   // tanh
        scalar_t out_gate = 1.0 / (1.0 + exp(-out_gate_in));       // sigmoid

        // Update cell state and hidden state
        scalar_t c_val = forget_gate * c_prev[idx] + in_gate * cell_gate;
        scalar_t h_val = out_gate * tanh(c_val);

        // Write back results
        c_next[idx] = c_val;
        h_next[idx] = h_val;
    }
}

// C++ wrapper for the CUDA kernel
std::vector<torch::Tensor> lstm_cell_cuda(
    torch::Tensor igates,
    torch::Tensor hgates,
    torch::Tensor c_prev) {

    auto batch_size = c_prev.size(0);
    auto hidden_size = c_prev.size(1);

    auto h_next = torch::empty_like(c_prev);
    auto c_next = torch::empty_like(c_prev);

    const int block_size = 256;
    const int num_blocks = (batch_size * hidden_size + block_size - 1) / block_size;

    AT_DISPATCH_FLOATING_TYPES(c_prev.scalar_type(), "lstm_cell_cuda", ([&] {
        lstm_cell_kernel<scalar_t><<<num_blocks, block_size>>>(
            igates.data_ptr<scalar_t>(),
            hgates.data_ptr<scalar_t>(),
            c_prev.data_ptr<scalar_t>(),
            h_next.data_ptr<scalar_t>(),
            c_next.data_ptr<scalar_t>(),
            hidden_size,
            batch_size);
    }));

    return {h_next, c_next};
}
"""

lstm_cpp_source = "std::vector<torch::Tensor> lstm_cell_cuda(torch::Tensor igates, torch::Tensor hgates, torch::Tensor c_prev);"

# Compile and load the inline CUDA extension
lstm_ops = load_inline(
    name="lstm_ops",
    cpp_sources=lstm_cpp_source,
    cuda_sources=lstm_source,
    functions=["lstm_cell_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        """
        Initialize the optimized LSTM model.
        """
        super(ModelNew, self).__init__()
        # We instantiate nn.LSTM to easily manage parameters (weights/biases) in the standard format
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True, dropout=dropout, bidirectional=False)
        self.fc = nn.Linear(hidden_size, output_size)
        self.num_layers = num_layers
        self.dropout = dropout

    def forward(self, x, h0, c0):
        """
        Forward pass using custom CUDA kernels for the LSTM cell recurrence.
        """
        batch_size, seq_len, _ = x.size()

        # 'layer_input' will be updated as we pass through layers
        layer_input = x

        # List to store final cell states (c_n) for each layer
        final_c_states = []

        for i in range(self.num_layers):
            # Access weights and biases from the standard nn.LSTM module
            w_ih = getattr(self.lstm, f'weight_ih_l{i}')
            w_hh = getattr(self.lstm, f'weight_hh_l{i}')
            b_ih = getattr(self.lstm, f'bias_ih_l{i}')
            b_hh = getattr(self.lstm, f'bias_hh_l{i}')

            # Initial states for the current layer
            h_prev = h0[i]
            c_prev = c0[i]

            # Optimization: Pre-compute the input projection for all time steps at once
            # igates_seq shape: (batch_size, seq_len, 4 * hidden_size)
            igates_seq = F.linear(layer_input, w_ih, b_ih)

            layer_outputs = []

            # Sequential loop over time steps
            for t in range(seq_len):
                # Compute hidden projection: (batch_size, 4 * hidden_size)
                # We use F.linear for matrix multiplication as it's highly optimized (cuBLAS)
                hgates = F.linear(h_prev, w_hh, b_hh)

                # Use custom CUDA kernel for the element-wise LSTM cell update
                # This fuses the addition, sigmoids, tanhs, and state updates
                state = lstm_ops.lstm_cell_cuda(igates_seq[:, t, :], hgates, c_prev)

                h_prev = state[0]
                c_prev = state[1]

                layer_outputs.append(h_prev)

            # Stack outputs for the next layer
            layer_output_tensor = torch.stack(layer_outputs, dim=1)

            # Apply dropout if applicable (except for the last layer)
            if self.dropout > 0 and i < self.num_layers - 1:
                layer_output_tensor = F.dropout(layer_output_tensor, p=self.dropout, training=self.training)

            layer_input = layer_output_tensor
            final_c_states.append(c_prev)

        # The original model computes the FC layer on the last time step but discards it for return.
        # We execute it to preserve computational equivalence (e.g. for gradients/hooks).
        _ = self.fc(layer_input[:, -1, :])

        # Return the final cell states, stacked to shape (num_layers, batch_size, hidden_size)
        return torch.stack(final_c_states, dim=0)

