import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the GRU cell fusion
gru_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__device__ inline float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ inline float tanh_f(float x) {
    return tanhf(x);
}

__global__ void gru_cell_fused_kernel(
    const float* __restrict__ x_gates, // [batch, 3*hidden] (Precomputed input projections)
    const float* __restrict__ h_gates, // [batch, 3*hidden] (Computed recurrent projections)
    const float* __restrict__ h_prev,  // [batch, hidden]
    float* __restrict__ h_next,        // [batch, hidden]
    int hidden_size,
    int batch_size) 
{
    int b = blockIdx.x; 
    // Each block handles one batch element
    // Loop ensures we cover all hidden units if hidden_size > blockDim.x
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        if (b >= batch_size) return;

        // Offsets
        int gate_idx_base = b * 3 * hidden_size + i;
        int h_idx = b * hidden_size + i;

        // Load pre-computed gates
        // x_gates contains: W_ix @ x + b_ix
        // h_gates contains: W_hx @ h_prev + b_hx

        // Chunk 0: Reset gate (r)
        float xr = x_gates[gate_idx_base];
        float hr = h_gates[gate_idx_base];

        // Chunk 1: Update gate (z)
        float xz = x_gates[gate_idx_base + hidden_size];
        float hz = h_gates[gate_idx_base + hidden_size];

        // Chunk 2: New gate (n)
        float xn = x_gates[gate_idx_base + 2 * hidden_size];
        float hn = h_gates[gate_idx_base + 2 * hidden_size];

        float hp = h_prev[h_idx];

        // Apply activations
        // r = sigmoid(xr + hr)
        float r = sigmoid(xr + hr);

        // z = sigmoid(xz + hz)
        float z = sigmoid(xz + hz);

        // n = tanh(xn + r * hn)
        // Note: r scales the recurrent part of the n computation
        float n = tanh_f(xn + r * hn);

        // h_new = (1 - z) * n + z * h_prev
        float h_new = (1.0f - z) * n + z * hp;

        h_next[h_idx] = h_new;
    }
}

std::vector<torch::Tensor> gru_scan_cuda(
    torch::Tensor input_proj,
    torch::Tensor h0,
    torch::Tensor w_hh,
    torch::Tensor b_hh) 
{
    // input_proj: [seq_len, batch, 3*hidden]
    // h0: [batch, hidden]
    // w_hh: [3*hidden, hidden] (PyTorch Linear weights format)
    // b_hh: [3*hidden]

    auto seq_len = input_proj.size(0);
    auto batch_size = input_proj.size(1);
    auto hidden_size = h0.size(1);

    auto output = torch::zeros({seq_len, batch_size, hidden_size}, h0.options());
    auto current_h = h0.clone();

    // Launch configuration
    int threads = 256;
    if (hidden_size < 256) threads = hidden_size;
    dim3 block_dim(threads);
    dim3 grid_dim(batch_size);

    for (int t = 0; t < seq_len; ++t) {
        // Compute Recurrent Projections
        // h_gates = current_h @ w_hh.T + b_hh
        // We use addmm: beta*input + alpha*(mat1 @ mat2)
        // input=b_hh, mat1=current_h, mat2=w_hh.t()
        auto h_gates = torch::addmm(b_hh, current_h, w_hh.t());

        auto x_gates_t = input_proj[t]; // View of [batch, 3*hidden]
        auto h_next = torch::empty_like(current_h);

        gru_cell_fused_kernel<<<grid_dim, block_dim>>>(
            x_gates_t.data_ptr<float>(),
            h_gates.data_ptr<float>(),
            current_h.data_ptr<float>(),
            h_next.data_ptr<float>(),
            hidden_size,
            batch_size
        );

        current_h = h_next;
        output[t] = h_next;
    }

    return {output, current_h};
}
"""

gru_cpp_source = "std::vector<torch::Tensor> gru_scan_cuda(torch::Tensor input_proj, torch::Tensor h0, torch::Tensor w_hh, torch::Tensor b_hh);"

gru_cuda_module = load_inline(
    name="gru_cuda_fused",
    cpp_sources=gru_cpp_source,
    cuda_sources=gru_source,
    functions=["gru_scan_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.bias = bias
        self.batch_first = batch_first

        # We manually maintain parameters to replicate nn.GRU behavior
        self.weights_ih = nn.ParameterList()
        self.weights_hh = nn.ParameterList()
        self.biases_ih = nn.ParameterList()
        self.biases_hh = nn.ParameterList()

        for i in range(num_layers):
            in_s = input_size if i == 0 else hidden_size

            # GRU weights are (3*hidden, input_dim)
            self.weights_ih.append(nn.Parameter(torch.Tensor(3 * hidden_size, in_s)))
            self.weights_hh.append(nn.Parameter(torch.Tensor(3 * hidden_size, hidden_size)))

            if bias:
                self.biases_ih.append(nn.Parameter(torch.Tensor(3 * hidden_size)))
                self.biases_hh.append(nn.Parameter(torch.Tensor(3 * hidden_size)))
            else:
                # Use fixed zeros if bias is False, registered as buffers or just created on fly
                # To keep it simple and compatible with optimizer, we create non-trainable tensors or just zeros
                # Here we use parameters initialized to zero but require_grad=False could be set if needed
                # However, standard nn.GRU doesn't have these params if bias=False. 
                # To simplify forward pass logic, we store zeros.
                self.biases_ih.append(nn.Parameter(torch.zeros(3 * hidden_size), requires_grad=False))
                self.biases_hh.append(nn.Parameter(torch.zeros(3 * hidden_size), requires_grad=False))

        self.reset_parameters()

    def reset_parameters(self):
        for i in range(self.num_layers):
            # Using standard initialization
            nn.init.xavier_uniform_(self.weights_ih[i])
            nn.init.orthogonal_(self.weights_hh[i])
            if self.bias:
                nn.init.zeros_(self.biases_ih[i])
                nn.init.zeros_(self.biases_hh[i])

    def forward(self, x, h0):
        # Handle batch_first
        if self.batch_first:
            x = x.transpose(0, 1) # Convert to (seq, batch, feature)

        seq_len, batch_size, _ = x.size()

        output = x
        h_n_list = []

        for i in range(self.num_layers):
            h_prev = h0[i] # (batch, hidden)

            w_ih = self.weights_ih[i]
            w_hh = self.weights_hh[i]
            b_ih = self.biases_ih[i]
            b_hh = self.biases_hh[i]

            # 1. Pre-compute Input Projections for the entire sequence (MatMul)
            # F.linear(input, weight, bias) -> input @ weight.T + bias
            # x_gates shape: (seq, batch, 3*hidden)
            x_gates = F.linear(output, w_ih, b_ih)

            # 2. Run Custom CUDA Recurrent Loop
            # Returns output (seq, batch, hidden) and last hidden state
            output, h_last = gru_cuda_module.gru_scan_cuda(x_gates, h_prev, w_hh, b_hh)

            h_n_list.append(h_last)

        if self.batch_first:
            output = output.transpose(0, 1)

        return output

