import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the RNN recurrence
rnn_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void rnn_scan_kernel(
    const float* __restrict__ x_proj,
    const float* __restrict__ h0,
    const float* __restrict__ W_hh_t,
    float* __restrict__ h_out,
    int seq_len,
    int batch_size,
    int hidden_size) {

    // Allocate shared memory for the hidden state of the current timestep
    extern __shared__ float h_shared[];

    int b = blockIdx.x;
    int tid = threadIdx.x;

    // Boundary check
    if (b >= batch_size || tid >= hidden_size) return;

    // Load initial hidden state
    float current_h = h0[b * hidden_size + tid];

    int batch_offset = b * hidden_size;
    int input_stride = batch_size * hidden_size;

    for (int t = 0; t < seq_len; ++t) {
        // Load current hidden state to shared memory for fast broadcast access
        h_shared[tid] = current_h;
        __syncthreads();

        // Compute recurrence: h_prev @ W_hh^T
        // We compute the dot product of the previous hidden state (h_shared) 
        // and the corresponding column of the transposed weight matrix.
        // W_hh_t is passed as W_hh.t().contiguous(), so it is effectively column-major relative to W_hh.
        // Memory access pattern: W_hh_t[k * hidden_size + tid]
        // Since 'tid' varies fast (across threads) and 'k' varies slow (loop), 
        // threads in a warp access contiguous memory addresses (coalesced read).

        float acc = 0.0f;
        for (int k = 0; k < hidden_size; ++k) {
            acc += h_shared[k] * W_hh_t[k * hidden_size + tid];
        }

        // Add pre-computed input projection and bias (included in x_proj)
        // x_proj flat index: t * (B*H) + b*H + tid
        int flat_idx = t * input_stride + batch_offset + tid;

        float val = x_proj[flat_idx] + acc;

        // Apply Activation (Tanh)
        current_h = tanhf(val);

        // Write to global memory output
        h_out[flat_idx] = current_h;

        // Synchronization to ensure all threads have finished reading h_shared 
        // before it is overwritten in the next iteration.
        __syncthreads();
    }
}

torch::Tensor rnn_cuda_forward(
    torch::Tensor x_proj,
    torch::Tensor h0,
    torch::Tensor W_hh_t) {

    auto seq_len = x_proj.size(0);
    auto batch_size = x_proj.size(1);
    auto hidden_size = x_proj.size(2);

    auto h_out = torch::zeros_like(x_proj);

    // One block per batch sample, one thread per hidden unit.
    // This assumes hidden_size <= 1024 (max threads per block).
    const int threads = hidden_size; 
    const int blocks = batch_size;
    const int shared_mem = hidden_size * sizeof(float);

    rnn_scan_kernel<<<blocks, threads, shared_mem>>>(
        x_proj.data_ptr<float>(),
        h0.data_ptr<float>(),
        W_hh_t.data_ptr<float>(),
        h_out.data_ptr<float>(),
        seq_len,
        batch_size,
        hidden_size
    );

    return h_out;
}
"""

rnn_cpp_source = "torch::Tensor rnn_cuda_forward(torch::Tensor x_proj, torch::Tensor h0, torch::Tensor W_hh_t);"

# Compile the inline CUDA code
rnn_cuda_module = load_inline(
    name="rnn_cuda_module",
    cpp_sources=rnn_cpp_source,
    cuda_sources=rnn_cuda_source,
    functions=["rnn_cuda_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        """
        Initialize the Optimized RNN model.
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size

        # We keep the same parameter structure as the original model
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        self.h2o = nn.Linear(hidden_size, output_size)

        self.rnn_cuda = rnn_cuda_module

    def forward(self, x: torch.Tensor, h0: torch.Tensor) -> torch.Tensor:
        """
        Forward pass using custom CUDA kernel for the recurrent loop.
        """
        # Ensure inputs are on the correct device
        if x.device.type != 'cuda':
            x = x.cuda()
        h0 = h0.to(x.device)

        # 1. Pre-compute Input Projections
        # The original operation is Linear(cat(x, h)). This is equivalent to: x@W_x.T + h@W_h.T + bias.
        # We can compute x@W_x.T + bias for all timesteps in parallel using highly optimized cuBLAS (via PyTorch).

        # Split the weights of i2h into input-part (W_ih) and hidden-part (W_hh)
        w_ih = self.i2h.weight[:, :self.input_size]
        w_hh = self.i2h.weight[:, self.input_size:]

        # Project inputs and add the bias
        # Shape: (seq_len, batch_size, hidden_size)
        x_proj = F.linear(x, w_ih, self.i2h.bias)

        # 2. Prepare Weights for Custom Kernel
        # To optimize memory bandwidth in the kernel, we want coalesced reads.
        # The kernel computes h_prev @ W_hh.T.
        # We pass W_hh.t() contiguous in memory so that threads reading W_hh_t[k, tid] access contiguous addresses.
        w_hh_t_contig = w_hh.t().contiguous()

        # 3. Run Custom Recurrent Kernel
        # This replaces the Python loop over seq_len
        h_all = self.rnn_cuda.rnn_cuda_forward(x_proj, h0, w_hh_t_contig)

        # 4. Output Projection
        # Apply the final linear layer to all hidden states at once
        output = self.h2o(h_all)

        return output

