import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for NetVLAD aggregation and intra-normalization
netvlad_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ inline float warpReduceSum(float val) {
    for (int offset = warpSize / 2; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__device__ inline float blockReduceSum(float val) {
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % warpSize;
    int wid = threadIdx.x / warpSize;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / warpSize) ? shared[threadIdx.x] : 0.0f;

    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void netvlad_core_kernel(
    const float* __restrict__ x,           
    const float* __restrict__ assignment,  
    const float* __restrict__ clusters,    
    float* __restrict__ out,               
    int B, int N, int D, int K) {

    // Grid: (K, B)
    // Block: (D) 
    // This kernel assumes D fits within the maximum block size (e.g. 1024).
    // For D=512 this is perfectly efficient.

    int k = blockIdx.x;
    int b = blockIdx.y;
    int d = threadIdx.x;

    if (d >= D) return;

    // Cluster center value: clusters is (1, D, K) -> effectively (D, K) in layout
    // Flat index: d*K + k
    float c_val = clusters[d * K + k]; 

    float sum_vx = 0.0f;
    float sum_a = 0.0f;

    // Pointers to the start of the N-loop for this (b, d) and (b, k)
    // x: (B, N, D)
    const float* x_ptr = x + b * N * D + d;       
    // assignment: (B, N, K)
    const float* a_ptr = assignment + b * N * K + k; 

    // Accumulate residuals: sum(a * (x - c)) = sum(a*x) - sum(a)*c
    for (int n = 0; n < N; ++n) {
        float a = a_ptr[n * K];      // assignment strides by K
        float val = x_ptr[n * D];    // x strides by D
        sum_vx += a * val;
        sum_a += a;
    }

    // VLAD residual for this dimension d
    float v = sum_vx - sum_a * c_val;

    // Intra-normalization (L2 normalization over dimension D)
    float v_sq = v * v;
    float sum_sq = blockReduceSum(v_sq); 

    // Broadcast norm to all threads in block
    __shared__ float inv_norm;
    if (threadIdx.x == 0) {
        // match PyTorch epsilon 1e-12
        inv_norm = rsqrtf(sum_sq + 1e-12f);
    }
    __syncthreads();

    v = v * inv_norm;

    // Write output
    // out shape: (B, D, K). Strides (D*K, K, 1)
    // flat index = b*D*K + d*K + k
    out[b * D * K + d * K + k] = v;
}

torch::Tensor netvlad_cuda(torch::Tensor x, torch::Tensor assignment, torch::Tensor clusters) {
    int B = x.size(0);
    int N = x.size(1);
    int D = x.size(2);
    int K = assignment.size(2);

    auto out = torch::empty({B, D, K}, x.options());

    dim3 grid(K, B);
    dim3 block(D); 

    netvlad_core_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        assignment.data_ptr<float>(),
        clusters.data_ptr<float>(),
        out.data_ptr<float>(),
        B, N, D, K
    );

    return out;
}
"""

netvlad_cpp = "torch::Tensor netvlad_cuda(torch::Tensor x, torch::Tensor assignment, torch::Tensor clusters);"

# Compile the extension
netvlad_ext = load_inline(
    name="netvlad_ext",
    cpp_sources=netvlad_cpp,
    cuda_sources=netvlad_source,
    functions=["netvlad_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        self.clusters = nn.Parameter(init_sc * torch.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        self.clusters2 = nn.Parameter(init_sc * torch.randn(1, feature_size, cluster_size))

        self.netvlad_ext = netvlad_ext

    def forward(self, x, mask=None):
        B, N, D = x.shape

        # 1. Soft Assignment Calculation
        # Keep x contiguous for later matmul and kernel
        x_flat = x.view(-1, self.feature_size)

        if x_flat.device != self.clusters.device:
             raise ValueError(f"x.device {x_flat.device} != cluster.device {self.clusters.device}")

        # Standard Gemm + BN + Softmax is highly optimized in PyTorch/CuBLAS
        assignment = torch.matmul(x_flat, self.clusters)
        assignment = self.batch_norm(assignment)
        assignment = F.softmax(assignment, dim=1)

        # Prepare assignment for Custom Kernel
        # Slice ghost clusters: (BN, K+G) -> (BN, K)
        # View as (B, N, K) and ensure contiguous memory for the kernel
        assignment = assignment[:, :self.cluster_size].view(B, N, self.cluster_size).contiguous()

        # 2. VLAD Aggregation + Intra-Norm (Fused Kernel)
        # Fuses: Weighted Sum, Center Subtraction, Transposes, and L2 Intra-Normalization
        # Input shapes: x(B, N, D), assignment(B, N, K), clusters2(1, D, K)
        # Output shape: (B, D, K)
        vlad = self.netvlad_ext.netvlad_cuda(x, assignment, self.clusters2)

        # 3. Flatten and Global L2 Norm
        vlad = vlad.view(B, -1)
        vlad = F.normalize(vlad, dim=1)

        return vlad

