import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
from itertools import repeat
import collections.abc

# --------------------------------------------------------------------------------
# Custom CUDA Kernels for Swin Transformer
# --------------------------------------------------------------------------------

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void patch_merging_kernel(
    const float* __restrict__ x, 
    float* __restrict__ out, 
    int B, int H, int W, int C
) {
    // Output dimensions
    int out_H = H / 2;
    int out_W = W / 2;
    int out_C = C * 4;

    int total_elements = B * out_H * out_W * out_C;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Map linear index to output coordinates (b, h, w, c_out)
        int c_out = idx % out_C;
        int temp = idx / out_C;
        int w = temp % out_W;
        temp = temp / out_W;
        int h = temp % out_H;
        int b = temp / out_H;

        // Determine input source coordinates based on channel index
        // c_out range [0, 4C). 
        // 0-C: (2h, 2w), C-2C: (2h+1, 2w), 2C-3C: (2h, 2w+1), 3C-4C: (2h+1, 2w+1)
        int c_in = c_out % C;
        int type = c_out / C; // 0, 1, 2, 3

        int dy = (type == 1 || type == 3) ? 1 : 0;
        int dx = (type == 2 || type == 3) ? 1 : 0;

        int in_h = h * 2 + dy;
        int in_w = w * 2 + dx;

        // Linear input index
        int in_idx = ((b * H + in_h) * W + in_w) * C + c_in;

        out[idx] = x[in_idx];
    }
}

__global__ void window_partition_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B, int H, int W, int C, int ws
) {
    int total_elements = B * H * W * C;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Output logically: (B, H/ws, W/ws, ws, ws, C)
        // But we just need to map output linear index to input linear index

        int c = idx % C;
        int temp = idx / C;
        int wx = temp % ws;
        temp = temp / ws;
        int wy = temp % ws;
        temp = temp / ws;
        int w_blk = temp % (W / ws);
        temp = temp / (W / ws);
        int h_blk = temp % (H / ws);
        int b = temp / (H / ws);

        int src_h = h_blk * ws + wy;
        int src_w = w_blk * ws + wx;

        int src_idx = ((b * H + src_h) * W + src_w) * C + c;

        out[idx] = x[src_idx];
    }
}

__global__ void window_reverse_kernel(
    const float* __restrict__ windows,
    float* __restrict__ x,
    int B, int H, int W, int C, int ws
) {
    int total_elements = B * H * W * C;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // idx is for destination x (B, H, W, C)
        int c = idx % C;
        int temp = idx / C;
        int w = temp % W;
        temp = temp / W;
        int h = temp % H;
        int b = temp / H;

        int h_blk = h / ws;
        int wy = h % ws;
        int w_blk = w / ws;
        int wx = w % ws;

        int H_blks = H / ws;
        int W_blks = W / ws;

        // Map to windows tensor layout: (B, H_blks, W_blks, ws, ws, C)
        // Flattened index calculation
        int win_idx = (((((b * H_blks + h_blk) * W_blks + w_blk) * ws + wy) * ws + wx) * C + c);

        x[idx] = windows[win_idx];
    }
}

torch::Tensor patch_merging_cuda(torch::Tensor x) {
    int B = x.size(0);
    int H = x.size(1);
    int W = x.size(2);
    int C = x.size(3);

    auto out = torch::empty({B, H/2, W/2, 4*C}, x.options());

    int total = out.numel();
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;

    patch_merging_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), B, H, W, C
    );
    return out;
}

torch::Tensor window_partition_cuda(torch::Tensor x, int window_size) {
    int B = x.size(0);
    int H = x.size(1);
    int W = x.size(2);
    int C = x.size(3);

    // Output shape: (B * (H/ws) * (W/ws), ws, ws, C)
    // Flattened logical view for kernel: (B, H/ws, W/ws, ws, ws, C)
    int num_windows = (H / window_size) * (W / window_size);
    auto out = torch::empty({B * num_windows, window_size, window_size, C}, x.options());

    int total = x.numel();
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;

    window_partition_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), B, H, W, C, window_size
    );
