import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for ReLU and Global Average Pooling
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Simple ReLU Kernel
// Computes out[i] = max(0, in[i]) element-wise
__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor custom_relu(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    relu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}

// Global Average Pooling Kernel
// Performs average pooling over H and W dimensions for each N and C.
// Output shape: (N, C, 1, 1)
__global__ void avg_pool_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                int N, int C, int H, int W) {
    // Parallelize over N * C (Batch size * Channels)
    // Each thread computes the mean for one feature map
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_channels = N * C;

    if (idx < total_channels) {
        int n = idx / C;
        int c = idx % C;

        // Calculate the starting offset for the current feature map (n, c, :, :)
        int offset = n * C * H * W + c * H * W;

        float sum = 0.0f;
        int area = H * W;

        // Sum all elements in the HxW map
        for (int i = 0; i < area; ++i) {
            sum += input[offset + i];
        }

        output[idx] = sum / (float)area;
    }
}

torch::Tensor custom_avg_pool(torch::Tensor input) {
    // Input shape: (N, C, H, W)
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    // Output shape: (N, C, 1, 1)
    auto output = torch::empty({N, C, 1, 1}, input.options());

    int total_threads = N * C;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    avg_pool_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), N, C, H, W);

    return output;
}
"""

