import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused BatchNorm + ReLU
# This fuses the memory-bound operations: normalization, affine transform, and ReLU activation
fused_bn_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_bn_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    float* __restrict__ output,
    int size,
    int C,
    int H,
    int W,
    float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        int HW = H * W;
        // Calculate channel index: idx = n*C*HW + c*HW + h*W + w
        // idx / HW = n*C + c
        int c = (idx / HW) % C;

        float val = input[idx];
        float m = mean[c];
        float v = var[c];
        float w = weight[c];
        float b = bias[c];

        // Fused Batch Norm computation
        // y = (x - mean) / sqrt(var + eps) * weight + bias
        // Optimization: Precompute scale and shift
        // scale = weight * rsqrt(var + eps)
        // shift = bias - mean * scale

        float inv_std = rsqrtf(v + eps);
        float scale = w * inv_std;
        float shift = b - m * scale;

        float bn_out = val * scale + shift;

        // Fused ReLU
        output[idx] = bn_out > 0.0f ? bn_out : 0.0f;
    }
}

torch::Tensor fused_bn_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor mean,
    torch::Tensor var,
    float eps) {

    auto output = torch::empty_like(input);

    int size = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_bn_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        output.data_ptr<float>(),
        size, C, H, W, eps
    );

    return output;
}
"""

