class FusedBatchNormReLU(nn.Module):
    def __init__(self, num_features, eps=1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        # Mimic BatchNorm2d parameters
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer('running_mean', torch.zeros(num_features))
        self.register_buffer('running_var', torch.ones(num_features))

    def forward(self, x):
        # Calls the custom CUDA kernel using running stats (inference mode behavior)
        return fused_ops.fused_bn_relu_cuda(
            x, self.weight, self.bias, self.running_mean, self.running_var, self.eps
        )

class ModelNew(nn.Module):
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        super(ModelNew, self).__init__()
        self.growth_rate = growth_rate
        layers = []
        for i in range(num_layers):
            layers.append(self._make_layer(num_input_features + i * growth_rate, growth_rate))
        self.layers = nn.ModuleList(layers)

    def _make_layer(self, in_features: int, growth_rate: int):
        # Replace BatchNorm2d + ReLU with custom FusedBatchNormReLU kernel
        # Dropout(0.0) is identity, so it is removed for efficiency
        return nn.Sequential(
            FusedBatchNormReLU(in_features),
            nn.Conv2d(in_features, growth_rate, kernel_size=3, padding=1, bias=False)
        )

    def forward(self, x):
        """
        Optimized forward pass using pre-allocation.
        Instead of creating a new concatenated list and tensor at every layer (O(N^2) memory copies),
        we pre-allocate the final output tensor and fill it slice-by-slice.
        """
        B, C0, H, W = x.shape
        num_layers = len(self.layers)
        final_channels = C0 + num_layers * self.growth_rate

        # Pre-allocate the full storage tensor
        storage = torch.empty(B, final_channels, H, W, device=x.device, dtype=x.dtype)

        # Copy the initial input to the beginning of storage
        storage[:, :C0, :, :] = x

        current_c = C0
        for layer in self.layers:
            # Create a view of the valid features so far
            inp = storage[:, :current_c, :, :]

            # Compute new features
            out = layer(inp)

            # Write new features directly into the pre-allocated storage
            storage[:, current_c : current_c + self.growth_rate, :, :] = out

            current_c += self.growth_rate

        return storage

