# Define custom CUDA kernels for ReLU and MaxPool2d
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

// CUDA Kernel for Element-wise ReLU
__global__ void relu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

// Wrapper for ReLU
torch::Tensor relu_cuda(torch::Tensor input) {
    auto out = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

// CUDA Kernel for MaxPool2d (Kernel=2, Stride=2)
// Assumes input is (N, C, H, W) and output is (N, C, H/2, W/2)
__global__ void maxpool2d_kernel(const float* __restrict__ x, float* __restrict__ out, 
                                 int N, int C, int H, int W, 
                                 int out_H, int out_W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * C * out_H * out_W;

    if (idx < total_threads) {
        // Map linear index to (n, c, h_out, w_out)
        int w_out = idx % out_W;
        int tmp = idx / out_W;
        int h_out = tmp % out_H;
        tmp = tmp / out_H;
        int c = tmp % C;
        int n = tmp / C;

        int h_in_start = h_out * 2;
        int w_in_start = w_out * 2;

        // Calculate pointer to the specific image/channel
        const float* img_ptr = x + n * (C * H * W) + c * (H * W);

        float max_val = -FLT_MAX;

        // Unrolled 2x2 pooling loop
        #pragma unroll
        for (int i = 0; i < 2; ++i) {
            #pragma unroll
            for (int j = 0; j < 2; ++j) {
                int h_in = h_in_start + i;
                int w_in = w_in_start + j;

                // Boundary check (though usually VGG dims are even)
                if (h_in < H && w_in < W) {
                    float val = img_ptr[h_in * W + w_in];
                    max_val = fmaxf(max_val, val);
                }
            }
        }
        out[idx] = max_val;
    }
}

// Wrapper for MaxPool2d
torch::Tensor maxpool2d_cuda(torch::Tensor input) {
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int out_H = H / 2;
    int out_W = W / 2;

    auto out = torch::empty({N, C, out_H, out_W}, input.options());

    int total_threads = N * C * out_H * out_W;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    maxpool2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(),
                                                 N, C, H, W, out_H, out_W);
    return out;
}
