import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused Linear + ReLU
fused_linear_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_linear_relu_kernel(
    const float* __restrict__ X, 
    const float* __restrict__ W, 
    const float* __restrict__ B, 
    float* __restrict__ Y, 
    int M, int N, int K, 
    bool use_relu) 
{
    // Tile size
    const int TS = 32;

    // Block and Thread indices
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column indices for output Y
    int row = by * TS + ty;
    int col = bx * TS + tx;

    // Shared memory with padding to reduce bank conflicts
    // As stores tiles of X. Bs stores tiles of W.
    __shared__ float As[TS][TS + 1];
    __shared__ float Bs[TS][TS + 1];

    float val = 0.0f;

    // Loop over tiles covering the K dimension
    int num_tiles = (K + TS - 1) / TS;
    for (int t = 0; t < num_tiles; ++t) {

        // Load tile of X into As
        // We need X[row, t*TS + tx]
        int x_col = t * TS + tx;
        if (row < M && x_col < K) {
            As[ty][tx] = X[row * K + x_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of W into Bs
        // W shape is (N, K). We need rows of W corresponding to Y columns [bx*TS ... bx*TS + TS - 1].
        // To optimize memory access in the compute phase, we transpose W in shared memory.
        // We load W[w_row, w_col] where w_row is output feature index, w_col is input feature index.
        // We store it into Bs[w_col_in_tile][w_row_in_tile].

        int w_row = bx * TS + ty;
        int w_col = t * TS + tx;

        if (w_row < N && w_col < K) {
            Bs[tx][ty] = W[w_row * K + w_col];
        } else {
            Bs[tx][ty] = 0.0f;
        }

        __syncthreads();

        // Compute dot product for this tile
        // Thread (ty, tx) computes element for Y[row, col]
        // It accumulates sum(As[ty][k] * Bs[k][tx])
        // As[ty][k] is X[row, current_k]
        // Bs[k][tx] is W[col, current_k] (due to transpose storage)

        #pragma unroll
        for (int k = 0; k < TS; ++k) {
            val += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Store result
    if (row < M && col < N) {
        // Add bias
        if (B != nullptr) {
            val += B[col];
        }

        // Apply ReLU
        if (use_relu) {
            val = fmaxf(0.0f, val);
        }

        Y[row * N + col] = val;
    }
}

torch::Tensor fused_linear_cuda(torch::Tensor X, torch::Tensor W, torch::Tensor B, bool use_relu) {
    int M = X.size(0);
    int K = X.size(1);
    int N = W.size(0);

    auto Y = torch::empty({M, N}, X.options());

    dim3 block(32, 32);
    dim3 grid((N + 31) / 32, (M + 31) / 32);

    const float* B_ptr = (B.defined()) ? B.data_ptr<float>() : nullptr;

    fused_linear_relu_kernel<<<grid, block>>>(
        X.data_ptr<float>(), 
        W.data_ptr<float>(), 
        B_ptr, 
        Y.data_ptr<float>(), 
        M, N, K, 
        use_relu
    );

    return Y;
}
"""

fused_linear_cpp = """
torch::Tensor fused_linear_cuda(torch::Tensor X, torch::Tensor W, torch::Tensor B, bool use_relu);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_linear_cpp,
    cuda_sources=fused_linear_source,
    functions=["fused_linear_cuda"],
    verbose=False,
    extra_cflags=['-O3'],
)

class FusedLinear(nn.Module):
    def __init__(self, in_features, out_features, bias=True, activation=False):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.activation = activation

        self.weight = nn.Parameter(torch.empty((out_features, in_features)))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_features))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / (fan_in**0.5)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, input):
        # Fallback to cuda() if input is on cpu, though strictly we expect cuda input
        if input.device.type != 'cuda':
            input = input.cuda()

        return fused_ops.fused_linear_cuda(
            input, 
            self.weight, 
            self.bias if self.bias is not None else torch.Tensor(), 
            self.activation
        )

class ModelNew(nn.Module):
    def __init__(self, input_size, layer_sizes, output_size):
        super(ModelNew, self).__init__()

        layers = []
        current_input_size = input_size

        # Build hidden layers with fused Linear + ReLU
        for layer_size in layer_sizes:
            layers.append(FusedLinear(current_input_size, layer_size, bias=True, activation=True))
            current_input_size = layer_size

        # Build output layer with fused Linear (no ReLU)
        layers.append(FusedLinear(current_input_size, output_size, bias=True, activation=False))

        self.network = nn.Sequential(*layers)

    def forward(self, x):
        return self.network(x)

