import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused Add + LayerNorm
# This kernel fuses the element-wise addition of the residual connection
# with the subsequent Layer Normalization, reducing memory bandwidth usage.
fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename T>
__global__ void fused_add_layernorm_kernel(
    const T* __restrict__ x,
    const T* __restrict__ residual,
    const T* __restrict__ gamma,
    const T* __restrict__ beta,
    T* __restrict__ out,
    int D,
    float epsilon) {

    // One block per row
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int offset = row * D;

    // Load and Add
    // We compute (x + residual)
    float val = 0.0f;
    if (tid < D) {
        val = static_cast<float>(x[offset + tid]) + static_cast<float>(residual[offset + tid]);
    }

    // Shared memory for reduction
    extern __shared__ float s_data[];

    // --- Mean Calculation ---
    // Initialize shared memory. If tid >= D, pad with 0 for reduction.
    s_data[tid] = (tid < D) ? val : 0.0f;
    __syncthreads();

    // Tree reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    float mean = s_data[0] / D;
    __syncthreads();

    // --- Variance Calculation ---
    float diff = 0.0f;
    if (tid < D) {
        diff = val - mean;
        diff = diff * diff;
    }
    s_data[tid] = (tid < D) ? diff : 0.0f;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    float var = s_data[0] / D;
    float inv_std = rsqrtf(var + epsilon);

    // --- Normalize and Scale ---
    if (tid < D) {
        float n_val = (val - mean) * inv_std;
        out[offset + tid] = static_cast<T>(n_val * static_cast<float>(gamma[tid]) + static_cast<float>(beta[tid]));
    }
}

torch::Tensor fused_add_layernorm_cuda(
    torch::Tensor x, 
    torch::Tensor residual, 
    torch::Tensor gamma, 
    torch::Tensor beta, 
    float epsilon) {

    auto D = x.size(-1);
    auto N = x.numel() / D;

    // Ensure inputs are contiguous
    x = x.contiguous();
    residual = residual.contiguous();

    auto out = torch::empty_like(x);

    // Determine block size (Next power of 2)
    int threads = 1;
    while (threads < D) threads *= 2;
    // Cap at 1024 threads per block
    if (threads > 1024) threads = 1024; 

    // Check if D is supported by this simple kernel
    TORCH_CHECK(D <= 1024, "fused_add_layernorm_cuda only supports embedding dim <= 1024");

    int shared_mem = threads * sizeof(float);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(x.scalar_type(), "fused_add_layernorm_cuda", ([&] {
        fused_add_layernorm_kernel<scalar_t><<<N, threads, shared_mem>>>(
            x.data_ptr<scalar_t>(),
            residual.data_ptr<scalar_t>(),
            gamma.data_ptr<scalar_t>(),
            beta.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            D,
            epsilon
        );
    }));

    return out;
}
"""

fused_ops_cpp = "torch::Tensor fused_add_layernorm_cuda(torch::Tensor x, torch::Tensor residual, torch::Tensor gamma, torch::Tensor beta, float epsilon);"

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=["fused_add_layernorm_cuda"],
    verbose=False,
)

class CustomTransformerEncoderLayer(nn.Module):
    def __init__(self, d_model, nhead, dim_feedforward, dropout=0.0):
        super().__init__()
        self.self_attn = nn.MultiheadAttention(d_model, nhead, dropout=dropout, batch_first=True)

        # Implementation of Feedforward model
        self.linear1 = nn.Linear(d_model, dim_feedforward)
        self.dropout = nn.Dropout(dropout)
        self.linear2 = nn.Linear(dim_feedforward, d_model)

        self.norm1 = nn.LayerNorm(d_model)
        self.norm2 = nn.LayerNorm(d_model)
        self.dropout1 = nn.Dropout(dropout)
        self.dropout2 = nn.Dropout(dropout)
        self.activation = F.relu # Default for nn.TransformerEncoderLayer

    def forward(self, src):
        # 1. Self-Attention Block
        # Standard implementation: src = norm1(src + dropout(attn(src)))
        # We compute attn, then fuse add + norm

        # attn_output: (B, L, D)
        attn_output, _ = self.self_attn(src, src, src)
        attn_output = self.dropout1(attn_output)

        # Fused Add + LayerNorm
        # src = LayerNorm(src + attn_output)
        src = fused_ops.fused_add_layernorm_cuda(
            src, 
            attn_output, 
            self.norm1.weight, 
            self.norm1.bias, 
            self.norm1.eps
        )

        # 2. Feed Forward Block
        # Standard implementation: src = norm2(src + dropout(linear2(activation(linear1(src)))))

        ff_output = self.linear2(self.dropout(self.activation(self.linear1(src))))
        ff_output = self.dropout2(ff_output)

        # Fused Add + LayerNorm
        # src = LayerNorm(src + ff_output)
        src = fused_ops.fused_add_layernorm_cuda(
            src, 
            ff_output, 
            self.norm2.weight, 
            self.norm2.bias, 
            self.norm2.eps
        )

        return src

class ModelNew(nn.Module):
    def __init__(self, num_classes, embed_dim=512, num_heads=8, num_layers=6, 
                 mlp_ratio=4.0, patch_size=4, in_channels=3, image_size=32):
        super(ModelNew, self).__init__()

        self.patch_size = patch_size
        self.image_size = image_size
        self.embed_dim = embed_dim

        # Keeping Conv2d as it is highly optimized in CuDNN
        self.conv1 = nn.Conv2d(in_channels, embed_dim, kernel_size=patch_size, stride=patch_size)

        num_patches = (image_size // patch_size) ** 2

        # Keeping Linear Projection (Aggressive dimensionality reduction)
        self.linear_proj = nn.Linear(embed_dim * num_patches, embed_dim)

        # Replaced nn.TransformerEncoderLayer with CustomTransformerEncoderLayer
        # which uses custom CUDA fused kernels
        self.transformer_layers = nn.ModuleList([
            CustomTransformerEncoderLayer(
                d_model=embed_dim,
                nhead=num_heads,
                dim_feedforward=int(embed_dim * mlp_ratio),
                dropout=0.0
            ) for _ in range(num_layers)
        ])

        self.cls_token = nn.Parameter(torch.zeros(1, 1, embed_dim))
        self.fc_out = nn.Linear(embed_dim, num_classes)

    def forward(self, x):
        B = x.size(0)
        x = self.conv1(x)                  
        x = x.flatten(start_dim=1)         
        x = self.linear_proj(x)            

        cls_tokens = self.cls_token.expand(B, -1, -1)  
        x = torch.cat((cls_tokens, x.unsqueeze(1)), dim=1) 

        for layer in self.transformer_layers:
            x = layer(x)

        return self.fc_out(x[:, 0])

