import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GRU cell operations
gru_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void gru_cell_fused_kernel(
    const float* __restrict__ input_gates,  // [batch_size, 3 * hidden_size] (precomputed W_ih * x + b_ih)
    const float* __restrict__ hidden_gates, // [batch_size, 3 * hidden_size] (W_hh * h_prev + b_hh)
    const float* __restrict__ h_prev,       // [batch_size, hidden_size]
    float* __restrict__ h_curr,             // [batch_size, hidden_size]
    int hidden_size,
    int batch_size) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int row = idx / hidden_size; // batch index
        int col = idx % hidden_size; // hidden unit index

        // Calculate offset for the gates. 
        // Gates are stored as concatenation of R, Z, N chunks.
        // Size of gates row is 3 * hidden_size.
        int gate_idx = row * (3 * hidden_size) + col;

        // Input contributions
        float i_r = input_gates[gate_idx];
        float i_z = input_gates[gate_idx + hidden_size];
        float i_n = input_gates[gate_idx + 2 * hidden_size];

        // Hidden contributions
        float h_r = hidden_gates[gate_idx];
        float h_z = hidden_gates[gate_idx + hidden_size];
        float h_n = hidden_gates[gate_idx + 2 * hidden_size];

        float h_p = h_prev[idx];

        // Reset gate: r = sigmoid(i_r + h_r)
        float r = 1.0f / (1.0f + expf(-(i_r + h_r)));

        // Update gate: z = sigmoid(i_z + h_z)
        float z = 1.0f / (1.0f + expf(-(i_z + h_z)));

        // New gate: n = tanh(i_n + r * h_n)
        // Note: standard GRU applies reset gate to the hidden state contribution of the new gate
        float n = tanhf(i_n + r * h_n);

        // Next hidden state: h_t = (1 - z) * n + z * h_{t-1}
        float h_new = (1.0f - z) * n + z * h_p;

        h_curr[idx] = h_new;
    }
}

torch::Tensor gru_cell_cuda(torch::Tensor input_gates, torch::Tensor hidden_gates, torch::Tensor h_prev) {
    auto batch_size = h_prev.size(0);
    auto hidden_size = h_prev.size(1);

    // Output tensor
    auto h_curr = torch::empty_like(h_prev);

    // Ensure inputs are contiguous
    input_gates = input_gates.contiguous();
    hidden_gates = hidden_gates.contiguous();
    h_prev = h_prev.contiguous();

    const int block_size = 256;
    const int num_blocks = (batch_size * hidden_size + block_size - 1) / block_size;

    gru_cell_fused_kernel<<<num_blocks, block_size>>>(
        input_gates.data_ptr<float>(),
        hidden_gates.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        h_curr.data_ptr<float>(),
        hidden_size,
        batch_size
    );

    return h_curr;
}
"""

gru_cpp_source = "torch::Tensor gru_cell_cuda(torch::Tensor input_gates, torch::Tensor hidden_gates, torch::Tensor h_prev);"

# Compile and load the inline CUDA functions
gru_ops = load_inline(
    name="gru_ops",
    cpp_sources=gru_cpp_source,
    cuda_sources=gru_source,
    functions=["gru_cell_cuda"],
    verbose=False,
)

class FusedGRUCell(nn.Module):
    """
    A GRU layer implemented with a custom CUDA kernel for the element-wise 
    recurrent steps, while using PyTorch MM for matrix multiplications.
    """
    def __init__(self, input_size, hidden_size, bias=True):
        super().__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.bias = bias

        # Weights for input projection (concat of r, z, n)
        self.weight_ih = nn.Parameter(torch.empty(3 * hidden_size, input_size))
        # Weights for hidden projection (concat of r, z, n)
        self.weight_hh = nn.Parameter(torch.empty(3 * hidden_size, hidden_size))

        if bias:
            self.bias_ih = nn.Parameter(torch.empty(3 * hidden_size))
            self.bias_hh = nn.Parameter(torch.empty(3 * hidden_size))
        else:
            self.register_parameter('bias_ih', None)
            self.register_parameter('bias_hh', None)

        self.reset_parameters()

    def reset_parameters(self):
        std = 1.0 / (self.hidden_size ** 0.5)
        nn.init.uniform_(self.weight_ih, -std, std)
        nn.init.uniform_(self.weight_hh, -std, std)
        if self.bias:
            nn.init.uniform_(self.bias_ih, -std, std)
            nn.init.uniform_(self.bias_hh, -std, std)

    def forward(self, x_seq, h_0):
        # x_seq: (seq_len, batch, input_size)
        # h_0: (batch, hidden_size)

        seq_len, batch_size, _ = x_seq.size()

        # Flatten x to (seq_len * batch, input_size) for large GEMM
        x_flat = x_seq.view(-1, self.input_size)

        # Precompute W_ih * x + b_ih for all timesteps
        if self.bias:
            input_gates_all = torch.addmm(self.bias_ih, x_flat, self.weight_ih.t())
        else:
            input_gates_all = torch.mm(x_flat, self.weight_ih.t())

        # Reshape back to (seq_len, batch, 3*hidden)
        input_gates_all = input_gates_all.view(seq_len, batch_size, 3 * self.hidden_size)

        h_curr = h_0
        outputs = []

        # Recurrent loop
        for t in range(seq_len):
            # Input contribution for this timestep
            i_gates = input_gates_all[t]

            # Compute Hidden contribution: W_hh * h_prev + b_hh
            if self.bias:
                h_gates = torch.addmm(self.bias_hh, h_curr, self.weight_hh.t())
            else:
                h_gates = torch.mm(h_curr, self.weight_hh.t())

            # Fused CUDA kernel for gate activation and state update
            h_curr = gru_ops.gru_cell_cuda(i_gates, h_gates, h_curr)
            outputs.append(h_curr)

        return torch.stack(outputs, dim=0)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.batch_first = batch_first
        # The original architecture is bidirectional
        self.bidirectional = True 

        # We manually manage layers to allow for our custom cell
        self.fwd_layers = nn.ModuleList()
        self.bwd_layers = nn.ModuleList()

        for i in range(num_layers):
            # First layer input is input_size, subsequent layers take output from previous bi-layer
            layer_in_size = input_size if i == 0 else hidden_size * 2

            self.fwd_layers.append(FusedGRUCell(layer_in_size, hidden_size, bias))
            self.bwd_layers.append(FusedGRUCell(layer_in_size, hidden_size, bias))

    def forward(self, x, h0):
        # x: (seq_len, batch, input_size) (if batch_first=False)
        # h0: (num_layers * 2, batch, hidden_size)

        if self.batch_first:
            x = x.transpose(0, 1)

        current_input = x

        for i in range(self.num_layers):
            # Get initial hidden states for this layer's forward and backward directions
            h0_fwd = h0[2 * i]
            h0_bwd = h0[2 * i + 1]

            # Forward pass
            out_fwd = self.fwd_layers[i](current_input, h0_fwd)

            # Backward pass
            # Reverse input sequence
            rev_input = torch.flip(current_input, [0])
            out_bwd_rev = self.bwd_layers[i](rev_input, h0_bwd)
            # Reverse output sequence back
            out_bwd = torch.flip(out_bwd_rev, [0])

            # Concatenate outputs for next layer
            current_input = torch.cat([out_fwd, out_bwd], dim=2)

        output = current_input

        if self.batch_first:
            output = output.transpose(0, 1)

        return output

