import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for ReLU6 and Element-wise Addition
# We implement efficient kernels to replace standard PyTorch operators within the MBConv blocks.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel for ReLU6: y = min(max(x, 0), 6)
// This is used as the activation function in MBConv blocks.
__global__ void relu6_kernel(const float* __restrict__ x, float* __restrict__ y, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        y[idx] = fminf(fmaxf(val, 0.0f), 6.0f);
    }
}

// Kernel for Element-wise Add: out = a + b
// This is used for the residual connection in MBConv blocks.
__global__ void add_kernel(const float* __restrict__ a, const float* __restrict__ b, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

// C++ wrapper for ReLU6 (out-of-place)
torch::Tensor relu6_cuda(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    relu6_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), y.data_ptr<float>(), size);
    return y;
}

// C++ wrapper for ReLU6 (in-place)
void relu6_cuda_inplace(torch::Tensor x) {
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    relu6_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), x.data_ptr<float>(), size);
}

// C++ wrapper for Add (in-place: a += b)
void add_cuda_inplace(torch::Tensor a, torch::Tensor b) {
    int size = a.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), a.data_ptr<float>(), size);
}
"""

cpp_source = """
torch::Tensor relu6_cuda(torch::Tensor x);
void relu6_cuda_inplace(torch::Tensor x);
void add_cuda_inplace(torch::Tensor a, torch::Tensor b);
"""

# Compile the inline CUDA code
# We compile kernels for ReLU6 (both inplace and out-of-place) and In-place Add.
cuda_ops = load_inline(
    name="efficientnet_cuda_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["relu6_cuda", "relu6_cuda_inplace", "add_cuda_inplace"],
    verbose=False,
)

class CustomReLU6(nn.Module):
    def __init__(self, inplace=False):
        super(CustomReLU6, self).__init__()
        self.inplace = inplace

    def forward(self, x):
        if self.inplace:
            cuda_ops.relu6_cuda_inplace(x)
            return x
        return cuda_ops.relu6_cuda(x)

class CustomInplaceAdd(nn.Module):
    def __init__(self):
        super(CustomInplaceAdd, self).__init__()

    def forward(self, a, b):
        # Performs a += b in-place using the custom CUDA kernel
        cuda_ops.add_cuda_inplace(a, b)
        return a

class MBConvNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        super(MBConvNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        hidden_dim = in_channels * expand_ratio

        # Helper for custom residual addition
        self.custom_add = CustomInplaceAdd() if self.use_residual else None

        if expand_ratio != 1:
            self.expand_conv = nn.Sequential(
                nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(hidden_dim),
                CustomReLU6(inplace=True) # Replaced nn.ReLU6 with custom CUDA version
            )

        self.depthwise_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=(kernel_size-1)//2, groups=hidden_dim, bias=False),
            nn.BatchNorm2d(hidden_dim),
            CustomReLU6(inplace=True) # Replaced nn.ReLU6 with custom CUDA version
        )

        self.project_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(out_channels)
        )

    def forward(self, x):
        identity = x

        if hasattr(self, 'expand_conv'):
            x = self.expand_conv(x)

        x = self.depthwise_conv(x)
        x = self.project_conv(x)

        if self.use_residual:
            # Replaced standard tensor addition (x += identity) with custom CUDA kernel
            x = self.custom_add(x, identity)

        return x

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        EfficientNetB0 architecture implementation in PyTorch with Custom CUDA Kernels.
        """
        super(ModelNew, self).__init__()

        # Initial convolutional layer
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)

        # MBConv blocks using MBConvNew with custom CUDA ops
        self.blocks = nn.Sequential(
            MBConvNew(32, 16, kernel_size=3, stride=1, expand_ratio=1),
            MBConvNew(16, 24, kernel_size=3, stride=2, expand_ratio=6),
            MBConvNew(24, 24, kernel_size=3, stride=1, expand_ratio=6),
            MBConvNew(24, 40, kernel_size=5, stride=2, expand_ratio=6),
            MBConvNew(40, 40, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(40, 80, kernel_size=3, stride=2, expand_ratio=6),
            MBConvNew(80, 80, kernel_size=3, stride=1, expand_ratio=6),
            MBConvNew(80, 112, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(112, 112, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(112, 192, kernel_size=5, stride=2, expand_ratio=6),
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(192, 320, kernel_size=3, stride=1, expand_ratio=6)
        )

        # Final convolutional layer
        self.conv2 = nn.Conv2d(320, 1280, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn2 = nn.BatchNorm2d(1280)

        # Fully connected layer
        self.fc = nn.Linear(1280, num_classes)

    def forward(self, x):
        """
        Forward pass of the EfficientNetB0 model.
        """
        x = F.relu(self.bn1(self.conv1(x)))
        x = self.blocks(x)
        x = F.relu(self.bn2(self.conv2(x)))
        x = F.adaptive_avg_pool2d(x, (1, 1))
        x = x.view(x.size(0), -1)
        x = self.fc(x)
        return x

