import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for a Fused GRU Cell and the C++ scan loop
gru_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

// Fused GRU Cell Kernel
// Computes gates and updates hidden state for a whole batch
__global__ void gru_cell_fused_kernel(
    const float* __restrict__ gx,       // Input projections (batch, 3*hidden)
    const float* __restrict__ gh,       // Hidden projections (batch, 3*hidden)
    const float* __restrict__ h_prev,   // Previous hidden state (batch, hidden)
    float* __restrict__ h_new,          // New hidden state (batch, hidden)
    int batch_size, 
    int hidden_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int b = idx / hidden_size;
        int h = idx % hidden_size;

        int stride = hidden_size;
        // The layout of weights in PyTorch GRU results in (3*hidden) in the last dim.
        // Order: reset (r), update (z), new (n).
        // gx and gh are pointers to the start of the row for this batch

        int offset_r = b * 3 * stride + h;
        int offset_z = b * 3 * stride + stride + h;
        int offset_n = b * 3 * stride + 2 * stride + h;

        // Sigmoid for r and z
        // r = sigmoid(Wx_r + Wh_r)
        float r_val = 1.0f / (1.0f + expf(-(gx[offset_r] + gh[offset_r])));
        float z_val = 1.0f / (1.0f + expf(-(gx[offset_z] + gh[offset_z])));

        // Tanh for n (candidate hidden state)
        // n = tanh(Wx_n + r * Wh_n)
        float n_input = gx[offset_n] + r_val * gh[offset_n];
        float n_val = tanhf(n_input);

        float h_prev_val = h_prev[b * stride + h];

        // h_t = (1 - z) * n + z * h_{t-1}
        float h_new_val = n_val + z_val * (h_prev_val - n_val);

        h_new[b * stride + h] = h_new_val;
    }
}

// C++ implementation of the recurrence loop
// Moves the loop over sequence length from Python to C++ to reduce overhead
std::vector<torch::Tensor> gru_scan_cuda(
    torch::Tensor input,    // (seq_len, batch, input_size)
    torch::Tensor hx,       // (batch, hidden_size)
    torch::Tensor w_ih,     // (3*hidden, input_size)
    torch::Tensor w_hh,     // (3*hidden, hidden_size)
    torch::Tensor b_ih,     // (3*hidden)
    torch::Tensor b_hh      // (3*hidden)
) {
    auto seq_len = input.size(0);
    auto batch_size = input.size(1);
    auto input_size = input.size(2);
    auto hidden_size = hx.size(1);

    // 1. Pre-compute input projections for all time steps: X @ W_ih.T + b_ih
    // Flatten input to (seq*batch, input)
    auto input_flat = input.view({seq_len * batch_size, input_size});
    // Result: (seq*batch, 3*hidden)
    auto gx_all = torch::addmm(b_ih, input_flat, w_ih.t());
    // Reshape to (seq, batch, 3*hidden) to access by time step
    gx_all = gx_all.view({seq_len, batch_size, 3 * hidden_size});

    // Prepare output tensor for the sequence of hidden states
    auto output = torch::empty({seq_len, batch_size, hidden_size}, hx.options());

    // Working buffer for current hidden state (initialized with h0)
    auto h_curr = hx.clone();

    // Pre-allocate buffer for hidden projection to avoid allocation in loop
    auto gh_buffer = torch::empty({batch_size, 3 * hidden_size}, hx.options());

    int threads = 256;
    int blocks = (batch_size * hidden_size + threads - 1) / threads;

    // 2. Recurrence loop
    for (int t = 0; t < seq_len; ++t) {
        // Compute hidden projection: gh = h_curr @ W_hh.T + b_hh
        torch::addmm_out(gh_buffer, b_hh, h_curr, w_hh.t());

        // Get pre-computed input projection for this step
        auto gx_t = gx_all[t];

        // Launch fused kernel to compute gates and update h_curr
        gru_cell_fused_kernel<<<blocks, threads>>>(
            gx_t.data_ptr<float>(),
            gh_buffer.data_ptr<float>(),
            h_curr.data_ptr<float>(),
            h_curr.data_ptr<float>(), // Update in-place
            batch_size,
            hidden_size
        );

        // Store the new hidden state in the output sequence
        output[t] = h_curr;
    }

    return {output, h_curr};
}
"""

gru_cpp_source = """
