class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super(ModelNew, self).__init__()
        # We use the standard nn.GRU to manage weights and initialization correctly
        self.gru = nn.GRU(input_size, hidden_size, num_layers, bias, batch_first, dropout=0, bidirectional=True)
        self.num_layers = num_layers
        self.hidden_size = hidden_size
        self.batch_first = batch_first
        self.ops = gru_custom_ops

    def forward(self, x, h0):
        # x: (seq_len, batch, input_size) if batch_first=False
        # h0: (num_layers * num_directions, batch, hidden_size)

        if self.batch_first:
            x = x.transpose(0, 1)

        current_input = x
        final_h_n = []
        num_directions = 2 # Bidirectional is fixed to True in the problem

        for layer in range(self.num_layers):
            # ---------------- Forward Direction ----------------
            w_ih = getattr(self.gru, f'weight_ih_l{layer}')
            w_hh = getattr(self.gru, f'weight_hh_l{layer}')
            b_ih = getattr(self.gru, f'bias_ih_l{layer}')
            b_hh = getattr(self.gru, f'bias_hh_l{layer}')

            # Initial hidden state for this layer/direction
            h0_fwd = h0[layer * num_directions]

            # Execute custom CUDA scan
            out_fwd, h_n_fwd = self.ops.gru_scan_cuda(
                current_input, h0_fwd, w_ih, w_hh, b_ih, b_hh
            )

            # ---------------- Backward Direction ----------------
            w_ih_rev = getattr(self.gru, f'weight_ih_l{layer}_reverse')
            w_hh_rev = getattr(self.gru, f'weight_hh_l{layer}_reverse')
            b_ih_rev = getattr(self.gru, f'bias_ih_l{layer}_reverse')
            b_hh_rev = getattr(self.gru, f'bias_hh_l{layer}_reverse')

            h0_bwd = h0[layer * num_directions + 1]

            # Flip input sequence for backward pass
            input_rev = torch.flip(current_input, [0])

            # Execute custom CUDA scan on reversed input
            out_bwd_raw, h_n_bwd = self.ops.gru_scan_cuda(
                input_rev, h0_bwd, w_ih_rev, w_hh_rev, b_ih_rev, b_hh_rev
            )

            # Flip output back to original order
            out_bwd = torch.flip(out_bwd_raw, [0])

            # ---------------- Prepare Next Layer ----------------
            # Concatenate forward and backward outputs along feature dimension
            current_input = torch.cat([out_fwd, out_bwd], dim=2)

            final_h_n.append(h_n_fwd)
            final_h_n.append(h_n_bwd)

        # Stack final hidden states: (num_layers * num_directions, batch, hidden)
        h_n = torch.stack(final_h_n, dim=0)

        return h_n

