torch::Tensor fused_bn_relu6_cuda(torch::Tensor input, torch::Tensor bn_weight, torch::Tensor bn_bias, torch::Tensor bn_mean, torch::Tensor bn_var, float epsilon);
torch::Tensor fused_bn_cuda(torch::Tensor input, torch::Tensor bn_weight, torch::Tensor bn_bias, torch::Tensor bn_mean, torch::Tensor bn_var, float epsilon);
torch::Tensor custom_add_cuda(torch::Tensor a, torch::Tensor b);
"""

