class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        """
        MBConv block implementation with custom CUDA Kernels.
        """
        super(ModelNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        self.hidden_dim = in_channels * expand_ratio
        self.expand_ratio = expand_ratio

        # 1. Expand Phase
        if expand_ratio != 1:
            # We separate Conv and BN to use custom kernels efficiently
            self.expand_conv_c = nn.Conv2d(in_channels, self.hidden_dim, kernel_size=1, stride=1, padding=0, bias=False)
            self.expand_bn = nn.BatchNorm2d(self.hidden_dim)
            # ReLU6 is handled by fusion

        # 2. Depthwise Phase
        # Replaced Sequential(Conv, BN, ReLU) with custom fused op components
        self.dw_kernel_size = kernel_size
        self.dw_stride = stride
        self.dw_padding = (kernel_size - 1) // 2

        self.dw_conv_c = nn.Conv2d(self.hidden_dim, self.hidden_dim, kernel_size=kernel_size, 
                                   stride=stride, padding=self.dw_padding, groups=self.hidden_dim, bias=False)
        self.dw_bn = nn.BatchNorm2d(self.hidden_dim)
        # ReLU6 is handled by fusion

        # 3. Project Phase
        self.project_conv_c = nn.Conv2d(self.hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False)
        self.project_bn = nn.BatchNorm2d(out_channels)

    def forward(self, x):
        identity = x

        # 1. Expand Phase (1x1 Conv -> Fused BN+ReLU6)
        if self.expand_ratio != 1:
            x = self.expand_conv_c(x)
            x = mbconv_ops.fused_bn_relu6_cuda(
                x, 
                self.expand_bn.weight, 
                self.expand_bn.bias, 
                self.expand_bn.running_mean, 
                self.expand_bn.running_var, 
                self.expand_bn.eps
            )

        # 2. Depthwise Phase (Fused Depthwise Conv + BN + ReLU6)
        # Note: We must ensure inputs are contiguous for raw pointer access
        x = x.contiguous()
        x = mbconv_ops.fused_dw_conv_bn_relu_cuda(
            x,
            self.dw_conv_c.weight,
            self.dw_bn.weight,
            self.dw_bn.bias,
            self.dw_bn.running_mean,
            self.dw_bn.running_var,
            self.dw_kernel_size,
            self.dw_stride,
            self.dw_padding,
            self.dw_bn.eps
        )

        # 3. Project Phase (1x1 Conv -> Fused BN)
        x = self.project_conv_c(x)
        x = mbconv_ops.fused_bn_cuda(
            x,
            self.project_bn.weight,
            self.project_bn.bias,
            self.project_bn.running_mean,
            self.project_bn.running_var,
            self.project_bn.eps
        )

        # 4. Residual
        if self.use_residual:
            x = mbconv_ops.custom_add_cuda(x, identity)

        return x

