import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for Fused Linear + ReLU
# This implements a Tiled Matrix Multiplication (GEMM) with fused Bias addition and ReLU
# Block size is set to 32x32 to balance register pressure and occupancy
# Shared memory is padded to avoid bank conflicts
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32

template <bool use_relu>
__global__ void fused_linear_kernel(
    const float* __restrict__ a, 
    const float* __restrict__ b, 
    const float* __restrict__ bias, 
    float* __restrict__ c, 
    int M, int N, int K) {

    // Grid and Thread indices
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global Row (A) and Col (C) indices
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Shared memory for tiles
    // Padding [BLOCK_SIZE][BLOCK_SIZE + 1] prevents shared memory bank conflicts
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE + 1];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE + 1];

    float val = 0.0f;

    // Loop over the K dimension in chunks of BLOCK_SIZE
    for (int k = 0; k < K; k += BLOCK_SIZE) {

        // Load tile from Matrix A (Input)
        // A is (M, K). We load a [32x32] tile.
        // Thread (tx, ty) loads A[row, k+tx].
        // Note: We use 'tx' for the column index of A to allow coalesced global memory reads.
        if (row < M && (k + tx) < K)
            As[ty][tx] = a[row * K + k + tx];
        else
            As[ty][tx] = 0.0f;

        // Load tile from Matrix B (Weights)
        // B is (N, K). We need to effectively transpose B during computation.
        // We load rows of B corresponding to the columns of C.
        // The block's output columns correspond to indices [bx*32 ... bx*32+31].
        // We map thread (tx, ty) to load B[bx*32 + ty, k + tx].
        // This ensures coalesced reads from B as well.
        int b_row = bx * BLOCK_SIZE + ty;
        if (b_row < N && (k + tx) < K)
            Bs[ty][tx] = b[b_row * K + k + tx];
        else
            Bs[ty][tx] = 0.0f;

        __syncthreads();

        // Compute dot product for the tile
        #pragma unroll
        for (int i = 0; i < BLOCK_SIZE; ++i) {
            // As[ty][i] is the element from A at (row, k+i)
            // Bs[tx][i] is the element from B at (col, k+i)
            // Note: Bs was loaded such that Bs[y_local][x_local] holds B[bx*32 + y_local, ...].
            // To get B[col, ...], where col = bx*32 + tx, we access Bs[tx][i].
            val += As[ty][i] * Bs[tx][i];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        // Add Bias
        if (bias != nullptr) {
            val += bias[col];
        }

        // Apply ReLU if enabled
        if (use_relu) {
            val = fmaxf(0.0f, val);
        }

        c[row * N + col] = val;
    }
}

torch::Tensor linear_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, bool use_relu) {
    int M = input.size(0);
    int K = input.size(1);
    int N = weight.size(0);

    auto output = torch::empty({M, N}, input.options());

    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    if (use_relu) {
        fused_linear_kernel<true><<<grid, block>>>(
            input.data_ptr<float>(), 
            weight.data_ptr<float>(), 
            bias.defined() ? bias.data_ptr<float>() : nullptr, 
            output.data_ptr<float>(), 
            M, N, K);
    } else {
        fused_linear_kernel<false><<<grid, block>>>(
            input.data_ptr<float>(), 
            weight.data_ptr<float>(), 
            bias.defined() ? bias.data_ptr<float>() : nullptr, 
            output.data_ptr<float>(), 
            M, N, K);
    }

    return output;
}
"""

cpp_source = """
torch::Tensor linear_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, bool use_relu);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["linear_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False
)

class FusedLinear(nn.Module):
    """
    Custom Linear layer that fuses Matrix Multiplication, Bias Addition, and optionally ReLU.
    """
    def __init__(self, in_features, out_features, use_relu=False):
        super().__init__()
        self.use_relu = use_relu
        self.in_features = in_features
        self.out_features = out_features

        # Weights are stored as (out_features, in_features) to match nn.Linear
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))

        self.reset_parameters()

    def reset_parameters(self):
        # Initialize weights similar to nn.Linear (Kaiming Uniform)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        # Ensure inputs are contiguous for the CUDA kernel
        if not x.is_contiguous():
            x = x.contiguous()
        return fused_ops.linear_cuda(x, self.weight, self.bias, self.use_relu)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_layer_sizes, output_size):
        super(ModelNew, self).__init__()

        layers = []
        current_input_size = input_size

        # Build layers: Linear + ReLU fused into FusedLinear(use_relu=True)
        for hidden_size in hidden_layer_sizes:
            layers.append(FusedLinear(current_input_size, hidden_size, use_relu=True))
            current_input_size = hidden_size

        # Final layer: Linear only (use_relu=False)
        layers.append(FusedLinear(current_input_size, output_size, use_relu=False))

        self.network = nn.Sequential(*layers)

    def forward(self, x):
        return self.network(x)

