import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define CUDA Kernels for ReLU and specific MaxPool2d (2x2, stride 2)
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cfloat>

// Custom ReLU Kernel
// Simple element-wise operation to replace nn.ReLU
__global__ void relu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor custom_relu_cuda(torch::Tensor input) {
    auto out = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 512;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}

// Custom MaxPool2d Kernel
// Specialized for kernel_size=2, stride=2, which is used throughout VGG.
// This allows avoiding the generic logic overhead of the standard operator.
__global__ void maxpool2d_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                 int n, int c, int h, int w, 
                                 int out_h, int out_w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int num_outputs = n * c * out_h * out_w;

    if (idx < num_outputs) {
        // Map linear index to output coordinates (n, c, ph, pw)
        int pw = idx % out_w;
        int ph = (idx / out_w) % out_h;
        int pc = (idx / (out_w * out_h)) % c;
        int pn = idx / (out_w * out_h * c);

        // Calculate pooling window starting position
        int h_start = ph * 2;
        int w_start = pw * 2;

        // Calculate input pointer offset for (N, C, H, W) layout
        // Flattened index = n*C*H*W + c*H*W + h*W + w
        int input_base = ((pn * c + pc) * h + h_start) * w + w_start;

        float max_val = -FLT_MAX;

        // Unroll the 2x2 loop
        #pragma unroll
        for(int i=0; i<2; ++i) {
            #pragma unroll
            for(int j=0; j<2; ++j) {
                // Read input value
                float val = input[input_base + i * w + j];
                if (val > max_val) max_val = val;
            }
        }
        output[idx] = max_val;
    }
}

torch::Tensor custom_maxpool2d_cuda(torch::Tensor input) {
    // Input shape: (N, C, H, W)
    int n = input.size(0);
    int c = input.size(1);
    int h = input.size(2);
    int w = input.size(3);

    // Calculate output shape for kernel=2, stride=2
    int out_h = h / 2;
    int out_w = w / 2;

    auto output = torch::empty({n, c, out_h, out_w}, input.options());

    int num_outputs = n * c * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (num_outputs + block_size - 1) / block_size;

    maxpool2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        n, c, h, w, out_h, out_w
    );

    return output;
}
"""

cpp_source = """
torch::Tensor custom_relu_cuda(torch::Tensor input);
torch::Tensor custom_maxpool2d_cuda(torch::Tensor input);
"""

# Compile the inline CUDA code
custom_ops = load_inline(
    name='custom_vgg_ops',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['custom_relu_cuda', 'custom_maxpool2d_cuda'],
