import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for ReLU6 and Global Average Pooling
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// ReLU6 Kernel: y = min(max(x, 0), 6)
__global__ void relu6_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        out[idx] = fminf(fmaxf(val, 0.0f), 6.0f);
    }
}

torch::Tensor relu6_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    relu6_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}

// Global Average Pooling Kernel
// Reduces (N, C, H, W) to (N, C, 1, 1)
__global__ void global_avg_pool_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                       int N, int C, int H, int W) {
    // Grid maps to (N, C). Each thread handles one channel of one sample.
    int idx = blockIdx.x * blockDim.x + threadIdx.x; 
    int total_channels = N * C;

    if (idx < total_channels) {
        int spatial_size = H * W;
        // Input is assumed contiguous (N, C, H, W)
        // Offset to the start of the HxW image for this channel
        const float* img_ptr = input + idx * spatial_size;

        float sum = 0.0f;
        for (int i = 0; i < spatial_size; ++i) {
            sum += img_ptr[i];
        }
        output[idx] = sum / (float)spatial_size;
    }
}

torch::Tensor global_avg_pool_cuda(torch::Tensor x) {
    // x: (N, C, H, W)
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto out = torch::empty({N, C, 1, 1}, x.options());

    int total_threads = N * C;
    const int threads_per_block = 256;
    const int blocks = (total_threads + threads_per_block - 1) / threads_per_block;

    global_avg_pool_kernel<<<blocks, threads_per_block>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), N, C, H, W);

    return out;
}
"""

