class CustomReLU6(nn.Module):
    def __init__(self, inplace=False):
        super(CustomReLU6, self).__init__()
        # Note: Inplace optimization is not implemented in this custom kernel for simplicity,
        # but the interface is kept consistent.

    def forward(self, x):
        return custom_ops.relu6_cuda(x)

class CustomGlobalAvgPool2d(nn.Module):
    def __init__(self, output_size=(1, 1)):
        super(CustomGlobalAvgPool2d, self).__init__()

    def forward(self, x):
        # Ensure memory is contiguous for the kernel pointer arithmetic
        if not x.is_contiguous():
            x = x.contiguous()
