import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Define Custom CUDA Kernel for Fused Scale + Causal Mask + Softmax
fused_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = max(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void fused_causal_softmax_kernel(float* __restrict__ data, int batch_heads, int T, float scale) {
    // Each block handles one row of the attention matrix (size T)
    int row = blockIdx.x; 
    if (row >= batch_heads * T) return;

    // Calculate the row index within the sequence (0 to T-1) to determine the causal boundary
    int row_in_seq = row % T; 

    int tid = threadIdx.x;

    // Check bounds. We assume blockDim.x >= T or we handle masking for tid >= T
    // Pointer to the start of the row
    float* row_ptr = data + row * T;

    float val = -INFINITY;

    // 1. Load, Scale, and Mask
    if (tid < T) {
        val = row_ptr[tid];
        val *= scale;
        // Causal Mask: Mask position if column (tid) > row (row_in_seq)
        if (tid > row_in_seq) {
            val = -INFINITY;
        }
    }

    // 2. Compute Max for stability (Block Reduction)
    // Reduce within warp
    float max_val = warpReduceMax(val);

    // Shared memory for partial warp results (max 32 warps for 1024 threads)
    static __shared__ float shared_max[32];
    int lane = tid % 32;
    int wid = tid / 32;

    if (lane == 0) shared_max[wid] = max_val;
    __syncthreads();

    // Reduce across warps (only first warp does this)
    float block_max_val = (tid < ((blockDim.x + 31) / 32)) ? shared_max[lane] : -INFINITY;

    if (wid == 0) {
        block_max_val = warpReduceMax(block_max_val);
        // Store result in shared memory for broadcast
        shared_max[0] = block_max_val; 
    }
    __syncthreads();
    max_val = shared_max[0];

    // 3. Compute Exp and Sum (Block Reduction)
    float exp_val = 0.0f;
    if (tid < T) {
        // Safe exp since val <= max_val
        // If val is -INF, exp is 0
        exp_val = expf(val - max_val);
    }

    float sum_val = warpReduceSum(exp_val);

    static __shared__ float shared_sum[32];
    if (lane == 0) shared_sum[wid] = sum_val;
    __syncthreads();

    float block_sum_val = (tid < ((blockDim.x + 31) / 32)) ? shared_sum[lane] : 0.0f;
    if (wid == 0) {
        block_sum_val = warpReduceSum(block_sum_val);
        shared_sum[0] = block_sum_val;
    }
    __syncthreads();
    sum_val = shared_sum[0];

    // 4. Normalize and Store
    if (tid < T) {
        // Add epsilon to avoid div by zero if completely masked (unlikely on diagonal)
        row_ptr[tid] = exp_val / (sum_val + 1e-9f);
    }
}

torch::Tensor fused_causal_softmax_cuda(torch::Tensor input, float scale) {
    // Input is (Batch, Heads, T, T)
    // Flattened view for kernel: (Batch*Heads*T, T)

    int B = input.size(0);
    int NH = input.size(1);
    int T = input.size(2);

    // Ensure contiguous memory
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    int total_rows = B * NH * T;

    // Determine block size (Next power of 2 covering T)
    int block_size = 32;
    while (block_size < T && block_size < 1024) block_size *= 2;
    // Cap at 1024 (typical max threads per block). 
    // Note: If T > 1024, this simple 1-block-per-row kernel requires modification (looping).
    // Assuming T <= 1024 based on problem constraints.
    if (T > 1024) block_size = 1024; 

    fused_causal_softmax_kernel<<<total_rows, block_size>>>(
        input.data_ptr<float>(), 
        B * NH, 
        T, 
        scale
    );

    return input;
}
"""

