// Simple ReLU kernel: x = max(0, x)
__global__ void relu_kernel(float* x, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float val = x[idx];
        if (val < 0.0f) {
            x[idx] = 0.0f;
        }
    }
}

// Fused Add + ReLU kernel: out = max(0, out + identity)
__global__ void add_relu_kernel(float* out, const float* identity, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float val = out[idx] + identity[idx];
        if (val < 0.0f) {
            val = 0.0f;
        }
        out[idx] = val;
    }
}

// C++ wrapper for ReLU
torch::Tensor custom_relu_cuda(torch::Tensor x) {
    auto n = x.numel();
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;

    // Launch kernel
    relu_kernel<<<blocks, threads>>>(x.data_ptr<float>(), n);

    return x;
}

// C++ wrapper for Fused Add + ReLU
torch::Tensor custom_add_relu_cuda(torch::Tensor out, torch::Tensor identity) {
    auto n = out.numel();
    const int threads = 256;
    const int blocks = (n + threads - 1) / threads;

    // Launch kernel
    add_relu_kernel<<<blocks, threads>>>(out.data_ptr<float>(), identity.data_ptr<float>(), n);

    return out;
}
"""

