import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
# This kernel performs Fused BatchNorm -> ReLU -> AvgPool2d(2,2).
# It takes the input (N, C, H, W) and produces (N, C, H/2, W/2).
# This reduction in spatial resolution allows the subsequent Conv1x1 to run 4x faster.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_bn_relu_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C, int H, int W,
    float epsilon
) {
    // Dimensions of the output tensor
    int out_h = H / 2;
    int out_w = W / 2;
    int total_elements = N * C * out_h * out_w;

    // Grid-stride loop or just check bounds
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Decode linear index to (n, c, h_out, w_out)
        // Output layout is NCHW (contiguous)
        int temp = idx;
        int w_out = temp % out_w;
        temp /= out_w;
        int h_out = temp % out_h;
        temp /= out_h;
        int c = temp % C;
        int n = temp / C;

        // Input strides
        // Input layout is NCHW
        long long input_base = (long long)n * C * H * W + (long long)c * H * W;
        int h_in_start = h_out * 2;
        int w_in_start = w_out * 2;

        // Load BatchNorm parameters for channel c
        float m = mean[c];
        float v = var[c];
        float g = weight[c];
        float b = bias[c];

        // Pre-calculate BN scale and shift
        // y = (x - mean) / sqrt(var + eps) * gamma + beta
        // y = x * (gamma * rsqrt(var + eps)) + (beta - mean * gamma * rsqrt(var + eps))
        float inv_std = rsqrtf(v + epsilon);
        float scale = g * inv_std;
        float shift = b - m * scale;

        float sum = 0.0f;

        // Process 2x2 pooling window
        #pragma unroll
        for (int dy = 0; dy < 2; ++dy) {
            #pragma unroll
            for (int dx = 0; dx < 2; ++dx) {
                int h_in = h_in_start + dy;
                int w_in = w_in_start + dx;

                long long in_idx = input_base + (long long)h_in * W + w_in;
                float x = input[in_idx];

                // Apply BN
                float x_bn = x * scale + shift;

                // Apply ReLU
                float x_relu = x_bn > 0.0f ? x_bn : 0.0f;

                sum += x_relu;
            }
        }

        // Compute Average and store
        output[idx] = sum * 0.25f;
    }
}

torch::Tensor fused_bn_relu_pool_cuda(
    torch::Tensor input,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor weight,
    torch::Tensor bias,
    float epsilon) {

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int out_H = H / 2;
    int out_W = W / 2;

    auto output = torch::empty({N, C, out_H, out_W}, input.options());

    int total_elements = N * C * out_H * out_W;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_bn_relu_pool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        N, C, H, W,
        epsilon
    );

    return output;
}
"""

cpp_source = """
torch::Tensor fused_bn_relu_pool_cuda(
    torch::Tensor input, 
    torch::Tensor mean, 
    torch::Tensor var, 
    torch::Tensor weight, 
    torch::Tensor bias, 
    float epsilon);
"""

# Compile and load the custom operator
fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['fused_bn_relu_pool_cuda'],
    verbose=False,
    extra_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, num_input_features: int, num_output_features: int):
        """
        Optimized Model architecture using custom CUDA kernels and operator reordering.
        Strategy:
        1. Original: BN -> ReLU -> Conv1x1 -> AvgPool
        2. Optimized: Fused(BN -> ReLU -> AvgPool) -> Conv1x1

        Since Conv1x1 is a linear operation per pixel and commutes with AvgPool (linear),
        we can perform the pooling (spatial reduction) *before* the convolution.
        This reduces the number of multiply-adds in the Convolution by 4x (from H*W to H/2*W/2).
        The custom kernel fuses BN, ReLU, and AvgPool into a single pass, saving memory bandwidth.
        """
        super(ModelNew, self).__init__()
        self.bn = nn.BatchNorm2d(num_input_features)
        self.conv = nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False)
        self.fused_ops = fused_ops

    def forward(self, x):
        # Handle BatchNorm statistics logic
        if self.training:
            # Calculate current batch mean and variance
            # torch.var_mean over (N, H, W) dimensions
            var, mean = torch.var_mean(x, dim=(0, 2, 3), unbiased=False, keepdim=False)

            # Update running statistics (standard PyTorch BN behavior)
            n = x.numel() / x.size(1)
            with torch.no_grad():
                self.bn.running_mean.mul_(1 - self.bn.momentum).add_(mean, alpha=self.bn.momentum)
                # Running variance uses unbiased estimate
                var_unbiased = var * (n / (n - 1))
                self.bn.running_var.mul_(1 - self.bn.momentum).add_(var_unbiased, alpha=self.bn.momentum)
        else:
            mean = self.bn.running_mean
            var = self.bn.running_var

        # Execute custom Fused Kernel: BN + ReLU + AvgPool
        # Input: (N, C, H, W) -> Output: (N, C, H/2, W/2)
        x_fused = self.fused_ops.fused_bn_relu_pool_cuda(
            x, mean, var, self.bn.weight, self.bn.bias, self.bn.eps
        )

        # Execute Conv1x1 on the spatially reduced tensor
        out = self.conv(x_fused)

        return out

