import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define Custom CUDA Kernels
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel for ReLU6: min(max(x, 0), 6)
__global__ void relu6_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        val = val < 0.0f ? 0.0f : val;
        val = val > 6.0f ? 6.0f : val;
        output[idx] = val;
    }
}

// Wrapper for ReLU6
torch::Tensor relu6_cuda(torch::Tensor input) {
    auto input_c = input.contiguous();
    auto output = torch::empty_like(input_c);
    int size = input_c.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu6_kernel<<<num_blocks, block_size>>>(
        input_c.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );
    return output;
}

// Kernel for standard ReLU: max(x, 0)
__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = val < 0.0f ? 0.0f : val;
    }
}

// Wrapper for ReLU
torch::Tensor relu_cuda(torch::Tensor input) {
    auto input_c = input.contiguous();
    auto output = torch::empty_like(input_c);
    int size = input_c.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(
        input_c.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );
    return output;
}

// Kernel for Global Average Pooling + Flatten
// Input: (N, C, H, W) -> Output: (N, C)
__global__ void global_avg_pool_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                       int N, int C, int H, int W) {
    // Each thread calculates the average for one channel of one batch item
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * C;

    if (idx < total_threads) {
        int c = idx % C;
        int n = idx / C;

        // Input assumes NCHW contiguous layout
        // Offset to the start of the HxW feature map
        int offset = n * (C * H * W) + c * (H * W);
        const float* input_ptr = input + offset;

        float sum = 0.0f;
        int spatial = H * W;
        // Simple loop reduction (efficient for small spatial dims like 7x7 in EfficientNet)
        for (int i = 0; i < spatial; ++i) {
            sum += input_ptr[i];
        }

        output[idx] = sum / (float)spatial;
    }
}

