import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------------
# Custom CUDA Kernel for Fused GRU Cell
# --------------------------------------------------------------------------------
# This kernel fuses the element-wise operations of a GRU cell:
# 1. Sigmoid activations for Reset (r) and Update (z) gates.
# 2. Tanh activation for the New (n) gate.
# 3. Element-wise mixing of the hidden state.
#
# It takes pre-computed linear projections (W*x + b) and (W*h + b) as inputs.

gru_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ inline float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void gru_cell_fused_kernel(
    const float* __restrict__ gates_x, 
    const float* __restrict__ gates_h, 
    const float* __restrict__ h_prev, 
    float* __restrict__ h_next,
    int batch_size, 
    int hidden_size) {

    // Global index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int b = idx / hidden_size;
        int h = idx % hidden_size;

        // Stride for the packed gate matrices (3 * hidden_size)
        int row_stride = 3 * hidden_size;

        // Base pointers for this batch index
        const float* gx_row = gates_x + b * row_stride;
        const float* gh_row = gates_h + b * row_stride;

        // ---------------------------------------------------------
        // Reset Gate (r)
        // Offset: 0
        // r = sigmoid((Wx_r + bx_r) + (Wh_r + bh_r))
        // ---------------------------------------------------------
        float r_lin = gx_row[h] + gh_row[h];
        float r = sigmoid(r_lin);

        // ---------------------------------------------------------
        // Update Gate (z)
        // Offset: hidden_size
        // z = sigmoid((Wx_z + bx_z) + (Wh_z + bh_z))
        // ---------------------------------------------------------
        float z_lin = gx_row[h + hidden_size] + gh_row[h + hidden_size];
        float z = sigmoid(z_lin);

        // ---------------------------------------------------------
        // New Gate (n)
        // Offset: 2 * hidden_size
        // n = tanh((Wx_n + bx_n) + r * (Wh_n + bh_n))
        // Note: PyTorch applies bias to both parts.
        // ---------------------------------------------------------
        float n_lin_x = gx_row[h + 2 * hidden_size];
        float n_lin_h = gh_row[h + 2 * hidden_size];
        float n = tanhf(n_lin_x + r * n_lin_h);

        // ---------------------------------------------------------
        // Hidden State Update
        // h_t = (1 - z) * n + z * h_{t-1}
        // ---------------------------------------------------------
        float h_prev_val = h_prev[b * hidden_size + h];
        float h_new_val = (1.0f - z) * n + z * h_prev_val;

        h_next[b * hidden_size + h] = h_new_val;
    }
}

torch::Tensor gru_cell_fused_cuda(
    torch::Tensor gates_x, 
    torch::Tensor gates_h, 
    torch::Tensor h_prev) {

    int batch_size = h_prev.size(0);
    int hidden_size = h_prev.size(1);

    auto h_next = torch::empty_like(h_prev);

    int total_threads = batch_size * hidden_size;
    int threads_per_block = 256;
    int num_blocks = (total_threads + threads_per_block - 1) / threads_per_block;

    gru_cell_fused_kernel<<<num_blocks, threads_per_block>>>(
        gates_x.data_ptr<float>(),
        gates_h.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        h_next.data_ptr<float>(),
        batch_size,
        hidden_size
    );

    return h_next;
}
"""

gru_cpp_source = "torch::Tensor gru_cell_fused_cuda(torch::Tensor gates_x, torch::Tensor gates_h, torch::Tensor h_prev);"

# Compile and load the custom kernel
gru_kernel = load_inline(
    name="gru_fused_ops",
    cpp_sources=gru_cpp_source,
    cuda_sources=gru_source,
    functions=["gru_cell_fused_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        """
        Optimized Model using custom CUDA kernels for GRU computations.
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.bias = bias
        self.batch_first = batch_first

        # We retain nn.GRU to hold parameters in a standard way
        # but we will bypass its forward method and use our custom implementation.
        self.gru = nn.GRU(input_size, hidden_size, num_layers, bias, batch_first, dropout=0, bidirectional=False)

    def forward(self, x, h0):
        # Handle batch_first
        if self.batch_first:
            x = x.transpose(0, 1)

        seq_len, batch_size, _ = x.shape

        # h0 shape: (num_layers, batch, hidden)

        current_input = x
        final_hidden_states = []

        # Loop through each layer manually
        for layer in range(self.num_layers):
            # Access weights directly from the nn.GRU module
            w_ih = getattr(self.gru, f'weight_ih_l{layer}')
            w_hh = getattr(self.gru, f'weight_hh_l{layer}')
            b_ih = getattr(self.gru, f'bias_ih_l{layer}')
            b_hh = getattr(self.gru, f'bias_hh_l{layer}')

            # 1. Pre-compute Input Linear Transformation for the entire sequence at once
            # Reshape to (seq_len * batch_size, input_dim) to use a large GEMM
            # Result: (seq_len, batch_size, 3 * hidden_size)
            input_flat = current_input.view(-1, current_input.size(-1))

            # Compute W_ih * x + b_ih
            gates_x_flat = F.linear(input_flat, w_ih, b_ih)
            gates_x = gates_x_flat.view(seq_len, batch_size, 3 * self.hidden_size)

            # Initial hidden state for this layer
            h_t = h0[layer]

            layer_outputs = []

            # 2. Recurrent loop
            for t in range(seq_len):
                # Compute W_hh * h + b_hh
                # This must be done sequentially as h_t depends on h_{t-1}
                gates_h = F.linear(h_t, w_hh, b_hh)

                # Custom CUDA Kernel: Fused Gate Logic and State Update
                # This replaces multiple split/sigmoid/tanh/add/mul operations
                h_t = gru_kernel.gru_cell_fused_cuda(gates_x[t], gates_h, h_t)

                layer_outputs.append(h_t)

            # Stack outputs for the next layer
            # Shape: (seq_len, batch_size, hidden_size)
            current_input = torch.stack(layer_outputs, dim=0)

            # Save the final hidden state of this layer
            final_hidden_states.append(h_t)

        # Stack final hidden states: (num_layers, batch, hidden)
        h_n = torch.stack(final_hidden_states, dim=0)

        return h_n

