import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source for Fused Scale + Causal Mask + ReLU
# This kernel performs the following element-wise operations efficiently:
# 1. Scaling: x = x * scale
# 2. Causal Masking: if col > row, x = 0 (effectively -inf before ReLU)
# 3. ReLU: x = max(0, x)
fused_attn_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_scale_mask_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float scale,
    int T,
    int numel) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        // The tensor shape is (B, H, T, T)
        // We calculate row and column indices for the last two dimensions (T x T)
        // to determine the position relative to the diagonal.

        int col = idx % T;
        int row = (idx / T) % T;

        // Causal masking logic:
        // In the original code, the upper triangle (col > row) is set to -inf.
        // Since the next operation is ReLU, and ReLU(-inf) = 0, we can simply set these to 0.
        if (col > row) {
            output[idx] = 0.0f;
        } else {
            // Apply scaling
            float val = input[idx] * scale;
            // Apply ReLU
            output[idx] = val > 0.0f ? val : 0.0f;
        }
    }
}

torch::Tensor fused_scale_mask_relu_cuda(torch::Tensor input, float scale) {
    // Ensure input is contiguous for linear indexing
    auto input_contig = input.contiguous();
    auto output = torch::empty_like(input_contig);

    int T = input_contig.size(-1);
    int numel = input_contig.numel();

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    fused_scale_mask_relu_kernel<<<num_blocks, block_size>>>(
        input_contig.data_ptr<float>(),
        output.data_ptr<float>(),
        scale,
        T,
        numel
    );

    return output;
}
"""

fused_attn_cpp_source = (
    "torch::Tensor fused_scale_mask_relu_cuda(torch::Tensor input, float scale);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_attn_cpp_source,
    cuda_sources=fused_attn_source,
    functions=["fused_scale_mask_relu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized version of the Multi-head masked self-attention layer.
    Uses a custom CUDA kernel to fuse Scaling, Causal Masking, and ReLU activation.
    """

    def __init__(self, n_embd, n_head, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.n_head = n_head
        self.n_embd = n_embd
        # The explicit bias buffer is removed as masking is handled dynamically in the kernel

    def forward(self, x):
        B, T, C = x.size()

        # Calculate query, key, values for all heads in batch
        # self.c_attn(x) -> (B, T, 3*C)
        q, k ,v  = self.c_attn(x).split(self.n_embd, dim=2)

        # Reshape to (B, nh, T, hs)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        # Causal self-attention
        # (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        att = q @ k.transpose(-2, -1)

        # Calculate scale factor
        scale = 1.0 / math.sqrt(k.size(-1))

        # Apply Fused Scale + Causal Mask + ReLU using custom CUDA kernel
        # This replaces:
        # att = att * scale
        # att = att.masked_fill(mask == 0, -inf)
        # att = F.relu(att)
        att = fused_ops.fused_scale_mask_relu_cuda(att, scale)

        # Weighted sum of values
        # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = att @ v 

        # Re-assemble all head outputs side by side
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        return y

