        Initialize the Optimized RNN model.
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size

        # Initialize hidden state (using global batch_size as in the original architecture)
        self.hidden = torch.randn((batch_size, hidden_size))

        # We retain the original Linear definition to ensure parameter compatibility 
        # (e.g., loading state_dicts from the original model).
        # The i2h layer weights contain both Input->Hidden and Hidden->Hidden weights.
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)  # Input to hidden
        self.h2o = nn.Linear(hidden_size, output_size)  # Hidden to output

        # Tanh is replaced by the fused custom kernel
        self.fused_ops = fused_rnn_ops

    def forward(self, x: torch.Tensor, initial_hidden=None) -> torch.Tensor:
        """
        Forward pass of the Optimized RNN with Custom CUDA Kernels.
        """
        if initial_hidden is not None:
            self.hidden.copy_(initial_hidden)
        self.hidden = self.hidden.to(x.device)

        # OPTIMIZATION:
        # Instead of torch.cat((x, self.hidden), dim=1), which allocates a large temporary tensor,
        # we virtually split the weights of i2h and perform two separate Matrix Multiplications.
        # This reduces memory bandwidth usage significantly.

        # Slice the weights from the combined Linear layer
        # w_x corresponds to the input part (0 to input_size)
        w_x = self.i2h.weight[:, :self.input_size]
        # w_h corresponds to the hidden part (input_size to end)
        w_h = self.i2h.weight[:, self.input_size:]

        # Compute Matrix Multiplications using PyTorch's optimized cuBLAS calls
        # Note: torch.mm does not add bias.
        gate_x = torch.mm(x, w_x.t())
        gate_h = torch.mm(self.hidden, w_h.t())

        # FUSED KERNEL:
        # Combine the results of the two MMs, add the bias, and apply Tanh in a single CUDA kernel.
        # This replaces: hidden = tanh(gate_x + gate_h + bias)
        self.hidden = self.fused_ops.fused_rnn_cell_cuda(gate_x, gate_h, self.i2h.bias)

        # Compute output (Standard Linear layer is already highly optimized)
        output = self.h2o(self.hidden)

        return output

