import torch
import torch.nn as nn
import torch.nn.functional as F
import torch as th
import math
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for fused Softmax+Slice and fused VLAD aggregation+IntraNorm
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__inline__ __device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0;
    if (wid == 0) val = warpReduceSum(val);
    return val;
}

// Fuses Softmax and Ghost Cluster slicing
// Input: logits (B*N, K+G)
// Output: assignment (B*N, K)
__global__ void softmax_slice_kernel(
    const float* __restrict__ logits, 
    float* __restrict__ assignment, 
    int K, int total_clusters, int size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= size) return;

    const float* row_logits = logits + idx * total_clusters;
    float* row_assign = assignment + idx * K;

    // 1. Max for stability
    float max_val = -1e38f;
    for(int i=0; i<total_clusters; ++i) {
        float val = row_logits[i];
        if(val > max_val) max_val = val;
    }

    // 2. Sum Exp
    float sum_exp = 0.0f;
    for(int i=0; i<total_clusters; ++i) {
        sum_exp += expf(row_logits[i] - max_val);
    }

    // 3. Softmax + Slice (write only K)
    float inv_sum = 1.0f / sum_exp;
    for(int i=0; i<K; ++i) {
        row_assign[i] = expf(row_logits[i] - max_val) * inv_sum;
    }
}

// Fuses VLAD aggregation (residuals) and Intra-Normalization
// Input: assignment (B, N, K), x (B, N, D), clusters (D, K)
// Output: out (B, D, K)
// Grid: (K, B), Block: (D)
__global__ void vlad_kernel(
    const float* __restrict__ assignment, 
    const float* __restrict__ x, 
    const float* __restrict__ clusters, 
    float* __restrict__ out, 
    int B, int N, int K, int D) {

    int k = blockIdx.x;
    int b = blockIdx.y;
    int d = threadIdx.x;

    if (d >= D) return;

    // Load cluster centroid for this (d, k)
    // clusters layout is (1, D, K) row-major -> offset d*K + k
    float c_val = clusters[d * K + k];

    float sum_w = 0.0f;
    float sum_wx = 0.0f;

    // Pointers for x and assignment for the current batch b
    // assignment: (B, N, K) -> offset b*N*K + n*K + k
    const float* a_ptr = assignment + b * N * K + k;

    // x: (B, N, D) -> offset b*N*D + n*D + d
    const float* x_ptr = x + b * N * D + d;

    // Loop over N samples
    for(int n=0; n<N; ++n) {
        float w = *a_ptr;
        float val = *x_ptr;
        sum_w += w;
        sum_wx += w * val;

        a_ptr += K;
        x_ptr += D;
    }

    // Calculate residual: sum(a*x) - sum(a)*c
    float res = sum_wx - sum_w * c_val;

    // Fused Intra-Normalization (L2 norm over D dimension)
    // All threads in block correspond to dimension D for the same (b, k)
    float res_sq = res * res;
    float norm_sq = blockReduceSum(res_sq);

    __shared__ float inv_norm;
    if (threadIdx.x == 0) {
        inv_norm = rsqrtf(norm_sq + 1e-12f);
    }
    __syncthreads();

    res *= inv_norm;

    // Write output
    // out shape (B, D, K) contiguous. Offset b*D*K + d*K + k
    out[b * D * K + d * K + k] = res;
}

torch::Tensor softmax_slice_cuda(torch::Tensor logits, int K) {
    auto B_N = logits.size(0);
    auto total_clusters = logits.size(1);

    auto assignment = torch::empty({B_N, K}, logits.options());

    const int block_size = 256;
    const int num_blocks = (B_N + block_size - 1) / block_size;

    softmax_slice_kernel<<<num_blocks, block_size>>>(
        logits.data_ptr<float>(), 
        assignment.data_ptr<float>(), 
        K, total_clusters, B_N);

    return assignment;
}

torch::Tensor vlad_cuda(torch::Tensor assignment, torch::Tensor x, torch::Tensor clusters) {
    int B = x.size(0);
    int N = x.size(1);
    int D = x.size(2);
    int K = assignment.size(2);

    // Output shape (B, D, K) to match layout required for flattened (B, DK) where K is fast dim
    auto out = torch::empty({B, D, K}, x.options());

    dim3 grid(K, B);
    dim3 block(D); // Assumes D <= 1024

    vlad_kernel<<<grid, block>>>(
        assignment.data_ptr<float>(),
        x.data_ptr<float>(),
        clusters.data_ptr<float>(),
        out.data_ptr<float>(),
        B, N, K, D
    );

    return out;
}
"""

cpp_source = """
torch::Tensor softmax_slice_cuda(torch::Tensor logits, int K);
torch::Tensor vlad_cuda(torch::Tensor assignment, torch::Tensor x, torch::Tensor clusters);
"""

netvlad_kernels = load_inline(
    name="netvlad_kernels",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["softmax_slice_cuda", "vlad_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        # Parameters match original model
        self.clusters = nn.Parameter(init_sc * th.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        self.clusters2 = nn.Parameter(init_sc * th.randn(1, feature_size, cluster_size))

    def forward(self, x, mask=None):
        B, N, D = x.shape

        # 1. Linear Projection & BatchNorm
        # x: B x N x D -> (BN) x D
        x_flat = x.view(-1, self.feature_size)

        # assignment_logits: (BN) x (K+G)
        assignment_logits = th.matmul(x_flat, self.clusters)
        assignment_logits = self.batch_norm(assignment_logits)

        # 2. Custom Kernel: Softmax + Slice Ghost Clusters
        # Replaces F.softmax and slicing
        # Input: (BN, K+G) -> Output: (BN, K)
        assignment = netvlad_kernels.softmax_slice_cuda(assignment_logits, self.cluster_size)

        # Reshape to (B, N, K) for aggregation
        assignment = assignment.view(B, N, self.cluster_size)

        # 3. Custom Kernel: VLAD Aggregation + Intra-Normalization
        # Fuses weighted sum of inputs, weighted sum of clusters, subtraction, and L2 intra-norm
        # Input: assignment (B, N, K), x (B, N, D), clusters2 (1, D, K)
        # Output: (B, D, K)
        vlad = netvlad_kernels.vlad_cuda(assignment, x, self.clusters2)

        # 4. Flatten + Global L2 Normalization
        # vlad is (B, D, K) in memory. Flattening to (B, D*K) keeps D blocks of K. 
        # This matches the logical layout required.
        vlad = vlad.view(B, -1)
        vlad = F.normalize(vlad)

        return vlad

