import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Channel Shuffle
channel_shuffle_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void channel_shuffle_kernel(const float* __restrict__ input, float* __restrict__ output,
                                       int batch_size, int channels, int height, int width, int groups) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int hw = height * width;
    int chw = channels * hw;
    int total_elements = batch_size * chw;

    if (idx < total_elements) {
        // Calculate indices from the linear index
        // idx corresponds to the output tensor position
        int n = idx / chw;
        int rem = idx % chw;
        int c_out = rem / hw;
        int s = rem % hw; // spatial index (h * width + w)

        // The ShuffleNet shuffle operation logic:
        // Python: x.view(N, G, K, H, W).transpose(1, 2).contiguous().view(N, C, H, W)
        // Where C = G * K.
        // The output channel index c_out corresponds to the flattened (K, G) layout.
        // c_out = k * G + g
        // We need to map this back to the input channel index c_in which corresponds to (G, K) layout.
        // c_in = g * K + k

        // Recover k and g from c_out
        int k = c_out / groups;
        int g = c_out % groups;

        // Calculate input channel index
        int channels_per_group = channels / groups; // K
        int c_in = g * channels_per_group + k;

        // Calculate input linear index
        int in_idx = n * chw + c_in * hw + s;

        output[idx] = input[in_idx];
    }
}

torch::Tensor channel_shuffle_cuda(torch::Tensor input, int groups) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::empty_like(input);

    int total_elements = batch_size * channels * height * width;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    channel_shuffle_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels, height, width, groups
    );

    return output;
}
"""

channel_shuffle_cpp_source = "torch::Tensor channel_shuffle_cuda(torch::Tensor input, int groups);"

# Compile the inline CUDA code
channel_shuffle_ext = load_inline(
    name="channel_shuffle_ext",
    cpp_sources=channel_shuffle_cpp_source,
    cuda_sources=channel_shuffle_source,
    functions=["channel_shuffle_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, groups=3):
        """
        Optimized ShuffleNet unit implementation with custom CUDA channel shuffle.
        """
        super(ModelNew, self).__init__()

        assert out_channels % 4 == 0
        mid_channels = out_channels // 4

        # First 1x1 group convolution
        self.conv1 = nn.Conv2d(in_channels, mid_channels, kernel_size=1, stride=1, padding=0, groups=groups, bias=False)
        self.bn1 = nn.BatchNorm2d(mid_channels)

        # Depthwise 3x3 convolution
        self.conv2 = nn.Conv2d(mid_channels, mid_channels, kernel_size=3, stride=1, padding=1, groups=mid_channels, bias=False)
        self.bn2 = nn.BatchNorm2d(mid_channels)

        # Second 1x1 group convolution
        self.conv3 = nn.Conv2d(mid_channels, out_channels, kernel_size=1, stride=1, padding=0, groups=groups, bias=False)
        self.bn3 = nn.BatchNorm2d(out_channels)

        self.groups = groups

        # Shortcut connection
        if in_channels == out_channels:
            self.shortcut = nn.Sequential()
        else:
            self.shortcut = nn.Sequential(
                nn.Conv2d(in_channels, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(out_channels)
            )

    def forward(self, x):
        """
        Forward pass with optimized channel shuffle.
        """
        out = F.relu(self.bn1(self.conv1(x)))
        out = self.bn2(self.conv2(out))

        # Optimized CUDA Shuffle operation
        # Replaces: reshape -> transpose -> reshape
        out = channel_shuffle_ext.channel_shuffle_cuda(out, self.groups)

        out = F.relu(self.bn3(self.conv3(out)))

        out += self.shortcut(x)
        return out

