import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused slicing and linear layer
# This kernel optimizes the post-LSTM operation: out = fc(out[:, -1, :])
# It avoids creating a temporary tensor for the slice and fuses the linear projection.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_last_step_linear_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int seq_len,
    int hidden_dim,
    int output_dim) {

    // Grid dimensions: x -> output features, y -> batch size
    // Each thread computes one output value: output[b, o]
    int o_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int b_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (b_idx < batch_size && o_idx < output_dim) {
        float sum = 0.0f;

        // The input tensor has shape (Batch, Seq_Len, Hidden_Dim)
        // We want to access the last time step: input[b_idx, seq_len-1, :]
        // Memory offset = b_idx * (seq_len * hidden_dim) + (seq_len - 1) * hidden_dim
        // This simplifies to: (b_idx * seq_len + seq_len - 1) * hidden_dim

        int input_row_offset = (b_idx * seq_len + seq_len - 1) * hidden_dim;
        int weight_row_offset = o_idx * hidden_dim;

        // Perform dot product for this specific output element (Matrix-Vector multiply logic)
        for (int h = 0; h < hidden_dim; ++h) {
            sum += input[input_row_offset + h] * weight[weight_row_offset + h];
        }

        // Add bias if present
        if (bias != nullptr) {
            sum += bias[o_idx];
        }

        output[b_idx * output_dim + o_idx] = sum;
    }
}

torch::Tensor fused_last_step_linear_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias) {

    // Check inputs
    auto batch_size = input.size(0);
    auto seq_len = input.size(1);
    auto hidden_dim = input.size(2);
    auto output_dim = weight.size(0);

    // Ensure contiguous memory for raw pointer access
    auto input_contig = input.contiguous();
    auto weight_contig = weight.contiguous();

    auto output = torch::zeros({batch_size, output_dim}, input.options());

    const float* bias_ptr = (bias.defined()) ? bias.data_ptr<float>() : nullptr;

    // Configure kernel launch
    // Block size 16x16 = 256 threads
    dim3 block(16, 16);
    dim3 grid((output_dim + block.x - 1) / block.x, (batch_size + block.y - 1) / block.y);

    fused_last_step_linear_kernel<<<grid, block>>>(
        input_contig.data_ptr<float>(),
        weight_contig.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        seq_len,
        hidden_dim,
        output_dim
    );

    return output;
}
"""

cpp_source = (
    "torch::Tensor fused_last_step_linear_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_last_step_linear",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_last_step_linear_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        super(ModelNew, self).__init__()
        # Initialize LSTM (keeping standard implementation as it wraps efficient CuDNN)
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True, dropout=dropout, bidirectional=True)

        # Initialize weights for the Linear layer manually to be used in custom kernel
        # Bidirectional LSTM output size is hidden_size * 2
        linear_in_features = hidden_size * 2

        # Weights: (output_size, input_size) for linear layer
        self.weight = nn.Parameter(torch.empty(output_size, linear_in_features))
        self.bias = nn.Parameter(torch.empty(output_size))

        # Initialize parameters
        self.reset_parameters()

    def reset_parameters(self):
        # Initialize weights similar to nn.Linear default initialization
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / (fan_in**0.5) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x, h0, c0):
        # Forward propagate LSTM
        # out: tensor of shape (batch_size, seq_length, hidden_size * 2)
        out, _ = self.lstm(x, (h0, c0))

        # Use custom CUDA kernel to fuse slicing the last time step and the linear projection
        # Replaces: out = self.fc(out[:, -1, :])
        out = fused_ops.fused_last_step_linear_cuda(out, self.weight, self.bias)

        return out

