import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for a fused "Select Last Step + Linear Layer" operation
# This kernel takes the full output of the LSTM (Batch, Seq, Hidden), selects the last time step,
# and performs the matrix multiplication and bias addition for the linear layer in one go.
fused_linear_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_last_step_linear_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int seq_len,
    int hidden_size,
    int output_size) 
{
    // Grid dimensions: x = output_size, y = batch_size
    // Block dimensions: x = 256 (fixed block size for reduction)

    int o_idx = blockIdx.x; // Output feature index
    int b_idx = blockIdx.y; // Batch index
    int tid = threadIdx.x;  // Thread index within block

    // Calculate offsets
    // Input is (Batch, Seq, Hidden). We want input[b, -1, :]
    // The flat index start for the last sequence element of batch b is:
    int input_offset = b_idx * seq_len * hidden_size + (seq_len - 1) * hidden_size;

    // Weight is (Output, Hidden). We want row weight[o, :]
    int weight_offset = o_idx * hidden_size;

    float thread_sum = 0.0f;

    // Loop over hidden_size. 
    // If hidden_size > blockDim.x, threads process multiple elements.
    for (int h = tid; h < hidden_size; h += blockDim.x) {
        float in_val = input[input_offset + h];
        float w_val = weight[weight_offset + h];
        thread_sum += in_val * w_val;
    }

    // Shared memory for reduction
    extern __shared__ float sdata[];
    sdata[tid] = thread_sum;
    __syncthreads();

    // Parallel reduction in shared memory
    // Assumes blockDim.x (256) is a power of 2
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // The first thread writes the result + bias to global memory
    if (tid == 0) {
        output[b_idx * output_size + o_idx] = sdata[0] + bias[o_idx];
    }
}

torch::Tensor fused_last_step_linear_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
