    int seq_len = input.size(1);
    int hidden_size = input.size(2);
    int output_size = weight.size(0); // Weight shape is (Out, Hidden)

    auto output = torch::empty({batch_size, output_size}, input.options());

    // Launch configuration
    const int block_size = 256;
    dim3 grid(output_size, batch_size);
    size_t shared_mem_size = block_size * sizeof(float);

    fused_last_step_linear_kernel<<<grid, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        seq_len,
        hidden_size,
        output_size
    );

    return output;
}
