    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        """
        Initialize the Optimized LSTM model.
        """
        super(ModelNew, self).__init__()
        self.hidden_size = hidden_size
        self.num_layers = num_layers

        # Keep the cuDNN optimized LSTM
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers,
                            batch_first=True, dropout=dropout, bidirectional=False)

        # Replace nn.Linear with custom parameters managed manually
        # Weight shape for linear layer: (output_size, hidden_size)
        self.fc_weight = nn.Parameter(torch.Tensor(output_size, hidden_size))
        self.fc_bias = nn.Parameter(torch.Tensor(output_size))

        self.reset_parameters()

    def reset_parameters(self):
        # Initialize parameters to match nn.Linear default initialization
        nn.init.kaiming_uniform_(self.fc_weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.fc_weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.fc_bias, -bound, bound)

    def forward(self, x, h0=None, c0=None):
        """
        Forward pass using custom CUDA kernel for the head.
        """
        batch_size = x.size(0)

        # Initialization logic for hidden states (kept from original)
        if h0 is None:
