import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels
# 1. Element-wise ReLU (In-place)
# 2. Fused ReLU + Global Average Pooling (Gap) for the final classification block
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(float* x, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        if (val < 0) x[idx] = 0;
    }
}

void relu_inplace_cuda(torch::Tensor x) {
    int size = x.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;
    relu_kernel<<<blocks, threads>>>(x.data_ptr<float>(), size);
}

// Fused ReLU + Global Average Pooling
// Input: (N, C, H, W)
// Output: (N, C)
// Grid: (C, N, 1), Block: (256, 1, 1)
__global__ void fused_relu_gap_kernel(const float* __restrict__ x, float* __restrict__ out, 
                                      int C, int H, int W, int HW) {
    // blockIdx.x corresponds to C
    // blockIdx.y corresponds to N
    int c = blockIdx.x;
    int n = blockIdx.y;

    // Offset to the specific (n, c) feature map
    // x is contiguous (N, C, H, W)
    int offset = n * C * HW + c * HW;

    float sum = 0.0f;

    // Iterate over all H*W elements for this channel
    // Stride by blockDim.x to handle HW > blockDim.x
    for (int i = threadIdx.x; i < HW; i += blockDim.x) {
        float val = x[offset + i];
        // Apply ReLU
        sum += (val > 0.0f) ? val : 0.0f;
    }

    // Block reduction (summing partial results from threads)
    // Using shared memory
    static __shared__ float sdata[256];
    int tid = threadIdx.x;
    sdata[tid] = sum;
    __syncthreads();

    // Unrolled reduction for block size 256
    if (tid < 128) sdata[tid] += sdata[tid + 128]; __syncthreads();
    if (tid < 64)  sdata[tid] += sdata[tid + 64];  __syncthreads();
    if (tid < 32)  sdata[tid] += sdata[tid + 32];  __syncthreads();
    if (tid < 16)  sdata[tid] += sdata[tid + 16];  __syncthreads();
    if (tid < 8)   sdata[tid] += sdata[tid + 8];   __syncthreads();
    if (tid < 4)   sdata[tid] += sdata[tid + 4];   __syncthreads();
    if (tid < 2)   sdata[tid] += sdata[tid + 2];   __syncthreads();
    if (tid < 1)   sdata[tid] += sdata[tid + 1];   __syncthreads();

    // Write result
    if (tid == 0) {
        out[n * C + c] = sdata[0] / (float)HW;
    }
}

torch::Tensor fused_relu_gap_cuda(torch::Tensor x) {
    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);
    auto HW = H * W;

    auto out = torch::empty({N, C}, x.options());

    dim3 grid(C, N);
    dim3 block(256);

    fused_relu_gap_kernel<<<grid, block>>>(x.data_ptr<float>(), out.data_ptr<float>(), C, H, W, HW);

    return out;
}
"""

cpp_source = """
void relu_inplace_cuda(torch::Tensor x);
torch::Tensor fused_relu_gap_cuda(torch::Tensor x);
"""

# Compile and load the custom kernels
cuda_ops = load_inline(
    name="dense_net_custom_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["relu_inplace_cuda", "fused_relu_gap_cuda"],
    verbose=False,
)

class CustomReLU(nn.Module):
    """
    Custom ReLU module that uses the optimized CUDA kernel when available.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x):
        if x.is_cuda:
            cuda_ops.relu_inplace_cuda(x)
        else:
            F.relu(x, inplace=True)
        return x

class DenseBlock(nn.Module):
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        super(DenseBlock, self).__init__()
        layers = []
        for i in range(num_layers):
            layers.append(self._make_layer(num_input_features + i * growth_rate, growth_rate))
        self.layers = nn.ModuleList(layers)

    def _make_layer(self, in_features: int, growth_rate: int):
        return nn.Sequential(
            nn.BatchNorm2d(in_features),
            CustomReLU(), # Replaced standard ReLU
            nn.Conv2d(in_features, growth_rate, kernel_size=3, padding=1, bias=False),
            nn.Dropout(0.0)
        )

    def forward(self, x):
        features = [x]
        for layer in self.layers:
            new_feature = layer(x)
            features.append(new_feature)
            x = torch.cat(features, 1)
        return x

class TransitionLayer(nn.Module):
    def __init__(self, num_input_features: int, num_output_features: int):
        super(TransitionLayer, self).__init__()
        self.transition = nn.Sequential(
            nn.BatchNorm2d(num_input_features),
            CustomReLU(), # Replaced standard ReLU
            nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False),
            nn.AvgPool2d(kernel_size=2, stride=2)
        )

    def forward(self, x):
        return self.transition(x)

class ModelNew(nn.Module):
    def __init__(self, growth_rate: int = 32, num_classes: int = 1000):
        super(ModelNew, self).__init__()

        # Initial convolution and pooling
        self.features = nn.Sequential(
            nn.Conv2d(3, 64, kernel_size=7, stride=2, padding=3, bias=False),
            nn.BatchNorm2d(64),
            CustomReLU(), # Replaced standard ReLU
            nn.MaxPool2d(kernel_size=3, stride=2, padding=1)
        )

        num_features = 64
        block_layers = [6, 12, 24, 16]

        self.dense_blocks = nn.ModuleList()
        self.transition_layers = nn.ModuleList()

        for i, num_layers in enumerate(block_layers):
            block = DenseBlock(num_layers=num_layers, num_input_features=num_features, growth_rate=growth_rate)
            self.dense_blocks.append(block)
            num_features = num_features + num_layers * growth_rate

            if i != len(block_layers) - 1:
                transition = TransitionLayer(num_input_features=num_features, num_output_features=num_features // 2)
                self.transition_layers.append(transition)
                num_features = num_features // 2

        # Final batch norm and classifier
        self.final_bn = nn.BatchNorm2d(num_features)
        self.classifier = nn.Linear(num_features, num_classes)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.features(x)

        for i, block in enumerate(self.dense_blocks):
            x = block(x)
            if i != len(self.dense_blocks) - 1:
                x = self.transition_layers[i](x)

        x = self.final_bn(x)

        # Use fused kernel for ReLU + AdaptiveAvgPool + Flatten
        if x.is_cuda:
            x = cuda_ops.fused_relu_gap_cuda(x)
        else:
            x = F.relu(x, inplace=True)
            x = F.adaptive_avg_pool2d(x, (1, 1)).view(x.size(0), -1)

        x = self.classifier(x)
        return x

def get_inputs():
    batch_size = 10
    height, width = 224, 224
    return [torch.rand(batch_size, 3, height, width).cuda()]

def get_init_inputs():
    num_classes = 10
    return [32, num_classes]

