#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void maxpool3x3_s1_p1_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output, 
    int batch, int channels, int height, int width) 
{
    // Use a flat index mapping
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int num_elements = batch * channels * height * width;

    if (idx < num_elements) {
        // Calculate dimensions from flat index (assuming NCHW layout)
        int w_out = idx % width;
        int h_out = (idx / width) % height;
        int c = (idx / (width * height)) % channels;
        int n = idx / (width * height * channels);

        // Calculate offset for the current image and channel
        int input_offset = n * (channels * height * width) + c * (height * width);

        // Initialize max_val to a very small number
        float max_val = -FLT_MAX;

        // Unrolled 3x3 window loop
        #pragma unroll
        for (int i = 0; i < 3; ++i) {
            #pragma unroll
            for (int j = 0; j < 3; ++j) {
                // Determine input indices with padding=1
                // The window centered at (h_out, w_out) effectively corresponds to 
                // input range [h_out-1, h_out+1]
                int h_in = h_out + i - 1;
                int w_in = w_out + j - 1;

                float val;
                // Boundary checks for padding
                if (h_in >= 0 && h_in < height && w_in >= 0 && w_in < width) {
                    val = input[input_offset + h_in * width + w_in];
                } else {
                    val = -FLT_MAX; // Padding value
                }

                max_val = fmaxf(max_val, val);
            }
        }

        output[idx] = max_val;
    }
}

torch::Tensor maxpool_cuda(torch::Tensor input) {
    // Determine input dimensions
    int batch = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    // Output has the same shape as input for k=3, s=1, p=1
    auto output = torch::empty_like(input);

    int num_elements = batch * channels * height * width;
    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    maxpool3x3_s1_p1_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        batch, channels, height, width
    );

    return output;
}
"""

