    def __init__(self, in_channels, out_1x1, reduce_3x3, out_3x3, reduce_5x5, out_5x5, pool_proj):
        super(ModelNew, self).__init__()

        # Algorithmic Optimization: Operator Fusion
        # Fuse the initial 1x1 convolutions from branch1x1, branch3x3, and branch5x5
        # into a single convolution to increase arithmetic intensity and reduce kernel launches.
        self.out_1x1 = out_1x1
        self.reduce_3x3 = reduce_3x3
        self.reduce_5x5 = reduce_5x5

        fused_out_channels = out_1x1 + reduce_3x3 + reduce_5x5
        self.fused_1x1 = nn.Conv2d(in_channels, fused_out_channels, kernel_size=1)

        # Subsequent layers for the 3x3 branch
        self.branch3x3_conv = nn.Conv2d(reduce_3x3, out_3x3, kernel_size=3, padding=1)

        # Subsequent layers for the 5x5 branch
        self.branch5x5_conv = nn.Conv2d(reduce_5x5, out_5x5, kernel_size=5, padding=2)

        # Pooling branch
