import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm>

// ------------------------------------------------------------------
// 1. Simple ReLU Kernel
// ------------------------------------------------------------------
__global__ void simple_relu_kernel(const float* __restrict__ inp, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = inp[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor simple_relu_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    input = input.contiguous();
    auto out = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    simple_relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

// ------------------------------------------------------------------
// 2. Fused ReLU + Concat Kernel
//    Performs: cat([relu(t1), relu(t2)], dim=1)
// ------------------------------------------------------------------
__global__ void fused_relu_concat_kernel(
    const float* __restrict__ t1,
    const float* __restrict__ t2,
    float* __restrict__ out,
    int N, int C1, int C2, int HW,
    int total_elements) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    int C_out = C1 + C2;
    int block_len = C_out * HW;
    int split_len = C1 * HW;

    for (int i = idx; i < total_elements; i += stride) {
        // Map linear index to interleaved layout:
        // Output buffer structure:
        // Batch 0: [t1_data (C1*HW)] [t2_data (C2*HW)]
        // Batch 1: [t1_data (C1*HW)] [t2_data (C2*HW)]

        int n = i / block_len;
        int rem = i % block_len;

        float val;
        if (rem < split_len) {
            // Belongs to t1
            // Index in t1: n * (C1*HW) + rem
            int t1_idx = n * split_len + rem;
            val = t1[t1_idx];
        } else {
            // Belongs to t2
            // Index in t2: n * (C2*HW) + (rem - split_len)
            int t2_idx = n * (C2 * HW) + (rem - split_len);
            val = t2[t2_idx];
        }

        // Apply ReLU
        out[i] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor fused_relu_concat_cuda(torch::Tensor t1, torch::Tensor t2) {
    TORCH_CHECK(t1.is_cuda(), "t1 must be a CUDA tensor");
    TORCH_CHECK(t2.is_cuda(), "t2 must be a CUDA tensor");
    t1 = t1.contiguous();
    t2 = t2.contiguous();

    int N = t1.size(0);
    int C1 = t1.size(1);
    int C2 = t2.size(1);
    int H = t1.size(2);
    int W = t1.size(3);
    int HW = H * W;

    auto out = torch::empty({N, C1 + C2, H, W}, t1.options());
    int total_elements = out.numel();

    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;
    // Limit grid size to ensure launch succeeds
    if (num_blocks > 65535) num_blocks = 65535;

    fused_relu_concat_kernel<<<num_blocks, block_size>>>(
        t1.data_ptr<float>(), t2.data_ptr<float>(), out.data_ptr<float>(),
        N, C1, C2, HW, total_elements);

    return out;
}

// ------------------------------------------------------------------
// 3. Fused ReLU + Global Average Pooling Kernel
//    Performs: AdaptiveAvgPool2d((1,1)) on ReLU(x), output flattened
// ------------------------------------------------------------------
__global__ void relu_avg_pool_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int HW) {

    // Grid dim: (N, C)
    int n = blockIdx.x; 
    int c = blockIdx.y; 
    int tid = threadIdx.x;

    // C is effectively gridDim.y
    int C = gridDim.y;

    // Pointer to the start of channel (n, c)
    // Offset = n * (C * HW) + c * HW
    const float* input_channel = inp + (n * C * HW) + (c * HW);

    float sum = 0.0f;
    // Stride loop to sum all pixels in the channel
    for (int i = tid; i < HW; i += blockDim.x) {
        float val = input_channel[i];
        sum += (val > 0.0f ? val : 0.0f); // Apply ReLU on load
    }

    // Block reduction using shared memory
    __shared__ float sdata[256];
    sdata[tid] = sum;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[n * C + c] = sdata[0] / (float)HW;
    }
}

torch::Tensor relu_avg_pool_cuda(torch::Tensor inp) {
    TORCH_CHECK(inp.is_cuda(), "Input must be a CUDA tensor");
    inp = inp.contiguous();

    int N = inp.size(0);
    int C = inp.size(1);
    int H = inp.size(2);
    int W = inp.size(3);
    int HW = H * W;

    // Output shape (N, C)
    auto out = torch::empty({N, C}, inp.options());

    dim3 grid(N, C);
    dim3 block(256);

    relu_avg_pool_kernel<<<grid, block>>>(inp.data_ptr<float>(), out.data_ptr<float>(), HW);

    return out;
}
"""

cpp_source = """
torch::Tensor simple_relu_cuda(torch::Tensor input);
torch::Tensor fused_relu_concat_cuda(torch::Tensor t1, torch::Tensor t2);
torch::Tensor relu_avg_pool_cuda(torch::Tensor inp);
"""

# Compile the inline CUDA code
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["simple_relu_cuda", "fused_relu_concat_cuda", "relu_avg_pool_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class FireModuleNew(nn.Module):
    def __init__(self, in_channels, squeeze_channels, expand1x1_channels, expand3x3_channels):
        super(FireModuleNew, self).__init__()

        self.squeeze = nn.Conv2d(in_channels, squeeze_channels, kernel_size=1)
        # Squeeze activation handled by simple_relu_cuda

