import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernel for fused Add + ReLU
# This fuses the element-wise addition of the residual connection and the subsequent ReLU activation
# into a single kernel to reduce memory bandwidth usage.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_add_relu_kernel(float* out, const float* identity, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = out[idx] + identity[idx];
        // ReLU
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor fused_add_relu_cuda(torch::Tensor out, torch::Tensor identity) {
    // Ensure inputs are contiguous for direct pointer access
    // If they are not, .contiguous() returns a copy, which is safe to modify in-place for the return value
    if (!out.is_contiguous()) out = out.contiguous();
    if (!identity.is_contiguous()) identity = identity.contiguous();

    auto size = out.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_add_relu_kernel<<<num_blocks, block_size>>>(
        out.data_ptr<float>(),
        identity.data_ptr<float>(),
        size
    );

    return out;
}
"""

cpp_source = """
torch::Tensor fused_add_relu_cuda(torch::Tensor out, torch::Tensor identity);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_resnet_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_add_relu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    expansion = 1

    def __init__(self, in_channels, out_channels, stride=1):
        """
        :param in_channels: Number of input channels
        :param out_channels: Number of output channels
        :param stride: Stride for the first convolutional layer
        """
        super(ModelNew, self).__init__()
        # Standard layers are kept as they are highly optimized in PyTorch/cuDNN
        self.conv1 = nn.Conv2d(in_channels, out_channels, kernel_size=3, stride=stride, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(out_channels)
        self.relu = nn.ReLU(inplace=True)
        self.conv2 = nn.Conv2d(out_channels, out_channels, kernel_size=3, stride=1, padding=1, bias=False)
        self.bn2 = nn.BatchNorm2d(out_channels)

        self.downsample = nn.Sequential(
            nn.Conv2d(in_channels, out_channels * self.expansion, kernel_size=1, stride=stride, bias=False),
            nn.BatchNorm2d(out_channels * self.expansion),
        )
        self.stride = stride

    def forward(self, x):
        """
        :param x: Input tensor, shape (batch_size, in_channels, height, width)
        :return: Output tensor, shape (batch_size, out_channels, height, width)
        """
        identity = x

        out = self.conv1(x)
        out = self.bn1(out)
        out = self.relu(out)

        out = self.conv2(out)
        out = self.bn2(out)

        if self.downsample is not None:
            identity = self.downsample(x)

        # Replaced standard pytorch addition and relu with fused custom kernel
        # Original:
        # out += identity
        # out = self.relu(out)

        # New optimized path:
        out = fused_ops.fused_add_relu_cuda(out, identity)

        return out

