import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels
# 1. fast_relu_cuda: In-place ReLU element-wise kernel.
# 2. fused_maxpool_relu_cuda: Fused MaxPool2d and ReLU kernel. 
#    Optimizes by combining the pooling and activation, reducing memory bandwidth 
#    and potentially calculating ReLU on fewer elements (after pooling).
#    Logic: ReLU(MaxPool(x)) == MaxPool(ReLU(x)). 
#    We perform pooling then clamp output to >= 0.

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void relu_kernel(float* x, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        x[idx] = fmaxf(x[idx], 0.0f);
    }
}

__global__ void fused_maxpool_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int n_elements,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int kernel_size, int stride, int padding
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < n_elements) {
        // Map linear index to output coordinates (n, c, h_out, w_out)
        int w_out_idx = idx % W_out;
        int temp = idx / W_out;
        int h_out_idx = temp % H_out;
        int temp2 = temp / H_out;
        int c_idx = temp2 % C;
        int n_idx = temp2 / C;

        // Calculate input window start
        int h_start = h_out_idx * stride - padding;
        int w_start = w_out_idx * stride - padding;

        float max_val = -FLT_MAX;

        // Pointer arithmetic for the specific channel/image
        int input_offset = n_idx * (C * H * W) + c_idx * (H * W);
        const float* input_slice = input + input_offset;

        // MaxPool Loop
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h_in = h_start + kh;
                int w_in = w_start + kw;

                if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                    float val = input_slice[h_in * W + w_in];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }

        // Fused ReLU: Apply ReLU to the pooled result
        output[idx] = fmaxf(max_val, 0.0f);
    }
}

torch::Tensor fast_relu_cuda(torch::Tensor input) {
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), size);

    return input;
}

torch::Tensor fused_maxpool_relu_cuda(torch::Tensor input, int kernel_size, int stride, int padding) {
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int H_out = (H + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    int num_kernels = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (num_kernels + block_size - 1) / block_size;

    fused_maxpool_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_kernels,
        N, C, H, W,
        H_out, W_out,
        kernel_size, stride, padding
    );

    return output;
}
"""

cpp_source = """
torch::Tensor fast_relu_cuda(torch::Tensor input);
torch::Tensor fused_maxpool_relu_cuda(torch::Tensor input, int kernel_size, int stride, int padding);
"""

# Compile and load the custom kernels
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fast_relu_cuda", "fused_maxpool_relu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()

        # Keep Conv layers standard (cuDNN is hard to beat)
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self.conv2 = nn.Conv2d(in_channels=96, out_channels=256, kernel_size=5, padding=2)
        self.conv3 = nn.Conv2d(in_channels=256, out_channels=384, kernel_size=3, padding=1)
        self.conv4 = nn.Conv2d(in_channels=384, out_channels=384, kernel_size=3, padding=1)
        self.conv5 = nn.Conv2d(in_channels=384, out_channels=256, kernel_size=3, padding=1)

        # Fully connected layers
        self.fc1 = nn.Linear(in_features=256 * 6 * 6, out_features=4096)
        self.fc2 = nn.Linear(in_features=4096, out_features=4096)
        self.fc3 = nn.Linear(in_features=4096, out_features=num_classes)

        self.ops = custom_ops

    def forward(self, x):
        # Optimized Block 1: Conv -> Fused MaxPool+ReLU
        # Original: Conv -> ReLU -> MaxPool
        x = self.conv1(x)
        # kernel=3, stride=2, padding=0 (default for MaxPool2d)
        x = self.ops.fused_maxpool_relu_cuda(x, 3, 2, 0)

        # Optimized Block 2: Conv -> Fused MaxPool+ReLU
        x = self.conv2(x)
        x = self.ops.fused_maxpool_relu_cuda(x, 3, 2, 0)

        # Optimized Block 3: Conv -> FastReLU
        x = self.conv3(x)
        x = self.ops.fast_relu_cuda(x)

        # Optimized Block 4: Conv -> FastReLU
        x = self.conv4(x)
        x = self.ops.fast_relu_cuda(x)

        # Optimized Block 5: Conv -> Fused MaxPool+ReLU
        x = self.conv5(x)
        x = self.ops.fused_maxpool_relu_cuda(x, 3, 2, 0)

        x = torch.flatten(x, 1)

        # FC layers: Linear -> FastReLU
        # Dropout removed as it was p=0.0 (identity)
        x = self.fc1(x)
        x = self.ops.fast_relu_cuda(x)

        x = self.fc2(x)
        x = self.ops.fast_relu_cuda(x)

        x = self.fc3(x)

        return x

