import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# -----------------------------------------------------------------------------------------
# Custom CUDA Operators Implementation
# -----------------------------------------------------------------------------------------

cpp_source = """
torch::Tensor relu_cuda(torch::Tensor input);
torch::Tensor avgpool2x2_cuda(torch::Tensor input);
torch::Tensor global_avgpool_cuda(torch::Tensor input);
"""

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// -----------------------------------------------------------------------------------------
// Kernel: ReLU
// Simple element-wise ReLU: f(x) = max(0, x)
// -----------------------------------------------------------------------------------------
__global__ void relu_kernel(const float* __restrict__ x, float* __restrict__ out, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float val = x[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor relu_cuda(torch::Tensor input) {
    auto x = input.contiguous();
    auto out = torch::empty_like(x);
    int n = x.numel();
    int threads = 256;
    int blocks = (n + threads - 1) / threads;

    relu_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(), n);
    return out;
}

// -----------------------------------------------------------------------------------------
// Kernel: 2x2 Average Pooling
// Fixed kernel_size=2, stride=2. Matches nn.AvgPool2d(2, stride=2)
// -----------------------------------------------------------------------------------------
__global__ void avgpool2x2_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                  int C, int H, int W, int out_H, int out_W, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Map linear index to output coordinates (n, c, oh, ow)
        int temp = idx;
        int ow = temp % out_W; temp /= out_W;
        int oh = temp % out_H; temp /= out_H;
        int c  = temp % C;     temp /= C;
        int n  = temp;

        // Input top-left coordinates
        int ih = oh * 2;
        int iw = ow * 2;

        // Linear input index
        int in_base = ((n * C + c) * H + ih) * W + iw;

        // Sum 2x2 block
        float val = input[in_base];
        val += input[in_base + 1];
        val += input[in_base + W];
        val += input[in_base + W + 1];

        output[idx] = val * 0.25f;
    }
}

torch::Tensor avgpool2x2_cuda(torch::Tensor input) {
    auto x = input.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    // Output dimensions (floor logic)
    int out_H = H / 2;
    int out_W = W / 2;

    auto out = torch::empty({N, C, out_H, out_W}, x.options());
    int total = N * C * out_H * out_W;

    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    avgpool2x2_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(),
                                           C, H, W, out_H, out_W, total);
    return out;
}

// -----------------------------------------------------------------------------------------
// Kernel: Global Average Pooling
// Reduces (N, C, H, W) -> (N, C, 1, 1). Efficient for small spatial maps (end of network).
// -----------------------------------------------------------------------------------------
__global__ void global_avgpool_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                      int C, int H, int W, int total_elements) {
    // One thread per output channel (N * C)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int n = idx / C;
        int c = idx % C;

        const float* img_ptr = input + (n * C + c) * H * W;
        float sum = 0.0f;
        int size = H * W;

        // Simple serial reduction per thread (efficient for small feature maps e.g. 7x7)
        for (int i = 0; i < size; ++i) {
            sum += img_ptr[i];
        }
        output[idx] = sum / (float)size;
    }
}

torch::Tensor global_avgpool_cuda(torch::Tensor input) {
    auto x = input.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto out = torch::empty({N, C, 1, 1}, x.options());
    int total = N * C;

    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    global_avgpool_kernel<<<blocks, threads>>>(x.data_ptr<float>(), out.data_ptr<float>(),
                                               C, H, W, total);
    return out;
}
"""

densenet_ops = load_inline(
    name='densenet_ops',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['relu_cuda', 'avgpool2x2_cuda', 'global_avgpool_cuda'],
    verbose=False
)

# -----------------------------------------------------------------------------------------
# New Architecture Definition using Custom Kernels
# -----------------------------------------------------------------------------------------

class CustomReLU(nn.Module):
    def __init__(self, inplace=False):
        super().__init__()
        # Note: inplace is ignored here, the custom kernel returns a new tensor.
        # This is compatible functionality-wise.

    def forward(self, x):
        return densenet_ops.relu_cuda(x)

class CustomAvgPool2x2(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return densenet_ops.avgpool2x2_cuda(x)

class DenseBlockNew(nn.Module):
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        super(DenseBlockNew, self).__init__()
        layers = []
        for i in range(num_layers):
            layers.append(self._make_layer(num_input_features + i * growth_rate, growth_rate))
        self.layers = nn.ModuleList(layers)

    def _make_layer(self, in_features: int, growth_rate: int):
        # Replaced nn.ReLU with CustomReLU
        return nn.Sequential(
            nn.BatchNorm2d(in_features),
            CustomReLU(inplace=True),
            nn.Conv2d(in_features, growth_rate, kernel_size=3, padding=1, bias=False),
            nn.Dropout(0.0)
        )

    def forward(self, x):
        features = [x]
        for layer in self.layers:
            new_feature = layer(x)
            features.append(new_feature)
            x = torch.cat(features, 1)
        return x

class TransitionLayerNew(nn.Module):
    def __init__(self, num_input_features: int, num_output_features: int):
        super(TransitionLayerNew, self).__init__()
        # Replaced nn.ReLU with CustomReLU and nn.AvgPool2d with CustomAvgPool2x2
        self.transition = nn.Sequential(
            nn.BatchNorm2d(num_input_features),
            CustomReLU(inplace=True),
            nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False),
            CustomAvgPool2x2()
        )

    def forward(self, x):
        return self.transition(x)

class ModelNew(nn.Module):
    def __init__(self, growth_rate: int = 32, num_classes: int = 1000):
        super(ModelNew, self).__init__()

        # Replaced nn.ReLU with CustomReLU
        self.features = nn.Sequential(
            nn.Conv2d(3, 64, kernel_size=7, stride=2, padding=3, bias=False),
            nn.BatchNorm2d(64),
            CustomReLU(inplace=True),
            nn.MaxPool2d(kernel_size=3, stride=2, padding=1)
        )

        num_features = 64
        block_layers = [6, 12, 48, 32]

        self.dense_blocks = nn.ModuleList()
        self.transition_layers = nn.ModuleList()

        for i, num_layers in enumerate(block_layers):
            block = DenseBlockNew(num_layers=num_layers, num_input_features=num_features, growth_rate=growth_rate)
            self.dense_blocks.append(block)
            num_features = num_features + num_layers * growth_rate

            if i != len(block_layers) - 1:
                transition = TransitionLayerNew(num_input_features=num_features, num_output_features=num_features // 2)
                self.transition_layers.append(transition)
                num_features = num_features // 2

        self.final_bn = nn.BatchNorm2d(num_features)
        self.classifier = nn.Linear(num_features, num_classes)
        self.final_relu = CustomReLU(inplace=True)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.features(x)

        for i, block in enumerate(self.dense_blocks):
            x = block(x)
            if i != len(self.dense_blocks) - 1:
                x = self.transition_layers[i](x)

        x = self.final_bn(x)
        x = self.final_relu(x)

        # Replaced F.adaptive_avg_pool2d with Custom Global Avg Pool Kernel
        x = densenet_ops.global_avgpool_cuda(x)

        x = x.view(x.size(0), -1)
        x = self.classifier(x)
        return x

