import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for LSTM
lstm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>
#include <math.h>

__device__ __forceinline__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ __forceinline__ float tanh_opt(float x) {
    return tanhf(x);
}

__global__ void lstm_cell_kernel(
    const float* __restrict__ wx,      // (Seq, Batch, 4*H)
    const float* __restrict__ wh_t,    // (H, 4*H) Transposed weights
    const float* __restrict__ bias,    // (4*H)
    const float* __restrict__ h0,      // (Batch, H)
    const float* __restrict__ c0,      // (Batch, H)
    float* __restrict__ h_out,         // (Seq, Batch, H)
    float* __restrict__ h_last,        // (Batch, H)
    float* __restrict__ c_last,        // (Batch, H)
    int seq_len,
    int batch_size,
    int hidden_size) 
{
    // Shared memory for h_prev
    extern __shared__ float smem_h[];

    int tid = threadIdx.x;
    int bid = blockIdx.x;

    if (bid >= batch_size || tid >= hidden_size) return;

    // Initialize state
    float h_curr = (h0 != nullptr) ? h0[bid * hidden_size + tid] : 0.0f;
    float c_curr = (c0 != nullptr) ? c0[bid * hidden_size + tid] : 0.0f;

    // Load initial h into shared memory
    smem_h[tid] = h_curr;
    __syncthreads();

    // Strides
    int wx_stride_seq = batch_size * 4 * hidden_size;
    int wx_stride_batch = 4 * hidden_size;
    int wh_stride_row = 4 * hidden_size; // wh_t is (H, 4H)

    // Offsets for gates in the 4H dimension
    int off_i = 0;
    int off_f = hidden_size;
    int off_g = 2 * hidden_size;
    int off_o = 3 * hidden_size;

    for (int t = 0; t < seq_len; t++) {
        // Compute the gates for this thread (which corresponds to one hidden unit)
        // We need to compute i[tid], f[tid], g[tid], o[tid]

        int base_wx = t * wx_stride_seq + bid * wx_stride_batch;

        // Load bias + input projection
        float val_i = bias[off_i + tid] + wx[base_wx + off_i + tid];
        float val_f = bias[off_f + tid] + wx[base_wx + off_f + tid];
        float val_g = bias[off_g + tid] + wx[base_wx + off_g + tid];
        float val_o = bias[off_o + tid] + wx[base_wx + off_o + tid];

        // Perform matrix-vector multiplication part for H: h_prev @ wh_t
        // We need the dot product of h_prev (1xH) and the column of wh_t corresponding to this gate/unit.
        // Since wh_t is row-major (H, 4H), the "column" is actually stride 4H accesses?
        // No, we passed wh_t as (H, 4H). The weights for computing output `u` are in column `u`.
        // So we want dot(h_prev, column `off_x + tid` of wh_t).
        // column `c` of wh_t is formed by elements wh_t[k][c] for k in 0..H.
        // In flat memory: wh_t[k * 4H + c].

        float dot_i = 0.0f;
        float dot_f = 0.0f;
        float dot_g = 0.0f;
        float dot_o = 0.0f;

        // Loop over the hidden size to accumulate dot product
        // This loop reads h_prev from shared memory (fast) and wh_t from global (coalesced-ish if offsets align)
        for (int k = 0; k < hidden_size; k++) {
            float hk = smem_h[k];
            int row_offset = k * wh_stride_row;
            dot_i += hk * wh_t[row_offset + off_i + tid];
            dot_f += hk * wh_t[row_offset + off_f + tid];
            dot_g += hk * wh_t[row_offset + off_g + tid];
            dot_o += hk * wh_t[row_offset + off_o + tid];
        }

        val_i += dot_i;
        val_f += dot_f;
        val_g += dot_g;
        val_o += dot_o;

        // Apply activations
        float sig_i = sigmoid(val_i);
        float sig_f = sigmoid(val_f);
        float tanh_g = tanh_opt(val_g);
        float sig_o = sigmoid(val_o);

        // Update cell state and hidden state
        c_curr = sig_f * c_curr + sig_i * tanh_g;
        h_curr = sig_o * tanh_opt(c_curr);

        // Wait for all threads to finish computation before updating shared memory
        __syncthreads();
        smem_h[tid] = h_curr;
        __syncthreads(); // Wait for update before next iteration reads

        // Store output for this timestep
        h_out[t * (batch_size * hidden_size) + bid * hidden_size + tid] = h_curr;
    }

    // Store final states
    h_last[bid * hidden_size + tid] = h_curr;
    c_last[bid * hidden_size + tid] = c_curr;
}

std::vector<torch::Tensor> lstm_forward_cuda(
    torch::Tensor wx, 
    torch::Tensor wh, 
    torch::Tensor bias, 
    torch::Tensor h0, 
    torch::Tensor c0,
    int hidden_size) {

    auto seq_len = wx.size(0);
    auto batch_size = wx.size(1);

    // Output tensors
    auto options = wx.options();
    auto h_out = torch::empty({seq_len, batch_size, hidden_size}, options);
    auto h_last = torch::empty({batch_size, hidden_size}, options);
    auto c_last = torch::empty({batch_size, hidden_size}, options);

    // Launch configuration
    dim3 grid(batch_size);
    dim3 block(hidden_size);
    int smem_size = hidden_size * sizeof(float);

    lstm_cell_kernel<<<grid, block, smem_size>>>(
        wx.data_ptr<float>(),
        wh.data_ptr<float>(),
        bias.data_ptr<float>(),
        h0.defined() ? h0.data_ptr<float>() : nullptr,
        c0.defined() ? c0.data_ptr<float>() : nullptr,
        h_out.data_ptr<float>(),
        h_last.data_ptr<float>(),
        c_last.data_ptr<float>(),
        seq_len,
        batch_size,
        hidden_size
    );

    return {h_out, h_last, c_last};
}
"""

lstm_cpp_source = "std::vector<torch::Tensor> lstm_forward_cuda(torch::Tensor wx, torch::Tensor wh, torch::Tensor bias, torch::Tensor h0, torch::Tensor c0, int hidden_size);"

# Compile the inline CUDA code
lstm_cuda_ops = load_inline(
    name="lstm_cuda_opt",
    cpp_sources=lstm_cpp_source,
    cuda_sources=lstm_source,
    functions=["lstm_forward_cuda"],
    verbose=False,
)

class CustomLSTM(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, dropout=0.0):
        super().__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.dropout = dropout

        self.weights_ih = nn.ParameterList()
        self.weights_hh = nn.ParameterList()
        self.biases_ih = nn.ParameterList()
        self.biases_hh = nn.ParameterList()

        for i in range(num_layers):
            layer_input_size = input_size if i == 0 else hidden_size

            # Initialize parameters similar to nn.LSTM
            w_ih = nn.Parameter(torch.randn(4 * hidden_size, layer_input_size))
            w_hh = nn.Parameter(torch.randn(4 * hidden_size, hidden_size))
            b_ih = nn.Parameter(torch.zeros(4 * hidden_size))
            b_hh = nn.Parameter(torch.zeros(4 * hidden_size))

            self.weights_ih.append(w_ih)
            self.weights_hh.append(w_hh)
            self.biases_ih.append(b_ih)
            self.biases_hh.append(b_hh)

    def forward(self, x, state):
        h_0, c_0 = state

        h_n_list = []
        c_n_list = []

        layer_input = x # Shape (Batch, Seq, Input)

        # Kernel expects (Seq, Batch, Input) for efficient striding? 
        # Actually kernel expects wx (Seq, Batch, 4H).
        # We process input projection in PyTorch then permute.

        for i in range(self.num_layers):
            # 1. Project Input: x @ W_ih.T + b_ih
            # Input x is (Batch, Seq, In). W_ih is (4H, In).
            # Output is (Batch, Seq, 4H).
            # We add b_ih here or in the kernel? Kernel takes combined bias.
            # To optimize, we can compute X @ W_ih.T here, and add bias inside kernel.

            # Projection:
            # We use standard pytorch matmul which is highly optimized
            wx = F.linear(layer_input, self.weights_ih[i]) # (Batch, Seq, 4H)

            # Permute to (Seq, Batch, 4H) for the kernel
            wx = wx.permute(1, 0, 2).contiguous()

            # Prepare other weights
            # W_hh is (4H, H). Kernel expects (H, 4H) for coalescing.
            wh_t = self.weights_hh[i].t().contiguous()

            # Combine biases
            bias = self.biases_ih[i] + self.biases_hh[i]

            # States for this layer
            h_init = h_0[i]
            c_init = c_0[i]

            # Call Custom CUDA Kernel
            h_seq, h_last, c_last = lstm_cuda_ops.lstm_forward_cuda(
                wx, wh_t, bias, h_init, c_init, self.hidden_size
            )

            h_n_list.append(h_last)
            c_n_list.append(c_last)

            # Output of this layer is input to next
            # h_seq is (Seq, Batch, Hidden). 
            # Next layer projection expects (Batch, Seq, Hidden).
            layer_input = h_seq.permute(1, 0, 2)

            # Dropout (except last layer)
            if self.dropout > 0 and i < self.num_layers - 1:
                layer_input = F.dropout(layer_input, p=self.dropout, training=self.training)

        # Stack final states
        h_n = torch.stack(h_n_list, dim=0)
        c_n = torch.stack(c_n_list, dim=0)

        # Return output (Batch, Seq, Hidden) and state
        return layer_input, (h_n, c_n)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        super(ModelNew, self).__init__()
        # Replace nn.LSTM with CustomLSTM
        self.lstm = CustomLSTM(input_size, hidden_size, num_layers, dropout=dropout)
        self.fc = nn.Linear(hidden_size, output_size)

    def forward(self, x, h0, c0):
        # Forward propagate LSTM
        out, state = self.lstm(x, (h0, c0))

        # Decode the hidden state of the last time step
        # Note: out is (Batch, Seq, Hidden)
        out = self.fc(out[:, -1, :])

        # Return only the hidden state stack as per original architecture
        return state[0]

