import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange
from torch.utils.cpp_extension import load_inline

# Custom CUDA Kernel for Fused Diagonal SSM Computation
# This kernel fuses the segment sum, exponentiation, kernel materialization, and matrix multiplication
# for the diagonal block (intra-chunk) computation Y_diag.
# It replaces the O(L^2) memory complexity with O(L) shared memory and avoids materializing large masks.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void ssm_diag_kernel(
    const float* __restrict__ A_cumsum, // (B, H, C, L)
    const float* __restrict__ B_blocks, // (B, C, L, H, N)
    const float* __restrict__ C_blocks, // (B, C, L, H, N)
    const float* __restrict__ X_blocks, // (B, C, L, H, P)
    float* __restrict__ Y_out,          // (B, C, L, H, P)
    int B_size, int C_size, int H_size, int L_size, int N_size, int P_size
) {
    // Dynamic shared memory configuration
    // Layout:
    // A_smem: L
    // B_smem: L * N
    // C_smem: L * N
    // K_smem: L * L  (Triangular kernel matrix)
    // X_smem: L * P  (Optional, but helps if P is small. Here P=64, fits)

    extern __shared__ float smem[];
    float* s_A = smem;
    float* s_B = s_A + L_size;
    float* s_C = s_B + L_size * N_size;
    float* s_K = s_C + L_size * N_size;
    float* s_X = s_K + L_size * L_size; 

    // Grid Mapping
    // flat_idx covers (B, C, H)
    int idx = blockIdx.x;
    int total_blocks = B_size * C_size * H_size;
    if (idx >= total_blocks) return;

    // Decode indices
    int h = idx % H_size;
    int temp = idx / H_size;
    int c = temp % C_size;
    int b = temp / C_size;

    int tid = threadIdx.x;
    int block_dim = blockDim.x;

    // Pointers offsets
    // A: (b, h, c, l) -> stride(c)=L, stride(h)=C*L, stride(b)=H*C*L
    long long offset_A = (long long)b * H_size * C_size * L_size + (long long)h * C_size * L_size + (long long)c * L_size;

    // B, C, X: (b, c, l, h, ...)
    // Strides for l dimension involve H and inner dim
    long long stride_l_B = H_size * N_size;
    long long stride_l_X = H_size * P_size;

    // Base offsets for the chunk (b, c, 0, h, 0)
    long long base_B = ((long long)b * C_size * L_size + (long long)c * L_size) * stride_l_B + (long long)h * N_size;
    long long base_C = ((long long)b * C_size * L_size + (long long)c * L_size) * stride_l_B + (long long)h * N_size;
    long long base_X = ((long long)b * C_size * L_size + (long long)c * L_size) * stride_l_X + (long long)h * P_size;
    long long base_Y = base_X; // Y has same shape as X

    // 1. Load A (L)
    for (int i = tid; i < L_size; i += block_dim) {
        s_A[i] = A_cumsum[offset_A + i];
    }

    // 2. Load B and C (L * N)
    // Flattened loop for B and C
    int total_BN = L_size * N_size;
    for (int i = tid; i < total_BN; i += block_dim) {
        int l = i / N_size;
        int n = i % N_size;
        s_B[i] = B_blocks[base_B + l * stride_l_B + n];
        s_C[i] = C_blocks[base_C + l * stride_l_B + n];
    }

    // 3. Load X (L * P)
    int total_XP = L_size * P_size;
    for (int i = tid; i < total_XP; i += block_dim) {
        int l = i / P_size;
        int p = i % P_size;
        s_X[i] = X_blocks[base_X + l * stride_l_X + p];
    }

    __syncthreads();

    // 4. Compute K matrix (L * L)
    // K[l, s] = (sum_n C[l,n]*B[s,n]) * exp(A[l] - A[s]) if s <= l else 0
    int total_LL = L_size * L_size;
    for (int i = tid; i < total_LL; i += block_dim) {
        int l = i / L_size;
        int s = i % L_size;

        float val = 0.0f;
        if (s <= l) {
            // Dot product C[l] . B[s]
            float dot = 0.0f;
            for (int n = 0; n < N_size; ++n) {
                dot += s_C[l * N_size + n] * s_B[s * N_size + n];
            }

            // Decay
            float decay_val = s_A[l] - s_A[s];
            val = dot * expf(decay_val);
        }
        s_K[l * L_size + s] = val;
    }

    __syncthreads();

    // 5. Compute Y = K * X (L * P)
    // Y[l, p] = sum_s K[l, s] * X[s, p]
    for (int i = tid; i < total_XP; i += block_dim) {
        int l = i / P_size;
        int p = i % P_size;

        float acc = 0.0f;
        // Optimization: s loop only needs to go up to l because K is triangular
        for (int s = 0; s <= l; ++s) {
            acc += s_K[l * L_size + s] * s_X[s * P_size + p];
        }

        // Write global
        Y_out[base_Y + l * stride_l_X + p] = acc;
    }
}

torch::Tensor ssm_diag_cuda_func(torch::Tensor A_cumsum, torch::Tensor B_blocks, torch::Tensor C_blocks, torch::Tensor X_blocks) {
    // Inputs must be contiguous in the last dimension? 
    // We handle strides manually in kernel for dimensions > 1, but assume dense packing for simplicity or use passed strides.
    // The kernel implementation assumes the specific layout resulting from the python code's rearrange + contiguous.

    // Shapes:
    // A: (B, H, C, L)
    // B, C: (B, C, L, H, N)
    // X: (B, C, L, H, P)

    int batch_size = A_cumsum.size(0);
    int n_heads = A_cumsum.size(1);
    int n_chunks = A_cumsum.size(2);
    int block_len = A_cumsum.size(3);

    int d_state = B_blocks.size(4);
    int d_head = X_blocks.size(4);

    auto Y = torch::empty_like(X_blocks);

    // Shared memory size
    // L + 2*L*N + L*L + L*P
    int smem_size = (block_len + 2 * block_len * d_state + block_len * block_len + block_len * d_head) * sizeof(float);

    int total_blocks = batch_size * n_chunks * n_heads;
    int threads = 256;

    ssm_diag_kernel<<<total_blocks, threads, smem_size>>>(
        A_cumsum.data_ptr<float>(),
        B_blocks.data_ptr<float>(),
        C_blocks.data_ptr<float>(),
        X_blocks.data_ptr<float>(),
        Y.data_ptr<float>(),
        batch_size, n_chunks, n_heads, block_len, d_state, d_head
    );

    return Y;
}
"""

cpp_source = """
torch::Tensor ssm_diag_cuda_func(torch::Tensor A_cumsum, torch::Tensor B_blocks, torch::Tensor C_blocks, torch::Tensor X_blocks);
"""

# Compile the CUDA kernel
ssm_diag_module = load_inline(
    name="ssm_diag_fused",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["ssm_diag_cuda_func"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, batch_size, seq_length, n_heads, d_head, d_state, block_len=64):
        """
        Optimized Mamba Structured State Space model.
        """
        super(ModelNew, self).__init__()

        assert seq_length % block_len == 0, "Sequence length must be divisible by block length"

        self.batch_size = batch_size
        self.seq_length = seq_length
        self.n_heads = n_heads
        self.d_head = d_head
        self.d_state = d_state
        self.block_len = block_len

        # Initialize parameters
        self.A = nn.Parameter(torch.randn(batch_size, seq_length, n_heads))
        self.B = nn.Parameter(torch.randn(batch_size, seq_length, n_heads, d_state))
        self.C = nn.Parameter(torch.randn(batch_size, seq_length, n_heads, d_state))

        self.ssm_kernel = ssm_diag_module

    def segsum(self, x):
        """Naive segment sum calculation (kept for the inter-chunk part which is small)."""
        T = x.size(-1)
        x_cumsum = torch.cumsum(x, dim=-1)
        x_segsum = x_cumsum[..., :, None] - x_cumsum[..., None, :]
        mask = torch.tril(torch.ones(T, T, device=x.device, dtype=bool), diagonal=0)
        x_segsum = x_segsum.masked_fill(~mask, -torch.inf)
        return x_segsum

    def forward(self, X, initial_states=None):
        """
        Forward pass implementing the SSD operation using fused CUDA kernels.
        """
        # Rearrange into blocks/chunks
        # Ensure contiguous memory for CUDA kernel
        X_blocks = rearrange(X, "b (c l) ... -> b c l ...", l=self.block_len).contiguous()
        A_blocks = rearrange(self.A, "b (c l) ... -> b c l ...", l=self.block_len)
        B_blocks = rearrange(self.B, "b (c l) ... -> b c l ...", l=self.block_len).contiguous()
        C_blocks = rearrange(self.C, "b (c l) ... -> b c l ...", l=self.block_len).contiguous()

        # A_blocks needs transpose for the logic, and we need cumsum
        # A_blocks: b c l h -> b h c l
        A_blocks = rearrange(A_blocks, "b c l h -> b h c l").contiguous()
        A_cumsum = torch.cumsum(A_blocks, dim=-1)

        # 1. Compute diagonal block outputs using Fused CUDA Kernel
        # This replaces the expensive L materialization and Einsum
        Y_diag = self.ssm_kernel.ssm_diag_cuda_func(A_cumsum, B_blocks, C_blocks, X_blocks)

        # 2. Compute intra-chunk states
        # A_cumsum is (b, h, c, l). Slice last dim -> (b, h, c, 1)
        decay_states = torch.exp((A_cumsum[:, :, :, -1:] - A_cumsum))
        # decay_states: b h c l
        # B_blocks: b c l h n
        # X_blocks: b c l h p
        # Einsum: bclhn, bhcl, bclhp -> bchpn
        # We perform this in PyTorch as it's O(L) and relatively fast compared to O(L^2) part
        states = torch.einsum("bclhn,bhcl,bclhp->bchpn", 
                            B_blocks, decay_states, X_blocks)

        # 3. Compute inter-chunk recurrence
        if initial_states is None:
            initial_states = torch.zeros_like(states[:, :1])
        states = torch.cat([initial_states, states], dim=1)

        # A_cumsum[..., -1] is (B, H, C). Pad -> (B, H, C+1)
        decay_chunk = torch.exp(self.segsum(F.pad(A_cumsum[:, :, :, -1], (1, 0))))
        new_states = torch.einsum("bhzc,bchpn->bzhpn", decay_chunk, states)
        states = new_states[:, :-1]

        # 4. Compute state-to-output conversion
        state_decay_out = torch.exp(A_cumsum)
        # Note: A_cumsum is (B, H, C, L). einsum expects 'bhcl'. Matches.
        Y_off = torch.einsum('bclhn,bchpn,bhcl->bclhp', 
                           C_blocks, states, state_decay_out)

        # Combine diagonal and off-diagonal terms
        Y = rearrange(Y_diag + Y_off, "b c l h p -> b (c l) h p")

        return Y

