import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Softmax along the last dimension
softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

template<typename T>
__inline__ __device__ T warpReduceMax(T val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2)
        val = max(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

template<typename T>
__inline__ __device__ T blockReduceMax(T val) {
    static __shared__ T shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceMax(val);

    if (lane == 0) shared[wid] = val;

    __syncthreads();

    // Read from shared memory only if thread is in the first warp
    // and corresponds to a warp that wrote data
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : -1e37f;

    if (wid == 0) val = warpReduceMax(val);

    return val;
}

template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

template<typename T>
__inline__ __device__ T blockReduceSum(T val) {
    static __shared__ T shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;

    __syncthreads();

    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0;

    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void softmax_last_dim_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (row_idx >= rows) return;

    // Load data
    float val = -1e37f; // Initialize with a very small number
    if (tid < cols) {
        val = input[row_idx * cols + tid];
    }

    // Compute Max
    float max_val = blockReduceMax(val);

    // Broadcast max to all threads
    __shared__ float s_max;
    if (tid == 0) s_max = max_val;
    __syncthreads();
    max_val = s_max;

    // Compute Exp
    float exp_val = 0.0f;
    if (tid < cols) {
        exp_val = expf(val - max_val);
    }

    // Compute Sum
    float sum_val = blockReduceSum(exp_val);

    // Broadcast sum to all threads
    __shared__ float s_sum;
    if (tid == 0) s_sum = sum_val;
    __syncthreads();
    sum_val = s_sum;

    // Write output
    if (tid < cols) {
        output[row_idx * cols + tid] = exp_val / sum_val;
    }
}

torch::Tensor softmax_last_dim_cuda(torch::Tensor input) {
    // Treat input as (N*C*H, W) where W is the last dimension
    auto input_flat = input.contiguous();
    int cols = input.size(-1);
    int rows = input.numel() / cols;

    auto output = torch::empty_like(input_flat);

    int block_size = 32;
    // Find next power of 2
    while (block_size < cols && block_size < 1024) block_size *= 2;

    softmax_last_dim_kernel<<<rows, block_size>>>(input_flat.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output.view_as(input);
}
"""

softmax_cpp_source = "torch::Tensor softmax_last_dim_cuda(torch::Tensor input);"

# Compile the inline CUDA code
softmax_cuda = load_inline(
    name="softmax_cuda",
    cpp_sources=softmax_cpp_source,
    cuda_sources=softmax_source,
    functions=["softmax_last_dim_cuda"],
    verbose=False,
)

class SoftmaxLastDim(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return softmax_cuda.softmax_last_dim_cuda(x)

class DoubleConvNew(nn.Module):
    def __init__(self, in_channels, out_channels):
        super().__init__()
        self.double_conv = nn.Sequential(
            nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            SoftmaxLastDim(),
            nn.Conv2d(out_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            SoftmaxLastDim()
        )

    def forward(self, x):
        return self.double_conv(x)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, features):
        super(ModelNew, self).__init__()
        self.encoder1 = DoubleConvNew(in_channels, features)
