import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for Channel Shuffle and Element-wise Addition
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void channel_shuffle_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    int total_elements,
    int C, int H, int W,
    int groups,
    int channels_per_group,
    int S) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Decompose linear index to find (n, c, h, w)
        // idx = n * (C * S) + c * S + hw
        // S = H * W

        int hw = idx % S;
        int tmp = idx / S;
        int c = tmp % C;
        int n_offset = (tmp / C) * C * S; // Base offset for the batch item

        // Shuffle logic:
        // Current channel c corresponds to group g and inner index k
        // c = g * channels_per_group + k
        int g = c / channels_per_group;
        int k = c % channels_per_group;

        // Target channel c_out corresponds to (k, g)
        // c_out = k * groups + g
        int c_out = k * groups + g;

        // Reconstruct output index
        int out_idx = n_offset + c_out * S + hw;

        output[out_idx] = input[idx];
    }
}

torch::Tensor channel_shuffle_cuda(torch::Tensor input, int groups) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    auto output = torch::empty_like(input);
    int total_elements = input.numel();
    int channels_per_group = C / groups;
    int S = H * W;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "channel_shuffle_cuda", ([&] {
        channel_shuffle_kernel<scalar_t><<<num_blocks, block_size>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            total_elements,
            C, H, W,
            groups,
            channels_per_group,
            S);
    }));

    return output;
}

template <typename scalar_t>
__global__ void add_kernel(const scalar_t* __restrict__ a, const scalar_t* __restrict__ b, scalar_t* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor add_cuda(torch::Tensor a, torch::Tensor b) {
    auto out = torch::empty_like(a);
    int size = a.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    AT_DISPATCH_FLOATING_TYPES(a.scalar_type(), "add_cuda", ([&] {
        add_kernel<scalar_t><<<num_blocks, block_size>>>(
            a.data_ptr<scalar_t>(),
            b.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            size);
    }));
    return out;
}
